window.ATLAS_I18N_LOR={"01IO012":["Disciplinas Gêmeas","Conceda +3|+0 ou +0|+3 a um aliado nesta rodada.","","\"Nunca tema a mudança. Ela questionará e testará seus limites. A mudança é a nossa maior professora.\" – Karma","Feitiço",[],["Ionia"],"COMUM"],"01IO015":["Yasuo","Quando você Atordoar ou Retornar um inimigo, eu causo 2 de dano a ele.","Você Atordoou ou Retornou 5+ unidades.","\"A morte é como o vento...\"","Unidade",[],["Ionia"],"Campeão"],"01IO020":["Guardiã das Máscaras","Ao me invocar, conceda +1|+0 aos outros aliados nesta rodada.","","\"Hoje seu rosto se tornará o reflexo da disciplina, do treinamento, da humildade e do equilíbrio. Hoje você se tornará Kinkou.\"","Unidade",[],["Ionia"],"COMUM"],"01IO045":["Arauto da Primavera","Auxiliar: Conceda Roubo de Vida ao meu aliado auxiliado nesta rodada.","","\"Durante o reinado invernal\nOuvimos pegadas sobre o chão nevado. \nPor onde passava, videiras e folhas subiam ao alto\nAbrindo caminho à nova estação do Arauto.\"\n– Poema Shon-Xan","Unidade",[],["Ionia"],"COMUM"],"01IO008":["Fada das Lâminas","Quando você Atordoar ou Retornar uma unidade, eu ganho +2|+0.","","\"Ah, você me acha 'engraçadinha', é? 'Fofinha'? Olha só que fofinho ISSO AQUI!\"","Unidade",["YORDLE"],["Ionia"],"RARO (A)"],"01IO040":["Lâmina Vital Kinkou","","","\"Este lugar já abrigou nossas escolas, templos e casas. Agora vagamos por essas ruínas infestadas de sombras. A Ordem de Zed corrompeu este lugar sagrado. E eles pagarão por isso.\"","Unidade",[],["Ionia"],"COMUM"],"01IO041":["Karma","Fim de Rodada: Crie na mão um feitiço aleatório das suas regiões.","Você está Iluminado.","\"Pela reflexão, podemos focar a mente e encontrar caminhos para superar qualquer obstáculo.\"","Unidade",[],["Ionia"],"Campeão"],"01IO011":["Retorno","Retorne um aliado.","","Um combatente sábio não é só determinado, mas também comedido. Uma retirada bem-sucedida permite lutar melhor outro dia.","Feitiço",[],["Ionia"],"COMUM"],"01IO009":["Zed","Atacar: Invoque 1 Sombra Viva atacante com os meus atributos.","Vi eu ou cópias aliadas de Sombras Vivas Golpeando o Nexus inimigo duas vezes.","\"O equilíbrio é uma tolice. As sombras me mostraram o verdadeiro poder.\"","Unidade",[],["Ionia"],"Campeão"],"01IO014":["Ancião da Clareira Verdejante","Ao me invocar, dê +1|+1 aos aliados na mão.","","O conhecimento ioniano é registrado por escrito, mas são os contos e ensinamentos dos venerados anciãos de Ionia que dão vida a esses textos.","Unidade",[],["Ionia"],"COMUM"],"01IO005":["Poro Parrudo","","","\"Pode parecer loucura, mas a última coisa que me lembro é de ter sentido algo... felpudo?\" – Brigante Navori","Unidade",["PORO"],["Ionia"],"COMUM"],"01IO044":["Conspirador Navori","Para me pôr em jogo, Retorne um aliado.","","\"Rápido, precisamos sair daqui! Meu nome? Juro que explico tudo no caminho...\"","Unidade",[],["Ionia"],"COMUM"],"01IO023":["Protetora Adornada","Jogar: Dê +3|+3 a um aliado na mão.","","\"Em momentos de conflito, os aldeões recorriam à guardiã do Vale do Outono. Aqueles que conquistavam seu coração recebiam bênçãos capazes de mudar os rumos da batalha.\"\n– Saga das Primeiras Terras","Unidade",[],["Ionia"],"RARO (A)"],"01IO029":["Sementes Semeadas","Dê +1|+0 aos aliados na mão.","","\"Não são apenas sementes, meus jovens aprendizes. São o legado da própria terra, as promessas de um futuro próspero.\" – Karma","Feitiço",[],["Ionia"],"RARO (A)"],"01IO003":["Marca Fatal","Remova Efêmero de um aliado e dê a um inimigo.","","\"Eu sou a lâmina na escuridão.\" – Zed\n\n","Feitiço",[],["Ionia"],"RARO (A)"],"01IO047":["Irrupção Sombria","Dê Efêmero a TODOS os seguidores em batalha.","","Quando os fluxos de magia entram em desequilíbrio, irrompem do mundo espiritual para o reino mortal, muitas vezes com resultados estarrecedores.","Feitiço",[],["Ionia"],"ÉPICO (A)"],"01IO026":["Mentor Inspirador","Jogar: Dê +1|+0 a um aliado na mão.","","\"Levei anos para cultivar este físico imponente! Dias incansáveis apreciando pássaros, descrevendo as nuvens e levantando bandejas de pão doce! Quem mais se dedicaria tanto?\"","Unidade",[],["Ionia"],"COMUM"],"01IO024":["Alvorada e Crepúsculo","Invoque 2 cópias idênticas a um aliado. Elas são Efêmeras.","","\"Shen é um homem dividido entre as demandas de dois mundos, mas que decepciona a ambos. Eu me dedico inteiramente a Ionia.\" – Zed","Feitiço",[],["Ionia"],"RARO (A)"],"01IO028":["Escamossauro","Jogar: Eu ganho +3|+0 ou +0|+3.","","Um dos habitantes mais velhos da Clareira Verdejante, ele aprendeu a se adaptar para sobreviver às provações do tempo.","Unidade",["RÉPTIL"],["Ionia"],"COMUM"],"01IO057":["Assassina das Sombras","Ao me invocar, compre 1.","","Ela desliza com graça\nTaciturna pelas sombras\nDeixando o vestígio das garras.","Unidade",[],["Ionia"],"COMUM"],"01IO032":["Shen","Auxiliar: Conceda Barreira ao meu aliado auxiliado nesta rodada.","Vi aliados ganharem Barreira 5 vezes.","\"Como mãos atadas, o plano mortal e o espiritual se entrelaçam.\"","Unidade",[],["Ionia"],"Campeão"],"01IO013":["Demônio da Sombra","","","\"O que você sacrificaria pelo poder? A transformação começa com um juramento... e só termina depois de tomar tudo o que podia de você.\" – Zed","Unidade",[],["Ionia"],"COMUM"],"01IO018":["Ímpeto","Conceda +1|+0 e Ataque Rápido a um aliado nesta rodada.","","O combate nada mais é do que uma corrida para tirar a vida de alguém antes que tirem a sua.","Feitiço",[],["Ionia"],"COMUM"],"01IO056":["Yone, o Perseguidor de Ventos","Jogar: Atordoe 2 inimigos.","","\"Quando eu era criança, perguntei ao meu irmão: 'O vento corre ou o vento segue?'. Na época, ele me seguia para se espelhar em mim. Hoje, eu o persigo para fazer justiça.\"\n","Unidade",[],["Ionia"],"RARO (A)"],"01IO016":["Sábio do Zéfiro","Jogar: Crie uma cópia idêntica a uma carta na mão que não seja Sábio do Zéfiro.","","\"Enquanto o guerreiro chorava por sua perda, o ancião o consolava: 'Procure o sábio dos céus. Só ele pode devolver o que está perdido, mas ainda guardado na memória.'\"\n– Saga das Primeiras Terras","Unidade",["AVE"],["Ionia"],"RARO (A)"],"01IO036":["Vigia da Clareira Verdejante","Golpear: Reduza em 1 o custo da unidade mais cara da mão.","","\"Patrulha, nós temos uma... não... DUAS criaturas peludas gigantescas vindo para cá! Chame refor... Ah. Espera aí. A luneta estava ao contrário de novo...\"","Unidade",["YORDLE"],["Ionia"],"COMUM"],"01IO033":["Minah Pés Ligeiros","Jogar: Retorne 3 inimigos.","","\"Lá estávamos nós, atravessando o campo quando, de repente, uma CRIANÇA surge do nada e PÁ, PÁ, PÁ – nos pega de surpresa!\" – Brigante Navori","Unidade",[],["Ionia"],"ÉPICO (A)"],"01IO001":["Ritual de Renovação","Cure um aliado ou o seu Nexus em 4. Compre 1.","","\"Só quando a mente evolui, o corpo fica pleno.\" – Karma","Feitiço",[],["Ionia"],"RARO (A)"],"01IO010":["Manter a União","Troque 2 aliados de lugar. Conceda Barreira a eles nesta rodada.","","\"Com passos equilibrados, eu sigo caminhando.\" – Shen\n","Feitiço",[],["Ionia"],"RARO (A)"],"01IO022":["Fantasma","Conceda Elusivo a um aliado nesta rodada.","","\"Vá, fique escondido... e só volte quando cumprir a tarefa.\"\n– Zed","Feitiço",[],["Ionia"],"COMUM"],"01IO021":["Cria do Vento","Ao me invocar, conceda +2|+2 aos outros aliados nesta rodada.","","\"A primavera floresce primeiro nos penhascos de Ionia, onde asas recém-formadas batem e acariciam a terra com as suaves brisas da estação.\"\n– Saga das Primeiras Terras","Unidade",[],["Ionia"],"ÉPICO (A)"],"01IO054":["Perspicácia das Eras","Crie na mão outro feitiço aleatório das suas regiões.\nIluminado: Em vez disso, crie 2.","","\"Quando sua esperança fraquejar, saiba que não está só. O passado está sempre ao nosso lado. Ele conhece inúmeros amanhãs e toda a esperança que eles trazem.\" – Karma","Feitiço",[],["Ionia"],"RARO (A)"],"01IO027":["Vidente Taciturna","Golpe ao Nexus: Crie uma cópia minha na mão.","","\"A carne é inconfiável. Frágil. Delicada como as fronteiras entre a luz e as sombras.\"","Unidade",[],["Ionia"],"ÉPICO (A)"],"01IO031":["Sorvedor de Nuvens","Seus feitiços Súbitos e Focados custam 1 a menos.","","Suas canções eram ouvidas até nas aldeias – longas e suaves ondas de som que se propagavam do céu para a encosta, tão disformes e estranhas quanto as nuvens vespertinas.","Unidade",[],["Ionia"],"RARO (A)"],"01IO002":["Vontade de Ionia","Retorne uma unidade.","","Quando os invasores pisaram em Ionia pela primeira vez, descobriram que subjugar seus habitantes não seria suficiente.","Feitiço",[],["Ionia"],"COMUM"],"01IO017":["Batedor Navori","Ao me invocar, me conceda Elusivo nesta rodada.","","\"Eu vou dar um jeito nele, não se preocupe. É só me tirar de lá que eu divido os lucros com você. Prometo que vale a pena!\"","Unidade",["YORDLE"],["Ionia"],"COMUM"],"01IO042":["Aluno em Treinamento","Ao invocar outro aliado, me conceda +1|+1 nesta rodada.","","\"Para que lutar quando não tem ninguém vendo os seus golpes?\"","Unidade",[],["Ionia"],"COMUM"],"01IO006":["Dupla da Clareira Verdejante","Ao invocar outro aliado, me conceda +1|+0 nesta rodada.","","\"Ei, cuidado com os galhos! Esquerda, ESQUERDA!\" \n\"Quando eu estiver nos SEUS ombros, Felpudinho, podemos ir pra onde você quiser. Até lá, quem decide sou eu!\"","Unidade",[],["Ionia"],"RARO (A)"],"01IO050":["Desbravadora Kinkou","Lealdade: Invoque um aliado com 1 de custo do seu deck.","","Aonde quer que vá, ela se certifica de que outros poderão segui-la.","Unidade",[],["Ionia"],"RARO (A)"],"01IO048":["Yusari","","","\"Sua Ordem nos expulsou de nossas terras. Você provou o seu poder, mestre Zed. Agora, me deixe provar que também sou digno de seus ensinamentos.\"","Unidade",[],["Ionia"],"RARO (A)"],"01IO007":["Ren Lâmina Sombria","Golpear: Crie 1 Demônio da Sombra na mão.","","“Corra, lute, recue... Não adianta, as sombras já vieram ao seu encontro.\"","Unidade",[],["Ionia"],"ÉPICO (A)"],"01IO053":["Evocador Esmeralda","Iluminado: Tenho +4|+4.","","\"Guerras são estimuladas pelos nossos instintos mais básicos, mas eles não têm poder sobre nossas maiores virtudes: confiança, paciência e reflexão.\"","Unidade",[],["Ionia"],"COMUM"],"01IO004":["Poção de Vida","Cure um aliado ou o seu Nexus em 3.","","Cada geração, região e família tem seus próprios remédios caseiros... embora alguns sejam inegavelmente mais eficazes que outros.","Feitiço",[],["Ionia"],"COMUM"],"01IO049":["Negação","Interrompa um feitiço Rápido, um feitiço Lento ou uma Habilidade.","","Não.","Feitiço",[],["Ionia"],"RARO (A)"],"01IO052":["Salteador Navori","Ao me invocar, invoque 1 Brigante Navori com os mesmos atributos que eu.","","\"Eu era um músico viajante, conhecido em todas as aldeias daqui até o Placídio. Até os noxianos chegarem. Agora tento sobreviver roubando uns trocados. Mamãe tinha razão, eu devia ter sido curandeiro...\"","Unidade",[],["Ionia"],"COMUM"],"01IO030":["O Empíreo","","","\"O próprio céu se erguia enquanto espirais de nuvens e ventanias pressionavam nossa brigada. Tentamos segui-lo, mas quem consegue perseguir o vento?\" – General da Legião","Unidade",["DRAGÃO"],["Ionia"],"ÉPICO (A)"],"01IO019":["Defensora da Clareira Verdejante","Quando um aliado receber Barreira, eu ganho +2|+0.","","\"A clareira protege seus nativos. E você... você não é daqui...\"","Unidade",[],["Ionia"],"COMUM"],"01IO046":["Tempestade de Aço","Atordoe um inimigo atacante.","","\"Hasagi!\" – Yasuo","Feitiço",["ELEMENTAL"],["Ionia"],"RARO (A)"],"01IO037":["Refúgio Espiritual","Conceda Barreira e Roubo de Vida a um aliado nesta rodada.","","\"Esta lâmina já foi do meu pai. Que ela lhe conceda a força que eu um dia não tive.\" – Shen","Feitiço",[],["Ionia"],"COMUM"],"01IO043":["Moldador de Rios","Golpear: Compre um feitiço.","","\"Somos os orgulhosos filhos das Primeiras Terras. Seus rios mágicos fluem por nossas veias vastayesas assim como por nosso reino.\"","Unidade",[],["Ionia"],"RARO (A)"],"01IO038":["Monja Solitária","Jogar: Retorne todos os outros aliados.","","\"Meus reflexos e instintos são a única companhia que desejo ter.\"","Unidade",[],["Ionia"],"RARO (A)"],"01IO039":["Sombra Distorcida","Retorne um aliado para invocar 1 Sombra Viva no lugar dele.","","Você enfrenta o inimigo que acredita ver? Ou será somente um truque das sombras?","Feitiço",[],["Ionia"],"COMUM"],"01IO055":["Guardião de Ki","Dê Barreira a um aliado na mão.\nCompre 1.","","\"Aqueles que mantiverem o equilíbrio serão protegidos pelos Kinkou.\" – Shen\n","Feitiço",[],["Ionia"],"COMUM"],"01NX020":["Draven","Ao me invocar ou Golpear: Crie 1 Revolução do Machado na mão.","Golpeei com 2+ Revoluções do Machado no total.","\"Quer um autógrafo? Entra na fila.\"","Unidade",[],["Noxus"],"Campeão"],"01NX006":["Vladimir","Jogar: Cause 1 de dano a qualquer número de aliados para causar a mesma quantidade de dano a um inimigo.","5+ aliados seus sobreviveram a dano.","Brutal. Frio. Cruel. Intrigante. Perspicaz. Charmoso.\nIrresistível...","Unidade",[],["Noxus"],"Campeão"],"01NX004":["Golpe Expurgante","Abata uma unidade com 3 ou menos de Poder.","","Todos morrem. Os fracos só morrem mais rápido.","Feitiço",[],["Noxus"],"RARO (A)"],"01NX048":["Curador Carmesim","Quando eu sobreviver a dano, crie uma unidade Carmesim aleatória na mão.","","\"Prezados companheiros!\" \"Lisonjeado estou! Aliás, eu recebi um convite.\" \"–Regozijo! Isso!\" \"Sim! Vou apresentar minha família.\" \"Refinadas como sempre. E você, Kye? Também vai?\"","Unidade",[],["Noxus"],"COMUM"],"01NX038":["Darius","","Vejo que o Nexus inimigo tem metade ou menos da sua Vida inicial.","\"Determinação de aço e a força de um titã. Não há melhor general para liderar a Legião Trifariana.\" – Swain\n","Unidade",[],["Noxus"],"Campeão"],"01NX023":["Anfitriã Aracnídea","Ao me invocar, dê +2|+0 a outras Aranhas aliadas.","","Com um único olhar, você pertence a ela. E com uma única mordida, você pertence a elas.","Unidade",["ARANHA"],["Noxus"],"RARO (A)"],"01NX013":["Estratégia Decisiva","Atordoe um inimigo. Conceda +2|+0 a todos os aliados nesta rodada.","","\"Qualquer idiota consegue usar força bruta contra um inimigo. Mas é preciso ser um visionário para guardar essa força até o momento decisivo.\" – Swain","Feitiço",[],["Noxus"],"RARO (A)"],"01NX046":["Vigia Aracnídea","Jogar: Atordoe um inimigo.","","\"Ah, como ela me cativa! Suas pernas longas, sua voz que me paralisa de tanta doçura e seus olhos vermelhos como as rosas. E pensar que ela escolheu jantar comigo!\"\n– Aristocrata Azarado","Unidade",["ARANHA"],["Noxus"],"COMUM"],"01NX047":["Transfusão","Cause 1 de dano a um aliado para conceder +2|+2 a outro aliado nesta rodada.","","\"Alguém tem que ceder, meu bem. Você cede e eu tomo.\"\n– Vladimir","Feitiço",[],["Noxus"],"COMUM"],"01NX040":["Sabotadora da Legião","Atacar: cause 1 de dano ao Nexus inimigo.","","\"Nossos Quebra-escudos conseguem cortar um homem ao meio, mas a Legião tem outros talentos à disposição para um toque mais... discreto.\" – Swain","Unidade",[],["Noxus"],"COMUM"],"01NX025":["Laço Fraterno","Dê +2|+0 a 2 aliados.","","\"Os laços forjados na guerra são tão fortes quanto os de parentesco. Ambos nascem do sangue.\" – Veterano da Legião","Feitiço",[],["Noxus"],"COMUM"],"01NX055":["Aranha Doméstica","Ao me invocar, invoque 1 Cria Aracnídea.","","\"Minhas aranhas adoram companhia. Pena que a recíproca não é verdadeira.\" – Elise","Unidade",["ARANHA"],["Noxus"],"COMUM"],"01NX030":["Discípula Carmesim","Quando eu sobreviver a dano, cause 1 de dano ao Nexus inimigo.","","\"Edvin! Aí está você, bonitão. Estava pensando em você agorinha!\" \"Oh, então vamos juntos.\" \"Não se preocupe, eu te acompanho.\" \"Gostei! Ou quem sabe não usar nada?\"","Unidade",[],["Noxus"],"RARO (A)"],"01NX007":["Apresentador da Arena","Atacar: Conceda +1|+0 a outros aliados atacantes nesta rodada.","","Ele urrou de alegria. Naquele momento, o coração da arena pulsava junto ao seu, e a empolgação da multidão era retratada em seu punho erguido e vitorioso.","Unidade",[],["Noxus"],"RARO (A)"],"01NX021":["Saqueador da Legião","Atacar: Dê +1|+1 aos Saqueadores da Legião aliados globalmente.","","A Legião Trifariana é seguida por salteadores oportunistas que se aproveitam dos fracos e feridos em seu caminho.","Unidade",[],["Noxus"],"COMUM"],"01NX009":["Favorito do Público","Ao me invocar, eu ganho +1|+1 por cada outro aliado que você tiver.","","Alguns Desafiadores são adorados por seu carisma. Outros, por suas técnicas ligeiras. Vessid não tem nada disso a seu favor, mas ninguém esmaga os rivais com mais eficiência que ele.","Unidade",[],["Noxus"],"RARO (A)"],"01NX011":["Reta da Morte","Um aliado em batalha Golpeia um inimigo em batalha.","","\"Tenho o melhor trabalho do mundo.\" – Draven","Feitiço",[],["Noxus"],"COMUM"],"01NX053":["Desafio","Se tiver um aliado com 5+ de Poder, abata TODAS as unidades com Poder igual ou menor a 4.","","\"QUEM ESTÁ PRONTO PARA O DESAAAAFIOOOOO?!\"\n– Apresentador da Arena","Feitiço",[],["Noxus"],"ÉPICO (A)"],"01NX054":["Rugido Intimidante","Atordoe todos os inimigos com 4 ou menos de Poder.","","\"Ele está respirando fundo, acho que é... Opa! Aí está, minha gente! O famoso grito de guerra do Trovão! Estamos todos com as pernas bambas... Trovããããão!\" – Apresentador da Arena","Feitiço",[],["Noxus"],"RARO (A)"],"01NX029":["Veterano da Legião","Quando outro aliado sobreviver a dano, dê +1|+0 a ele.","","Ele voltou da guerra à beira da morte e só sobreviveu graças ao amor do marido e aos bálsamos do boticário. Noxus fez de tudo para garantir os valiosos conselhos dele após se aposentar da batalha.","Unidade",[],["Noxus"],"ÉPICO (A)"],"01NX014":["Shiraza, a Lâmina","Eu causo o dobro de dano ao Nexus.","","\"Ele disse o quê?! Esse cara não tem nada na cabeça. Mas aqueles ombros...\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"01NX042":["Katarina","Ao me invocar, crie 1 Fio da Lâmina Fugaz na mão.","Eu Golpeei uma vez. Quando eu subir de nível, me Retorne.","\"Nada como um bom alvo demaciano para aguçar os sentidos...\"","Unidade",[],["Noxus"],"Campeão"],"01NX051":["Capitão Farron","Ao me invocar, crie 2 Dizimar na mão.","","Dentro do Sumidouro de Zaun, o jovem Benn Farron foi considerado uma ameaça. Instável. Inaceitável. Mas nas fileiras de Noxus, ele foi acolhido. Condecorado. Implacável.","Unidade",[],["Noxus"],"ÉPICO (A)"],"01NX012":["Retaguarda da Legião","","","Em Noxus, onde soldados são venerados por sua audácia no campo de batalha, ficar na retaguarda não passa de um castigo.","Unidade",[],["Noxus"],"COMUM"],"01NX043":["Fio da Lâmina","Cause 1 de dano a qualquer coisa.","","\"Nas mãos certas, uma lâmina pode cortar qualquer coisa... qualquer coisa mesmo.\" – Katarina","Feitiço",[],["Noxus"],"COMUM"],"01NX037":["Granadeiro da Legião","Suspiro Final: Cause 1 de dano ao Nexus inimigo.","","Todo noxiano aprende que servir ao império é aproveitar bem a vida, mas poucos têm uma vida tão espetacular quanto os granadeiros da Legião.","Unidade",[],["Noxus"],"COMUM"],"01NX010":["General da Legião","Ao me invocar, eu ganho +1|+1 por cada unidade que você tiver Atordoado ou Retornado nesta partida.","","Todo noxiano conhece os três Princípios da Força, mas para que um soldado seja promovido, ele deve aprender a dominá-los.","Unidade",[],["Noxus"],"COMUM"],"01NX017":["Percussionista da Legião","Auxiliar: Conceda Ataque Rápido ao meu aliado auxiliado nesta rodada.","","A Legião espalhou o alcance do império ao som de cada batida dos tambores dela. Nada podia detê-los. E nada os deteve.","Unidade",[],["Noxus"],"COMUM"],"01NX003":["Agente de Apostas da Arena","Início de Rodada: Descarte sua carta de menor custo para comprar 1.","","\"... você vai apostar na Shiraza como ÚNICA SOBREVIVENTE, mas tem aquele garoto ioniano... É, ele perdeu um braço... mas não morreu. É um sobrevivente também, viu só? Mas você pode dobrar a aposta...\"","Unidade",["YORDLE"],["Noxus"],"RARO (A)"],"01NX039":["Visão","Ao jogar ou descartar, dê +1|+0 aos aliados.","","\"Aqueles que não enxergam o futuro não o merecem.\" – Jericho Swain","Feitiço",[],["Noxus"],"RARO (A)"],"01NX041":["Quebra-escudos Trifariano","","","\"Não estou com paciência para fazer um cerco. Mandem os Quebra-escudos.\" – Darius","Unidade",[],["Noxus"],"COMUM"],"01NX036":["Desafiador Minotauro","Início de Rodada: Atordoe o inimigo Mais Fraco.","","\"Não me interessa o que fizeram ou por quê. Quer que eu acerte suas contas em combate? Pagamento adiantado. Não dou desconto para histórias tristes.\"","Unidade",[],["Noxus"],"RARO (A)"],"01NX044":["Aríete","Atacar: Eu ganho +4|+0.","","\"Senhor, eles se recusam a abrir os portões. Exigiram falar com Darius, mas ele está a dois dias daqui. Devemos enviar alguém para buscá-lo?\"\n\"Não, não será necessário.\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"01NX005":["Aristocrata Carmesim","Jogar: Cause 1 de dano a um aliado e dê +1|+0 e Sobrepujar a ele.","","\"Ah, você também? Para o Baile do– \"A minha é insuportável.\" \"Então o meu pai me renegaria... Vamos usar vestidos combinando?\"","Unidade",[],["Noxus"],"COMUM"],"01NX016":["Aspirante a Trifariano","Ao me invocar, eu ganho +2|+0 se você tiver outro aliado de Noxus.","","\"Você ganhará este título quando seu machado já tiver perdido o fio no combate e suas botas estiverem ensopadas de sangue.\"\n– Veterano da Legião","Unidade",[],["Noxus"],"COMUM"],"01NX019":["Poder","Conceda +3|+0 e Sobrepujar a um aliado nesta rodada.","","\"Quando digo que sutileza é algo superestimado, não quero dizer que seja ruim. Só superestimado.\" – Darius","Feitiço",[],["Noxus"],"COMUM"],"01NX015":["Cria Preciosa","","","Ela ama todas elas, mas ama esta aqui um pouquinho mais.","Unidade",["ARANHA"],["Noxus"],"COMUM"],"01NX050":["Lótus da Morte","Cause 1 de dano a TODAS as unidades em batalha.","","\"Dance comigo!\" – Katarina","Feitiço",[],["Noxus"],"RARO (A)"],"01NX056":["Shunpo","Cause 2 de dano a um inimigo, depois Mobilize.","","Quando você reparar na lâmina, já será tarde demais.","Feitiço",[],["Noxus"],"COMUM"],"01NX033":["Avaliadora Trifariana","Ao me invocar, compre 1 por cada aliado com 5+ de Poder que você tiver.","","\"É preciso um olhar meticuloso para selecionar quem é digno de entrar na Legião Trifariana. Ela consegue distinguir claramente as ovelhas dos lobos.\" – General da Legião","Unidade",[],["Noxus"],"RARO (A)"],"01NX052":["Sangue por Sangue","Cause 1 de dano a um seguidor aliado. Se ele sobreviver, crie uma cópia dele na mão.","","A primeira aula de um hemomante é sempre a maior sujeira.","Feitiço",[],["Noxus"],"COMUM"],"01NX045":["Desafiador Selvagem","","","\"A seguir, GARRAS! Tivemos uma batalha SANGRENTA da última vez contra os Cinco Psicóticos... que agora são três. Façam suas apostas sobre a vítima de hoje! Quatro para um!\" – Karl, Agente de Apostas da Arena","Unidade",[],["Noxus"],"RARO (A)"],"01NX031":["Trifariana Ambiciosa","","","Conquistar um lugar na Legião Trifariana já basta para a maioria, mas não para todos.","Unidade",[],["Noxus"],"RARO (A)"],"01NX002":["Dizimar","Cause 4 de dano ao Nexus inimigo.","","\"Às vezes, é preciso talento estratégico para derrubar uma fortaleza. Às vezes, você só precisa bater com mais força.\"\n– Darius","Feitiço",[],["Noxus"],"RARO (A)"],"01NX008":["Basilisqueiro","Lealdade: Eu ganho +1|+1 e Sobrepujar.","","Esta unidade até usa cavalos, mas não como montaria. Eles são bons como ração.","Unidade",[],["Noxus"],"RARO (A)"],"01NX034":["Poro Carinhoso","","","\"Noxus não é lugar para... para frac... Dá pra alguém TIRAR ESSA COISA DE CIMA DE MIM?!\" – Darius","Unidade",["PORO"],["Noxus"],"COMUM"],"01NX035":["Fã Número 1 do Draven","Ao me invocar, mova Draven para o topo do seu deck caso você não o tenha na mão ou em jogo.","","\"Quer um autógrafo? E-Entra na fila!\"","Unidade",[],["Noxus"],"COMUM"],"01NX026":["Trifariano Imprudente","","","\"A imprudência é um defeito. Nas mãos da Legião, ela se torna uma ferramenta.\" – Swain","Unidade",[],["Noxus"],"COMUM"],"01NX027":["Elixir da Ira","Conceda +3|+0 a um aliado nesta rodada.","","\"Quando uma mão estendida é rejeitada, o punho se torna uma opção.\"\n– Expressão noxiana","Feitiço",[],["Noxus"],"COMUM"],"01NX022":["Guilhotina de Noxus","Abata uma unidade que tenha sofrido dano para criar 1 Guilhotina de Noxus Fugaz na mão.","","Para Darius, misericórdia é um golpe bem dado.","Feitiço",[],["Noxus"],"RARO (A)"],"01NX032":["Evocador Carmesim","Ao me invocar, cause 1 de dano a todos os outros aliados.","","\"Até se eu recusasse, vocês me arrastariam. Então... tudo bem.\"","Unidade",[],["Noxus"],"RARO (A)"],"01NX024":["Kato, o Braço","Auxiliar: Conceda +3|+0 e Sobrepujar ao meu aliado auxiliado nesta rodada.","","\"A Shiraza é uma ótima namo... digo, amiga! A gente não tá namorando. Mas se estivesse, eu desejaria um feliz aniversário de namoro. Obrigado, sem mais perguntas.\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"01NX049":["Astúcia","Atordoe um inimigo.","","\"Ofereça a corda para que os inimigos se enforquem e você se poupa do trabalho de levá-los até a forca.\" – LeBlanc","Feitiço",[],["Noxus"],"COMUM"],"01DE031":["Oradores da Alvorada","Fim de Rodada: Dê +1|+1 a outros aliados se algum aliado tiver morrido nesta rodada.","","\"Cidadãos, o mal venceu por ora, mas não prevalecerá no fim. Lembrem-se daqueles que já se foram e usem a lembrança deles como escudo!\"","Unidade",[],["Demacia"],"ÉPICO (A)"],"01DE022":["Lucian","","Vi a morte de 4+ aliados ou de uma Senna aliada.","\"Ficarei bem, Senna, enquanto tiver você comigo.\"","Unidade",[],["Demacia"],"Campeão"],"01DE019":["Mobilizando","Reduza em 1 o custo dos aliados na mão.","","\"Dos campos de treinamento ao fronte em algumas semanas. É isso o que esperamos de todos capazes de lutar em Demacia.\" – Garen","Feitiço",[],["Demacia"],"RARO (A)"],"01DE042":["Lux","","Vi você jogar 6+ de Mana em feitiços. Quando eu subir de nível, crie 1 Centelha Final na mão.","\"Eu sempre soube que havia algo diferente em mim... uma luz que vem de dentro. Não sei bem o que é, mas tenho que descobrir!\" ","Unidade",[],["Demacia"],"Campeão"],"01DE010":["Lanceiro de Rapina","Suspiro Final: Crie 1 Elite aleatória na mão.","","\"É preciso ter coragem para confiar a própria vida a uma Rapina Prateada engajada em combate e bem longe do chão. Coragem e vigor.\" – Garen","Unidade",["ELITE","AVE"],["Demacia"],"RARO (A)"],"01DE020":["Defensora da Vanguarda","","","\"Não sabíamos o que eram aquelas criaturas. Mas conhecíamos bem os rostos de nossos companheiros, e somente isso importava.\"","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE034":["Ferreiro de Batalha","Ao invocar uma carta Elite, ela ganha +1|+1.","","Guerras são vencidas na forja.","Unidade",[],["Demacia"],"RARO (A)"],"01DE002":["Tianna Stemmaguarda","Ao me invocar, Mobilize.","","\"Nossa Casa já sangrou por este reino. Você não destruirá a honra da família por uns truquezinhos de luz baratos.\"","Unidade",[],["Demacia"],"ÉPICO (A)"],"01DE012":["Garen","Ao me invocar, conceda +1|+1 aos outros aliados nesta rodada.","Golpeei duas vezes.","O treinamento e a resiliência são os pilares de um soldado. Mesmo diante de grandes perigos, nós não hesitaremos.","Unidade",["ELITE"],["Demacia"],"Campeão"],"01DE017":["Guerreiro Solitário","Se você tiver exatamente 1 aliado, dê +3|+3 a ele.","","Quando todos falham, cabe a um verdadeiro herói encontrar o caminho da vitória.","Feitiço",[],["Demacia"],"RARO (A)"],"01DE045":["Fiora","","Abati 2 inimigos.","\"Das arenas aos torneios, dos treinos ao campo de batalha, eu anseio por um adversário à altura. Não descansarei até saber que sou a melhor.\"","Unidade",[],["Demacia"],"Campeão"],"01DE052":["Formação Aciária","Ao me invocar ou Atacar: Conceda Barreira aos aliados nesta rodada.","","\"Esta formação é a base da nossa estratégia. Cada soldado deve confiar em seu escudo e nos de seus companheiros. Enquanto eles estiverem de pé, nosso reino também estará.\"\n– Garen\n","Unidade",[],["Demacia"],"ÉPICO (A)"],"01DE021":["Perseguição Implacável","Mobilize.",""," \"Todos precisam encarar seus medos. Sorte sua que estou bem aqui.\" – Lucian\n","Feitiço",[],["Demacia"],"COMUM"],"01DE025":["Deter","Um aliado Captura uma unidade.","","\"Rendam-se. Nós somos a lei e vocês, os subordinados. Simples assim.\" – Doutrinador dos Caçadores de Magos","Feitiço",[],["Demacia"],"COMUM"],"01DE007":["Julgamento","Um aliado em batalha Golpeia todos os inimigos em batalha.","","A justiça sempre cobra suas dívidas.","Feitiço",[],["Demacia"],"ÉPICO (A)"],"01DE055":["Duelista dos Laurent","Jogar: Dê Desafiador a um aliado na mão.","","\"Parecia um idiota engomadinho com uma espada cara... mas ele sabia mesmo usá-la! Eu pediria uma revanche, mas não entendi seu nome por causa daquele sotaque ridículo.\" –\nAlferes demaciano","Unidade",[],["Demacia"],"COMUM"],"01DE048":["Instigador dos Caçadores de Magos","Eu ganho +2|+2 depois que você jogar um feitiço com 6+ de custo nesta partida.","","\"Há muito tempo, a magia selvagem das Guerras Rúnicas devastou Runeterra. Nossa Ordem foi criada para proteger o reino, livrando-o de toda a magia, venha de dentro ou de fora.\" – Manual dos Caçadores de Magos","Unidade",[],["Demacia"],"RARO (A)"],"01DE001":["Porta-Estandarte da Vanguarda","Lealdade: Dê +1|+1 aos outros aliados.","","\"É preciso entender o peso que nosso estandarte carrega. Ele representa nosso rei, nossas casas, nossos cidadãos; nossa crença inabalável em Demacia. Erga-o e mostre a eles nosso orgulho.\" – Tianna Stemmaguarda","Unidade",["ELITE"],["Demacia"],"RARO (A)"],"01DE043":["Chefs de Guerra","Auxiliar: Conceda +1|+1 ao meu aliado auxiliado nesta rodada.","","Não se deve subestimar ninguém do exército demaciano.","Unidade",[],["Demacia"],"COMUM"],"01DE049":["Poro Valente","","","\"O novo recruta tem a coragem e perseverança dos nossos melhores soldados. Será que ele entrará para a Vanguarda algum dia? Ele é... menor que os outros, mas veremos.\"\n– Sargento da Vanguarda","Unidade",["PORO"],["Demacia"],"COMUM"],"01DE053":["Cavaleiro dos Laurent","Golpear: Crie na mão outro seguidor Desafiador aleatório das suas regiões.","","\"Santa paciência...\" – Fiora","Unidade",[],["Demacia"],"ÉPICO (A)"],"01DE033":["Em Memória","Eu custo 1 a menos para cada aliado que tiver morrido nesta rodada. Invoque um seguidor aleatório de Demacia com 5 de custo.","","\"Hoje, nos erguemos para corrigir as injustiças que abateram nossos companheiros. O sacrifício deles não foi em vão.\"\n– Guardiã Radiante","Feitiço",[],["Demacia"],"RARO (A)"],"01DE044":["Valor Redobrado","Cure completamente um aliado, depois dobre o Poder e a Vida dele.","","Em Demacia, ninguém afirma ser melhor que dois inimigos juntos só da boca para fora.","Feitiço",[],["Demacia"],"RARO (A)"],"01DE024":["Tutor dos Caçadores de Magos","Suspiro Final: Crie na mão um feitiço aleatório com 6+ de custo de uma região que não seja Demacia.","","\"Itens arcanos afloram uma curiosidade inegável. Mas é melhor deixá-los nas mãos competentes de nossos especialistas e longe da ignorância bem-intencionada dos cidadãos.\"\n– Manual dos Caçadores de Magos","Unidade",[],["Demacia"],"COMUM"],"01DE004":["Vanguarda de Rapinas Prateadas","Jogar: Invoque uma cópia idêntica minha.","","Elas surgiram nos céus como relâmpagos prateados: velozes e precisas mergulhando em direção ao alvo. E desapareceram tão subitamente quanto surgiram. ","Unidade",["ELITE","AVE"],["Demacia"],"COMUM"],"01DE011":["Protegido dos Laurent","","","\"Ele fez O QUÊ? Confiei a ele o inestimável sabre de Pierre de Guillard! Ele disse que só o usaria nos treinos!\" – Espadeiro dos Laurent","Unidade",[],["Demacia"],"COMUM"],"01DE047":["Sucessão","Invoque 1 Vanguarda Destemida.","","Vestimentas da Vanguarda Destemida são passadas de um soldado a outro para que novos recrutas sintam o peso e o orgulho sobre suas responsabilidades.","Feitiço",[],["Demacia"],"COMUM"],"01DE046":["Vigia da Vanguarda","","","Um lugar silencioso não é necessariamente seguro.","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE050":["Purificar","Silencie um seguidor.","","\"O Emblema Cinzento de petricita é sua maior proteção contra magia, simbolizando nossa responsabilidade e reforçando nossa autoridade. Honre-o acima de tudo.\"\n– Manual dos Caçadores de Magos","Feitiço",[],["Demacia"],"COMUM"],"01DE040":["Doutrinador dos Caçadores de Magos","Eu ganho +1|+1 e Desafiador depois que você jogar um feitiço com 6+ de custo nesta partida.","","\"Cidadãos de Demacia, é uma honra mantê-los seguros. Mas precisamos exigir seu apoio incondicional, pois mesmo dentro de nossas muralhas, os magos ainda caminham entre nós!\"\n","Unidade",[],["Demacia"],"RARO (A)"],"01DE036":["Escudeira da Vanguarda","Ao invocar uma carta Elite, reduza o meu custo em 1.","","\"Todos que conheci e as aventuras que vivi me ensinaram algo novo. Porém, quanto mais eu aprendia e ficava forte, mais percebia que ainda tinha um longo caminho...\" – Cithria, Escudeira da Vanguarda\n","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE037":["Ripostar","Conceda +3|+0 e Barreira a um aliado nesta rodada.","","\"Que previsível... Você luta como um poro!\" – Fiora","Feitiço",[],["Demacia"],"RARO (A)"],"01DE014":["Reforços","Invoque 2 Vanguardas Destemidas, depois dê +1|+1 a aliados de Elite.","","\"Nossos rivais sabem que atacar um de nós é o mesmo que atacar a todos nós.\"\n– O Código da Vanguarda\n","Feitiço",[],["Demacia"],"RARO (A)"],"01DE015":["Guardiã Radiante","Ao me invocar, eu ganho Roubo de Vida e Robusto se um aliado tiver morrido nesta rodada.","","\"Hordas de frias mãos moribundas levaram seus companheiros. Apenas ela permaneceu, um brilho de justiça cuja lâmina parecia entoar a cada golpe os nomes dos que partiram.\" – Alferes demaciano","Unidade",[],["Demacia"],"RARO (A)"],"01DE003":["Espadeiro dos Laurent","Jogar: Dê +2|+2 a um aliado.","","\"Sim, elas são lindas. Mas como qualquer instrumento delicado, elas só revelam sua verdadeira beleza nas mãos de um mestre.\" ","Unidade",[],["Demacia"],"RARO (A)"],"01DE026":["Combate Individual","Um aliado e um inimigo Golpeiam um ao outro.","","\"Guarde suas palavras. Nós falamos a língua das lâminas.\"\n– Fiora","Feitiço",[],["Demacia"],"COMUM"],"01DE032":["Barreira Prismática","Conceda Barreira a um aliado nesta rodada.","","\"Talvez o mundo te rejeite por ser diferente. Alguns dizem que as diferenças nos enfraquecem – mas, na verdade, elas nos fazem mais fortes e gentis. Mesmo nos piores momentos, eu te protegerei!\" – Lux","Feitiço",[],["Demacia"],"COMUM"],"01DE027":["En Garde","Conceda Desafiador aos aliados nesta rodada.","","\"Não há uma alma viva demaciana que recusaria uma aula de esgrima de um Laurent. Ou que sobreviveria a uma.\" – Fiora","Feitiço",[],["Demacia"],"RARO (A)"],"01DE006":["Sargento da Vanguarda","Ao me invocar, crie Por Demacia! na mão.","","\"Ele lidera nossos treinos do nascer ao pôr do sol e é o primeiro a adentrar a linha de combate. Resistente como o aço, firme como uma rocha – não poderia haver um líder melhor.\" – Alferes demaciano","Unidade",["ELITE"],["Demacia"],"RARO (A)"],"01DE038":["Senna, Sentinela da Luz","Quando vejo um Lucian aliado morrer pela primeira vez, eu ganho +1|+1 e Ataque Duplo.","","\"Sentinelas são a primeira linha de defesa entre os incansáveis mortos-vivos e os reinos humanos. Atacamos primeiro e com tudo o que temos, e NUNCA recuamos quando a vida de nossos companheiros está em jogo.\"","Unidade",[],["Demacia"],"RARO (A)"],"01DE041":["Lado a Lado","Conceda +3|+3 a 2 aliados nesta rodada.","","\"Me dá cobertura, vou avançar!\"\n\"Que engraçado, eu ia te dizer a mesma coisa.\"\n– Lorn e Dax do Batalhão Leste","Feitiço",[],["Demacia"],"RARO (A)"],"01DE035":["Por Demacia!","Conceda +3|+3 aos aliados nesta rodada.","","\"São os nossos lares, nossas famílias, nossos companheiros em combate. É o nosso orgulho, nossa honra, nossa força. Hoje, por sua defesa e existência, lutaremos bradando o seu nome: DEMACIA!\" – Sargento da Vanguarda","Feitiço",[],["Demacia"],"RARO (A)"],"01DE018":["Golpe Radiante","Conceda +1|+1 a um aliado nesta rodada.","","\"Os mortos-vivos lutam como se não houvesse amanhã. Então vamos garantir que não haja.\" – Lucian\n\n","Feitiço",[],["Demacia"],"COMUM"],"01DE009":["Protetora Aciária","Jogar: Conceda Barreira a um aliado nesta rodada.","","\"Somos uma nação próspera porque o destino de cada guerreiro tem um valor inestimável.\" – Rei Jarvan III","Unidade",[],["Demacia"],"COMUM"],"01DE039":["Cithria de Campinuvem","","","\"Todas as noites, antes de dormir, minha mãe contava histórias dos maiores heróis de Demacia enquanto afiava sua espada. Meus sonhos eram repletos de grandes aventuras... e hoje começa a minha própria história.\"","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE056":["Primeira-Espada da Vanguarda","Atacar: Eu ganho +2|+2.","","O grito de guerra ecoa. Já estou pronto para avançar. Só preciso das ordens de minha senhora para aceitar meu destino e cumprir sua vontade.","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE029":["Plumageiro Rastreador","Quando você invocar outro aliado, eu ganho Desafiador.","","Esses parentes das Rapinas Prateadas têm os instintos predatórios de seus semelhantes, mas não percebem que são muito menores.","Unidade",["AVE"],["Demacia"],"COMUM"],"01DE028":["Cavalaria da Vanguarda","","","A Vanguarda não precisa de tambores ou música para manter a sincronia na investida. Apenas o som firme e constante de cascos contra o chão.","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE013":["Cota de Malha","Dê Robusto a um aliado.","","O aço demaciano é conhecido no mundo inteiro por sua força superior; só pode ser forjado por ferreiros igualmente fortes e renomados.","Feitiço",[],["Demacia"],"COMUM"],"01DE023":["Investigadora dos Caçadores de Magos","Crie 1 Deter na mão depois de jogar um feitiço com 6+ de custo nesta partida.","","\"Perdoe a intromissão, mas precisaremos da sua cooperação total. Ficamos sabendo de alguns... 'acontecimentos estranhos'...\"","Unidade",[],["Demacia"],"COMUM"],"01DE051":["Cithria, a Audaciosa","Atacar: Conceda +1|+1 e Assustador a outros aliados atacantes nesta rodada.","","\"Contos, lendas… Nunca vi essas coisas como mera ficção, mas sim aventuras clamando por mim. Deixei Campinuvem em busca da minha própria aventura... acabei encontrando várias. E isso é só o começo.\"\n","Unidade",["ELITE"],["Demacia"],"ÉPICO (A)"],"01DE054":["Redentora da Vanguarda","Ao me invocar, compre uma unidade se um aliado tiver morrido nesta rodada.","","\"Os que já se foram serão lembrados em cada grito de guerra, cada golpe de nossas espadas e cada colisão de nossos escudos! Hoje, seremos vitoriosos!\"","Unidade",["ELITE"],["Demacia"],"COMUM"],"01DE030":["Precursora de Rapina","","","Lançaram uma chuva de flechas das paredes da fortaleza, mas nada conseguia atingir o feixe prateado disparando pelos céus. ","Unidade",["AVE"],["Demacia"],"COMUM"],"01PZ040":["Jinx","","Vejo que sua mão está vazia.","\"Qual o problema, Fishbones?\"\n\"Estou preocupado com você, Jinx! Sempre que fica entediada...\"\n\"... dá vontade de explodir alguma coisa! Ótima ideia, Fishbones!\"","Unidade",[],["Piltover e Zaun"],"Campeão"],"01PZ008":["Teemo","Golpe ao Nexus: Plante 5 Cogumelos Venenosos em cartas aleatórias do deck inimigo.","Você plantou 15+ Cogumelos Venenosos.","\"Escoteiros de Bandópolis - Regra 154: não tema o desconhecido! Regra 276: os moradores dos bosques são nossos amigos! Regra 354: se é peludo, pode ser seguro acariciar, mas não comer! Regra 417...\"","Unidade",["YORDLE"],["Bandópolis","Piltover e Zaun"],"Campeão"],"01PZ056":["Heimerdinger","Ao jogar um feitiço, crie uma Torre Fugaz com custo equivalente na mão. Ela custa 0.","Vi você invocar 12+ de Poder em aliados Tecnológicos.","\"Cientista maluco? Me poupe! Tá na cara que eu sou um cientista muito estável, só levemente desorganizado e eclético!\"","Unidade",["YORDLE"],["Bandópolis","Piltover e Zaun"],"Campeão"],"01PZ013":["Experimentador Aprimorado","Jogar: Descarte sua mão. Compre 3. Cause 3 de dano a um inimigo.","","Mesmo que seus sonhos tenham lhe custado as mãos, ele continuou acreditando. Nada ficaria em seu caminho.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ007":["Carro Alegórico","Auxiliar: Crie 4 cópias do aliado auxiliado no seu deck.","","O estrondo dos canhões atraiu multidões para a praça, ansiosas para ver o show. Depois todos passariam semanas tirando confete do cabelo.","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ018":["Prodígio da Academia","","","Como ela consegue mirar? Ótima pergunta.","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ019":["Aprendiz Dedicado","Ao me invocar, recarregue 2 de Mana de Feitiço.","","Nem todo mundo nasceu pronto para contribuir com o progresso de Piltover. Alguns precisam de orientação, por exemplo, aqueles que olham para a invenção com as lentes erradas.","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ025":["Comerciante de Cogumelos","Ao jogar um feitiço, Plante 3 Cogumelos Venenosos no deck inimigo.","","\"É do bom mesmo?\"\n\"Claro! Todos de primeira qualidade! Foram eles mesmos que disseram!\"\n\"Ok, então me d... Peraí, quê?\"\n\"Ahan! Esse aqui vai casar!\"\n\"Quantos você já usou?\"\n\"Vai casar com uma ostra!\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ048":["Corina Veraza","Jogar: Oblitere as 5 cartas no topo do seu deck para causar 1 de dano a todos os inimigos e ao Nexus inimigo por cada feitiço obliterado.","","\"Os piltovenses de mente fechada só conhecem engrenagens e sucata, não sabem apreciar a delicadeza de cada haste, pétala e célula do meu cultivar. Eles não merecem o gracioso fim que terão.\"","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ028":["Gambiarra","Ao jogar ou descartar, invoque 1 Sucatonguejo.","","Com um pouco de sucata e apenas alguns minutos, a jovem inventora recorreu a uma estranha fonte de inspiração: uma criatura que viu correndo pelos rios de uma selva distante.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ050":["Feitiço do Poder Crescente","Conceda +4|+0 e Ataque Rápido a um aliado nesta rodada.","","\"Pinica um pouco quando começa a brilhar. É normal... né?\" – Ezreal","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ054":["Bombardeiro Novato","Atacar: cause 2 de dano ao Nexus inimigo.","","\"Tem certeza?\"\n\"Não.\"\n\"Você devia ter dito que sim.\"\n\"Você não devia ter perguntado.\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ030":["Indivíduo Suspeito","Jogar: Selecione um seguidor. Me transforme em uma cópia idêntica a ele.","","\"Olá, nobres colegas Barões da Química!\"","Unidade",["YORDLE"],["Piltover e Zaun"],"RARO (A)"],"01PZ017":["Vendedor de Barris Usados","Ao me invocar, invoque 2 Barris Cáusticos.","","\"Foi o Ziel que te mandou? Eu já falei: o que é dele é dele. Não posso reembolsar algo que nunca vi antes, né? Mas recebi um lote de barris novos que até tô disposto a negociar...\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ038":["Draga do Sumidouro","Jogar: Descarte uma carta para comprar 1.","","No Sumidouro, tudo é aproveitado.","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ036":["Ezreal","Golpe ao Nexus: Crie 1 Disparo Místico Fugaz na mão.","Você alvejou inimigos 8+ vezes.","\"Óculos? Confere. Lenço? Confere. Manopla-incrível-com-recursos-mágicos-que-eu-não-entendo-totalmente? Confere, confere... e confere!\"","Unidade",[],["Piltover e Zaun"],"Campeão"],"01PZ035":["Jae Medarda","Quando me alvejarem, compre 1.","","Herdeiro do prestigioso Clã Medarda de Piltover, Jae prefere caçar artefatos antigos a administrar os negócios da família... para o desgosto do pai.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ010":["Nuvem de Cogumelos","Plante 5 Cogumelos Venenosos no deck inimigo.","","Quando o cogumelo estoura, primeiro há um baque suave. Depois, uma dor debilitante e aguda. Por fim, uma risadinha ao longe...","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ045":["Pedinte Zaunita","Jogar: Descarte uma carta para comprar 1.","","\"Esses ratos do Sumidouro que deviam cuidar uns dos outros.\"\n\"Eles preferem sentir pena de si mesmos.\"\n\"É um absurdo. Ah... Você viu minha bolsa?\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ002":["Barman do Beco","Ao me invocar, crie na mão uma carta aleatória para cada Barman do Beco que você tiver invocado nesta partida.","","\"Pois é, parceiro, o efeito é tão fraco quanto o cheiro do Sumidouro. O balde fica ali perto do vitrolex.\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ004":["Barragem Incendiária","Cause 3 de dano a uma unidade ou Nexus inimigo, 2 a outra e 1 a outra.","","\"Quando você tem talento, não tem essa história de tiro de sorte.\"\n– Ezreal","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ020":["Poro Audacioso","","","Seu primeiro lançamento foi puro acidente: escorregou e caiu dentro do canhão do Dia do Progresso enquanto se arrumava. Agora é o orgulho de Piltover, voando pelos céus para o deleite de todos.","Unidade",["PORO"],["Piltover e Zaun"],"COMUM"],"01PZ046":["Cópias Falsificadas","Selecione uma carta na mão. Crie 4 cópias idênticas no seu deck.","","A imitação é a forma mais sincera de roubo.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"01PZ052":["Disparo Místico","Cause 2 de dano a qualquer coisa.","","\"Eu NUNCA erro. Mas às vezes eu dou uns tiros de aviso...\"\n– Ezreal","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ033":["Buscando a Purrrfeição","Se você tiver jogado 20 cartas novas nesta partida, invoque Gatástrofe.","","\"No fim, todos que colaboraram com o projeto de von Yipp foram enganados. Não sabíamos detalhes do projeto... a monstruosidade que estávamos criando.\" – Engenheiro de projeto piltovense","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ005":["Transmogulador Hextec","Transforme um seguidor em uma cópia idêntica a outro seguidor.","","\"VOCÊ VIVIA DIZENDO QUE QUERIA PERDER PESO.\"\n\"MAS PRECISAVA ME TRANSFORMAR EM UM YORDLE?!\"\n\"MAS VOCÊ PERDEU PESO!\"\n\"... MAS EU VIREI UM YORDLE!\"","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"01PZ021":["Capangas de Midenstokke","Golpe ao Nexus: Invoque uma cópia idêntica a mim.","","\"Sr. Berz, achamos o senhor dormindo DENTRO do cofre, coberto de engrenagens de ouro e segurando a porta quebrada.\"\n\"Não era eu. Era só alguém parecido comigo.\"\n\"O senhor continua segurando a porta.\"\n\"Prove.\"","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ031":["Choque de Statikk","Cause 1 de dano a um inimigo ou ao Nexus inimigo e 1 de dano a outro inimigo.\nCompre 1.","","\"E foi assim que descobrimos a descarga de arco! Claro, meu predecessor havia imaginado essa hipótese, mas subestimou o alcance do arco. Pobre coitado...\" – Heimerdinger","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"01PZ059":["Esmagobô Dourado","","","MATAR. ESMAGAR. DESTRUIR. REPETIR.","Unidade",["TECNOLÓGICO"],["Piltover e Zaun"],"COMUM"],"01PZ001":["Remexida","Para jogar, descarte até 2 cartas. Compre 1 para cada carta que você descartou.","","\"Caraaaamba! CINCO EXECUTORES E UM GOLEM? Calmaê! Tenho uma coisinha que ajuda! Só preciso achar...\"\n– Jinx","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ057":["Montagem de Sucata","Invoque 2 Sucatonguejos.","","Duas criaturas adoráveis, antes separadas por uma faixa de terra intransponível, finalmente se encontraram nas águas mornas do Sumidouro.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ027":["Raio Termogênico","Para pôr em jogo, gaste todo o seu Mana.\nCause o mesmo valor de dano a uma unidade.","","\"Já esgotamos nosso tempo e nossos recursos e, embora o raio funcione, não conseguimos controlar o consumo de energia.\" – Experimentador zaunita","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"01PZ055":["Acadêmica Astuta","Ao comprar uma carta, me conceda +1|+0 nesta rodada.","","A imaginação é a faísca das grandes invenções. Mas é a pesquisa que transforma a faísca em uma fogueira.","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ014":["Inovação Não Licenciada","Invoque 1 Engenhoca Ilegal.","","\"Os contratempos são dos mais variados: tremores de explosões, vapores pútridos saindo das fissuras... Logo um desses imbecis vai explodir nossa cidade.\" – Filantropo piltovense","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ034":["Catador do Sumidouro","Lealdade: Crie 1 Mapa do Sumidouro na mão. Custa 0 nesta rodada.","","As crianças zaunitas logo começaram a explorar os antigos túneis de mineração e os níveis mais profundos das Vielas. Encontraram um mundo surpreendente, e amigos incríveis.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ003":["Robô de Montagem","Quando você joga um feitiço, eu ganho +1|+1.","","\"Qualquer zé-ninguém pode construir uma máquina, mas só um intelecto superior seria capaz de infundir o VERDADEIRO progresso em um cérebro mecanizado! Logo aqueles burocratas nojentos voltarão rastejando...\" – Klas Henwick","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ044":["Detonador Quimiopunk","Jogar: Cause 1 de dano a todos os inimigos.","","\"... seu solo rapidamente mergulha em uma escala menor harmônica antes de arpejar – sim, isso é uma palavra – na transposição da ponte. Você não entenderia a obra dele.\"\n– Max Bliff, guarda do portão","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ029":["Benfeitor Ilustre","Jogar: Manifeste uma carta Épica das suas regiões.","","\"Eu era um homem raivoso, que destruía a concorrência para ganhar dinheiro e fama. Agora, eu invisto minha fortuna no altruísmo e espero que minha penitência me absolva dos meus erros.\"","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ051":["Malucânica","Todos os seus feitiços e Habilidades causam 1 de dano adicional.","","\"Você quer ser um verdadeiro estouro? Veio ao lugar certo!\"","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ023":["Professor Von Yipp","Ao invocar um aliado com 1 de custo, dê +2|+2 a ele.","","\"Hoje eu apresento ao comitê minha mais nova invenção, demonstrada pelo meu estimado colega...\"","Unidade",["FELINO"],["Piltover e Zaun"],"RARO (A)"],"01PZ024":["Volticista Instável","Eu ganho +4|+0 e Ataque Rápido depois que você jogar um feitiço com 6+ de custo nesta partida.","","Nome: Klas Henwick | Idade: 51 | Licença: Condicional de Classe 2 | Situação: Revogada | Obs.: Ignorou repetidos avisos para reduzir a potência após explosão do laboratório (Caso 13X764NM). ENTRADA PROIBIDA.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ049":["Dia do Progresso!","Compre 3 cartas e reduza o custo delas em 1.","","DIA DO PROGRESSO!\nCelebre na PRAÇA DOS PORTÕES SOLARES!\nConfira INVENÇÕES HEXTEC!\nSurpreenda-se com o PORO AUDACIOSO!\nEscute o HOMEM DO AMANHÃ sobre a SITUAÇÃO DE HOJE!\nGRATUITO! \nPara toda família piltovense!","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"01PZ006":["Guardião da Praça","Eu custo 1 a menos para cada feitiço que você tiver jogado nesta partida.","","Você tem vinte segundos para cooperar.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ053":["Bando de Raxinins","Ao me invocar, crie Nuvem de Cogumelos na mão.","","\"Isso mesmo! Um bando inteiro se esgueirando por aí! Eles PARECEM loucos, mas sei que estão planejando alguma coisa! Cogumelos. Queijo... sorvete. Do que eu tava falando?\"\n– Comerciante de Cogumelos","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ012":["Mordidinha Flamejante!","Ao me descartar, me invoque.","","\"PEGUEM ELES, MORDIDINHAS!\" – Jinx","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ039":["Anime-se!","Para pôr em jogo, descarte 1.\nCause 3 de dano a qualquer coisa.","","\"FOGO EM GERAL!\" – Jinx","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"01PZ016":["Faísca de Genialidade","Crie na mão um feitiço aleatório das suas regiões com 6+ de custo.\nRecarregue seu Mana de Feitiço.","","Uma única epifania é suficiente para criar um legado.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ058":["Raxinim Grandona","Ao me invocar, crie 2 Nuvens de Cogumelos na mão.","","\"Vi uma grandona, aham! Ela é pesada como um cavalo e astuta como um krugue. Tem que ficar de olho naquela espertinha. Não é à toa que é a rainha deles!\"\n– Comerciante de Cogumelos","Unidade",["YORDLE"],["Piltover e Zaun"],"RARO (A)"],"01PZ009":["Aeronauta Amador","","","\"Máquinas voadoras particulares? Nada mais que um sonho infantil! Na verdade, acabei de mandar meu pupilo jogar o último protótipo no lixo. Cadê ele mesmo?\" – Engenheiro piltovense","Unidade",[],["Piltover e Zaun"],"COMUM"],"01PZ042":["Marinheira Intrépida","Auxiliar: Conceda Elusivo ao meu aliado auxiliado nesta rodada.","","Muitos piltovenses exploram o desconhecido por meio da ciência na segurança da Cidade do Progresso. Já outros preferem embarcar rumo ao horizonte e desvendar um mistério bem maior: o mundo.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ026":["Mapa do Sumidouro","Dê Elusivo a um aliado.","","\n\"Os piltovenses acham que sabem tudo, mas os mapas só mostram o que a gente conta! Só quem é daqui conhece mesmo o lugar. E você também pode... por um preço.\"\n– Ajuna Lem, Catador do Sumidouro","Feitiço",[],["Piltover e Zaun"],"COMUM"],"01PZ043":["Ladrão Quimiopunk","Golpe ao Nexus: Crie na mão uma cópia idêntica de um feitiço aleatório do deck inimigo.","","A Cidade do Progresso esperava que os excluídos se voltassem uns contra os outros. Em vez disso, eles se uniram, se reergueram e criaram um novo lar. Não era muito, mas era deles. Zaun.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"01PZ047":["Barril Cáustico","Suspiro Final: Cause 1 de dano aos DOIS Nexus.","","\"Eu te diria pra usar um traje... se lá embaixo não fosse abafado igual sovaco de raxinim. Mas pode usar luvas. E reza pra gosma não cair em nada importante.\" – Ziel, capataz zaunita","Unidade",[],["Piltover e Zaun"],"COMUM"],"01FR024":["Anivia","Atacar: Cause 1 de dano a todos os inimigos e ao Nexus inimigo.\nSuspiro Final: Eu ressuscito e me transformo em Ovonivia.","Você está Iluminado.","\"Como filha desta terra hostil, meu dever é protegê-la. Nem o tempo, nem a guerra, nem mesmo a morte impedirá minha vigília.\"","Unidade",["AVE"],["Freljord"],"Campeão"],"01FR039":["Tryndamere","","Em vez de morrer, eu subo de nível.","\"Não morra pela causa. Viva por ela...\"","Unidade",[],["Freljord"],"Campeão"],"01FR006":["Legado Glacinata","Dê +2|+2 a um aliado e a todas as cópias aliadas dele globalmente.","","\"Somos glacinatas, cuja linhagem carrega a magia de Freljord. Nossos ancestrais selaram um mal antigo e cabe a nós, os poucos que restaram, manter vigilância contra seu retorno.\" – Gregor, o Guardião","Feitiço",[],["Freljord"],"COMUM"],"01FR022":["Falcão dos Presságios","Ao me invocar, dê +1|+1 aos 2 aliados no topo do seu deck.","","\"Nossos rapinadores chegaram aos portões avarosianos três vezes... e três vezes foram recebidos por arcos e flechas. Que tipo de bruxaria os avisa de nossos ataques?\" – Steffen, Tano das Cicatrizes","Unidade",["AVE"],["Freljord"],"COMUM"],"01FR042":["Ventos Rigorosos","Congele 2 inimigos.","","\"Vai me desafiar nas minhas próprias terras? Mas que criaturinha despreparada.\" – Anivia","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"01FR009":["Braum","Quando eu sobreviver a dano pela primeira vez, invoque 1 Poro Poderoso.","Sobrevivi a 10+ de dano no total.","\"Papai, conta aquela do Braum e da porta!\"\n\"Ou quando ele caiu e dividiu uma montanha em duas!\"\n\"Ah! E aquela vez que ele salvou a taverna de um yeti furioso!\"","Unidade",[],["Freljord"],"Campeão"],"01FR018":["Lobo das Glacipresas","Golpear: Se eu golpear uma unidade com 0 de Poder, eu a abato.","","Os predadores das terras nortenhas descobriram que as presas mais fáceis são aquelas já incapacitadas pelo frio do inverno.","Unidade",["CANINO"],["Freljord"],"RARO (A)"],"01FR036":["Atirador Avarosiano","Jogar: Cause 1 de dano a um inimigo.","","Em Freljord, ou você caça ou morre de fome.","Unidade",[],["Freljord"],"COMUM"],"01FR045":["Steffen, Tano das Cicatrizes","Quando eu sobreviver a dano, ganho +3|+0.","","\"Selei meu juramento à Garra do Inverno quando Sejuani me deu minha primeira cicatriz. Desde então, todas as minhas cicatrizes foram conquistadas a serviço dela.\"","Unidade",[],["Freljord"],"COMUM"],"01FR008":["Poro Solitário","Ao me invocar, crie na mão outro Poro aleatório com 1 de custo.","","\"Passei a vida inteira em Freljord e, mesmo assim, nada me abalou mais do que encontrar esse coitadinho.\" – Pastor de Poros","Unidade",["PORO"],["Freljord"],"COMUM"],"01FR055":["Estraçalhar","Cause 4 de dano a um inimigo se ele tiver 0 de Poder. Caso contrário, Congele o inimigo.","","\"Quando o inverno chega, ele abranda os fortes e derruba os fracos.\" – Steffen, Tano das Cicatrizes","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"01FR038":["Ashe","Atacar: Congele o inimigo Mais Forte.","Você reduziu o Poder de 5+ inimigos a 0. Quando eu subir de nível, crie 1 Flecha de Cristal no topo do deck.","\"Quando olho para minha terra, eu vejo o que ela é, mas vejo também o que poderia ser. Próspera e abundante, não apenas para o meu povo, mas para todos que buscam a paz. Uma Freljord unida.\"","Unidade",[],["Freljord"],"Campeão"],"01FR029":["Súplica","Compre um Campeão.","","\"Rapinadores se aproximando! Soem o alarme e acendam as tochas, precisamos de toda a ajuda possível!\" – Vigilante Avarosiano","Feitiço",[],["Freljord"],"RARO (A)"],"01FR035":["Rapinadora Incólume","Quando eu sobreviver a dano, ganho +3|+0.","","\"Os avarosianos criam seus filhos de forma que envelhecem despreparados para o calor da batalha. Os nossos já nascem no fogo da própria guerra.\" – Vrynna, Mãe das Cicatrizes\n","Unidade",[],["Freljord"],"COMUM"],"01FR020":["Avalanche","Cause 2 de dano a TODAS as unidades.","","A alma de toda avalanche é uma pequena rocha que não conseguiu parar quieta.","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"01FR014":["Filhote de Yeti","Suspiro Final: Crie 2 Yetis Enfurecidos no seu deck.","","\"Ele era tão pequeno e tranquilo! É difícil acreditar que cresceria e se tornaria... bem... um yeti.\" – Armadilheiro avarosiano","Unidade",["YETI"],["Freljord"],"COMUM"],"01FR049":["Lobo Espreitador","Ao me invocar, seu oponente invoca 1 Lebre da Neve.","","\"Quem nasceu lebre, nunca será lobo.\"\n– Provérbio da Garra do Inverno","Unidade",["CANINO"],["Freljord"],"COMUM"],"01FR037":["Batedores Avarosianos","Lealdade: Dê +3|+3 e Sobrepujar ao aliado no topo do seu deck.","","Quando as fileiras de reforços apareceram no cume, os Batedores se curvaram perante a mãe de guerra, pois a rainha Ashe, sua Avarosa encarnada, trazia a promessa de paz.","Unidade",[],["Freljord"],"RARO (A)"],"01FR026":["Garreroz Alfa","","","O vigor de um cavalo de guerra aliado à selvageria imprudente de um gato.","Unidade",["FELINO"],["Freljord"],"COMUM"],"01FR030":["Aço Quebradiço","Congele um inimigo com 3 ou menos de Vida.","","\"Frio? Haha! Espero que seus espíritos sejam mais resistentes do que esse aço de verão!\" – Braum","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"01FR013":["Vrynna, Mãe das Cicatrizes","Quando eu sobreviver a dano, ganho +3|+0.","","\"Prefiro morrer tremendo de frio a dividir uma lareira com os seguidores fracotes da Ashe. Mas se é calor que eles querem, é isso que terão.\"","Unidade",[],["Freljord"],"ÉPICO (A)"],"01FR019":["Sopro Invernal","Abata todos os inimigos com 0 de Poder, depois Congele todos os inimigos.","","O inverno é a primeira e última Mãe de Guerra encarada por quem tenta invadir Freljord. Seus Jurados de Sangue são o vento impiedoso e o gelo implacável.","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"01FR041":["Guarda Termestre Avarosiano ","Ao me invocar, dê +1|+1 aos aliados no seu deck.","","\"Muitas tribos sob uma só bandeira! Talvez um dia Freljord inteira lute lado a lado.\"","Unidade",[],["Freljord"],"ÉPICO (A)"],"01FR025":["Pastor de Poros","Ao me invocar, compre um Poro se você Contemplar um Poro.","","Um rebanho só precisa de duas coisas: amor e companhia. O resto vem sozinho.\n","Unidade",[],["Freljord"],"RARO (A)"],"01FR054":["Rapinadora Cicatrizela","","","\"Os fracos fazem a colheita, os fortes levam os frutos. Esses vermes avarosianos descobrirão o seu papel!\"","Unidade",[],["Freljord"],"RARO (A)"],"01FR021":["Tarkaz, o Desgarrado","Atacar: Cause 1 de dano a TODAS as unidades em batalha.","","\"Tarkaz lutou mais e melhor do que a maioria. Acho que ele aceitou bem a derrota. Bom, mais ou menos...\"\n– Tryndamere","Unidade",[],["Freljord"],"ÉPICO (A)"],"01FR043":["Coração da Fofuteia","Jogar: Combine seus seguidores Poros em 1 carta Fofuteia de Poros e dê a ela os atributos e palavras-chave positivas deles.","","\"Só mais uma historinha, mas silêncio para a mamãe não dar bronca!\"\n\"Há muito tempo, saqueadores atacaram a aldeia de Avarosa. Os aldeões eram poucos e pareciam perdidos, mas um poro apareceu para ajudar...\"","Unidade",["PORO"],["Freljord"],"RARO (A)"],"01FR033":["Pedras Destinadas","Início de Rodada: Ganhe uma gema de Mana adicional nesta rodada.","","\"Esses pilares de pedras ancestrais são lembretes de que somos os filhos de uma longa linhagem de tribos a enfrentar essas terras indomáveis\" – Ashe","Unidade",[],["Freljord"],"COMUM"],"01FR011":["Arqueiro do Vale de Gelo","Jogar: Congele um inimigo.","","Avarosianos têm orgulho de suas estações rigorosas e terras geladas. Seus perspicazes defensores demonstram isso.","Unidade",[],["Freljord"],"COMUM"],"01FR050":["Taverneiro Gentil","Jogar: Cure um aliado ou o seu Nexus em 3.","","\"Este simpático estabelecimento é o Coruja Embriagada! Temos ensopados e bebidas para espantar o frio. Pode entrar!\"","Unidade",[],["Freljord"],"COMUM"],"01FR052":["Aquela que Vaga","Jogar: Oblitere TODAS as unidades com 4 ou menos de Poder em jogo e nas mãos.","","\"Eu saí dos escombros e vi uma grande cauterização na terra ao meu redor. Em vez dos meus companheiros, havia cinzas fumegantes, e um vulto assombroso se movia ao longe...\"\n– Bjerg, o Andarilho","Unidade",[],["Freljord"],"ÉPICO (A)"],"01FR016":["Poritos","Dê +1|+1 a Poros aliados globalmente.","","\"Eles comem tudo e depois olham para você, com a linguinha para fora, felizes como Elnuks tosquiados no verão, pedindo mais! Quem teria coragem de negar?\" – Confeiteiro avarosiano","Feitiço",[],["Freljord"],"COMUM"],"01FR005":["Fúria da Batalha","Dê +8|+4 a um aliado.","","\"Já me disseram que tenho... pavio curto.\" – Tryndamere","Feitiço",[],["Freljord"],"RARO (A)"],"01FR023":["Chamado da Mãe de Guerra","Invoque o aliado no topo do seu deck agora e a CADA Início de Rodada.","","Chegará o dia em que um chamado inconfundível ressoará por Freljord. Nesse dia, todos se levantarão para responder, pois será o anúncio de que nossos antigos inimigos retornaram.","Feitiço",[],["Freljord"],"ÉPICO (A)"],"01FR047":["Místico Selvagem","Iluminado: Tenho +4|+4.","","\"Aqueles que aprendem a rugir feito animais acabam esquecendo sua língua nativa.\" – Anivia","Unidade",[],["Freljord"],"COMUM"],"01FR056":["Yeti Gélido","Ao me invocar, Congele inimigos com 3 ou menos de Vida.","","\"AaaaaaaAAaaaAaaaaah!\" – Bjerg, o Andarilho","Unidade",["YETI"],["Freljord"],"RARO (A)"],"01FR027":["Elnuk Bovino","","","Os contos populares avarosianos falam do \"Velho Tio Elnuk\", um senhorzinho rabugento e teimoso que só queria um pedacinho de grama e uma discussão para enfiar o pé na lama.","Unidade",["ELNUK"],["Freljord"],"COMUM"],"01FR057":["Mentalidade de Bando","Conceda +2|+2 e Sobrepujar aos aliados nesta rodada.","","Um uivo solitário ecoou pela noite, seguido por outro, e mais outro. Em instantes, o bando uivou em uníssono – um coro de vozes frenéticas clamando por sangue.","Feitiço",[],["Freljord"],"RARO (A)"],"01FR004":["Elixir de Ferro","Conceda +0|+2 a um aliado nesta rodada.","","\"A coisa tá feia lá fora, né? Não se preocupe! O Coruja serve uma bebida especial tão forte que descongela até os ossos!\"\n– Taverneiro Gentil","Feitiço",[],["Freljord"],"COMUM"],"01FR048":["Armadilheiro Avarosiano","Ao me invocar, crie 1 Yeti Enfurecido nas 3 cartas no topo do seu deck.","","\"Não peguei nada a semana inteira! Ou as feras ficaram mais espertas, ou tem alguma coisa afugentando tudo...\"","Unidade",[],["Freljord"],"COMUM"],"01FR017":["Tropa de Elnuks","Jogar: Das 6 cartas no topo do seu deck, invoque todos os Elnuks e coloque o resto no seu deck.","","\"Avarosianos são como Elnuks – comedores de grama com olhos sem vida, facilmente abatidos até por um guerreiro sem cicatrizes. Por isso só sobrevivem em bandos.\" – Vrynna, Mãe das Cicatrizes","Unidade",["ELNUK"],["Freljord"],"COMUM"],"01FR046":["Tenha Coragem","Dê +3|+3 a um aliado que tenha sofrido dano.","","\"Embora gravemente ferido, Braum arqueou a cabeça para trás e deu uma grande gargalhada. Ele sabia que tempos difíceis sempre dão origem a heróis!\"\n– O Conto de Braum","Feitiço",[],["Freljord"],"RARO (A)"],"01FR012":["Catalisador das Eras","Receba uma gema de Mana vazia e cure seu Nexus em 3.","","Rubis e safiras nem chegam perto do brilho da pedra das eras – uma gema brilhante com propriedades revitalizantes lendárias. ","Feitiço",[],["Freljord"],"COMUM"],"01FR040":["Xamã das Glacipresas","Início de Rodada: Congele o inimigo Mais Forte.","","\"Para entrar em comunhão com a natureza, o segredo é não se esconder do frio, mas sim apreciar sua brutalidade.\"","Unidade",[],["Freljord"],"RARO (A)"],"01FR031":["Yeti Ancestral","Fim de Rodada: Reduza meu custo em 1.","","\"O que foi isso? Parecia um espirro. Geleiras... espirram?\"\n– Bjerg, o Andarilho","Unidade",["YETI"],["Freljord"],"RARO (A)"],"01FR053":["Poro Poderoso","","","\"Meu parceiro aqui perdeu um olho defendendo o Rei Poro de um Garreroz gigantesco! Afinal, não é o tamanho do martelo, mas o tamanho do coração que importa.\" – Pastor de Poros\n","Unidade",["PORO"],["Freljord"],"COMUM"],"01FR010":["Pacto dos Jurados de Sangue","Dê +0|+3 a 2 aliados.","","\"Serei a tocha em seu coração, o seu escudo de proteção. Sempre encontrarei força para proteger nossos semelhantes, e nossas vidas fluirão juntas com este pacto de sangue.\"\n– Tryndamere","Feitiço",[],["Freljord"],"RARO (A)"],"01FR001":["Lampejo Congelado","Congele um inimigo.","","O frio ataca sem aviso, desamparando até os mais poderosos guerreiros.","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"01FR032":["Vidente Constelado","Ao jogar um feitiço, dê +1|+1 ao aliado no topo do seu deck.","","\"Que eles tenham ouvidos apurados para escutar a chegada do vento, pés leves para atravessar as nevascas iminentes e olhos penetrantes para enxergar além do véu do inverno.\"","Unidade",[],["Freljord"],"RARO (A)"],"01FR051":["Contos Fantásticos","Se você tiver um Yeti, invoque 1 Yeti Enfurecido. Caso contrário, crie um no topo do seu deck.","","\"... e esse aqui tem uma boca cheia de dentes grandes e tortos, uns brações bem fortes, um olhar zangado e um RUGIDO BEEEEEM ALTO, DE CAIR AS ÁRVORES! Foi o tio Bjerg que me disse!\" – Ingvar, a Jovem","Feitiço",[],["Freljord"],"COMUM"],"01FR034":["Aqueles que Perduram","Ao me invocar, eu ganho +1|+1 para cada aliado que tiver morrido.","","\"Ah, o velho Bjerg já viu de tudo um pouco. Perdeu sua tripulação no norte, voltou completamente desorientado meses depois. Agora só fala em feras gigantes e garras enormes. Coitado...\" – Taverneiro Gentil","Unidade",[],["Freljord"],"RARO (A)"],"01FR007":["Bjerg Balbuciador","Ao me invocar, compre uma unidade com 5+ de Poder.","","\"V-Você tem que acreditar em mim! Era enorme! Sério mesmo, ENOOORME!\"","Unidade",[],["Freljord"],"COMUM"],"01FR003":["Vigilante Avarosiano","Suspiro Final: Compre 1.","","\"Já procurei meu lugar em campos de batalha distantes. Agora, encontrei-o em minha terra natal. Meus olhos servem ao povo, e a segurança de todos está em minhas mãos.\"","Unidade",[],["Freljord"],"COMUM"],"01SI038":["Fantasma Travessa","Quando outro aliado morrer, cause 1 de dano ao Nexus inimigo.","","Massacrar os soldados que acreditaram no choro de uma garotinha não foi sua travessura mais cruel: foi plantar a dúvida nos sobreviventes para que ignorassem o choro das próprias filhas...","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI049":["Vislumbre do Além","Abata um aliado para comprar 2.","","\"Cometi um erro. Não devíamos ter espiado além da bruma pálida. Seja qual for a verdade que existe lá, não vale o preço para descobri-la.\" – Arie Wrence, Vindicador Destemido","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI053":["Elise","Atacar: Invoque 1 Cria Aracnídea atacante.","Início de Rodada: Você tem 3+ Aranhas adicionais.","Antiga líder de uma das casas mais poderosas de Noxus, Elise se associou às Ilhas das Sombras para manter sua beleza e juventude em troca de algumas pobres almas. Decisão fácil.","Unidade",["ARANHA"],["Ilhas das Sombras"],"Campeão"],"01SI057":["Crocólito Ancestral","Para me pôr em jogo, abata 2 aliados.","","\"Coloque-os na gaiola, tum-ta-dum... \nArranque as almas deles, um por um...\nNão os deixe ir, não, senhor!\nE os outros espíritos tremem de pavor...\"","Unidade",["RÉPTIL"],["Ilhas das Sombras"],"RARO (A)"],"01SI023":["Pastora de Almas","Ao invocar um aliado Efêmero, dê +1|+1 a ele.","","Apenas os caídos sabiam que ela não andava só. Apenas eles conseguiam enxergar os inúmeros companheiros que ela guiava para terras longínquas.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI010":["Massacre das Sombras","Invoque 2 Cavaleiros Espectrais.","","Agora, vivem exatamente como morreram: leais até o último suspiro.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI042":["Hecarim","Atacar: Invoque 2 Cavaleiros Espectrais atacantes.","Você atacou com 7+ aliados Efêmeros.","Isso não é um trovão. A Sombra da Guerra se aproxima.","Unidade",[],["Ilhas das Sombras"],"Campeão"],"01SI027":["Oferendas Frescas","Se 3+ aliados tiverem morrido nesta rodada, invoque Maldíbula.","","\"Ajoelhe-se perante seu deus de presas. Ou melhor, morra diante dele.\" – Elise","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI048":["Guardião Amaldiçoado","Suspiro Final: Invoque 1 Aberração Liberta.","","Loucura e tempo. Não há dupla mais impiedosa.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI018":["Escriba das Lamentações","Ao me invocar, crie na mão a cópia de um aliado que tiver morrido nesta partida.","","\"E nosso autor mal sabia que logo a Ruína... a Ruína... não, não, não, droga, a tinta vazou de novo! E nosso autor... não, não, não!\"","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI030":["Kalista","","Vi 3+ aliados morrerem.","Em vida, ela foi uma general, uma protetora, uma heroína. Mas com a perda do corpo, não restou nada dela além das chamas ardentes da retaliação – um espírito vingativo incapaz de morrer.","Unidade",[],["Ilhas das Sombras"],"Campeão"],"01SI035":["Rhasa, o Ruptor","Jogar: Abata os 2 inimigos Mais Fracos se um aliado tiver morrido nesta rodada.","","\"Disseram que... seria a jornada de uma lenda. Deveríamos proteger... o futuro de Demacia. Velejamos com tanta esperança. Mas tudo... todas aquelas vidas... para quê?\"\n– Arie Wrence, soldado demaciano","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI005":["Crustageist","Eu custo 1 a menos para cada aliado que tiver morrido nesta partida.","","Este monstro já foi a calamidade de um reino há muito tempo esquecido. Agora, ele vasculha campos de batalha abandonados, adicionando restos à sua carapaça e almas ao seu âmago.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI037":["Poro Sinistro","","","Bom, existem jeitos piores de morrer.","Unidade",["PORO"],["Ilhas das Sombras"],"COMUM"],"01SI052":["Thresh","","Vi 6+ unidades morrerem.","\"Clink, clenk, lá vêm as correntes trazendo a sua sina...\nClink, clenk, com suas correntes, o Guardião se aproxima...\"","Unidade",[],["Ilhas das Sombras"],"Campeão"],"01SI033":["Comandante Ledros","Jogar: Cause dano ao Nexus inimigo equivalente à metade da Vida dele. O dano causado é arredondado para cima. Suspiro Final: Me retorne para a mão.","","A maioria dos espíritos se perde com o passar do tempo e o desgaste de suas memórias. Mas a angústia deixou Ledros ancorado ao passado. Há coisas que nem o tempo consegue dissipar.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI003":["O Tormento","Ressuscite os 6 aliados Mais Fortes que morreram nesta partida e dê Efêmero a eles.","","Certas noites, espíritos famintos se aglomeram na Névoa Negra. Eles são carregados pelos mares para caçar os vivos, alimentando as trevas crescentes com novos mortos-vivos.","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI041":["O Imortal","Suspiro Final: Me ressuscite no próximo Início de Rodada e me dê +1|+1 por cada vez que eu tiver morrido.","","O velho mártir se lembrava de ter levado seus companheiros diretamente para a morte. Porém, há muitos anos não consegue lembrar o por quê...","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI045":["Absorção de Alma","Drene 4 de um aliado.","","\"O que te mata só me deixa mais forte.\" – Thresh","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI036":["Sensação Rastejante","Se um aliado tiver morrido nesta rodada, invoque 2 Crias Aracnídeas.","","Aquela sensação agoniante por cima da pele não é nada perto da sensação por baixo dela.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI051":["Prodígio Atormentado","Quando outro aliado morrer ou usar Suspiro Final: Recarregue seu Mana de Feitiço.","","Trabalhava noite e dia aperfeiçoando sua composição. Então, em um piscar de olhos, um silêncio sombrio passou por ele. Outros gritaram e fugiram para se salvar. Mas ele não percebeu nada.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI012":["Pescador Distraído","Jogar: Dê Efêmero a um aliado na mão e reduza o custo dele em 1.","","Ah, pobre rapaz...","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI031":["Precursor de Ferro","Atacar: Eu ganho +1|+0 por cada aliado Efêmero que você tiver.","","Na morte, assim como em vida, ele grita seus comandos deturpados e malignos. Na morte, assim como em vida, os cavaleiros leais de Hecarim respondem, avançando para iniciar o massacre.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI034":["Lança Negra","Se um aliado tiver morrido nesta rodada, cause 4 de dano a uma unidade.","","\"Nossa lança brada pelos caídos.\" – Kalista","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI043":["Aristocrata Azarado","Suspiro Final: Invoque 1 Cria Aracnídea.","","\"S-Senhora Elise? A-Aonde você foi?\"","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI009":["Espíritos Agitados","Auxiliar: Dê +2|+0 e Efêmero ao meu aliado auxiliado.","","Diante da Ruína, alguns enxergam apenas destruição e sofrimento. Outros veem uma oportunidade.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI007":["Relíquia Assombrada","Invoque 3 Espíritos Libertados.","","Estes artefatos antigos são estimados tanto pelos vivos, ávidos por tomá-los, quanto pelos mortos, desesperados para mantê-los em seu poder.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI056":["Predadora Desenfreada","Ao me invocar, conceda +1|+0 a outras Aranhas aliadas e -1|-0 aos inimigos nesta rodada.","","\"Elas fazem uma teia do tamanho de um homem em menos de um minuto... Quer uma demonstração?\" – Elise","Unidade",["ARANHA"],["Ilhas das Sombras"],"RARO (A)"],"01SI001":["Vingança","Abata uma unidade.","","Os traídos invocam Kalista no momento da morte, esperando que a lança dela traga a vingança.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI019":["A Caixa","Cause 3 de dano a cada inimigo que foi invocado nesta rodada.","","\"Ninguém escapa.\" – Thresh","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI011":["Açougueiro Voraz","Para me pôr em jogo, abata um aliado.","","Você é o que você come.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI014":["Espectro da Névoa","Ao me invocar, dê +1|+0 aos Espectros da Névoa aliados globalmente.","","Esses espectros das Ilhas perderam a identidade, transformando-se em um amálgama de fome pura e insaciável.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI022":["Marca das Ilhas","Dê +2|+2 e Efêmero a um aliado.","","Poder, mas a que preço?","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI006":["Possessão","Roube um seguidor inimigo nesta rodada (não pode jogar se já tiver 6 aliados ou Monumentos).","","Quando ele acordou, deparou-se com suas mãos encharcadas de sangue e o acampamento estranhamente silencioso. ","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI028":["Alma Dividida","Invoque uma cópia idêntica a um aliado. Ela é Efêmera e 1|1.","","\"Tirei o corpo da água para identificar o pobre coitado. Quando coloquei a mão no ombro dele, a cabeça se virou e mostrou o rosto. Era... eu?\" – Arie Wrence, soldado demaciano","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI025":["Atrocidade","Abata um aliado para causar dano equivalente ao Poder dele a qualquer coisa.","","O ato de matar não significa nada para aqueles que não podem morrer.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI046":["Chamado da Névoa","Ressuscite um aliado aleatório que tiver morrido nesta rodada.","","\"A Névoa separa os espíritos dos corpos, deixando para trás uma paródia cruel da vida. Já a vi corromper minhas terras, mas hoje vou àquelas ilhas pôr um fim nisso.\" – Arie Wrence, vindicador destemido","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI050":["Despertar da Ninhada","Invoque 3 Crias Aracnídeas, depois dê +1|+0 a Aranhas aliadas.","","Elas nascem mais famintas do que nunca.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"01SI016":["Evocadora de Espectros","Lealdade: Invoque 1 Espectro da Névoa.","","Ela aparece sem fazer som algum, mas os horrores que traz consigo são bem menos sutis.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI021":["Carruagem de Tubarões","Suspiro Final: Na próxima vez que um aliado Efêmero atacar, me ressuscite como atacante.","","\"Ela viu O QUÊ? Entendi. A loucura é uma companheira cruel, boticário. Pelo menos os outros ainda demonstram um resquício de lucidez.\" – Cirurgião demaciano","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI032":["Cronista da Ruína","Jogar: Abata um aliado, depois ressuscite-o.","","Ela costumava se sentar ao lado do pai – um lorde que trabalhava como curador – enquanto ele estudava os tomos empoeirados. Ele desejava que a filha continuasse seu trabalho... mas não assim.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI058":["Mensageiro Etéreo","Jogar: Abata um aliado para invocar um seguidor aleatório que custe 2 a mais.","","Espíritos, emprestem suas vozes a mim! Juntos, invocaremos uma escuridão sem fim!","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI054":["Aperto dos Mortos-Vivos","Drene 3 de uma unidade.","","Não há nada que os mortos queiram mais do que silenciar a incessante pulsação dos vivos.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI044":["Matrona Espectral","Jogar: Escolha um aliado na mão. Invoque uma cópia idêntica a ele. Ela é Efêmera.","","A Ruína corrompeu todos em seu caminho. Os gentis se tornaram cruéis. Os corajosos se tornaram violentos. A razão deu lugar ao ressentimento.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI039":["Terror Aracnídeo","","","Alguns espíritos maléficos se inspiram na fauna local, transformando o familiar em algo apavorante.","Unidade",["ARANHA"],["Ilhas das Sombras"],"COMUM"],"01SI020":["O Reacendedor","Ao me invocar, ressuscite o Campeão aliado Mais Forte que tiver morrido.","","Qual é o propósito de uma vela prestes a se apagar senão o de acender sua sucessora?","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI029":["Lamento Fulminante","Cause 1 de dano a todos os inimigos. Cure seu Nexus em 3.","","O que nos mata deixa eles mais fortes.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI004":["Perdição das Águas Sombrias","","","Alguns dos que fugiam da Ruína tentaram se jogar ao mar, acreditando que a corrupção não chegaria até as profundezas. Mas estavam enganados.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI026":["Presa do Guardião","Suspiro Final: Crie na mão outro seguidor aleatório com Suspiro Final com 3 ou menos de custo.","","Ele prendeu a respiração o máximo que pôde, rezando para que o Guardião fosse embora. Mal sabia ele que a perseguição era só o começo do tormento que fazia Thresh se deleitar...","Unidade",[],["Ilhas das Sombras"],"COMUM"],"01SI040":["Banquete Cruel","Drene 1 de uma unidade para invocar 1 Cria Aracnídea.","","\"Minha… minha senhora! Não tinha percebido o seu fascínio por… esses aracnídeos! Você poderia tirá-los de perto de mim? S-Senhora Elise? Por favor?\" – Lorde Sassen, Aristocrata Azarado","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"01SI015":["A Ruína","Abata TODAS as unidades.","","E pensar que algo tão puro quanto o amor poderia causar uma tragédia tão cruel e inevitável.","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"01SI055":["Devora-Almas","","","\"Enquanto nossa frota se aproximava das terras amaldiçoadas, eu pensei: aquelas criaturas terríveis surgiram desse lugar nefasto? Ou será que algum dia viveram de verdade?\" – Arie Wrence, soldado demaciano","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"01SI047":["Memórias Evanescentes","Selecione um seguidor. Crie uma cópia Efêmera dele na mão.","","Por um instante, ela se lembrou: raios de sol tocando sua pele, o doce sabor das amoras na boca e a gentil melodia da clareira passando com a brisa. E depois... mais nada.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"02PZ001":["Submiaurino","Ao me invocar, compre 1.\nDepois, se você tiver jogado pelo menos 10 outras cartas novas nesta partida, eu ganho +4|+0.","","Nada poderia impedir sua fuga daqueles humanos simplórios. Nem mesmo uma aguinha...","Unidade",["FELINO"],["Piltover e Zaun"],"ÉPICO (A)"],"02PZ010":["Investigador Veterano","Ao me invocar, TODOS os jogadores compram 1.","","Alguns agentes confiam em seus instintos para resolver um caso. Outros, em seus contatos. Mas os pontos fortes do Agente J. S. Harknor são a diligência e a burocracia. Muita burocracia.","Unidade",["YORDLE"],["Piltover e Zaun"],"COMUM"],"02PZ006":["Te peguei!","Ao me comprar, eu custo 2 a menos nesta rodada.\nCause 3 de dano a uma unidade.","","\"Poderia experimentar essas algemas, Sr. Berz?\"\n\"O que eu ganho com isso?\"\n\"Pode ficar com elas.\"\n\"... Então tá.\"\n\"Você está preso. Levem-no!\"","Feitiço",[],["Piltover e Zaun"],"COMUM"],"02PZ004":["Quebra-Cofres","Conceda +2|+0 a um aliado nesta rodada.\nCrie 1 Quebra-Cofres Fugaz na mão.","","\"Deixo minhas mãos falarem por mim.\" – Vi.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"02PZ007":["Investigadora Perspicaz","Ao jogar uma carta com 2 de custo, compre 1 carta e dê Fugaz a ela.","","\"Todos os detetives reagem aos acontecimentos, mas um bom detetive pode prevê-los, e um detetive excepcional não deixa que aconteçam.\" – O Manual dos Vigias","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"02PZ002":["Mecânica Chefe Zevi","Ao comprar uma carta, dê a ela Fugaz e crie uma cópia idêntica a ela na mão.","","Aos cinco anos de idade, ela criou a primeira faca sônica de multifrequência do mundo. Embora não fosse muito prática (servia principalmente para cortar sanduíches), o feito a levou à Divisão de Armamentos dos Vigias.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"02PZ008":["Vi","Enquanto eu estiver em jogo ou na mão, eu ganho +1|+0 quando você jogar outra carta (máx. de +8|+0).","Eu Golpeei causando 10+ de dano com um Golpe.","\"Defensora Vi, por favor! Pense no povo! Nos danos colaterais! Nos PROCESSOS POR LESÃO CORPORAL!\"\n– Investigadora Perspicaz","Unidade",[],["Piltover e Zaun"],"Campeão"],"02PZ009":["Rastro Suspeito","Crie na mão uma carta aleatória com 2 de custo das suas regiões. Ela custará 2 a menos nesta rodada.","","\"E, por conseguinte...\", anunciou o Agente Harknor, \"...o rastro nos leva a...\"","Feitiço",[],["Piltover e Zaun"],"COMUM"],"02PZ003":["Equipando!","Ao me comprar, eu custo 2 a menos nesta rodada.\nDeixe um aliado com 4|4.","","\"Problema nas docas! Leve isso e diga que eu mandei lembranças.\" – Mecânica Chefe Zevi","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"02PZ005":["Vigias da Ronda","Ao me comprar, eu custo 1 a menos nesta rodada.","","A técnica de corrida da Vigia Mir era uma grande piada entre os outros executores. O Vigia Kepple nunca entendeu.","Unidade",[],["Piltover e Zaun"],"COMUM"],"02BW040":["Artilharia Cascuda","","","\"TALVÊS MINHA MAIÓ FORSSA É MEU COMANDU SOBE AS PEÇOA E AXO QUE O GEITO QUE EU ISCREVO\"\n– Bilhete escrito na areia","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW057":["Mergulhador Evasivo","","","\"Juro que vi algo muito estranho nos recifes... O que colocaram nas laranjas? É só isso que eu quero saber..\"\n– Suboficial","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW041":["A Fera Submarina","","","\"Não tema a fera que você conhece\nPois alguns sobrevivem ao seu furor\nMas aquele que quebra a proa\nArrasta todos para o terror\" – Escrito na viga de uma taverna de Águas de Sentina\"","Unidade",["MONSTRO MARINHO"],["Águas de Sentina"],"COMUM"],"02BW013":["Degoladora à Espreita","","","\"Aí o babaca disse que meus quadris 'se moviam como as ondas do mar'. Mandei calar a boca ou eu arrancava a língua dele fora.\"","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW034":["Estátua de Macaco","Início de Rodada: Cause 2 de dano a mim e invoque 1 Miquinho Explosivo.","","\"Aqui está uma... lembrancinha. A tripulação roubou de um velho rival meu. Parece que aquele papo de 'poderes misteriosos e ancestrais' não era totalmente mentira...\" – Miss Fortune","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW056":["Devorador das Profundezas","Jogar: Oblitere um inimigo com menos Vida do que eu.","","\"Eu navegava, meio na surdina\nPela Baía de Águas de Sentina\nQuando ela surgiu, por trás da escarpa\nA Dama Orelhuda Naufragada...\" – \"Canção da Dama Orelhuda Naufragada\"","Unidade",["MONSTRO MARINHO"],["Águas de Sentina"],"ÉPICO (A)"],"02BW060":["Corsária Atiradora","Quando aliados atacarem, cause 1 de dano ao Nexus inimigo.","","\"Ser baixa é uma baita vantagem de combate. Ninguém tem o cuidado de olhar pra baixo.\"","Unidade",["YORDLE"],["Águas de Sentina"],"COMUM"],"02BW011":["Yordle Vigarista","Lealdade: Pilhe 1 e crie 1 Tiro de Aviso na mão.","","\"Amigos adoram se ajudar, sabia? E você? Gosto da luz no seu olhar e do brilho no seu alfanje! De fato, é um belo alfanje...\"","Unidade",["YORDLE"],["Águas de Sentina"],"RARO (A)"],"02BW030":["Colecionadora de Naufrágios","Ao me invocar, Abdique 2 e crie 2 Tesouros no seu deck.","","\"Hoje em dia, há mais tesouros sob as ondas do que na superfície. Seria moleza de conseguir, se não fosse por ela.\"\n– Carniceiro Farpado","Unidade",["MONSTRO MARINHO"],["Águas de Sentina"],"ÉPICO (A)"],"02BW019":["Bolhurso","","","Correntes vívidas de magia circulam pelos rochedos das Ilhas das Serpentes, alimentando os extraordinários habitantes do oceano.","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW007":["Apostadora Audaciosa","Para me pôr em jogo, descarte 2.\nAtacar: Compre 2 cartas e dê Fugaz a elas.","","\"Na maioria das vezes, não tem mistério. As mesas ficam cheias de idiotas que não prestam atenção no jogo e só querem saber de farra. Problema deles. Quanto mais moedas no meu bolso, melhor.\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW014":["Criaturas Coralinas","Ao me invocar, crie na mão um feitiço aleatório com 1 de custo das suas regiões.","","Nas águas rasas, há muitos tipos de vida marinha, mas nada se compara aos recifes da Via Azure. A Via é um lugar mágico e deslumbrante, cheio de surpresas.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW055":["Capataz Farpada","Saquear: Dê +1|+0 a aliados com 1 de custo globalmente.","","Quando ela dispara, os Anzóis devem ser rápidos. O sangue na água atrai muitas companhias... e nenhuma delas é bem-vinda.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW017":["Caixeiro Cítrico","Saquear: Cure aliados e seu Nexus em 3 e Mobilize.","","\"Todo marujo se 'achar' durão! Soco pra lá, soco pra cá... Legal, legal mesmo. Mas ainda 'precisar' de laranja! Deixa pele bonita, dente forte e eu feliz. Então, ou come, ou anda na prancha. Simples.\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW038":["Zap Nadajato","Ao me invocar, compre um feitiço do seu deck que custe 3 ou menos.","","Zap já completou o circuito da Via Azure em pouco menos de três minutos. Ela teve até que desviar do casco do Jilldaw perto da chegada! As correntes naquele dia estavam DEMAIS!","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW021":["Caçador de Escamâminas","Jogar: Dê Vulnerável a um inimigo.","","\"Ouvi dizer que ele nada quilômetros atrás de seu alvo e, quando encontra, nunca erra. Não sei se é um homem ou um peixe, mas sei que conhece essas águas melhor do que ninguém.\" – Carniceiro Farpado","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW035":["Xerife Lariette Rose","Ao me invocar, dê Vulnerável a todos os inimigos.","","Águas de Sentina pode não ter leis, mas algumas almas destemidas fazem valer sua própria noção de justiça.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW058":["Carniceiro Farpado","Saquear: Eu ganho +1|+1.","","Para entrar nos Anzóis Farpados, é preciso sangrar. Os marinheiros devem provar que conhecem navios, combate e tábuas de corte. Os candidatos mais repugnantes passam pelos três de uma vez só.","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW028":["Rex Correnteza","Saquear: Jogue Barragem de Canhão 7 vezes em inimigos aleatórios.","","\"Deixe os marinheiros, deixe os destroços.\nA batalha já acabou.\nA fumaça clareou a água, o capitão encontrou Rex,\nE o navio se despedaçou.\" – \"Voltando Pra Casa, Sally\"","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW037":["Olho Abissal","Golpe ao Nexus: Compre 1.","","\"Arr, arr, eles gritaram\nRumo a Nashramae eles zarparam\nMas a natureza agiu, levando muitos a perecer\nE os outros encontrarão o olho que tudo vê!\" – \"O Olho Que Tudo Vê\"","Unidade",["MONSTRO MARINHO"],["Águas de Sentina"],"RARO (A)"],"02BW008":["Suboficial","Jogar: Invoque 1 Barril de Pólvora ou um seguidor aleatório com 1 de custo.","","Ele descobriu que poucas coisas motivavam tanto um marinheiro quanto um estopim aceso.","Unidade",["YORDLE"],["Águas de Sentina"],"RARO (A)"],"02BW047":["Catadores de Refugo","Ao me invocar, Abdique 3.","","Só alguém muito especial para estragar um equipamento tão bem construído. Mas se há uma coisa em que eles são bons, é nisso. Só nisso.","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW004":["Ajudante do Apavorador","Ao me invocar, invoque 1 Barril de Pólvora.","","\"Podemos atacar ao amanhecer, quando eles estão alertas e com os canhões prontos para responder. Ou atacamos ao escurecer, quando eles nunca vão esquecer...\"","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW002":["O Apavorador","Ao me invocar, compre Gangplank.\nDobre todo o dano causado pelos seus feitiços, Habilidades e aliados.","","\"Uhhh, podem se despedir e baixar as velas,\npois O Apavorador se aproxima.\nRumo a mares profundos, onde há pilhas de moribundos,\npois O Apavorador se aproxima!\" – \"O Apavorador se aproxima\"","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW016":["Cassinobô","Ao me invocar ou Início de Rodada: Eu ganho +0|+1 por cada carta que você tiver comprado na última rodada e meus atributos são embaralhados.","","Um dos protótipos disparou três bombas e explodiu. Os modelos mais recentes não contam com esse \"recurso\".","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW027":["Frota Caçadora","Ao me invocar, seu oponente invoca 1 Narval Dourado.","","O ouro que brilha sob as ondas não vem de moedas nem lingotes, mas dos chifres reluzentes do astuto adversário do Capitão da Frota Carniceira.","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW050":["Solista Serena","Saquear: Reduza em 2 o custo dos aliados na mão e no deck.","","\"Uma jornada musical nos aguarda! Venha curtir os ritmos de Runeterra! O ingresso custa só algumas moedas, e gorjetas são muito bem-vindas...\" – Promotor de Eventos","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW015":["A Sereia","Ao me invocar, compre Miss Fortune.\nQuando eu estiver no ataque, todos os seus feitiços e Habilidades causam 1 de dano adicional.","","A Sereia é inconfundível. As velas peroladas e a madeira polida a deixam tão imponente quanto a capitã que conduz o leme.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW010":["Poro Saqueador","Saquear: Eu ganho 2 palavras-chave aleatórias.","","\"Ele tá no quadro de procurados faz tempo, pois é um verme impiedoso e rabugento que não poupa absolutamente ninguém. Mas sabe o que é pior? Ele... ele é uma fofura.\"\n– Gangplank","Unidade",["PORO"],["Águas de Sentina"],"COMUM"],"02BW009":["Malandro da Sinuca","Ao me invocar, compre 1 carta no próximo Início de Rodada e dê Fugaz a ela.","","\"Não faz sentido. Eu tava com tudo, mas aquela última... não teve jeito. Acho que hoje não é meu dia...\" – Apostadora Audaciosa","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW005":["Assassina de Aluguel","Ao me invocar, dê Vulnerável ao inimigo Mais Forte.","","\"É você na foto? Credo, é ainda mais feio do que eu imaginava. Espero que sua cabeça valha a pena.\"","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW039":["Caçadores de Peixe-Jaula","Ao me invocar, crie um Monstro Marinho aleatório na mão.","","O sonho da fortuna leva inúmeras tripulações ao alto-mar. Essas pobres almas logo descobrem como as águas podem ser impiedosas e por que tão poucos retornam.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW006":["Mágico Mistificador","Jogar: Transforme um aliado em um seguidor aleatório com 5 de custo.","","\"Marvolio? Cadê... cadê minhas mãos?\"\n\"Agora elas vão aparecer! Tchã-rã! Ahem... Tchã... rã...!\"\n\"... CADÊ MINHAS MÃOS?!\"\n\"HORA DE PARTIR. MUITO OBRIGADO A TODOS!\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW036":["Narval Dourado","","","Reza a lenda que uma baleia de chifres roubou da Mulher Barbada. Como punição, a Mulher cobriu de ouro a gananciosa criatura, condenando-a a atrair a avareza alheia para todo o sempre.","Unidade",[],["Águas de Sentina"],"COMUM"],"02BW033":["Mercador Clandestino","Ao comprar uma carta inimiga, reduza o custo dela em 1.\nSaquear: Pilhe 1.","","\"Tudo o que você quiser, eu tenho! Até um 'estoque especial'... Mas se perguntarem, você não comprou de mim!\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02BW032":["Gangplank","Ao me invocar, invoque 1 Barril de Pólvora.","Você causou dano ao Nexus inimigo em 5+ rodadas diferentes.","\"Não fique encarando, pois ele percebe. E nunca fale mal dele, pois escuta tudo o que é sussurrado em Águas de Sentina. Lá vem ele. Cabeça baixa. Olhos ainda mais baixos.\" – Ajudante do Apavorador","Unidade",[],["Águas de Sentina"],"Campeão"],"02BW022":["Miss Fortune","Quando aliados atacarem, cause 1 de dano a todos os inimigos em batalha e ao Nexus inimigo.","Vi você atacar 4 vezes.","\"'Miss Fortune? Aqui você deve me chamar de 'capitã'.\"","Unidade",[],["Águas de Sentina"],"Campeão"],"02BW046":["Fizz","Ao jogar um feitiço, interrompa todas as Habilidades e feitiços inimigos direcionados a mim e me conceda Elusivo nesta rodada.","Você jogou 6+ feitiços.","De todas as lendárias criaturas de Águas de Sentina, Fizz é o mais volátil. Alguns marinheiros o culpam pelos inúmeros naufrágios na costa...","Unidade",["YORDLE"],["Bandópolis","Águas de Sentina"],"Campeão"],"02BW026":["Twisted Fate","Jogar: Jogue uma Carta do Destino.","Vi você comprar 9 cartas.","\"Agora fique de olho nas mãos, conte as cartas e tente acompanhar. E não se esqueça...\"","Unidade",[],["Águas de Sentina"],"Campeão"],"02BW053":["Nautilus","","Quando você estiver nas Profundezas. Quando eu subir de nível, copie os aliados Abdicados com 4+ de custo para o seu deck.","\"Foi uma âncora que destruiu tudo. Até puxou o Finn lá pra baixo. Só sobraram alguns de nós, mas a noite vem chegando... e o frio também. Desculpa, mãe. Você tinha razão. O Titã vive.\" – Bilhete encontrado","Unidade",[],["Águas de Sentina"],"Campeão"],"02BW061":["Par de Ases","Ao me comprar, eu custo 1 a menos nesta rodada.\nDê +2|+1 a um aliado.","","\"Nada como uma maré de sorte para acumular fichas.\"\n– Twisted Fate","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW024":["Encrenca em Dobro","Invoque 2 seguidores aleatórios com 1 de custo.","","\"Ô, Gav! Aquele não é o sujeito que estamos procurando? Parece que ele tem um amigo.\"\n\"Aquilo é... um homem-tubarão, Baz?\"\n\"E mais um montão de ouro. Vamos lá...\" – Baz e Gav, aspirantes a caçadores de recompensas","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW003":["Coação","Saquear: Retorne QUALQUER seguidor para a sua mão.","","\"Agora você trabalha pra gente!\" – Suboficial","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW025":["Lançar Isca","Dê Vulnerável a um inimigo e invoque Dentão.","","\"Tubarão!\" – Fizz","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW012":["Mais Pólvora!","Invoque 2 Barris de Pólvora.","","\"Barril!\" – Gangplank","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW018":["Negociarrr","Cause 1 de dano a qualquer coisa.\nSe o alvo for abatido, cause 1 de dano ao Nexus inimigo.","","A intermediação de Gangplank costuma ser breve... e sempre sangrenta.","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW048":["Fugitivo","Invoque um seguidor aleatório com 1 de custo.","","\"O que cê acha, Baz? Ele não parece tão durão.\"\n\"Tem certeza, Gav? Ele fugiu da prisão...\"\n\"Isso mostra que ele é esperto, não durão. Vamos!\" – Baz e Gav, aspirantes a caçadores de recompensas","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW043":["Escolha uma Carta","Para me pôr em jogo, coloque uma carta da mão no seu deck.\nCompre 2 cartas no próximo Início de Rodada e dê Fugaz a elas.","","\"Eu determino minha própria sorte.\" – Twisted Fate","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW051":["Trapaceiro Brincalhão","Remova um aliado atacante do combate para Mobilizar.","","\"Um salto à frente de você!\" – Fizz","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW054":["Correnteza","Atordoe um inimigo.\nColoque essa unidade no deck inimigo se você tiver 1 Nautilus.","","\"Afundarei todos vocês...\" – Nautilus","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW042":["Elo Mental","Nesta rodada, deixe o Poder e a Vida dos aliados igual ao número de outros feitiços que você tiver jogado nesta partida.","","As correntezas e marés que cercam Águas de Sentina são temidas por sua força e instabilidade... mas nenhum marinheiro conhece o verdadeiro poder daquelas águas.","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"02BW059":["Saraivada","Abdique 3.\nCause 7 de dano a uma unidade.","","\"Se afundou, é porque a carga valia a pena.\" – Ditado de Águas de Sentina","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW023":["Isca das Profundezas","Reduza em 1 o custo dos Monstros Marinhos aliados globalmente.\nCompre um Monstro Marinho.","","Os marujos sussurram sobre os dias sombrios que estão por vir. Quando o mar, agitado e revolto, trará horrores inimagináveis à superfície.","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW031":["Dois por Um","Cause 2 de dano a um inimigo.\nSe ele for abatido, cause 4 de dano ao Nexus inimigo.","","\"Eu sempre atiro primeiro.\" – Miss Fortune","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW029":["Recuperação","Abdique 2.\nCompre 2.","","Os destroços não passam muito tempo boiando. Qualquer marujo que se preze deve saber identificar cargas valiosas em meio às descartáveis...","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW049":["Produtos Surrupiados","Pilhe 1.\nSaquear: Pilhe mais 1.","","O que é meu, é meu. E o que é seu... também é meu.","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW001":["Tá Avisado","Conceda Vulnerável a um inimigo nesta rodada. Se ele morrer ainda nesta rodada, compre 1.","","\"Levanta a cabeça e não desanima, marujo! Se fizer corpo mole, o capitão te parte ao meio e dá as entranhas pras gaivotas! Se mexe!\" – Ajudante do Apavorador","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW063":["Truque de Mão","Saquear: Compre uma carta aleatória de não Campeão da mão do inimigo.","","\"Cartas não têm nada a ver com sorte, mas sim com pessoas. As pessoas do outro lado parecem receosas? Então pegue tudo que elas têm.\" – Twisted Fate","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW045":["Chuva de Disparos","Cause 1 de dano a três inimigos diferentes alvejados aleatoriamente ou ao Nexus inimigo.","","\"Pronta pra atirar!\" – Miss Fortune","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW020":["Tiro de Aviso","Cause 1 de dano ao Nexus inimigo.","","\"Você tem que atirar junto com os outros, rapaz! Isso que é uma saraivada!\" – Suboficial","Feitiço",[],["Águas de Sentina"],"COMUM"],"02BW044":["Rejeitar","Abdique 4.","","\"Quando algo não tem valor, é jogado no mar! E o mesmo vale pra vocês! Agora voltem ao trabalho!\" – Suboficial","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"02BW062":["Navegadora Nativa","Ao me invocar, invoque um seguidor aleatório com 1 de custo e dê Patrulheiro a ele.","","\"Eleve a luz da Mãe Serpente\nDas ondas até a imensidão.\nO céu observa com olhos acinzentados\nUm suave reflexo de sua contemplação.\nEla sorri, está em paz...\"\n– Oração para Nagacáburos","Unidade",[],["Águas de Sentina"],"RARO (A)"],"02FR009":["Guerreira Lupina","Saquear: Receba uma gema de Mana vazia.","","Os jovens da Garra do Inverno ganham um filhote de lobo assim que conseguem segurar uma arma. Sua criação é totalmente dedicada à batalha. O lobo é treinado para massacrar e devorar, e o guerreiro para saquear e roubar.","Unidade",[],["Freljord"],"COMUM"],"02FR004":["Pegando Friagem","Conceda Congelar e Vulnerável a um inimigo nesta rodada.","","\"Essa gente de sangue quente não dura um dia em Freljord!\" – Sejuani","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"02FR002":["Sejuani","Jogar: Conceda Congelar e Vulnerável a um inimigo nesta rodada.","Você causou dano ao Nexus inimigo em 5+ rodadas diferentes.","Embora seu mangual de Gelo Verdadeiro seja formidável, Sejuani é a verdadeira arma. Forjada no frio cortante de Freljord e testada pelos climas congelantes.","Unidade",[],["Freljord"],"Campeão"],"02FR001":["Guerreira Incandescente","Início de Rodada: Cause 1 de dano a TUDO.","","\"Eles cultivam campos férteis,\nSemeiam o que vão comer.\nColocamos tudo em chamas,\nPra Garra do Inverno recolher!\" – Cantiga das crianças da Garra do Inverno","Unidade",[],["Freljord"],"RARO (A)"],"02FR005":["Ursine Caminhalma","Saquear: Eu me transformo em Ursine Tempesgarra.","","Os Ursine eram humanos, mas abriram mão das comodidades da vida mortal pelo poder feroz e selvagem concedido pelo grande espírito de Volibear.","Unidade",[],["Freljord"],"COMUM"],"02FR010":["Despojos Divididos","Dê +1|+1 às 3 unidades no topo do seu deck.\nSaquear: Compre 1 delas.","","\"Dividir tudo por igual.\" – Guerreira Impiedosa","Feitiço",[],["Freljord"],"RARO (A)"],"02FR008":["A Colmilhadora","Ao me invocar, compre Sejuani.\nSaquear: Dobre o Poder e a Vida dos aliados no seu deck.","","\"Quando a primavera traz um clima ameno o bastante para plantar, traz também as embarcações... e os grãos, antes abundantes, tornam-se escassos.\" – Guarda Termestre Avarosiano","Unidade",[],["Freljord"],"ÉPICO (A)"],"02FR007":["Fúria do Norte","Conceda +3|+4 a um aliado nesta rodada.","","\"Solte a fera que há dentro de você!\" – Sejuani","Feitiço",[],["Freljord"],"COMUM"],"02FR006":["Guerreira Impiedosa","","","A Garra do Inverno domina Freljord, e todos conhecem a ferocidade de seus guerreiros implacáveis. Quando partem em busca de sangue, só resta torcer por uma morte rápida.","Unidade",[],["Freljord"],"COMUM"],"02FR003":["Aurora Poreal","Crie na mão 2 Poros aleatórios e 2 Poritos.","","\"Quando fazemos pedidos a um poro\nE olhamos para o céu,\nVemos poritos nas estrelas,\nComo faíscas de mel.\" – Ingvar, a Jovem","Feitiço",[],["Freljord"],"ÉPICO (A)"],"02NX001":["O Leviatã","Ao me invocar, compre Swain.\nInício de Rodada: Cause 1 de dano ao Nexus inimigo duas vezes.","","Quando os ionianos o viram pairando no horizonte, pensaram que fosse um monstro. Eles não estavam de todo enganados. O navio de aço era apavorante. A maior realização da engenharia naval noxiana.","Unidade",[],["Noxus"],"ÉPICO (A)"],"02NX007":["Swain","Golpe ao Nexus: Cause 3 de dano ao Nexus inimigo.","Você causou 14+ de dano fora de combate.","\"Um poder além da compreensão mortal me permite ver o que os outros não veem. Eu enxergo nas trevas que os outros temem.\"","Unidade",[],["Noxus"],"Campeão"],"02NX006":["Devasta-Cidades","Início de Rodada: Cause 1 de dano ao Nexus inimigo.","","A voz do ancião estava estranhamente calma quando ele perguntou: \"Qual é o sentido de juntar pedras para construir muros mais altos, se os noxianos sempre conseguem jogá-las de volta para o nosso lado?\"","Unidade",[],["Noxus"],"RARO (A)"],"02NX002":["Aurok Chifreluzente","Atacar: Atordoe todos os inimigos que sofreram dano.","","\"Por gerações, nós fomos subjugados. Só entendemos o verdadeiro sentido da liberdade quando Noxus invadiu nossas terras. E é por isso que eu luto pelo império.\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"02NX009":["Bando Voraz","Cause 4 de dano a uma unidade que tiver sofrido dano ou Atordoamento.","","Escute. Consegue ouvir? O som estrondoso de milhares de asas batendo.","Feitiço",[],["Noxus"],"RARO (A)"],"02NX004":["Demolidora Imperial","Jogar: Cause 1 de dano a um aliado para causar 2 de dano ao Nexus inimigo.","","\"Rápida e silenciosa... até a explosão.\"","Unidade",[],["Noxus"],"COMUM"],"02NX003":["Fervor Noxiano","Cause 3 de dano a um aliado para causar 3 de dano a qualquer coisa.","","\"Sacrifícios são necessários.\" – Jericho Swain","Feitiço",[],["Noxus"],"COMUM"],"02NX010":["Montapresa Encouraçado","Inimigos com 4 ou menos de Poder não podem me causar dano.","","\"Não há como parar uma fera de guerra depois que está em movimento. O melhor a fazer é sair do caminho.\"\n– Basilisqueiro","Unidade",[],["Noxus"],"RARO (A)"],"02NX008":["Mão da Morte","Cause 2 de dano a um inimigo e 1 de dano ao Nexus inimigo.","","\"Tente morrer com dignidade.\" – Swain","Feitiço",[],["Noxus"],"COMUM"],"02NX005":["Balista de Ferro","","","\"É fácil armar um cerco com as ferramentas certas. Primeiro trazemos eles pra fora, depois as balistas fazem o resto.\"\n– Engenheiro de Cerco","Unidade",[],["Noxus"],"COMUM"],"02DE003":["Texurso Leal","","","É verdade o que dizem. Os animais realmente se parecem com seus donos.","Unidade",[],["Demacia"],"COMUM"],"02DE008":["Companheiro Chifrídeo","","","Ao serem recrutados, os guardas passam meses na floresta com seus companheiros, aprendendo a prever cada movimento de seu animal. É preciso ter paciência, mas depois que o laço é formado, nada pode desfazê-lo.","Unidade",[],["Demacia"],"COMUM"],"02DE004":["Guardião da Presa Verde","","","\"Eu jurei proteger esta floresta e todos que buscam abrigo nela.\"","Unidade",["ELITE"],["Demacia"],"COMUM"],"02DE006":["Quinn","Ao me invocar, invoque Valor.","Vi você atacar 4 vezes.","\"Nossa Quinn sempre foi uma destemida cavaleira da patrulha. Com Valor ao seu lado e nos céus, eles formam uma dupla imbatível.\" – Genevieve Cordielmo, cavaleira da patrulha","Unidade",[],["Demacia"],"Campeão"],"02DE009":["Guarda Grisalho","Suspiro Final: Invoque 1 Texurso Leal.","","Bertrand começou a carreira nos Escoteiros de Bandópolis. Ele ganhou todos os distintivos, exceto 'Atitude Animada'.","Unidade",["YORDLE"],["Demacia"],"RARO (A)"],"02DE005":["Espírito Inflexível","Dê \"Não posso sofrer dano nem morrer\" a um aliado.","","Ignorando a dor na perna ferida, ela se levantou novamente, espada em punho. Não era só a determinação dela que a mantinha de pé, mas a determinação de toda Demacia.","Feitiço",[],["Demacia"],"ÉPICO (A)"],"02DE002":["Investida Anuviante","Invoque Valor.","","\"Ele está no meu cabelo! ELE ESTÁ NO MEU CABELO!\"\n– Saqueador da Legião","Feitiço",[],["Demacia"],"RARO (A)"],"02DE010":["Genevieve Cordielmo","Ao me invocar, conceda +1|+1 aos outros aliados nesta rodada.","","Ver os guardas-florestais de Demacia em batalha é inspirador. Eles lutam como um só. Humano e animal, lado a lado, ferozmente determinados e completamente inseparáveis.","Unidade",[],["Demacia"],"ÉPICO (A)"],"02DE007":["Determinação Guardiã","Conceda Robusto aos aliados nesta rodada.","","\"Quando o inimigo se aproximar, não se deixe tomar pelo medo, pois as árvores vão nos proteger.\" – Guardião da Presa Verde","Feitiço",[],["Demacia"],"RARO (A)"],"02DE001":["Golpe Orquestrado","Escolha um inimigo. 2 aliados Golpeiam o inimigo escolhido em sequência.","","\"Comigo, todos juntos!\" – Guardião da Presa Verde","Feitiço",[],["Demacia"],"COMUM"],"02SI005":["Seiva Mágica","Abdique 3.\nCure aliados em 3.","","\"As Ilhas serão purificadas.\" – Maokai","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"02SI010":["Florimorta Errante","Ao me invocar, Abdique 3.","","\"O grande ente continuou mostrando... criaturas. Esta... para espalhar a vida por onde passasse... notável como... aqui. Realmente são as Ilhas das Bênçãos!\" – Diário recuperado","Unidade",[],["Ilhas das Sombras"],"COMUM"],"02SI008":["Maokai","A cada rodada, ao invocar outro aliado pela primeira vez, Abdique 2 e invoque 1 Muda.","Suas unidades morreram ou suas cartas foram Abdicadas 25+ vezes.","Essas terras amaldiçoadas não derrubariam Maokai. O compromisso do ente é tão férreo, sua fúria tão intensa, que nada poderia atrapalhar.","Unidade",[],["Ilhas das Sombras"],"Campeão"],"02SI007":["Sapo Espinhoso","Suspiro Final: Abdique 2 e cure seu Nexus em 2.","","\"... espécie extraordinária... mesma criatura que encontrei na infância... não envelheceu nada! Será que... próxima cidade. Talvez esses incríveis camaradas vivam para sempre!\"\n– Diário recuperado","Unidade",[],["Ilhas das Sombras"],"COMUM"],"02SI003":["Terror das Marés","Monstros Marinhos aliados têm Assustador.\nAtacar: Conceda -2|-0 aos inimigos nesta rodada.","","Eles perceberam o perigo tarde demais. A fera titânica abriu a bocarra e avançou na direção deles. Os caçadores só puderam esperar a morte chegar enquanto os dentes enormes destruíam o navio.","Unidade",["MONSTRO MARINHO"],["Ilhas das Sombras"],"ÉPICO (A)"],"02SI001":["Colecionador da Nunclareira","Quando outro aliado morrer, Drene 1 do Nexus inimigo.","","\"Encontrei com Niven esta... o novo barqueiro! Ele remou... até... ele até canta bem! Antes... convidá-lo para jantar um dia.\" – Diário recuperado","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"02SI002":["Videira Vigorosa","Ao jogar um seguidor, abata-o para invocar 1 Videira Vigorosa.","","\"Hoje... mais uma extraordinária... veio à tona... crianças muito assustadas. Mas... nenhuma ameaça. Aproximou-se... criatura muito dócil. Vou procurar mais frutinhas para ela!\"\n– Diário recuperado","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"02SI004":["Defensora Arruinada","Jogar: Abata um aliado para invocar 2 Mudas.","","\"Cada coração é um jardim onde raízes podem se fixar!\"","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"02SI006":["Fera da Casca","Eu ganho +2|+2 na primeira vez que um aliado morrer.","","As criaturas das Ilhas das Sombras abriram mão do sentimentalismo há muito tempo. Elas precisam comer.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"02SI009":["Atirar Mudas","Invoque 1 Muda no próximo Início de Rodada.","","\"Ihuuuuuuuu!\" – Muda","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"02IO008":["Onda Sônica","Conceda Desafiador a um aliado nesta rodada.\nCrie 1 Ataque Ressonante Fugaz na mão.","","\"Domine a si mesmo...\" – Lee Sin","Feitiço",[],["Ionia"],"COMUM"],"02IO002":["Escamas do Dragão","Ao me invocar, crie 1 Proteção do Dragão na mão.","","\"Discípulos devem agir com compaixão, pois o Dragão nutriu as Primeiras Terras, concedendo calor e vida.\"\n– Ensinamentos do Dragão","Unidade",[],["Ionia"],"COMUM"],"02IO006":["Lee Sin","Ao jogar um feitiço, me conceda Desafiador nesta rodada.\nSe jogar outro, me conceda Barreira nesta rodada.","Você jogou 8+ feitiços.","\"O Dragão ajuda os dignos. Aos cansados, ele dá vigor. Aos enfermos, conforto. Aos perdidos, a luz. Aos abalados, o equilíbrio...\"","Unidade",[],["Ionia"],"Campeão"],"02IO004":["Chifres do Dragão","","","\"Discípulos devem lutar com todo o seu poder, pois o Dragão puxou o chão debaixo das ondas e nos deu as terras que hoje chamamos de lar.\" – Ensinamentos do Dragão.","Unidade",[],["Ionia"],"COMUM"],"02IO003":["Olho do Dragão","Início de Rodada: Fluxo: Invoque 1 Dragonito.","","\"Discípulos devem pensar com clareza, pois o Dragão atrai o sol que há no céu e revela o mundo que nos cerca.\"\n– Ensinamentos do Dragão.","Unidade",[],["Ionia"],"ÉPICO (A)"],"02IO001":["Garras do Dragão","Enquanto eu estiver na mão, me invoque ao jogar 2 feitiços em uma rodada.","","\"Discípulos devem escutar com atenção, pois o Dragão rugiu os primeiros sons e abençoou nossos jovens espíritos com o dom da magia.\" – Ensinamentos do Dragão","Unidade",[],["Ionia"],"COMUM"],"02IO005":["Palma Concussiva","Atordoe um inimigo para invocar 1 Cauda do Dragão.","","\"Você não me viu partir, nem me verá retornar.\" – Cauda do Dragão.","Feitiço",[],["Ionia"],"RARO (A)"],"02IO010":["Retirada","Retorne um aliado para criar 1 Revide Fugaz na mão.","","Os primeiros noxianos que desembarcaram em Ionia encontraram um inimigo fraco e despreparado. Muitos foram mortos, mas alguns conseguiram fugir...","Feitiço",[],["Ionia"],"RARO (A)"],"02IO007":["Fúria do Dragão","Um aliado chuta um oponente no Nexus inimigo, Golpeando ele e, depois, o Nexus.\nSe o inimigo sobreviver, Retorne-o.","","\"O Dragão deve ser liberado ou me consumirá por dentro.\" – Lee Sin","Feitiço",[],["Ionia"],"ÉPICO (A)"],"02IO009":["Meditação Profunda","Fluxo: Eu custo 2 a menos.\nCompre outros 2 feitiços.","","A meditação é uma jornada sem destino. Uma rota que só pode ser percorrida ao se perder pelo caminho.","Feitiço",[],["Ionia"],"RARO (A)"],"03NX019":["Caça aos Fracos","Seu oponente descarta o seguidor Mais Fraco da mão.","","\"Não há lugar para fracos neste mundo. Cada novo dia traz novos tormentos, novos métodos de tortura. Eu não mato, concedo misericórdia.\" – Arrel, a Rastreadora","Feitiço",[],["Noxus"],"RARO (A)"],"03NX022":["Garras Selvagens","Um aliado Golpeia um inimigo. Se ele tiver Sobrepujar, o dano excedente será repassado ao Nexus inimigo.","","\"Opa, o selvagem está MAIS selvagem do que nunca! Fiquem longe dessas garras, pessoal!\" – Apresentador da Arena","Feitiço",[],["Noxus"],"ÉPICO (A)"],"03NX007":["Riven","Ao me invocar, se tiver o Símbolo de Ataque, ou ao receber o Símbolo de Ataque, Reforje.","Você criou Lâmina do Exílio.","\"Eu não fugirei do que já fui. Prometi que consertaria tudo aquilo que quebrei...\"","Unidade",[],["Noxus"],"Campeão"],"03NX006":["Punho de Arma","Conceda +2|+0 a um aliado nesta rodada. Reforje.","","\"Para conhecer seu inimigo, primeiro é preciso conhecer a arma dele. Ela dirá como a pessoa se movimenta e golpeia. Essa é a forma de expressão mais pura que há.\" – Arrel, a Rastreadora","Feitiço",[],["Noxus"],"COMUM"],"03NX002":["Arrel, a Rastreadora","Fim de Rodada: Se você tiver jogado um feitiço em mim nesta rodada, eu Golpeio o inimigo Mais Fraco.","","\"Esconda-se... e te encontraremos. \nRespire... e te ouviremos.\nCorra... e te mataremos.\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"03NX018":["Apreender","Atordoe um inimigo.\nSe você tiver 1 Darius, Mobilize.","","\"Eu mesmo cuido disso.\" – Darius","Feitiço",[],["Noxus"],"RARO (A)"],"03NX009":["Cavaleira Colérica","","","\"Não há nada melhor do que caçar outros soldados. Para achá-los, é preciso pensar e se sentir como eles. Para capturá-los, é preciso temê-los como eles te temem. Esse é um vínculo que poucos conhecerão, mas que eu saboreio acima de tudo.\"","Unidade",[],["Noxus"],"COMUM"],"03NX017":["Basilisqueiro Sanguinário","Jogar: Cause 1 de dano a um aliado e a um inimigo 4 vezes.","","Os treinadores de basilisco deixam as feras sem comer nos dias que antecedem à batalha. Quando as criaturas são soltas, ficam absolutamente indomáveis, incapazes de distinguir aliados de inimigos.","Unidade",["RÉPTIL"],["Noxus"],"ÉPICO (A)"],"03NX015":["Técnicas de Sobrevivência","A Vida dos aliados não pode ficar inferior a 1 nesta rodada.\nAo descartar, a Vida do seu aliado Mais Forte não poderá ficar inferior a 1 nesta rodada.","","\"Os cães-dragão farejaram o rastro. Eles vão encontrá-la, e acabaremos com isso. Não há outro jeito.\" – Arrel, a Rastreadora","Feitiço",[],["Noxus"],"RARO (A)"],"03NX014":["Determinação Afiada","Conceda +3|+2 a um aliado nesta rodada.","","\"É, deixa que eu conserto as suas armas, cuido dos seus cavalos e cozinho sua maldita comida. Pra que mais eu serviria, não é mesmo?\" – Erath, Escudeiro da Lâmina","Feitiço",[],["Noxus"],"COMUM"],"03NX003":["Escudeiro da Lâmina","Suspiro Final: Reforje.","","\"É como as caçadoras disseram: cem dias e noites. Cem bolhas nos pés, cem insetos no café da manhã, cem conversas sobre \"lâmina\" e \"vingança\". E bem mais de cem encheções de saco dessas três. Vou te contar, viu...\" ","Unidade",[],["Noxus"],"COMUM"],"03NX001":["Tecelã de Runas","Ao me invocar, Reforje.","","\"Muitas armas são ferramentas grosseiras que valem tão pouco quanto as mãos de quem as fez. Mas uma arma infundida com magia rúnica é muito mais do que mero aço.\"","Unidade",[],["Noxus"],"COMUM"],"03NX005":["Caçadora Brutal","Ao me invocar, me conceda Ataque Rápido nesta rodada.","","\"Aí está você. Nós SABÍAMOS que não viria sem resistir. Ou, pelo menos, era o que esperávamos.\"","Unidade",[],["Noxus"],"RARO (A)"],"03BW006":["Jack, o Vencedor","Início de Rodada: Crie 1 Durma com os Peixinhos na mão.","","Anos no ringue de boxe ensinaram muitas lições valiosas a Jack. Ele aprendeu que, se o oponente pode sangrar, ele pode ter medo. Aprendeu o poder de um olhar silencioso. E o poder da violência sem limites.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"03BW010":["Rango no Rio","Um aliado Captura outro aliado e ganha os atributos do aliado capturado.","","\"Pode entrar, colega, e tudo o que você deseja será seu pela eternidade.\" – Tahm Kench","Feitiço",[],["Águas de Sentina"],"COMUM"],"03BW005":["Custos Afundados","Coloque 1 unidade ou Monumento no deck ao qual pertence.","","\"Eu ofereci exatamente o que você queria, colega. Mas nunca disse que duraria para sempre.\" – Tahm Kench","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"03BW004":["Tahm Kench","Ao me invocar ou Início de Rodada: Crie 1 Um Gosto Adquirido na mão.","Eu Capturei 3+ unidades. Quando eu subir de nível, Oblitere meus inimigos Capturados e liberte meus aliados.","\"Eu conheço essa expressão, colega. Sinto que você olha para as cartas na mão pensando que merece mais. Você só gosta do bom e do melhor, né? Talvez eu possa saciar sua fome e permitir que saboreie tudo aquilo que sempre desejou. Basta escrever seu nome nesse papel... e sua satisfação será eterna.\"","Unidade",[],["Águas de Sentina"],"Campeão"],"03BW002":["Lagarto Boêmio","Início de Rodada: Cause 2 de dano a mim.","","\"Ah, como as pessoas são burras! Basta uma bebida geladinha e uma cadeira quentinha para contarem qualquer segredo a rostos amigáveis. E quem tem um rosto mais amigável do que o jovem Leonard, hein?\" – Rãdivinha","Unidade",[],["Águas de Sentina"],"COMUM"],"03BW014":["Macacos me Mordam","Invoque 1 Miquinho Explosivo.\nSaquear: Invoque mais 1 no próximo Início de Rodada.","","\"Ah... você acha eles fofinhos? POIS ELES NÃO SÃO. Eles se enfiam em tudo que é canto, fazem mais sujeira que um marujo nauseado e NUNCA CALAM A BOCA. EU NÃO QUERO MACACOS NO NAVIO. E PONTO FINAL.\"\n– Suboficial","Feitiço",[],["Águas de Sentina"],"COMUM"],"03BW007":["Polvo Boxeador","Jogar: Cause 3 de dano a mim.","","\"Claro, o Pablo anda passando por uma fase difícil... e ele já levou umas porradas por aí, sim... mas sabe de uma coisa, camarada? Ele é o único por aqui que dá oito socos de uma vez.\" – Sabichão","Unidade",[],["Águas de Sentina"],"COMUM"],"03BW016":["Barcobum","Cause 1 de dano a uma unidade.\nInvoque Barris de Pólvora de acordo com a quantidade de dano causado.","","\"O jovem Gerent soou o alarme pouco antes da primeira explosão. O casco estremeceu, uma das velas pegou fogo, mas o Jilldaw aguentou. Achei que tivesse acabado. Mas, quando segui o olhar do Gerent e encarei o mar, vi mais quatro barcos a remo carregados de pólvora e vindo na nossa direção.\"\n– Sobrevivente do Jilldaw","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"03BW001":["Docas da Matança","Início de Rodada: Abdique 1. Se você estiver nas Profundezas, me destrua para invocar um Monstro Marinho aleatório.","","Todos os dias, moradores locais passam pelas Docas da Matança para ver os horrores capturados pelos caçadores sentinenses. Geralmente, as criaturas estão mortas. Geralmente.","Monumento",[],["Águas de Sentina"],"ÉPICO (A)"],"03BW015":["Senhor Resmunguejo","Jogar: Cause 2 de dano a mim.","","\"DÁ PRA COMEÇAR A LUTA LOGO?! VOU MOSTRAR PRA ESSE COROA FOLGADO POR QUE EU TENHO TANTOS APELIDOS. 'PABLO OITO SOCOS', 'O CRÁQUEM CRAQUE', 'O TERROR DOS TENTÁCULOS'! TU PODE SER VELHO, MAS QUANDO EU ARREBENTAR TUA FUÇA, VAI CHORAR FEITO CRIANCINHA!\" – Polvo Boxeador","Unidade",[],["Águas de Sentina"],"COMUM"],"03BW003":["Sabichão","Jogar: Cause 1 de dano a todos os outros aliados. Por cada um deles, eu ganho +1|+0.","","Chegar ao poder costuma ser uma empreitada violenta... mas geralmente não é essa bagunça.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"03BW017":["Bolheixe Ondulante","Eu custo 1 a menos para cada feitiço que você tiver jogado nesta partida.\nAo me invocar, crie na mão um feitiço aleatório com 1 de custo das suas regiões.","","\"Atenção, lecluta! Xua mixão é se infiltlá nas linhas inimigas, plantá o maió número di bolias pussível e contá pa gente TUDU QUI VOXÊ VIU. TENDEU?!\" – Almilante Shelly, Artilharia Cascuda","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"03BW008":["Rãdivinha","Jogar: Cause 1 de dano a mim e a um aliado para comprar 1.","","\"A velha Babs já passou por muita coisa. Já matou uns habitantes locais quando era jovem, mas acho que isso a deixa mais autêntica.\" – Lagarto Boêmio","Unidade",[],["Águas de Sentina"],"COMUM"],"03BW020":["Pandemônio Explosivo","Invoque 1 Miquinho Explosivo para cada vez que você tiver ativado Saquear nesta partida.","","\"Ah, essas bolinhas de pelo não são tão ruins. Vou dar uma dica: adoram de fogos de artifício. É só atacar os paióis de pólvora do inimigo e deixar os miquinhos fazerem o resto.\"\n– Miss Fortune","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"03BW009":["Extorsão","Cause 2 de dano a um aliado para dar Vulnerável a 2 inimigos.","","\"Vai me dizer onde arrumou esses 'barris extras', Slim? Hein? Ou prefere brincar de cabo de guerra com a sua língua e o braço do Jimbo? E não é em você que eu vou apostar.\"\n– Sabichão","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"03DE010":["A Grande Praça","Quando um aliado for invocado, conceda +1|+1 e Desafiador a ele nesta rodada.","","No pátio, só se ouvia o estandarte se debatendo na brisa. Tianna olhou para a formação e avaliou as fileiras reunidas. Ela fez um breve aceno de aprovação e ergueu o estandarte com um grito: \"Quem está pronto para lutar por Demacia?\". A resposta estrondosa da multidão fez até mesmo as montanhas tremerem. ","Monumento",[],["Demacia"],"ÉPICO (A)"],"03FR009":["O Abismo Uivante","Início de Rodada: Crie na mão 1 Campeão aleatório de nível 2 que não esteja na mão, no deck nem em jogo.","","Os heróis vêm até a ponte convocados por um chamado desconhecido. Eles enfrentam o frio cortante e a estrutura deteriorada para ver o que há além: vitória ou morte.","Monumento",[],["Freljord"],"ÉPICO (A)"],"03MT005":["Caminhos Divergentes","Compre um Monumento ou destrua um Monumento.","","Targon é um lugar caprichoso, onde o inquebrável se quebra e o quebrado se regenera.","Feitiço",[],["Targon"],"COMUM"],"03SI009":["Criptas de Helia","Início de Rodada: Se puder, abata seu aliado mais caro para invocar um aliado do seu deck com 1 a mais de custo.","","O que mais poderia atrair uma alma para esse lugar destroçado além da promessa de vida eterna e grande fortuna?","Monumento",[],["Ilhas das Sombras"],"ÉPICO (A)"],"03IO006":["Monastério de Hirana","Início de Rodada: Crie 1 Santuário na mão.","","As montanhas ionianas escondem santuários destinados àqueles que desejam focar a mente e renovar as energias.","Monumento",[],["Ionia"],"ÉPICO (A)"],"03NX013":["Terra Abrasada","Abata uma unidade que sofreu dano ou destrua um Monumento.","","\"Os cães-dragão farejaram o rastro. Eles vão encontrá-la, e acabaremos com isso. Não há outro jeito.\" – Arrel, a Rastreadora","Feitiço",[],["Noxus"],"COMUM"],"03NX004":["Arena de Noxkraya","Fim de Rodada: Seu aliado Mais Forte e seu inimigo Mais Fraco Golpeiam um ao outro.","","\"Oláááá, fãs dos desafiadores! Prontos pra mais uma noite de EMOÇÕES QUENTES no RINGUE DE FOGO?! Pois é, parece que nosso amigo Trikinho DEU AZAR hoje! Ele vai encarar o superultramegapoderoso GRANAAAAK, o Grande! Tragam os paramédicos, porque essa vai ser vapt-vupt!\"\n– Apresentador da Arena","Monumento",[],["Noxus"],"ÉPICO (A)"],"03DE004":["Capitã Arrika","Jogar: Capture uma unidade ou Monumento.","","Na infância, Arrika viu com os próprios olhos a devastação de que Noxus era capaz com a destruição de seu próprio lar. Ao se alistar no serviço militar, ela jurou nunca mais permitir que a flâmula noxiana fosse fincada em solo demaciano nem deixar que outras crianças ficassem órfãs.","Unidade",["ELITE"],["Demacia"],"RARO (A)"],"03IO005":["Volta ao Lar","Retorne uma unidade aliada ou Monumento aliado para Retornar uma unidade inimiga ou Monumento inimigo.","","\"Trevvvvorrrrrr, vooooltaaaaa...\" – Casa do Trevor","Feitiço",[],["Ionia"],"COMUM"],"03MT052":["Nascente Estelar","Fim de Rodada: Cure em 1 os aliados que sofreram dano. Depois, se eu tiver visto você curar 22+ de dano dos aliados, você vence a partida.","","\"Lá em cima, na cachoeira sagrada\nBem no fundo, nascentes de cura\nLuz reluzente, água iluminada\nVeja como o rio perdura\nNo topo da montanha de cristal.\"\n– Verso Ottrani","Monumento",[],["Targon"],"ÉPICO (A)"],"03MT064":["Topo do Targon","Início de Rodada: Reduza a 0 o custo de uma carta aleatória na mão de TODOS os jogadores nesta rodada.","","Diante do portão do Reino Celestial é possível encontrar o guardião cristalino de Targon. Muitas coisas se esvaem na presença dele: esperança, dúvida, medo. Suas provações acabam com preocupações mortais e revelam completamente a essência da alma de quem subiu até ali. E, sob o arbítrio do guardião, essa alma é julgada. ","Monumento",[],["Targon"],"ÉPICO (A)"],"03SI008":["Derrocada","Abata um aliado para abater uma unidade ou destruir um Monumento.","","Nada pode durar nessas ilhas assombradas. Tudo chegará ao fim.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"03PZ001":["A Universidade de Piltover","Início de Rodada: Descarte sua mão. Crie 3 cartas aleatórias na mão e dê Fugaz a elas.","","As invenções do Professor Cecil B. Heimerdinger o deixaram famoso, mas foram suas aulas descontraídas e demonstrações imprevisíveis que o consolidaram como uma das mentes mais geniais de Piltover.","Monumento",[],["Piltover e Zaun"],"ÉPICO (A)"],"03FR003":["Aquele que Encara","Jogar: Oblitere TODOS os Monumentos ou cause 3 de dano a TODAS as outras unidades.","","\"Nem tivemos tempo de pegar nossas coisas ou avisar os outros. Só conseguimos correr para a floresta e assistir enquanto nossos lares eram destruídos.\" – Guarda Termestre Avarosiano","Unidade",[],["Freljord"],"RARO (A)"],"03MT026":["Rahvun, a Lança da Alvorada","Amanhecer: Crie uma carta aleatória com Amanhecer na mão.\nÉ sempre Dia para nós.","","\"Mantenham a fé, Ra-Horak, e nossa luz nunca se apagará!\"","Unidade",[],["Targon"],"RARO (A)"],"03MT067":["Íbex de Cristal","Jogar: Dê Sobrepujar a um aliado.","","Aqueles que pretendem escalar o Targon devem se familiarizar com a fauna local. Nenhuma criatura conhece melhor os perigos de Targon, tampouco pode percorrer seu terreno gelado com tanta agilidade.","Unidade",[],["Targon"],"COMUM"],"03MT084":["Formando Estrelas","Evoque uma carta Celestial com 7 ou mais de custo e, depois, cure um aliado ou o seu Nexus em 5.","","\"Olhe para as estrelas. Se você tiver sorte, eu olharei de volta.\" – Aurelion Sol","Feitiço",[],["Targon"],"COMUM"],"03MT221":["As Presas","Jogar: Evoque uma carta Celestial que custe 3 ou menos.","","\"Mãe Lua, mostrai-me o caminho,\nRevelai os céus,\nMostrai-me o além.\"\n– Oração Lunari","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT093":["Estrela Desviada","Cause 5 de dano a um inimigo que já tiver atacado nesta rodada ou que esteja Atordoado.","","\"E é gooool!\" – Zoe","Feitiço",[],["Targon"],"COMUM"],"03MT073":["Lunari Portadora do Anoitecer","Ao me invocar, crie 1 Pólen de Pétala Noturna na mão.","","\"As pétalas noturnas florescem à noite e apenas na lua cheia. Símbolo do orgulho Lunari, seu pólen é usado há séculos, pois apenas nós sabemos como colhê-las de forma segura.\"","Unidade",[],["Targon"],"COMUM"],"03MT002":["Os Céus Caem","Eu custo 2 a menos para cada aliado Dragão ou Celestial que você tiver. Cause 15 de dano a todos os inimigos.","","\"Quando chegar a hora, acho que vou usar Runeterra como exemplo. Talvez eu arraste sua carcaça chamuscada comigo por toda a eternidade. Como um brinquedo velho e sem valor. Não sei. Não pensei tanto nisso.\" – Aurelion Sol","Feitiço",[],["Targon"],"ÉPICO (A)"],"03MT217":["Aphelios","Anoitecer: Escolha uma Arma Lunari para criar na mão.\nNa primeira vez que você jogar 2 outras cartas a cada rodada, crie na mão a Arma Lunari da Fase, se ainda não tiver uma.","Você jogou 4 ou mais Armas Lunari.","\"A cada conflito, mostramos aos Solari que somos dignos de respeito. Ensinamos a eles que a luz da lua é igual à do sol; ensinamos que não se deve subestimar o desconhecido; ensinamos as lições que eles ainda precisam aprender...\"\n– Porta-Voz Lunari","Unidade",[],["Targon"],"Campeão"],"03MT044":["Guardião do Sol","Amanhecer ou ao ativar outro Amanhecer: Eu ganho +1|+1.","","\"Guardião reluzente, sua ira queima como o sol do meio-dia. Venha e castigue aqueles que se atreveriam a invadir este lugar sagrado.\" – Inscrição do Guardião do Sol","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT056":["Diana","Anoitecer ou ao ativar outra carta com Anoitecer: Me conceda Desafiador nesta rodada.","Você ativou Anoitecer 4+ vezes.","Entre eles, preparando-se para a batalha, ali estava ela. Irradiando luz, adornada em prata e azul. Seus olhos brilhavam como estrelas. Quando a lua se ergueu e a iluminou, todos os Lunari ali reunidos fecharam os olhos. Em silenciosa oração, rogaram pela segurança dela e agradeceram por sua presença.","Unidade",[],["Targon"],"Campeão"],"03MT020":["Estrelacórnio Resplandecente","Jogar: Cure um aliado e o seu Nexus em 3.","","\"Está vendo aquela estrela se movendo no céu escuro? É um estrelacórnio adulto. Enquanto os jovens nos emprestam sua magia de cura até poderem retornar aos céus, os adultos dominam esse poder por conta própria. Dizem que ver um e saber do que se trata dá muita sorte. Mais sorte ainda é poder cuidar de um.\" – Lidari, Guardiã das Estrelas","Unidade",[],["Targon"],"COMUM"],"03MT091":["Constelário Maneiríssimo","Evoque uma carta Celestial que custe 3 ou menos.","","\"E eu chamo essas três estrelinhas MUITO brilhantes de... 'Pula-corda Celestial'! Ou tá mais pra uma carinha sorridente ao contrário?\" – Zoe","Feitiço",[],["Targon"],"RARO (A)"],"03MT047":["Cygnus, o Caçador da Lua","Anoitecer: Conceda Elusivo a um aliado nesta rodada.","","Os Lunari esperaram o anoitecer e a segurança que ele trazia. O caminho parecia deserto, mas Cygnus sabia que o acampamento dos Solari estava logo adiante. Ele gesticulou, e os outros formaram uma fila atrás dele.","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT094":["Lunari Espreitadora","Anoitecer: Eu ganho Elusivo.","","\"Voltemos nossos olhos para os céus, para o Sol, para nossa dama... Espere... O quê...? O que é aquilo...?\" – Sacerdote Solari","Unidade",[],["Targon"],"COMUM"],"03MT036":["Bênção Targonense","Dê +3|+3 a um aliado.","","\"Uma lembrancinha de Targon.\" – Taric","Feitiço",[],["Targon"],"RARO (A)"],"03MT092":["Cabra da Montanha","Golpear: Crie 1 Gema na mão.","","As cabras do Monte Targon são ainda mais perigosas do que as outras, pois as gemas em seus chifres liberam fragmentos afiados no momento do impacto. ","Unidade",[],["Targon"],"RARO (A)"],"03MT060":["Protetor Vigoroso","Início de Rodada: Cure seu Nexus em 3. Cause dano a mim equivalente ao valor da cura.","","\"Ninguém conhece os caminhos de Targon como eu, então acabo tendo que cuidar de uns estrelacórnios mais teimosos. Mas que bom que eles têm a mim!\" ","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT001":["Furins Furtivos","Jogar: Atordoe inimigos com 2 ou menos de Poder.","","Pelo silêncio cristalino das encostas montanhosas, ecoou o som tilintante de gelo caindo e, bem acima deles, algo que os viajantes podiam jurar ser... risadas.","Unidade",[],["Targon"],"COMUM"],"03MT055":["Soraka","Auxiliar: Eu e meu aliado auxiliado nos curamos em 4.","Você curou aliados que sofreram dano 4+ vezes.","\"Curar é, por natureza, um ato de altruísmo. Você não precisa extrair o poder dos outros; eles o oferecem de bom grado. Mostre compaixão e verá como eles brilham.\"","Unidade",[],["Targon"],"Campeão"],"03MT048":["Doadora de Dádivas","Ao me invocar, crie 1 Gema na mão.","","\"Dizem que o Protetor abençoou as gemas. Se usá-las, o espírito dele acompanhará você.\"","Unidade",[],["Targon"],"COMUM"],"03MT082":["Luz Matinal","Conceda +1|+1 aos aliados nesta rodada.\nAtive o efeito Amanhecer de um aliado.","","\"Levantamos com o alvorecer! E marchamos para a luz!\"\n– Leona","Feitiço",[],["Targon"],"RARO (A)"],"03MT058":["Taric","Auxiliar: Conceda Robusto a mim e ao meu aliado auxiliado nesta rodada. Copie neste aliado o último feitiço jogado por você apenas em mim nesta rodada (não é possível copiar de novo).","Vi você alvejar ou auxiliar aliados 7+ vezes.","\"A amável gentileza de Taric é uma inspiração para todos que o conhecem, estimulando-os a encontrar a chama interior para suportar as noites mais frias.\" – Vidente da Montanha","Unidade",[],["Targon"],"Campeão"],"03MT062":["Faiscóloga Avoada","Jogar: Se você Contemplar uma carta Celestial, dê +1|+1 e Escudo de Feitiço a um aliado.","","\"... e aí a brilhoboleta é igualzinha poeira estelar que cai no chão e depois voa de volta e elas são tão incríveis e eu vi uma tão linda ontem à noite e eu tô com fome e ela voou até as ESTRELAS e depois... \"","Unidade",[],["Targon"],"RARO (A)"],"03MT040":["Brilhoboleta","","","\"A esperança é uma coisa delicada que voa cada vez mais alto e não deve ser aprisionada.\" – Sacerdotisa Lunari","Unidade",[],["Targon"],"COMUM"],"03MT086":["Artista Sonhadora","Jogar: Descarte 1 para Evocar uma carta Celestial que custe 3 ou menos.","","\"Este é o meu favorito! Eu chamo de 'Identidade Metafísica da Psique Consciente'. Mas se você inclinar a assim... fica parecendo duas colheres.\"","Unidade",[],["Targon"],"RARO (A)"],"03MT016":["Esmagador Assustado","","","\"Puxa, o grande Esmagador tá com medo de passar pelo portalzinho? Tudo bem, vamos fazer o seguinte... HAHAHAHA, brincadeira, VAI NA FÉ!\" – Zoe","Unidade",[],["Targon"],"COMUM"],"03MT054":["Leona","Amanhecer: Atordoe o inimigo Mais Forte.","Você ativou Amanhecer 5+ vezes.","Entre eles, preparando-se para a batalha, ali estava ela. Irradiando luz, adornada em vermelho e dourado. Seus olhos brilhavam como brasas. Quando o sol raiou e iluminou sua cabeça como uma coroa, todos os Solari ali presentes baixaram os olhos, não por vergonha, mas em reverência à sua líder iluminada.","Unidade",[],["Targon"],"Campeão"],"03MT220":["A Encruzilhada","Anoitecer: Atordoe um inimigo. Se ele for um seguidor, atordoe-o novamente no próximo Início de Rodada.","","\"Mãe Lua, a noite chegou,\nQue possamos deter os que nos fazem mal,\nE ensiná-los a se redimir.\"\n– Oração Lunari","Unidade",[],["Targon"],"RARO (A)"],"03MT021":["O Dividemente Infinito","Jogar: Escolha 2 inimigos.\nInício de Rodada: Atordoe-os.","","Dizem que os viajantes que encaram a criatura nos olhos são atingidos por um conhecimento tão profundo, uma perspectiva tão impressionante, que suas mentes acabam por se desfazer.","Unidade",["DRAGÃO"],["Targon"],"ÉPICO (A)"],"03MT006":["Inviolus Vox","A cada rodada, quando um aliado com Fúria abater um inimigo pela primeira vez, crie um Dragão seguidor aleatório na mão.","","\"Olhe para os céus e veja o que eu vejo! Primeiro os sinais, pois, à noite, eles brilham. Depois a fúria, pois, de dia, tudo queima. Você vai ver! Todos nós vamos ver!\" – Arauta dos Dragões","Unidade",["DRAGÃO"],["Targon"],"ÉPICO (A)"],"03MT015":["Contemple o Infinito","Evocar.","","Os céus pairam sobre você, como uma tapeçaria escura cravejada de estrelas brilhantes. Você sente pequenez e modéstia diante de tamanha imensidão. Para onde você olhará primeiro?","Feitiço",[],["Targon"],"COMUM"],"03MT013":["Desolação Lunar","Silencie 2 unidades inimigas nesta rodada.\nAnoitecer: Elas não podem bloquear nesta rodada.","","\"Quem não está habituado ao luar deve aprender a enxergar na noite... ou não enxergará mais nada.\" – Diana","Feitiço",[],["Targon"],"COMUM"],"03MT009":["Zoe","Golpe ao Nexus: Crie 1 Constelário Maneiríssimo na mão ou reduza o custo em 1 se já tiver uma cópia.","Vi você jogar 10 cartas com nomes diferentes.","\"Oiiiiiêêêê! O que tá fazendo? Tá JOGANDO CARTAS? Posso jogar? Quê?! EU TÔ NESSE JOGO? Hahaha! Que dimensão boba...\"","Unidade",[],["Targon"],"Campeão"],"03MT087":["Aurelion Sol","Jogar: Evoque uma carta Celestial com 7 ou mais de custo.\nInício de Rodada: Crie uma carta Celestial aleatória na mão.","Fim de Rodada: Seus aliados têm 20+ de Poder total.","\"Pode escrever o que quiser sobre mim, criatura medíocre! Só não esqueça de dizer que sou lindo, magnífico e muitíssimo inteligente. Quer que eu soletre?\"","Unidade",["DRAGÃO"],["Targon"],"Campeão"],"03MT019":["Bastião","Dê +1|+1 e Escudo de Feitiço a um aliado.","","\"Honre a montanha.\" – Taric","Feitiço",[],["Targon"],"COMUM"],"03MT214":["O Voo","Golpe ao Nexus: Compre 1 e me coloque entre as primeiras 3 cartas do seu deck.","","\"Mãe Lua, dai-me confiança,\nConcedei-me a convicção do Voo,\nMostrai-me o caminho.\"\n– Oração Lunari","Unidade",["AVE"],["Targon"],"RARO (A)"],"03MT071":["Viajante Tyari","Auxiliar: Dê +0|+2 ao meu aliado auxiliado.","","Quando viaja, você deve se entregar à jornada, que inevitavelmente mudará quem você é. Quando viaja, você acaba voltando com algo novo... e deixando para trás parte do seu antigo eu. ","Unidade",[],["Targon"],"COMUM"],"03MT008":["Desejo","Cure completamente aliados que sofreram dano.","","\"Pela vida!\" – Soraka","Feitiço",[],["Targon"],"RARO (A)"],"03MT023":["Clarão Solar","Cause 6 de dano a uma unidade.\nAmanhecer: Em vez disso, Silencie-a nesta rodada e cause 6 de dano a ela.","","Poucas coisas sobrevivem a um olhar tão impassível quanto o do Sol.","Feitiço",[],["Targon"],"RARO (A)"],"03MT045":["Proteção Astral","Cure um aliado em 4 e dê +0|+4 a ele.","","\"Acharam que tinham nos derrotado? Rá! Estamos só começando.\" – Protetor Vigoroso","Feitiço",[],["Targon"],"COMUM"],"03MT080":["Guardião da Nascente","Ao me invocar, crie 1 Dádivas da Nascente na mão.","","\"Na maior parte do tempo, eu cuido das nascentes, mas a principal responsabilidade de um pastor é o seu rebanho. Às vezes, as prioridades podem entram em conflito.\"","Unidade",[],["Targon"],"COMUM"],"03MT042":["Roubo Arcano","Manifeste um feitiço inimigo jogado nesta partida.","","\"Caramba, isso foi DEMAIS! Mas seria bem melhor se eu mesma tivesse feito, né?! Beleza, falou, valeu!\" – Zoe","Feitiço",[],["Targon"],"RARO (A)"],"03MT057":["Forjassol Solari","Amanhecer: Me conceda Roubo de Vida nesta rodada.","","Quando a luz adentrou o local, o Forjassol voltou sua atenção a ela. O artefato Solari transformou os raios brilhantes do sol em um encantamento poderoso para a arma que ele empunhava.","Unidade",[],["Targon"],"COMUM"],"03MT041":["Mentor das Pedras","Auxiliar: Dê +2|+2 ao meu aliado auxiliado.\nSuspiro Final: Crie 3 Gemas na mão.","","\"Você entendeu alguma coisa do que ele disse?\"\n\"Nada. Mas ele parecia legal, né?\"\n– Emir e Haley, Peregrinos da Montanha","Unidade",["YORDLE"],["Targon"],"ÉPICO (A)"],"03MT027":["Lâmina Zênite","Dê +1|+2 a um aliado. Conceda Sobrepujar ao mesmo aliado nesta rodada.\nAmanhecer: Compre 1 Lâmina Zênite.","","\"Deixem que o Sol conceda-lhes a força d'Ela!\" – Sacerdote Solari","Feitiço",[],["Targon"],"COMUM"],"03MT096":["Sacerdotisa Solari","Amanhecer: Evoque uma carta Celestial com custo 4, 5 ou 6.","","Assim como qualquer outro targonense, os Solari também buscam orientação nas estrelas, pois o Sol é a estrela mais adorada em sua fé.","Unidade",[],["Targon"],"RARO (A)"],"03MT028":["Escudeira Solari","Amanhecer: Me conceda +0|+4 nesta rodada.","","\"Tolos são os que não vivem sob o manto da noite\". A escudeira se endireitou e ordenou: \"Abaixe as armas e entregue-se pacificamente\".\nA Lunari se agachou em silêncio, preparando as lâminas curvas mais uma vez. \nQue assim seja. \nA Solari também se preparou, levantando o escudo para refletir os raios do sol nascente. ","Unidade",[],["Targon"],"COMUM"],"03MT089":["Guardiã Crescente","Anoitecer: Eu ganho +2|+0.","","\"Guardiã estoica, o toque gentil da lua cheia restaura sua força. Desperte e nos proteja dos que se atreveriam a invadir este lugar sagrado.\" – Inscrição da Guardiã Crescente","Unidade",[],["Targon"],"RARO (A)"],"03MT051":["Toque Conselheiro","Cure um aliado ou o seu Nexus em 2. Compre 1.","","Os estrelacórnios brilham mais quando estão felizes.","Feitiço",[],["Targon"],"COMUM"],"03MT003":["Ninhada de Dragão","Compre 2 Dragões diferentes ou dê +1|+1 e Sobrepujar a aliados Dragões.","","\"O grito deles é estridente como o de um gato. Se ouvi-lo em algum lugar, ponha o rabinho entre as pernas e se proteja. Entendeu? Porque onde há ovos de dragão, há dragões.\"\n– Explorador targonense","Feitiço",[],["Targon"],"RARO (A)"],"03MT098":["Vigor Solar","Dê +0|+2 a um aliado.","","\"Nosso escudo é nossa convicção, nossa determinação, nossa fé na luz!\" – Escudeira Solari","Feitiço",[],["Targon"],"COMUM"],"03MT215":["Presentes do Além","Escolha uma Arma Lunari para criar na mão.","","\"Me dê sua mão, Aphelios...\" – Alune","Feitiço",[],["Targon"],"COMUM"],"03MT063":["Sonhaluna","Jogar: Evoque.\nAnoitecer: Reduza o custo da carta Evocada em 1.","","\"Olha só todas as nossas amigas no céu hoje! Tá vendo aquela estrela mais brilhante? É o olho do Mensageiro observando a gente! E aquele grupo escuro ali... é o Trapaceiro se escondendo atrás das nuvens! E aquela ali... QUIETO, KULUN! Você não pode sair derrubando as coisas...!\"","Unidade",[],["Targon"],"COMUM"],"03MT100":["Dragão do Eclipse","Amanhecer: A próxima unidade Celestial ou Dragão que você jogar custa 2 a menos.\nAnoitecer: Crie um seguidor Celestial e um Dragão aleatórios na mão.","","Escama de dragão (Dragão do Eclipse, Draco obscuratus)\nNotas: a escama tem incríveis propriedades ópticas. É altamente refletora sob a luz solar direta.\nRabisco: TAMBÉM BRILHA À NOITE!\n– Notas de Anden Mayne, Pesquisador Acadêmico","Unidade",["DRAGÃO"],["Targon"],"RARO (A)"],"03MT076":["Vidente da Montanha","Suas cartas Celestiais custam 1 a menos.\nLealdade: Evocar.","","\"As estrelas têm muito que ensinar e orientar. Para nós, elas são uma constante, uma forma de traçar nosso caminho.\"","Unidade",[],["Targon"],"RARO (A)"],"03MT029":["Pastora de Estrelas","Quando você cura um aliado que sofreu dano, eu ganho +2|+0.","","\"Desde que vi um deles cruzar o céu noturno, me apaixonei pelos estrelacórnios. Na época, eu nem imaginava que conheceria tantos!\"","Unidade",[],["Targon"],"RARO (A)"],"03MT219":["O Templo Velado","Na primeira vez que você jogar 2 outras cartas a cada rodada, recarregue 2 de Mana e dê +1|+0 ao aliado Mais Forte.","","É aqui, no Reino Espiritual, que Alune entra em comunhão com seu irmão Aphelios. É ela quem conforta o assassino silencioso com suas palavras e quem levanta o véu para entregar-lhe as armas da retaliação.","Monumento",[],["Targon"],"RARO (A)"],"03MT079":["Pestinha Estelar","Se você Contemplar uma carta Celestial, eu custo 2 a menos.","","\"Adultos são CHATOS. As únicas crianças legais são a Zoe e a galera dela. Eles me ensinam um montão de coisa. Diferente daquela tia sacerdotisa radiante... BLÉÉÉ!\"","Unidade",[],["Targon"],"COMUM"],"03MT007":["Estrelacórnio Inexperiente","","","\"Como qualquer iniciante, um dia os jovens estrelacórnios precisam fazer seu primeiro voo. Nesse aspecto, eles são como qualquer outra estrela no céu, pois caem com a mesma facilidade. Felizmente, estamos aqui para segurá-los e, no momento certo, devolvê-los.\" – Lidari, Guardiã das Estrelas","Unidade",[],["Targon"],"COMUM"],"03MT038":["Protetor Chamabranca","","","As crianças de Targon foram as primeiras a fazerem amizade com os dragões mais jovens e pacíficos. Essas criaturas mais novas podem ter sentido a curiosidade inocente das crianças e preferiram, em vez de machucá-las, oferecer proteção. ","Unidade",["DRAGÃO"],["Targon"],"COMUM"],"03MT014":["Arauta dos Dragões","Aliados Dragões custam 1 a menos.","","As nuvens rodopiavam em torno de suas formas gigantescas, e até o céu parecia tremer com seus lamentos. Ela sabia o que estava por vir, mas, em vez de medo, sentia o reconfortante abraço do destino.","Unidade",[],["Targon"],"RARO (A)"],"03MT110":["Out Of The Way","Pelo resto da partida, os fortalecimentos de aliados \"nesta rodada\" são permanentes (exceto Barreira). Compre 1.","","\"You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I’m better and ready to stay.\"\n– Kai'Sa, 'THE BADDEST'","Feitiço",[],["Targon"],"ÉPICO (A)"],"03MT017":["Marca do Mensageiro","Crie 5 Os Mensageiros no seu deck.","","\"O tempo passa, o céu se desloca; a Serpente se afasta e o Mensageiro assume seu lugar. Uma estação de abundância se aproxima...\" – Sacerdotisa Lunari","Feitiço",[],["Targon"],"RARO (A)"],"03MT025":["Fragmentos da Montanha","Encha sua mão de Gemas.","","\"Bastar virar um pouco a gema para vê-la brilhar sob a luz. Como as vidas dos mortais, cada uma tem sua chama interior.\" – Taric","Feitiço",[],["Targon"],"ÉPICO (A)"],"03MT216":["Sombras Celestes","Ao me invocar, recarregue 2 de Mana de Feitiço se Contemplar uma carta com Anoitecer.","","\"Mãe Lua, permita-me lembrar,\nQue, embora em solidão,\nSeus filhos dançam no céu,\nE eu não estou só.\"\n– Oração Lunari","Unidade",[],["Targon"],"COMUM"],"03MT012":["Árbitro do Pico","Eu custo 1 a menos para cada vez que você tiver alvejado ou auxiliado aliados nesta partida.","","O Árbitro é o teste final da montanha, pois somente o guardião pode ver além das façanhas do alpinista e enxergar seu espírito.","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT085":["Quietude","Silencie uma unidade nesta rodada.","","\"Eles conhecerão a serenidade.\" – Soraka","Feitiço",[],["Targon"],"RARO (A)"],"03MT081":["Peregrinos da Montanha","Auxiliar: Dê +2|+2 ao meu aliado auxiliado. Se ele tiver Auxiliar, dê +2|+2 ao aliado auxiliado dele e assim sucessivamente para cada aliado auxiliado.","","Todos que se aventuram no Monte Targon têm seus motivos. Alguns querem provar algo a alguém, outros querem provar algo a si mesmos.","Unidade",[],["Targon"],"ÉPICO (A)"],"03MT030":["Contempladora de Estrelas","Ao curar um aliado que sofreu dano, conceda Elusivo a ele nesta rodada.","","\"As estrelas não podem ficar conosco para sempre. Depois de cuidar delas, eu as devolvo aos céus numa labareda fugaz de luz estelar... e cascos agitados.\"","Unidade",[],["Targon"],"RARO (A)"],"03MT088":["Soldado Solari","Amanhecer: Me conceda +1|+1 nesta rodada.","","Sob o calor do sol, ele vigiava a prisão da herege, ignorando os suaves apelos que logo se transformaram num silêncio amargo.","Unidade",[],["Targon"],"COMUM"],"03MT033":["Vovô Rumul","Jogar: Dê +0|+4 a 2 aliados.","","\"Escute, Osu. Está ouvindo? Sinos! O vovô está de volta!\"\n– Illi, Pastora de Estrelas","Unidade",[],["Targon"],"RARO (A)"],"03MT035":["Cascata Lívida","Conceda +1|+1 a um aliado nesta rodada.\nAnoitecer: Compre 1.","","\"Sob o manto da noite, guardada por uma lua pálida.\"\n– Diana","Feitiço",[],["Targon"],"COMUM"],"03MT075":["Sacerdotisa Lunari","Anoitecer: Evocar.","","\"Ah, estrelas do céu, que viajam como muitos peregrinos pela noite. Fiquem conosco um instante, contem-nos o que viram.\" – O Hino da Noite","Unidade",[],["Targon"],"RARO (A)"],"03MT218":["Osso Estelar","Se você Contemplar uma carta Celestial, crie 1 O Mensageiro no seu deck e dê +1|+1 a aliados Celestiais globalmente.","","\"Que o Mensageiro toque,\nE, com sua alegria,\nIlumine as estrelas.\"\n– Oração Lunari","Feitiço",[],["Targon"],"ÉPICO (A)"],"03MT074":["Bolha do Soninho","Atordoe um inimigo. Crie 1 Estrela Desviada Fugaz na mão.","","\"É hora da naninha! Uma brilhoboleta, duuuuas brilhoboletas, trêêês... Ei, quequeéaquiloali?!\" – Zoe","Feitiço",[],["Targon"],"RARO (A)"],"03MT072":["Marcabrasa Derretida","","","Inúmeros desafios esperam quem escala o Monte Targon. Alguns deles, como a subida interminável, sugam suas forças lentamente. Já outros são bem mais imediatos.","Unidade",["DRAGÃO"],["Targon"],"COMUM"],"03MT039":["Poroboleta","","","No espaço, ninguém ouve sua alegria.","Unidade",["PORO"],["Targon"],"COMUM"],"03PZ019":["Porobot Recauchutado","Enquanto eu estiver na mão, tenho uma palavra-chave aleatória que muda a cada rodada. Ao me invocar, eu ganho essa palavra-chave.","","Não é tão macio quanto os verdadeiros, mas é tão bonitinho quanto um!","Unidade",["PORO"],["Piltover e Zaun"],"RARO (A)"],"03PZ005":["Balísticobô","Início de Rodada: Crie 1 Ignição na mão.","","\"O paciente solicitou que mantivéssemos apenas sua mente intacta, dizendo que foi lá que ele guardou todo o seu rancor.\"\n– Diário de um Aperfeiçoador, registro 1011","Unidade",[],["Piltover e Zaun"],"COMUM"],"03PZ004":["Raio da Morte – Mk 1","Cause 1 de dano a uma unidade. Crie 1 Raio da Morte – Mk 2 nas 3 cartas no topo do seu deck.","","\"Hoje, consegui demonstrar com êxito que a energia radiante pode ser concentrada em um único e poderoso raio! Com os ajustes certos, esse raio poderá se tornar uma ferramenta de precisão inimaginável, mas ainda há um longo caminho pela frente.\"\n– Anotações de Viktor","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"03PZ003":["Viktor","Ao me invocar ou Início de Rodada: Crie 1 Aprimoramento de Núcleo Hex na mão.","Você jogou 7+ cartas criadas.","\"Você já testemunhou muita tragédia, Zaun, mas chegou a hora de mudar tudo isso. E, como todo grande avanço, deve começar dentro de você.\"","Unidade",[],["Piltover e Zaun"],"Campeão"],"03PZ010":["Mímica Mecanizada","Atacar: Eu ganho todas as palavras-chave dos aliados.","","\"Sou como você, só que melhor.\"","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"03PZ022":["Give It All","Deixe o Poder e a Vida de todos os aliados iguais aos do aliado com Poder ou Vida mais altos.\nDê palavras-chave aliadas a todos os aliados.","","\"I know I know\nYou want some more\nIf you ready let’s go\nGiving it all\"\n– Seraphine, 'MORE'","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"03PZ014":["Criações Calculadas","Crie 1 Equipaníaco Armado, Balísticobô ou Miaudroide na mão e dê +1|+1 a ela.","","\"Racionalidade e escolha separam a humanidade de seus instintos animais básicos.\" – Viktor","Feitiço",[],["Piltover e Zaun"],"COMUM"],"03PZ013":["Melhoria Iterada","Selecione um seguidor. Crie uma cópia dele na mão com +1|+1.","","\"O autoaprimoramento é um jogo em que você é tanto herói quanto vilão. Você vai passar por dificuldades e pode até achar que venceu... mas, no fim, você sempre acabará atrapalhando a si mesmo.\" – Mímica Mecanizada","Feitiço",[],["Piltover e Zaun"],"COMUM"],"03PZ025":["Teste de Tensão","Remova Fugaz de todas as cartas na mão. Ao me descartar, compre 1 Fugaz.","","\"Na verdade, é muito simples. Substituí a moldura de aço por uma liga mais resistente que inventei e afastei a fiação das dobradiças para evitar curtos-circuitos no sistema. Nada demais.\" – Mecânica Chefe Zevi","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"03PZ012":["Equipaníaco Armado","","","\"Opa, braço novo! Sempre quis um desses. E o que temos aqui? Rodas de gravidade pras pernas? Ligas eletrônicas? DENTES DE METAL? Na verdade, deixa o meu rosto quieto. Eu gosto dele.\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"03PZ020":["Fundição de Núcleos Hex","Início de Rodada: TODOS os jogadores compram 1.","","\"Deixe que falem o que quiserem sobre meus métodos, eles não podem negar o progresso... A luz do meu conhecimento brilha como uma centelha em meio à escuridão da ignorância!\" – Viktor","Monumento",[],["Piltover e Zaun"],"RARO (A)"],"03PZ002":["Miaudroide","","","\"Passei anos na academia de Piltover lutando com garras e presas só pra ouvir que minhas tecnologias são 'perigosas demais' e que minha presença é 'fofinha demais'! Pois eu vou pra Miaun... ops, Zaun. Lá, sei que uma mente brilhante compartilha das minhas ambições...\"","Unidade",["FELINO"],["Piltover e Zaun"],"RARO (A)"],"03PZ011":["Pós-choque","Cause 3 de dano a uma unidade ou destrua um Monumento.","","\"Este raio de luz guiará nossa marcha até Piltover. Nada ficará no caminho da nossa Gloriosa Evolução!\" – Viktor","Feitiço",[],["Piltover e Zaun"],"COMUM"],"03PZ017":["Improbulador Trivolt","Cause 1 de dano a uma unidade. Invoque um seguidor aleatório com 1 de custo. Enquanto eu estiver na mão, quando você jogar uma carta com 3 de custo, aumente o dano e o custo da unidade invocada em 1.","","\"E em um, dois, TRÊS!!! Oh. Oh, minha nossa... Mais um resultado imprevisto?!\" – Heimerdinger","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"03PZ018":["Canhão de Poros","Para jogar, descarte 1.\nCrie 2 Poros Audaciosos na mão.","","Duas formas felpudas caem graciosamente sobre a multidão, deixando uma nuvem de pelos macios e um leve aroma de pão quentinho saindo do forno.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"03SI004":["Sombras Perseguidoras","Escolha um seguidor nas 4 cartas no topo do seu deck.\nCompre-o, coloque o resto no seu deck, depois crie 1 cópia Efêmera na mão.","","\"Vão... Cerquem-os...\" – Nocturne","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"03SI001":["Espreitador Eternebroso","Anoitecer: Crie uma cópia minha na mão.","","\"No começo, era só um par de olhos e uma voz solitária gorjeando nas sombras. Cada vez que eu olhava para trás, havia mais. Vozes cada vez mais altas, mais irritadas. Mas, assim que avistei o Dente, saí correndo.\" – Saqueador do Dente de Baleia","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"03SI018":["Gula","Abata um aliado com Suspiro Final para invocar um seguidor do seu deck que custe 1 a mais.","","\"HORA DO RANGO!\" – Açougueiro Voraz","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"03SI012":["Passagem Imerecida","Oblitere todas as unidades que foram invocadas mas não jogadas nesta rodada.","","\"É claro que a morte está presente em Demacia. Ela leva nossos entes queridos e sabemos que, um dia, também virá nos buscar. Mas nestas ilhas... quase dá pra sentir o gosto da morte. Posso senti-la nos pulmões quando respiro, posso escutá-la sussurrar no meu ouvido. Não é apenas uma noção abstrata. Ela está comigo. Agora mesmo. E levará a todos nós.\"\n– Notas de Jens Tommen, historiador","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"03SI014":["Sombras Invasoras","Dê +2|+2 e Efêmero a TODOS os aliados no seu deck e na sua mão.","","\"Pela mente ou pelo corpo, temo que os pesadelos das Ilhas das Sombras destruam a tudo e todos, e a insanidade reinará eternamente.\"\n– Notas de Jens Tommen, historiador","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"03SI016":["Go Hard","Drene 1 de uma unidade.\nCrie 2 cópias de Go Hard no seu deck. Toda terceira vez que isso acontecer, transforme todas cópias minhas globalmente em Pack Your Bags.","","\"We go hard, 'til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin't nobody bringing us down, down, down, down\"\n– Evelynn, 'POP/STARS'","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"03SI007":["Proteção das Trevas","Na próxima vez que você invocar um aliado nesta rodada, conceda +1|+0 e Escudo de Feitiço a ele.","","\"Assim que você botar o pé pra fora do Dente, vai sentir. Pontas de dedos na sua nuca, leves como a chuva. As criaturas nem se mexem quando você chega perto. Não temem minha lâmina nem minha tocha. Nada. São umas coisas horrorosas.\" – Saqueador do Dente de Baleia","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"03SI005":["Nocturne","Anoitecer: Dê Vulnerável a um inimigo e conceda -1|-0 aos inimigos nesta rodada.","Você atacou com 5+ aliados com Anoitecer ou Assustador.","\"Parece que, depois de abalar almas suficientes, a criatura invade nosso mundo. Só a esperança pode mandar este monstro de volta ao reino dele... mas a esperança já morreu há muito tempo por aqui, com o último suspiro de uma rainha e o grito eterno de um rei.\"\n– Notas de Jens Tommen, historiador","Unidade",[],["Ilhas das Sombras"],"Campeão"],"03SI006":["Assombrofera","Anoitecer: Drene 2 do Nexus inimigo.","","Os viajantes ficavam mais cansados a cada noite. O sono deles era agitado e os sonhos, vívidos demais. Dormir não trazia descanso, apenas exaustão, como se as vidas fossem sugadas pouco a pouco.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"03SI015":["Observador Inoportuno","Suspiro Final: Crie 2 cópias minhas no deck inimigo.","","Muitos dos espíritos das Ilhas das Sombras são criaturas absolutamente aterrorizantes e mórbidas. Mas alguns são só... hã... beeeem irritantes.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"03SI003":["Observadora Estígia","Anoitecer: Me conceda +2|+0 e Assustador nesta rodada.","","À medida que o sol dá lugar à escuridão, os terrores deste lugar acordam, observam e esperam.","Unidade",["AVE"],["Ilhas das Sombras"],"COMUM"],"03SI002":["Horror Indescritível","Drene 1 de qualquer coisa.\nAnoitecer: Crie uma carta aleatória com Anoitecer na mão.","","\"Cada dia que passa suga meu espírito, extrai o vigor que me levou a encontrar este lugar. O Dente de Baleia está lotado de sujeitos apáticos, aparentemente desiludidos de tudo, e acho que quanto mais tempo eu ficar por aqui, mais me assemelharei a eles.\"\n– Notas de Jens Tommen, historiador","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"03SI010":["Cavaleiro do Crepúsculo","Anoitecer: Eu ganho +1|+0 por cada vez que ativamos Anoitecer nesta partida.","","A cada pôr do sol, a noite abre suas asas escuras e apaga os últimos resquícios de esperança.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"03SI013":["Névoas Etéreas","Invoque 1 Espectro da Névoa.","","Espectros da Névoa se movem por planos invisíveis aos mortais, aparecem sem qualquer aviso e causam sofrimento a tudo o que encontram.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"03IO025":["Punhos Pulsantes","Dê +1|+0 e Ataque Rápido a um aliado. Se ele já tiver, dê Ataque Duplo.","","\"Bata muito, rápido e com força.\" – Chifres do Dragão","Feitiço",[],["Ionia"],"RARO (A)"],"03IO017":["Pix!","Auxiliar: Conceda +2|+1 ao meu aliado auxiliado nesta rodada.","","\"Ser amiga do Pix é pra quem tem sorte! Ele é pequenininho, legal e muito forte!\nEle adora gambás e gosta muito de... hããã, blá-blá-blás!\"\n– Lulu","Unidade",["FADA"],["Ionia"],"COMUM"],"03IO008":["Caprichos!","Transforme um seguidor em 1 Esquilo com 1|1 e Silenciar nesta rodada.","","\"Adoribus!\" – Lulu","Feitiço",[],["Ionia"],"COMUM"],"03IO001":["Florzinha de Estimação","Quando me auxiliarem, eu ganho +2|+0.","","Todos querem um mascote fiel, mas ninguém está preparado para a responsabilidade. Tem que levar para passear, oferecer uma dieta balanceada, adaptar a casa... Dá muito trabalho.","Unidade",["FADA"],["Ionia"],"COMUM"],"03IO019":["Determinação Individual","Escolha um aliado. Retorne TODAS as outras unidades e Monumentos.","","\"Eu percorro meu caminho sozinha.\" – Monja Solitária","Feitiço",[],["Ionia"],"ÉPICO (A)"],"03IO002":["Lulu","Auxiliar: Meu aliado auxiliado aumenta em até 4|4 nesta rodada.","Aliados foram Auxiliados 3+ vezes.","\"Não se preocupa, Pix! A gente vai sair da Clareira e deixar TUDO bem adoribus! Tá pronto?!\"","Unidade",["YORDLE"],["Bandópolis","Ionia"],"Campeão"],"03IO011":["Esquilo Bombado","Golpear: Dobre meu Poder.","","O segredo dele é vitamina de nozes, quatro vezes ao dia.","Unidade",["FADA"],["Ionia"],"RARO (A)"],"03IO009":["Silfo Saboroso","","","Energia: 104 kJ (25 kcal), Carboidratos: 5,88g, Açúcares: 3,53g, Fibras: 3g, Gorduras: 0,18g, Proteína: 0,98g, Água: 92g...","Unidade",["FADA"],["Ionia"],"COMUM"],"03IO003":["Guia Feérico","Jogar: Dê Elusivo a um aliado.","","\"Shh! Por aqui! Vamos fazer uma curva fechada à esquerda depois da casa na árvore e passar direto pelas flores falantes. Lu, tá me ouvindo? Lu? Lu! LULU! NÃO dê comida a elas. Não pode.\"","Unidade",["YORDLE"],["Ionia"],"RARO (A)"],"03IO007":["Trevor Dorminhão","Auxiliar: Crie 1 Murmuduende atacante com os atributos do meu aliado auxiliado.","","Você deve seguir seus sonhos, não manifestá-los com feitiços declamados inadvertidamente enquanto passeia por uma floresta mágica. Agora SILÊNCIO, por favor.","Unidade",["YORDLE"],["Ionia"],"ÉPICO (A)"],"03IO010":["Jovem Bruxa","Auxiliar: Conceda Ataque Rápido e +1|+0 ao meu aliado auxiliado nesta rodada.","","Sir Ribery Montague partiu em busca de uma grande jornada ou de uma família nobre para bajular. Mas o destino o levou a um Bandobosque escondido, onde a jovem Bri logo o transformou em sapo e saiu arrastando o coitado a todas as aventuras DELA. Pobre Rib!","Unidade",[],["Ionia"],"COMUM"],"03IO020":["Nananinanão!","Interrompa um feitiço Rápido ou Lento com 3 ou menos de custo.","","\"Não faz isso, seu paspalhão! Vai acabar machucando os antílopes!\" – Lulu","Feitiço",[],["Ionia"],"RARO (A)"],"03IO022":["Go Get It","Retorne um aliado para invocar 1 cópia Efêmera no lugar dele. Reduza o custo dela a 0 nesta rodada.","","\"More\nKnow I got it,\nSo here you go,\nYou look like you could use some more.\"\n– Akali, 'MORE'","Feitiço",[],["Ionia"],"ÉPICO (A)"],"03IO018":["Cuidador Felpudo","Quando me auxiliarem, me conceda +0|+3 nesta rodada.\nAuxiliar: Conceda +3|+0 ao meu aliado auxiliado nesta rodada.","","Os silfos roxos são criaturinhas tão dóceis que todos que os encontram querem cuidar deles. Bom, quase todos.","Unidade",["YORDLE"],["Ionia"],"RARO (A)"],"03DE008":["Tenente da Dracoguarda","Ao me invocar, se você Contemplar um Dragão, eu ganho Desafiador.","","\"Quando perdi meus companheiros de luta em Wrenwall, pensei que meu propósito também estivesse perdido... mas, na verdade, a batalha pode reacender qualquer coisa em um velho soldado.\"","Unidade",[],["Demacia"],"COMUM"],"03DE001":["Confronto","Dê Desafiador a um aliado.\nSe ele for um Dragão, compre 1.","","\"Ninguém fugirá de nós!\" – Shyvana","Feitiço",[],["Demacia"],"COMUM"],"03DE015":["Supressor Pétreo","TODOS os feitiços custam 1 a mais.","","O que antes era um bloco disforme e bruto de petricita logo vira algo valioso nas mãos habilidosas da escultora. É assim que uma obra realmente ganha vida.","Unidade",[],["Demacia"],"RARO (A)"],"03DE006":["Dragão Furioso","","","Todas as criaturas protegem seus filhotes com unhas e dentes, mas poucas são tão bem equipadas para lidar com possíveis ameaças quanto um dragão.","Unidade",["DRAGÃO"],["Demacia"],"COMUM"],"03DE025":["Sopro Ardente","Um aliado com Fúria Golpeia os 2 inimigos Mais Fracos em sequência.","","Por séculos, os demacianos só conheciam a fúria dos dragões pelas lendas. Wrenwall mudou isso.","Feitiço",["ELEMENTAL"],["Demacia"],"RARO (A)"],"03DE002":["Golpe Incansável","Um aliado e um inimigo Golpeiam um ao outro. Depois, se o aliado for um Dragão, cure-o em 5.","","Quando o cavaleiro e o dragão se afastaram, feridos e ofegantes, o último parecia revigorado. Ele farejava sangue e estava ávido por mais.","Feitiço",[],["Demacia"],"RARO (A)"],"03DE011":["Shyvana","Atacar: Me conceda +1|+1 nesta rodada.","Dragões aliados causaram 16+ de dano.","\"Por um lado, ela representa nossos inimigos mais odiados, pois sua espécie só trouxe sofrimento para Demacia. Por outro, o Príncipe confia nela, e ela demonstra ser uma combatente determinada e uma importante aliada. Espero que não traia a confiança que depositamos nela.\"\n– Página do relato do Tenente Jerik sobre Wrenwall","Unidade",["DRAGÃO"],["Demacia"],"Campeão"],"03DE003":["Vigia da Dracoguarda","Ao me invocar, se você Contemplar um Dragão, Mobilize.","","\"Olha, lá longe! Aquilo é...?\"\n\"Parece que sim.\"\n\"Como pode ter certeza?\"\n\"Ah, não tem como errar. Tape os ouvidos. Vai ser alto.\"\n– Anden e Yessenia","Unidade",[],["Demacia"],"RARO (A)"],"03DE013":["Matriarca Vigilante","","","\"Cuidado, soldados! Se tivermos cautela e não perturbarmos o ninho, podemos manter a mãe na defensiva. Se a importunarmos mais... Bom, é melhor estarmos prontos para correr.\" – Anden Mayne, Pesquisador Acadêmico","Unidade",["DRAGÃO"],["Demacia"],"COMUM"],"03DE005":["Pesquisador Acadêmico","Ao me invocar, crie um Dragão aleatório na mão.","","Ovo de dragão (Dragão Furioso, Draco murmurationis) \nLocal: encontrado pelo pesquisador Anden Mayne em uma expedição. \nNotas: período de gestação desconhecido. Incubação em andamento. Movimento recente dentro da casca. O ovo responde ao calor, à luz e ao martelo. Estudos atuais inconclusivos. \n– Notas de Anden Mayne, Pesquisador Acadêmico","Unidade",[],["Demacia"],"COMUM"],"03DE007":["Kadregrin, o Infernal","Ao me invocar, dê +4|+4 a outros Dragões aliados globalmente.","","Quando Demacia sofreu uma súbita onda de ataques de dragão, Shyvana sabia que a culpa era de Kadregrin, o Infernal. Outros dragões, inspirados pela natureza ousada e pela poderosa chama de Kadregrin, levaram terror aos demacianos. ","Unidade",["DRAGÃO"],["Demacia"],"ÉPICO (A)"],"03DE012":["Por Aqueles Que Caíram","Ao invocar uma carta Elite, reduza meu custo em 1.\nPara cada aliado morto nesta rodada, invoque 1 Vanguarda Destemida.","","\"Se um soldado cair, outro deve tomar seu lugar. Nossa bandeira jamais será derrubada.\" – Garen","Feitiço",[],["Demacia"],"ÉPICO (A)"],"03DE014":["Visão Aguçada","Conceda +1|+2 e Visão Aguçada a um aliado nesta rodada.","","Aqueles que ousarem invadir os muros de Demacia encontram um batalhão inteiro – de prontidão e fortemente armado.","Feitiço",[],["Demacia"],"COMUM"],"03FR020":["O Lar das Cicatrizes","Quando um aliado sobreviver a dano, dê +1|+0 e Robusto a ele.","","Há muitos locais honrosos no território da Garra do Inverno, mas um dos mais importantes é o Lar das Cicatrizes, onde barcos de guerra danificados que retornaram de invasões são rearranjados como salas comunais para guerreiros, familiares e amigos. Esses barcos simbolizam a tribo que os construiu\n– resistentes e adaptáveis.","Monumento",[],["Freljord"],"ÉPICO (A)"],"03FR007":["Troll Catador","Ao me invocar, se você Contemplar uma carta com 8+ de custo, eu ganho +3|+0.","","O patrulheiro se ajoelhou junto a um trapo de pano enterrado na neve. Apesar do ar gelado, o cheiro de suor humano e de fumaça persistia.\nEle soltou o tecido e viu, em uma das extremidades, um talismã pendurado, opaco sob o céu nublado. Avarosiano. ","Unidade",[],["Freljord"],"COMUM"],"03FR004":["Rugido Revigorante","Escolha uma unidade na mão para revelar. Cure seu Nexus em valor equivalente ao Poder dela.\nIluminado: Reduza o custo dela a 0.","","\"Os trolls adultos têm pele grossa e ossos densos que se recuperam rapidamente, o que faz deles terríveis inimigos. O abate deve ser rápido, ou eles se recuperam e voltam a lutar.\" – Atirador Avarosiano","Feitiço",[],["Freljord"],"RARO (A)"],"03FR017":["Presságio dos Ancestrais","Jogar: Se você Contemplar uma carta com 8+ de custo, dê Sobrepujar e Regeneração a um aliado.","","Dizem que pouquíssimos trolls sabem os cânticos dos Ancestrais, mas que aqueles que os conhecem podem invocar seus antepassados para conceder força e resistência excepcionais a todos os companheiros.","Unidade",[],["Freljord"],"RARO (A)"],"03FR006":["Trundle","Ao me invocar, crie 1 Pilar de Gelo na mão.","Eu vi você jogar Pilar de Gelo.","Uma a uma, tochas se acenderam ao longo do desfiladeiro, revelando o cenário. Eram dezenas de trolls, talvez centenas, todos enormes, fortes e letais.\n\"Vou perguntar mais uma vez\", rosnou Trundle, erguendo o Treme-ossos sobre o ombro. \"Você vão desistir ou vou ter que esmagar seus crânios?\"","Unidade",[],["Freljord"],"Campeão"],"03FR008":["Terremoto Glacial","Conceda -3|-0 a TODAS as unidades nesta rodada. Cause 3 de dano a TODAS as unidades.","","\"Enterrem eles vivos!\" – Trundle","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"03FR002":["Cântico dos Trolls","Conceda +0|+2 a um aliado para conceder -2|-0 a um inimigo nesta rodada.","","Os cânticos dos trolls variam muito. Eles diferem de grupo para grupo e costumam ser incompreensíveis. Mas uma coisa eles têm em comum: todos são aterrorizantes. ","Feitiço",[],["Freljord"],"COMUM"],"03FR011":["Uzgar, o Ancião","","","Antes que pudessem ouvir, eles sentiram o chão tremer. Tudo logo se tornou audível, como um trovão distante se aproximando.\nMeyrick levantou a cabeça e arregalou os olhos, ouvindo atentamente.\n\"O que é isso?\", sussurrou Anya, sacando seu arco. Mas Meyrick já estava correndo em direção à trilha. \n\"FUJAM!\"","Unidade",[],["Freljord"],"RARO (A)"],"03FR005":["Troll Devastadora","Ao me invocar, se você Contemplar uma carta com 8+ de custo, eu ganho Regeneração.","","Quando chegaram às cabanas avarosianas, eles convocaram Hgar. Com uma gargalhada, ela ergueu Quebração, sua arma, ansiosa para estraçalhar todas aquelas casinhas de madeira.","Unidade",[],["Freljord"],"COMUM"],"03FR018":["Convocando a Natureza","Nas 4 cartas no topo do seu deck, compre os Yetis, Poros e Elnuks. Depois, coloque o resto no seu deck.","","\"...de repente, um ELNUK GIGANTESCO saiu VOANDO das árvores com um Porinho minúsculo nas costas, aí um SIMPÁTICO YETI veio também, pois queria brincar com seus amigos, e todos correram montanha abaixo gritando RAAAAAWRRRRR, e depois...\" – Ingvar, a Jovem","Feitiço",[],["Freljord"],"COMUM"],"03FR010":["Rostos dos Ancestrais","Início de Rodada: Se você Contemplar uma carta com 8+ de custo, ganhe uma gema de Mana adicional nesta rodada.","","\"Venham, Ancestrais, venham,\nRompam os céus com mãos de gelo.\nVenham, Ancestrais, venham,\nTragam-nos força, e a eles, desespero.\"\n– Cântico dos Trolls","Unidade",[],["Freljord"],"COMUM"],"03FR019":["Vozes dos Ancestrais","Receba 2 gemas de Mana vazias.\nCompre cada carta que custa 8+ das primeiras 5 cartas do seu deck. Depois, coloque o resto no seu deck.","","Por várias gerações, os colonos avarosianos ouviram sons estranhos e inexplicáveis no tumulto das tempestades de neve. Certo dia, quando finalmente se aventuraram mais para o norte, descobriram sua origem: monólitos de trolls ancestrais murmuravam em línguas esquecidas, e o vento propagava seus lamentos.","Feitiço",[],["Freljord"],"COMUM"],"03FR025":["Dádivas dos Trolls","Dê Regeneração a um aliado. Se ele já tiver, dê +2|+2.","","Quem vê promessa de vitória no sangue dos trolls é digno de pena.","Feitiço",[],["Freljord"],"RARO (A)"],"03FR022":["Feel the Rush","Invoque 2 Campeões diferentes e aleatórios da sua mão e do deck. Aumente os atributos deles para 10|10.","","\"We got it all in our hands now\nSo can you handle what we're all about?\"\n– Ahri, 'POP/STARS'","Feitiço",[],["Freljord"],"ÉPICO (A)"],"04PZ001":["Ekko","Golpear: Crie 1 Artimanha Temporal Fugaz na mão.","Você Previu 4+ vezes. Quando eu subir de nível, crie 3 Cronoquebras no seu deck.","O lance não é quanto tempo você tem, é como você usa.","Unidade",[],["Piltover e Zaun"],"Campeão"],"04PZ005":["Chireano do Sumidouro","Ao invocar mais 1 Chireano do Sumidouro, me Oblitere e transforme aliados Chireanos do Sumidouro globalmente em Bandos do Sumidouro.","","Os primeiros mineradores zaunitas que encontraram os chireanos os viram como criaturas tímidas e simplórias. Mas, com o passar dos anos, à medida que os chireanos foram se acostumando aos humanos, revelaram fortes laços sociais e habilidades aparentemente natas com a tecnologia.","Unidade",[],["Piltover e Zaun"],"COMUM"],"04PZ014":["Pico de Produção","Para pôr em jogo, gaste todo o seu Mana. Invoque Torres aleatórias com custo total equivalente ao Mana gasto.","","\"Recursos insuficientes?! Construí minha primeira engenhoca mecanizada com peças de sucata e um capacitor térmico enferrujado. É preciso fazer render o que se tem!\"\n– Heimerdinger","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"04PZ003":["Giratempo","Para me pôr em jogo, descarte 1.\nCause 1 de dano a um inimigo ou ao Nexus inimigo, e cause 1 de dano a outro inimigo.","","\"Cuidado!\" – Ekko","Feitiço",[],["Piltover e Zaun"],"COMUM"],"04PZ011":["Jogada Anunciada","Compre 1.\nCrie 1 Convergência Paralela no seu deck.","","\"Linhas do tempo estilhaçadas...\" – Ekko","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"04PZ002":["Declínio Felino","Ao me invocar, crie 1 Cristal de Hexita nas últimas 10 cartas do seu deck.","","\"MAS OS MEUS PLAAAAAAAAAN... MIAUUUUUU!\"","Unidade",["FELINO"],["Piltover e Zaun"],"RARO (A)"],"04PZ020":["Trocobô Defeituoso","Jogar: Troque meus atributos com os de outra unidade.","","''Um novo Cassinobô? Não tinham fechado a fábrica há tempos atrás?''\n''Eu achava que sim. Alegaram algo sobre 'bombas giratórias' e 'incêndios não intencionais'.''\n''Ah, tá''\n''...Quer jogar?''\n''Com certeza''\n– Clientes zaunitas","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"04PZ013":["Elnuk Voluntário","Ao me invocar, crie um Elnuk aleatório nas 6 cartas no topo do seu deck.","","\"BELEZA, AMIGUINHO, FICA AÍ PARADINHO ENQUANTO EU VIRO ESSE NEGÓCIO AQUIIIII E BUM! RÁ! ELNUKS PRA TODO LADO! A gente só vai precisar de mais feno. E espaço.\" – Perfeccionista Prática","Unidade",["ELNUK"],["Piltover e Zaun"],"RARO (A)"],"04PZ010":["Cronologias Simultâneas","Dê a todos os seguidores na sua mão \"Ao me jogar, escolha 1 de 3 seguidores com o meu custo e me transforme nesse seguidor\".","","\"Vamos seguir as MINHAS regras.\" – Ekko","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"04PZ016":["Bumbuíno","Ao me invocar, crie 1 Mordidinha Flamejante! na mão.","","Jinx já teve um fornecedor mais convencional, mas eles brigaram. E por \"brigaram\", queremos dizer que o fornecedor caiu de uma janela. E por \"caiu de uma janela\", queremos dizer que ele foi defenestrado por uma explosão (causada pela Jinx, claro).","Unidade",[],["Piltover e Zaun"],"COMUM"],"04PZ007":["Artimanha Temporal","Preveja e, depois, compre 1.","","\"O futuro só depende de mim...\" – Ekko","Feitiço",[],["Piltover e Zaun"],"COMUM"],"04PZ012":["Perfeccionista Prática","Jogar: Preveja. Crie 3 cópias da carta escolhida no seu deck.","","\"A Kay é incrível. Ela segue sempre aquela ideia que diz que 'a prática leva à perfeição', sabe? E pode apostar que ela pratica MESMO.\" – Shomi","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"04PZ017":["Gloriosa Evolução","Suas cartas têm -1 de custo, Aperfeiçoar, são criadas por Gloriosa Evolução e passam a ser Tecnológicas.","","\"O progresso é tudo. Trarei o futuro para esta cidade, esteja ela pronta ou não.\" – Viktor","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"04PZ015":["Adaptatron 3000","Ao invocar 1 carta Tecnológica, compartilhamos palavras-chave.","","\"Ah, sim! O Adaptatron 3000! Adaptável, inventivo e muito bem apessoado! Se essa belezinha falasse, com certeza teríamos MUITO o que conversar.\" – Heimerdinger","Unidade",["TECNOLÓGICO"],["Piltover e Zaun"],"ÉPICO (A)"],"04PZ004":["Skatista Sagaz","Se você me vir em uma Previsão, me invoque.","","\"Ahh, Shomi manda MUITO no hoverboard. Uma vez, elu deu um mortal cortante, caiu direto num giro de bombordo e saiu voando no mergulho triplo! Foi algo assim. A questão é que elu é o máximo, entendeu?\" – Perfeccionista Prática","Unidade",[],["Piltover e Zaun"],"COMUM"],"04BW002":["Espeto de Osso","Um aliado Golpeia um inimigo e, depois, vai para o topo do seu deck.","","\"Seu presente de despedida...\" – Pyke","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"04BW007":["Peixe-jaula","Jogar: Cada aliado Espreitador Golpeia um inimigo aleatório.","","\"Nada melhor do que um peixe-jaula pra te mostrar quem merece confiança e quem merece a morte.\" – Pyke","Unidade",["ESPREITADOR"],["Águas de Sentina"],"ÉPICO (A)"],"04BW001":["Barbatelo Rubro","Jogar: Dê Vulnerável a um inimigo.","","Ao que tudo indica, Barbatelos Rubros quebram a quilha de embarcações por pura diversão. É muito raro que devorem os náufragos depois, deixando o banquete para outras criaturas desfrutarem.","Unidade",["ESPREITADOR"],["Águas de Sentina"],"COMUM"],"04BW005":["Pyke","Quando eu Espreitar, me transforme em Morte das Profundezas.","Pykes aliados causaram 15+ de dano.","\"... minhas visões voltaram. Vejo o olhar desesperado dele vidrado em mim enquanto o peixe-jaula o dilacera vivo. Tentamos puxar, mas o barco era muito pequeno e a criatura era grande demais. Não tive escolha. Tive que cortar a corda dele. Não teve jeito.\"\n– Carta ensanguentada","Unidade",["ESPREITADOR"],["Águas de Sentina"],"Campeão"],"04BW010":["Arpão de Monstros","Saquear: Eu custo 2 a menos.\nCause 5 de dano a uma unidade.","","\"A fera já está cercada, rapazes! Agora, podem mandar ver até que ela pare de se contorcer e que a água perca o azul!\"\n– Capataz Farpada","Feitiço",[],["Águas de Sentina"],"COMUM"],"04BW014":["Todos Alinhados","Invoque 1 Barril de Pólvora.\nCrie 1 Tudo Pelos Ares na mão.","","\"Tudo certo, Capitão. É só acender uma faísca que ela cuida do resto.\" – Ajudante do Apavorador","Feitiço",[],["Águas de Sentina"],"COMUM"],"04BW011":["Dados Viciados","Na próxima rodada, ao causar dano ao Nexus inimigo, Pilhe 1.","","\"O que está disposto a apostar, colega?\" – Tahm Kench","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"04BW015":["Tubarilho","","","\"Pode até não parecer, mas o que não falta neles é sede de sangue. Se baixar a guarda agora, eles vão saber onde caçar quando ficarem maiores. É melhor colocar luva pra mexer com eles.\" – Caçadores de Peixe-Jaula","Unidade",["ESPREITADOR"],["Águas de Sentina"],"COMUM"],"04BW003":["Cardume de Afianhas","Jogar: Eu inicio um ataque livre.","","\"Plic, ploc, respinga o sangue noite afora,\nTic, toc, é melhor se afogar agora\nNhac, nhoc, vêm os dentinhos nos fazer gritar\nTrac, troc, e nas profundezas nunca mais acordar!\"\n– Cantiga de ninar de Águas de Sentina","Unidade",["ESPREITADOR"],["Águas de Sentina"],"COMUM"],"04BW009":["Baía do Estripador","Quando os aliados atacarem, antes de ativar Espreitar, dê Espreitar ao aliado no topo do seu deck, transformando-o em um Espreitador.","","Não demorou muito para que as enseadas mais traiçoeiras de Águas de Sentina se tornassem lar de inúmeros monstros marinhos. Eles estão sempre ali, esperando chegar a próxima leva de tripulantes imprudentes que ignoraram os avisos do chefe do porto.","Monumento",[],["Águas de Sentina"],"RARO (A)"],"04BW008":["Riquezas Perdidas","Compre um Tesouro. Se não houver cartas desse tipo para comprar, crie 2 Tesouros no seu deck.","","\"Estamos ricos!\" – Carniceiro Farpado","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"04BW013":["Angra do Ladrão","Quando começar a minha Contagem, invoque um seguidor aleatório com 1 de custo.\nContagem 2: Dê +2|+1 e Assustador aos aliados com 1 de custo.","","\"Você acha que tem o que precisa pra fazer parte dos Anzóis Farpados, é? Vamos ver, pilantra. Quando acabarmos com você, ou irá valer o seu peso, ou pesará no fundo do mar, como isca pras criaturas!\" – Suboficial","Monumento",[],["Águas de Sentina"],"RARO (A)"],"04BW004":["Isca de Sangue","Crie 1 Cardume de Afianhas no topo do seu deck.","","\"Vou te dizer, prefiro virar rango de peixe-jaula do que ser pego por uma dessas coisas. Melhor morrer logo do que ficar gritando pros meus companheiros me matarem enquanto sou comido vivo.\" – Carniceiro Farpado","Feitiço",[],["Águas de Sentina"],"COMUM"],"04BW016":["Rex Destruído","Jogar: Jogue Barragem de Canhão em inimigos aleatórios para cada carta comprada nesta rodada, até 6 vezes.","","''...Rex?'' – Suboficial","Unidade",[],["Águas de Sentina"],"RARO (A)"],"04BW006":["A Lista","Dê Vulnerável a um inimigo. Se ele já estiver Vulnerável, o aliado Mais Forte inicia um ataque livre Desafiando esse inimigo.","","\"Você tem um nome, e eu tenho uma lista.\" – Pyke","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"04IO008":["Dança Desafiadora","Retorne uma unidade.\nDança das Lâminas 1.","","\"Recuem! Está na hora de outra pessoa dominar os holofotes!\" – Zinneia, Crescendo de Aço","Feitiço",[],["Ionia"],"COMUM"],"04IO005":["Irelia","Ao me invocar ou Início de Rodada: Se tiver o Símbolo de Ataque, crie 1 Dueto Impecável na mão.","Você atacou com 14+ aliados.","\"Quando estudávamos a arte e a beleza, nossos corações batiam mais fortes. Mas quando derrubaram nossos muros e nosso sangue, desabamos no solo...\"","Unidade",[],["Ionia"],"Campeão"],"04IO020":["Cardume Disperso","Jogar: Compre um feitiço Lento, Rápido ou Súbito.\nIluminado: Eu tenho Elusivo.","","As canções estranhas e belas dos Sorvedores de Nuvens conseguiram deter parte da Névoa Negra... mas não por muito tempo.","Unidade",[],["Ionia"],"RARO (A)"],"04IO004":["Lâmina Florescente","Jogar: Dança das Lâminas 2.","","\"Alguns pensam que as flores são frágeis e delicadas. Eles se esquecem da força que é necessária para se agarrar ao solo e inspirar esperança a cada florescer.\"\n– Zinneia, Crescendo de Aço","Unidade",[],["Ionia"],"COMUM"],"04IO003":["Lâmina da Vanguarda","Escolha um aliado para atacar em conjunto com Lâminas. Depois, Dança das Lâminas 3.","","\"Suspendam a retirada! Os noxianos começaram essa briga, mas nós vamos terminá-la.\" – Irelia","Feitiço",[],["Ionia"],"RARO (A)"],"04IO015":["Gotinha Dançante","Ao me Retornar, compre 1.","","\"A Água é flexível, adaptável. Ela assume a forma necessária no momento, avançando em direção às margens ou recuando para bem longe delas.\" – Monge Ioniano","Unidade",[],["Ionia"],"COMUM"],"04IO014":["Aprendiz das Sombras","Ao invocar um aliado Efêmero, me conceda +1|+0 nesta rodada.","","\"Você não passa de fumaça, um mero sussurro entre os ventos. Seus punhos precisam se fundir às trevas como as sombras fazem na escuridão. Vamos, de novo!\" – Madame Shi","Unidade",[],["Ionia"],"COMUM"],"04IO002":["Zinneia, Crescendo de Aço","Ao fazer a Dança das Lâminas, eu ataco com Lâminas.\nJogar: Dança das Lâminas 1.","","\"Aproximem-se, queridos. Hoje, nossos pés vão deslizar pelo solo que nos alimentou, com os movimentos ensinados por nossas famílias. Somos filhos de Ionia, e hoje dançaremos pela arte, pela liberdade e uns pelos outros!\"","Unidade",[],["Ionia"],"ÉPICO (A)"],"04IO007":["Sincopação","Troque 2 aliados.","","\"Dançar é se mover em harmonia com o movimento de todas as coisas.\" – Zinneia, Crescendo de Aço","Feitiço",[],["Ionia"],"RARO (A)"],"04IO011":["Conduzir e Seguir","Retorne um aliado para criar 1 Dueto Impecável na mão.","","\"Nossa performance será... inesquecível.\" – Zinneia, Crescendo de Aço","Feitiço",[],["Ionia"],"COMUM"],"04IO013":["Protetor Sagrado","Jogar: Conceda Barreira a um aliado nesta rodada e compre 1 Shen.\nAliados com Barreira têm Ataque Duplo.","","\"Nós lutamos para proteger esta terra, e ela retribui erguendo-se para nos defender. Nos fortalecemos com sua ira e a usamos para afugentar os inimigos. É assim que mantemos o equilíbrio.\" – Sacerdote ioniano","Unidade",[],["Ionia"],"ÉPICO (A)"],"04IO012":["Sombras do Passado","Retorne cada aliado e invoque 1 Sombra Viva no lugar de cada um deles.","","\"Deixe que ataquem nas sombras, onde as armas não têm serventia.\" – Zed","Feitiço",[],["Ionia"],"RARO (A)"],"04IO009":["Dançarina das Fitas","Jogar: Dança das Lâminas 1.","","\"Que vergonha, rapazes! Tanto poder e nenhum ritmo? Realmente, nem todo mundo nasceu pra brilhar...!\"","Unidade",[],["Ionia"],"RARO (A)"],"04IO001":["Músicos de Batalha","A cada rodada, depois que invocar 3 outros aliados, recarregue seu Mana de Feitiço e compre 1.","","Para alguns, a música representa um refúgio coletivo contra o sofrimento e a violência. Para outros, ela é uma forma de resistência.","Unidade",[],["Ionia"],"ÉPICO (A)"],"04IO006":["Defensor Costeiro","Ao invocar outro aliado, me conceda +2|+0 nesta rodada.","","Querida Kay, \nEles chegaram esta manhã em uma fila de navios que riscou o horizonte e manchou o nascer do sol. Suas máquinas dispararam contra as Planícies Prateadas, e agora uma densa camada de fumaça polui o ar de verão. Não podemos mais ficar parados. Com ancinhos ou pás, foices ou espadas, hoje enfrentaremos nosso destino. \nAmo você e nosso lar muito mais do que sou capaz de descrever.\n– Carta chamuscada","Unidade",[],["Ionia"],"COMUM"],"04SH100":["Preparação Cautelosa","Para me pôr em jogo, coloque uma carta da sua mão no seu deck.\nPreveja, depois crie uma cópia idêntica da carta escolhida na mão.","","\"As ações que tomamos hoje são sementes de árvores futuras.\" – Tai, Aprendiz de Cronomante","Feitiço",[],["Shurima"],"COMUM"],"04SH070":["Indigno","Conceda -4|-0 a um seguidor inimigo nesta rodada.\nAbata-o se você tiver menos gemas de Mana do que o oponente.","","\"O sol voltará a brilhar nas terras shurimanes.\" – Voz dos Renascidos","Feitiço",[],["Shurima"],"ÉPICO (A)"],"04SH081":["Fiandeira Baccai","Jogar: Dê -1|-0 e Vulnerável a um inimigo.","","Cada grão derrubado por ela rouba-lhes um segundo da vida, que se esvanece como areia ao vento.","Unidade",[],["Shurima"],"RARO (A)"],"04SH077":["Voz dos Reerguidos","Se você tiver subido um Campeão de nível, os aliados ganham +2|+0.","","\"Tempos atrás, eu a ouvi falar.\" O velho soldado sorriu e, por um instante, sua neta conseguiu imaginar: Shurima, dourada e reluzente, com o imponente Azir governando a cidade anunciada pela Voz dos Renascidos. \"Ela resgatou em nós uma paixão há muito adormecida.\"","Unidade",[],["Shurima"],"ÉPICO (A)"],"04SH019":["Rek'Sai","Quando eu Espreitar ou Atacar: Dê +1|+0 a aliados Espreitadores globalmente.\nFim de Rodada: Me coloque no seu deck.","Eu ataquei com 10+ de Poder.","\"O jovem Jhuraa estava explorando uma pequena caverna oculta, como já era de costume, quando se deparou com pergaminhos antigos! Levamos os artefatos para um tradutor em Medumarca, e neles... havia textos descrevendo um terror ancestral que perseguia nossos antepassados. Uma rainha. A rainha dos xer'sai!\" – Fezhaur, ancião de Vekaura","Unidade",["ESPREITADOR"],["Shurima"],"Campeão"],"04SH138":["A Penitência","Conceda +2|+1 a um aliado nesta rodada. Se tiver subido o nível de um Campeão nesta partida, crie 1 O Retorno da Penitência na mão.","","''Todos me disseram para não usá-lo. 'Ninguém deve empunhar uma arma tão poderosa'.'' – Akshan","Feitiço",[],["Shurima"],"COMUM"],"04SH089":["Naturalista do Deserto","Jogar: Destrua um Monumento. Se ele for aliado, invoque 1 Pedregurso Ranzinza.","","\"Kadira quebrou outra coisa hoje! Dessa vez, foi só uma parede de pedra, mas ela parecia bem antiga e deve ter sido importante para os antepassados de alguém. Ela tentou se safar dizendo que, em Tereshni, as paredes eram mais resistentes! Enfim, fiquei superirritada!\"\n– Diário de Zaifa","Unidade",[],["Shurima"],"RARO (A)"],"04SH015":["Raz Sanguescama","Atacar: Conceda -2|-0 a inimigos nesta rodada.","","\"Quando esse crocodilão nasceu, fizeram apostas pra adivinhar quanto tempo ele sobreviveria. Diziam que ele era uma aberração, o fracote da ninhada... mas ninguém pensou que ele acabaria devorando todos os irmãos. Hehe.\"","Unidade",[],["Shurima"],"ÉPICO (A)"],"04SH058":["Artífice das Areias","Atacar: Invoque 1 Soldado de Areia atacante.","","Poucos aprendem os mistérios do deserto, e quase ninguém consegue comandar suas areias como Azir. Dominar esse poder e conhecer os segredos das areias é uma dádiva concedida apenas aos seguidores mais fiéis e capazes de Azir.","Unidade",[],["Shurima"],"COMUM"],"04SH080":["Convocação do Bando","Para me pôr em jogo, coloque uma carta da mão no topo do seu deck.\nCrie 2 Espreitadores aleatórios na mão.","","\"Que o sol continue brilhando e os xer'sai permaneçam dormindo.\"\n– Oração dos Mercadores","Feitiço",[],["Shurima"],"COMUM"],"04SH035":["Dia do Pagamento","Crie 1 Descoberta de Sorte na mão.","","\"É claro que, como todo mundo, eu já tive dias bons e dias ruins. No meu ramo, os dias ruins podem ser horríveis... mas os dias bons podem ser interessantes à beça.\" – Sivir","Feitiço",[],["Shurima"],"COMUM"],"04SH028":["Preparativos Ancestrais","Jogar: Preveja.\nContagem 2: Invoque 1 Relologi.","","Alguns podem pensar que os autômatos se perderam no tempo, enterrados sob anos de areia acumulada. Na verdade, eles foram estrategicamente posicionados, e apenas esperam o momento do despertar.","Monumento",[],["Shurima"],"COMUM"],"04SH054":["Caçadora de Tesouros","Ao me invocar, crie 1 Areias Despertas na mão.","","\"Beleza, Davu. Você vai entrar, vai pegar... o que quer que tenha lá e vai deixar a gente rico. Me deixar rica. Você vai me deixar muito rica, entendeu? Ah, e se isso for uma armadilha, peço desculpas desde já.\"","Unidade",[],["Shurima"],"COMUM"],"04SH002":["Ceifeiro Baccai","Quando você Elimina uma unidade, eu ganho +1|+0.","","\"Todos os baccai fugiram ou foram poupados de seu sofrimento após Ascensões malsucedidas, e ninguém nunca os viu desde então. Quem sabe há quanto tempo estão escondidos naquelas tumbas sombrias carregando o peso de seu fracasso?\" – Escriba Kah'nir, História do Batalhão dos Ascendentes","Unidade",[],["Shurima"],"RARO (A)"],"04SH042":["Pedregurso Hibernado","Contagem 3 : Invoque 1 Pedregurso Ranzinza.","","\"MEU NOME É ZAIFA, E EU GOSTO DE ESCREVER COISAS SEM GRAÇA NO MEU DIÁRIO SEM GRAÇA QUANDO ACHO QUE TODOS ESTÃO DORMINDO. ATÉ O SAMI.\"\n– Diário de Zaifa","Monumento",[],["Shurima"],"COMUM"],"04SH032":["Trituradora Impiedosa","Reputação: Eu custo 1 a menos e, ao me invocar, eu ganho Sobrepujar.","","O soldado, com a força que lhe restava, tentou pegar a lança, mas aquela mulher aplicou ainda mais força sobre seu peito, até ele desistir. \"Nada disso\", repreendeu ela, mostrando os dentes afiados em um sorriso perverso. \"Agora ela é minha.\"","Unidade",[],["Shurima"],"COMUM"],"04SH055":["Exploradora das Ruínas","","","Antes de tentarem a sorte nas criptas, os mercenários e saqueadores de tumbas de Shurima precisam aprender a enfrentar as ameaças mais difusas do deserto. Primeiro, o calor escaldante. Depois, os inúmeros incursores dispostos a fazer carnificina.","Unidade",[],["Shurima"],"COMUM"],"04SH039":["Zilean","Jogar: Crie 4 Bombas-relógio no seu deck. Depois, Preveja.","Vi você destruir 2+ cartas Bombas-relógio aliadas.","Ao longo de muitos anos, Zilean criou uma rede de jovens magos promissores de vários tempos, todos capazes de continuar sua obra caso o impensável viesse a acontecer. Apesar de ser um mentor gentil e dedicado, quando buscava a solidão, uma profunda sensação de cansaço e sofrimento recaía sobre ele. Algo que só quem já viveu muitas vidas seria capaz de entender.","Unidade",[],["Shurima"],"Campeão"],"04SH073":["Taliyah","Jogar: Invoque uma cópia idêntica a um Monumento aliado.","Você invocou 5+ Monumentos.","\"O passo do nômade é sempre leve, pois é destituído do peso das raízes, e seu lar está sempre além do horizonte.\"\n– As Sociedades de Shurima","Unidade",[],["Shurima"],"Campeão"],"04SH091":["Khahiri, o Aluno","Ao me invocar, se você tiver Previsto nesta partida, eu ganho +1|+1.","","\"Lembre-se do que aprendemos\", disse Zilean, com a voz mais suave do que o normal. \"Tem certeza de que está pronto?\"\nKhahiri abriu um sorriso confiante para o mentor. \"Eu volto logo. Além disso, passei anos me preparando para este momento. Se não agora, quando?\"","Unidade",[],["Shurima"],"COMUM"],"04SH024":["Pináculo de Sal","Contagem 2: Invoque 1 Pedregurso Ranzinza. Se você tiver invocado 4+ Monumentos nesta partida, dê +2|+2 ao aliado Mais Forte.","","Os shurimanes que trabalham com sal aprendem rápido a reconhecer quais depósitos são bons para coleta e quais devem ser deixados em paz.","Monumento",[],["Shurima"],"COMUM"],"04SH003":["Azir","Quando aliados atacarem, invoque 1 Soldado de Areia atacante.","Você invocou 12+ aliados ou Monumentos.","\"Azir, quando assumiu o manto de imperador de Shurima, era uma pessoa arrogante, cega. Ele acumulou poderes e planejou sua Ascensão de forma a governar não apenas Shurima, mas o mundo inteiro.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes","Unidade",["ASCENDENTE","AVE"],["Shurima"],"Campeão"],"04SH011":["Pesquisadoras de Xenótipo","Ao me invocar, dê +3|+3 a 3 aliados aleatórios no seu deck.","","O Vazio traz consigo inúmeras surpresas. Crescendo ininterruptamente e encontrando cada vez mais formas de se infiltrar na torre, assemelha-se a um espinheiro invasivo, mas é infinitamente mais letal. Infelizmente, estudá-lo é algo difícil de se fazer, já que é preciso ter pesquisadores hábeis e talentosos que possam entender e prever sua ameaça.","Unidade",[],["Shurima"],"RARO (A)"],"04SH130":["Akshan","Ao me invocar ou Golpear: Invoque 1 Palácio do Senhor da Guerra ou Avance esse Monumento 1 rodada.","Palácio do Senhor da Guerra terminou sua Contagem. Quando eu subir de nível, invoque 1 Tesouro do Senhor da Guerra.","''O código dos Sentinelas tem muitas restrições complicadas. Coisas como 'Nunca tire uma vida em nome da vingança' e 'Lute pelo mundo, não por si mesmo'. Já eu...''","Unidade",[],["Shurima"],"Campeão"],"04SH114":["Ira do Deserto","Dê +1|+0 aos Soldados de Areia aliados globalmente.\nInvoque 2 Soldados de Areia.","","Eles não descansam. Eles não hesitam. Eles são intratáveis, insensíveis e inflexíveis.","Feitiço",[],["Shurima"],"RARO (A)"],"04SH067":["Renekton","Quando eu Desafiar um inimigo, me conceda +2|+1 nesta rodada.","Causei 10+ de dano.","\"É muito fácil esquecer que um dia ele já foi humano, pois a imagem crocodiliana lhe cai muito bem, dado o amor pela crueldade da batalha...\" – Escriba Kah'nir, História do Batalhão dos Ascendentes","Unidade",["ASCENDENTE","RÉPTIL"],["Shurima"],"Campeão"],"04SH120":["Possibilidades Imaginadas","Crie um Monumento aleatório com Contagem na mão ou Avance seus Monumentos em 1 rodada.","","\"O tempo é evanescente.\" – Zilean","Feitiço",[],["Shurima"],"RARO (A)"],"04SH119":["Ricochete","Reputação: Eu custo 3 a menos.\nCause 1 de dano a um inimigo aleatório ou ao Nexus inimigo 5 vezes.","","\"Acho que a coisa vai esquentar.\" – Sivir","Feitiço",[],["Shurima"],"COMUM"],"04SH068":["Evocador Xer'Sai","Jogar: Preveja.","","Nem todos os xer'sai nascem para matar. Alguns nascem para invocar outros da espécie com chamados agudos que estremecem as areias e os sentidos de qualquer um.","Unidade",["ESPREITADOR"],["Shurima"],"COMUM"],"04SH093":["Pedra Esculpida","Conceda +1|+1 a um aliado nesta rodada.\nSe tiver invocado um Monumento nesta partida, conceda +2|+1.","","\"Com a ajuda da terra, nós VAMOS nos defender!\" – Taliyah","Feitiço",[],["Shurima"],"COMUM"],"04SH079":["Areias Videntes","Preveja.\nConceda -2|-0 a um inimigo nesta rodada.","","\"Eu vi o meu destino e, desta vez, não serei detido.\" – Azir","Feitiço",[],["Shurima"],"RARO (A)"],"04SH038":["Saltador de Pedras","Ao me invocar, invoque 1 Areias Instáveis.","","“Hoje, iniciamos nossa jornada até Nashramae! Samir quer atravessar o Grande Sai antes da próxima lua cheia e está destruindo TUDO pela frente! Eu não sabia que uma simples prancha podia derrubar uma duna inteira. O Sami também não, mas ele está bem.\"\n– Diário de Zaifa","Unidade",[],["Shurima"],"COMUM"],"04SH104":["Preservacionista","Jogar: Avance um Monumento aliado em 3 rodadas.","","Sempre que quer um momento de paz, Zilean volta ao último jardim de Icathia, ainda intocado.","Unidade",[],["Shurima"],"RARO (A)"],"04SH128":["Errante de Vekaura","Ao me invocar, invoque 1 Palácio do Senhor da Guerra ou Avance esse Monumento em 2 rodadas.","","Ao ver Akshan pendurado na janela do quarto andar, Najah xingou baixinho. O bonitão chegara mais rápido. De novo. Revirando a adaga na mão, ela pensou no que diria a ele. Quem sabe, dessa vez ele finalmente demonstraria algum respeito.","Unidade",[],["Shurima"],"COMUM"],"04SH109":["Areia Movediça","Conceda -4|-0 a um inimigo ou -1|-0 a 2 inimigos nesta rodada. Desative as palavras-chave positivas deles nesta rodada.","","Em partes do deserto, ruínas antigas foram soterradas, criando buracos que levam viajantes desavisados pelo mesmo caminho. ","Feitiço",["ELEMENTAL"],["Shurima"],"COMUM"],"04SH043":["Areias Oscilantes","Cause 4 de dano a uma unidade.\nInvoque 2 Soldados de Areia.","","\"Ataquem. Cerquem-nos. Eles não são capazes de lutar contra esta terra.\" – Azir","Feitiço",[],["Shurima"],"RARO (A)"],"04SH099":["Surja!","Invoque 1 Soldado de Areia.\nCrie 1 Surja! Fugaz na mão.","","\"A ordem foi dada.\" – Azir","Feitiço",[],["Shurima"],"RARO (A)"],"04SH048":["Sacrário Interior","Reputação: Eu custo 3 a menos.\nContagem: 1 – Crie 2 Descobertas de Sorte na mão.","","\"Alguns mapas levam anos para serem decifrados, algumas armadilhas levam meses para serem desmontadas, e algumas criptas levam semanas para serem exploradas. Mas, quando finalmente conseguimos, vemos que cada segundo valeu a pena.\" – Sivir","Monumento",[],["Shurima"],"COMUM"],"04SH056":["Barganhadora","Ao me invocar, crie 1 Descoberta de Sorte na mão.","","\"Meu amigo, consegui para você esta raridade de beleza incomparável na lendária Tumba dos Imperadores e a retirei das mãos do grande Renekton. Na saída, fui cercada por dez, vinte cavaleiros montados em saurens sedentos de sangue! É um verdadeiro milagre que essa relíquia tenha vindo parar nas suas mãos.\"","Unidade",[],["Shurima"],"COMUM"],"04SH020":["Sivir","","Você causou 30+ de dano.","Sivir navegou pelos caminhos da vida como mercenária, assumindo todos os riscos e recompensas que acompanhavam sua escolha. Porém, quando uma fatídica expedição quase lhe custou tudo, o sangue que deixava seu corpo se encarregou de acordar um poder ancestral que elevaria tanto ela quanto Shurima à glória.","Unidade",[],["Shurima"],"Campeão"],"04SH057":["Marechal Inspiradora","Quando você invocar outro aliado, conceda +2|+0 a ele nesta rodada.","","Receber a bênção de Azir é uma grande honra. Dar uma bênção em nome dele, uma honra maior ainda.","Unidade",[],["Shurima"],"RARO (A)"],"04SH103":["Caçadora Implacável","Jogar: Dê Vulnerável a um inimigo.","","\"E... pronto. Bem amarradinho. Renekton gosta quando suas refeições ainda estão se contorcendo.\"","Unidade",[],["Shurima"],"COMUM"],"04SH065":["Xerxa'reth, o Titã Subterrâneo","Atacar: Se eu tiver 8+ de Poder, me conceda Assustador, Sobrepujar e Escudo de Feitiço nesta rodada.","","\"Dizem que, há centenas de anos, o grande posto avançado conhecido como Taraleek servia como ponto de troca de mercadorias nas margens do rio Khaleek. Porém, em um dia fatídico, uma criatura poderosa se ergueu do chão, aniquilando o local e todos que o chamavam de lar. Mas que tipo de monstro faria algo assim?\" – Historiador shurimane","Unidade",["ESPREITADOR"],["Shurima"],"ÉPICO (A)"],"04SH034":["A Mão do Relógio","Ao me invocar, crie 2 Séculos Instantâneos na mão.","","O constante ruído nos níveis inferiores da torre são causados pela Mão do Relógio, o guardião que controla as engrenagens lá embaixo.","Unidade",[],["Shurima"],"ÉPICO (A)"],"04SH082":["Caminho Ruinoso","Compre 1.\nSe tiver Eliminado uma unidade nesta rodada, Drene 2 do Nexus inimigo.","","Os Escavareias recrutam primeiro nos ranques inimigos. Quem sobrevive aos ataques, tem que escolher entre ficar com eles ou morrer.","Feitiço",[],["Shurima"],"RARO (A)"],"04SH075":["Decreto do Imperador","Conceda Vulnerável aos inimigos nesta rodada e invoque 6 Soldados de Areia.","","\"Meus soldados marcham.\" – Azir","Feitiço",[],["Shurima"],"ÉPICO (A)"],"04SH018":["Ritual de Dominância","Abata um aliado ou destrua uma de suas gemas de Mana para conceder -2|-0 a todos os inimigos nesta rodada.","","\"Nós lutamos, eles sangram!\" – Renekton","Feitiço",[],["Shurima"],"RARO (A)"],"04SH009":["Baccai Enfurecido","Jogar: Se você tiver Eliminado 4+ unidades nesta partida, um inimigo e eu nos Golpeamos.","","Quem guarda rancor alimenta cada vez mais esse sentimento, mesmo que os responsáveis por ele já estejam mortos há muito tempo.","Unidade",[],["Shurima"],"RARO (A)"],"04SH049":["Poro Destinado","Início de Rodada: Se você tiver subido um Campeão de nível, eu me transformo em Poro Venerado.","","Ele não sabia exatamente o que tinha encontrado... mas brilhava bastante e parecia o lanche ideal.","Unidade",["PORO"],["Shurima"],"COMUM"],"04SH045":["Exaustão","Conceda -2|-0 e Vulnerável a um inimigo nesta rodada.","","Os povos do deserto estão acostumados a lidar com o calor escaldante e implacável do sol, mas, quem não está, perde todas as forças em pouquíssimo tempo.","Feitiço",[],["Shurima"],"COMUM"],"04SH037":["Terra Desfiada","Invoque 2 Areias Instáveis.\nCompre 1.","","O Grande Sai é lindo de morrer, e isso vale especialmente para os fracos – muitas vidas já foram perdidas em suas dunas. Embora sejam os xer'sai quem ceifam grande parte delas, a terra também tem sua parcela de culpa.","Feitiço",["ELEMENTAL"],["Shurima"],"RARO (A)"],"04SH107":["Glória dos Ascendentes","Suba o nível de todos os aliados Ascendentes de nível 1.","","\"O futuro será escrito pela Ascensão!\" – Azir","Feitiço",[],["Shurima"],"ÉPICO (A)"],"04SH047":["Nasus","Tenho +1|+1 para cada unidade Eliminada por você nesta partida.","Eu Golpeei causando 10+ de dano com um Golpe.","\"A nova bênção recebida por Nasus permitiu que ele passasse várias vidas estudando e refletindo sobre a natureza da vida e da morte. Mas essa mesma existência prolongada, depois da queda de Shurima, viria a ser sua maldição.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes","Unidade",["ASCENDENTE","CANINO"],["Shurima"],"Campeão"],"04SH097":["Guardiã do Sacrário","Jogar: Abata um seguidor inimigo. Em vez disso, se você tiver Eliminado 13+ unidades nesta partida, abata todos os seguidores inimigos e depois invoque uma cópia minha.","","Os baccai são responsáveis por defender o sacrário interior, proteger os tesouros antigos que estão lá dentro e zelar pelos mortais que se acham espertos ou poderosos demais para resistir ao peso do julgamento do Curador.","Unidade",[],["Shurima"],"ÉPICO (A)"],"04SH026":["Vigilante das Dunas","Ao me invocar, invoque 1 Soldado de Areia.","","\"O imperador comanda. Eu e a areia obedecemos.\"","Unidade",[],["Shurima"],"COMUM"],"04SH102":["Embaixadora Dourada","Lealdade: Compre um Campeão e dê +2|+2 a ele.","","\"Nosso futuro glorioso está sob as areias, e cabe a nós pavimentar o caminho para Azir. O império dourado do deserto renascerá!\"","Unidade",[],["Shurima"],"COMUM"],"04SH001":["Aprendiz de Cronomante","Jogar: Preveja.","","Durante seu dias como estudante de cronomancia, Tai precisou aprender a conciliar a incerteza com a determinação. Era melhor depositar esperança em uma possível vitória do que ficar pensando no que poderia dar errado.","Unidade",[],["Shurima"],"COMUM"],"04SH022":["Devastadunas Xer'Sai","","","Mesmo que todos os xer'sai sejam hábeis cavadores de túneis, apenas os devastadunas têm o tamanho e o poder necessários para atravessar os leitos rochosos que serpenteiam o Grande Sai, abrindo caminhos e aumentando suas oportunidades de caça em outros locais.","Unidade",["ESPREITADOR"],["Shurima"],"RARO (A)"],"04SH030":["Alteração Temporal","Conceda \"Da próxima vez que eu morrer nesta rodada, eu me curo completamente e ganho +3|+3\" a um Campeão aliado.","","\"Não podemos impedir o inevitável... mas podemos adiar.\"\n– Zilean","Feitiço",[],["Shurima"],"RARO (A)"],"04SH013":["Preservário","Ao me invocar, compre 1.\nContagem 2 : Compre 1.","","Zilean mostra aos que traz à torre o que, de fato, estão tentando restaurar. O Preservacionista consegue lhes mostrar tudo, mesmo que apenas por um breve momento.","Monumento",[],["Shurima"],"RARO (A)"],"04SH062":["Disco Solar Soterrado","Início da Partida: Invoque 1 cópia minha do seu deck se todas as suas cartas forem de Shurima.\nContagem 25: Restaure o Disco Solar.\nEu Avanço 9 rodadas para cada vez que um aliado Ascendente subiu de nível nesta partida.","","Quando Azir avistou o Disco Solar da capital shurimane, ele não enxergou meramente o que era, mas o que poderia vir a ser: a chave para restaurar a antiga glória de Shurima.","Monumento",[],["Shurima"],"ÉPICO (A)"],"04SH016":["Ataque Sifão","Um aliado Golpeia uma unidade.\nSe ela morrer, dê +2|+2 a Campeões aliados globalmente.","","\"Sua alma será avaliada.\" – Nasus","Feitiço",[],["Shurima"],"RARO (A)"],"04SH125":["Larápia de Vekaura","Jogar: Conceda +2|+0 a um aliado para conceder -2|-0 a um inimigo nesta rodada.","","Tena esperou pacientemente até a saliva cáustica de seu bichinho corroer as grades douradas do portão dos fundos do palácio. Ela estava prestes a encontrar um tesouro de valor inestimável; mais que suficiente para restituir a antiga glória de Vekaura.","Unidade",[],["Shurima"],"RARO (A)"],"04SH108":["Lâmina Bumerangue","Um aliado Golpeia o inimigo Mais Forte e o Mais Fraco em sequência.","","\"Melhor abaixar!\" – Sivir","Feitiço",[],["Shurima"],"RARO (A)"],"04SH066":["Tempo Engarrafado","Preveja e Avance um Monumento aliado em 2 rodadas.","","\"Se você visse o tempo como eu vejo, saberia que ele não é imutável.\" – Zilean","Feitiço",[],["Shurima"],"COMUM"],"04SH021":["Khahiri, o Regressado","Ao me invocar, crie uma cópia minha no seu deck. Quando você me vir em uma Previsão, dê +2|+2 a todas as minhas cópias aliadas globalmente.","","Khahiri sumiu por apenas um instante antes de reaparecer repentinamente. Recebido por suspiros de surpresa e preocupação, ele estava praticamente uma década mais velho e empunhava uma arma estranha de aparência letal.","Unidade",[],["Shurima"],"RARO (A)"],"04SH101":["Conselheiros Devotos","Início de Rodada: Se você tiver subido um Campeão de nível, cure seus Campeões e seu Nexus em 2.","","\"Jurei fidelidade a Azir e a Shurima, meu lar! Não vai fazer o mesmo?\"","Unidade",[],["Shurima"],"RARO (A)"],"04SH012":["Hierofante Consagrado","Ao me invocar, avance sua cópia de Disco Solar Soterrado em 3 rodadas.","","\"Olha lá! É Padjuman, um dos anciãos de Nashramae! Eu acho que todo mundo veio aqui pra cidade, papai!\" – Espectador empolgado","Unidade",[],["Shurima"],"COMUM"],"04SH031":["Futuro Promissor","Dê \"o efeito de conclusão da minha Contagem é acionado duas vezes\" a um Monumento aliado.","","\"Os mortais passam tanto tempo esperando... Desejo que todos sejam recompensados por tanta paciência.\" – Zilean","Feitiço",[],["Shurima"],"ÉPICO (A)"],"04SH004":["Peso do Julgamento","Cause 2 de dano a um Campeão ou 4 de dano a um seguidor.","","\"Uma vida a troco de muitas outras. Uma vida em troca da prosperidade geral.\" – Nasus","Feitiço",[],["Shurima"],"COMUM"],"04SH059":["Ritual de Negação","Abata um aliado ou destrua uma de suas gemas de Mana para interromper todos os feitiços Rápidos, feitiços Lentos e Habilidades dos inimigos.","","A análise é a base da cronomancia, pois muitas ações devem ser interrompidas em prol da busca por soluções futuras.","Feitiço",[],["Shurima"],"ÉPICO (A)"],"04SH044":["Curador Mecanizado","Jogar: Avance um Monumento aliado em 2 rodadas.","","As estruturas que protegem a torre de Zilean são capazes de suportar a rigidez do deserto por milênios – e não é só por conta da construção engenhosa.","Unidade",[],["Shurima"],"COMUM"],"04SH076":["Ampulheta Ancestral","Oblitere um aliado para invocar 1 Estátua de Estase em seu lugar com a unidade retida em seu interior.","","\"Vem cá, Tai! Precisamos da sua ajuda com uma coisa.\"\n– Xetsa, Pesquisadora do Vazio","Feitiço",[],["Shurima"],"RARO (A)"],"04SH118":["Areias Despertas","Invoque 1 Combatente de Arenito.","","\"A caixa pode valer alguma coisa, mas o que tem dentro não deve valer nem um grão de areia. Ou seja, não vale a pena abrir. Falo por experiência.\" – Sivir","Feitiço",[],["Shurima"],"COMUM"],"04SH072":["Profetisa","Ao me invocar, dê Escudo de Feitiço a Monumentos e Campeões aliados.","","\"Ah, você não esperava encontrar água no meio do deserto, né? Não se preocupe. Venha, beba um pouco, lave os pés. Descanse na sombra. A nova Shurima de Azir é um verdadeiro oásis.\"","Unidade",[],["Shurima"],"COMUM"],"04SH041":["Vigilante do Sai","Jogar: Preveja. Se você escolher um Monumento, eu ganho Elusivo.","","\"Hoje tivemos problemas! Uma tempestade enorme começou a dar as caras pelo oeste, e Taliyah atravessou túneis xer'sai rumo ao sul. Eu descobri um templo ao norte, e agora estamos protegidos pelos muros de terracota. Os outros já estão dormindo, e as chamas, assim como eu, estão se esgotando. Espero ter bons sonhos.\"\n– Diário de Zaifa","Unidade",[],["Shurima"],"COMUM"],"04SH005":["Saqueador Sanguinário","","","Os Escavareias fazem tudo com os companheiros: lutam, caçam, matam... e se alimentam.","Unidade",[],["Shurima"],"COMUM"],"04SH083":["Presságio Voraz","Preveja.","","\"As barbatanas trazem medo, mas os dentes trazem mortes.\" – Ditado shurimane","Feitiço",[],["Shurima"],"RARO (A)"],"04SH092":["Chegou A Hora","Invoque 1 Relologi.\nSe você já tiver Previsto nesta partida, invoque 2.","","\"Vem cá e para de reclamar! Você está com areia nas engrenagens.\" – Tai, Aprendiz de Cronomante","Feitiço",[],["Shurima"],"COMUM"],"04SH046":["Quimera de Arenito","Eu custo 1 a menos para cada vez que um aliado tiver atacado nesta partida.","","Quando Azir voltou, os shurimanes viram feras lendárias que, apesar de serem de areia, eram muito impressionantes.","Unidade",[],["Shurima"],"RARO (A)"],"04SH105":["Tumba Arenosa","Quando aliados atacarem, invoque 1 Combatente de Arenito atacante.","","Enquanto eles passavam pelo desfiladeiro, a Artífice das Areias entoou as palavras mágicas. Uma rajada de vento ecoou pelo cânion e se voltou contra a trovoada de cascos galopantes.","Monumento",[],["Shurima"],"RARO (A)"],"04SH131":["Golpe de Arpéu","Um aliado que você alvejou nesta rodada Golpeia um inimigo.","","''Meu arpéu pega todos de surpresa!'' – Akshan","Feitiço",[],["Shurima"],"RARO (A)"],"04SH074":["Filhote Xer'Sai","","","Ocasionalmente, após dizimarem uma caravana, os caçadores recuam e permitem que seus filhotes pilhem os escombros. É aqui que os jovens xer'sai aprimoram seus instintos, aprendendo quais sons pertencem à paisagem desértica e quais indicam novas presas.","Unidade",["ESPREITADOR"],["Shurima"],"COMUM"],"04SH137":["Enxame Ruidoso","Ao me invocar, crie uma cópia minha na mão se já tiver subido o nível de um Campeão nesta partida.","","Acreditava-se que os escaravelhos gigantes tinham sumido junto com o império Shurimane. Mas ramos rastejantes da Névoa se infiltraram nas areias e os arrancaram de lá para servirem a Viego.\n","Unidade",[],["Shurima"],"ÉPICO (A)"],"04SH069":["Predador Desumano","Conceda +2|+0 a um aliado para conceder Vulnerável a um inimigo nesta rodada.","","\"Todos serão dilacerados!\" – Renekton","Feitiço",[],["Shurima"],"COMUM"],"04SH121":["Ritual de Chamado","Abata um aliado ou destrua uma de suas gemas de Mana para comprar um Campeão.","","\"Um sacrifício necessário.\" – Nasus","Feitiço",[],["Shurima"],"COMUM"],"04SH110":["Tecepedras","Manifeste um Monumento de custo acessível.","","\"Vamos! Ainda há tanto para ver!\" – Taliyah","Feitiço",["ELEMENTAL"],["Shurima"],"ÉPICO (A)"],"04SH051":["Palanque do Imperador","Quando aliados atacarem, invoque 1 Soldado de Areia atacante.","","Os Artífices das Areias ergueram as mãos, moldando a areia e formando conhecidos soldados blindados e sem rosto – um exército incansável e pronto para lutar pelo deus-imperador. ","Monumento",[],["Shurima"],"RARO (A)"],"04SH106":["Fogo Espiritual","Conceda aos inimigos -2|-0 e \"Fim de Rodada: Cause 2 de dano a mim\" nesta rodada.","","\"O espírito deles vai arder.\" – Nasus","Feitiço",[],["Shurima"],"RARO (A)"],"04SH129":["Brutamontes de Vekaura","Golpear: Crie 1 Descoberta de Sorte na mão.","","''Pronto, Barb. Esse era o último guarda deste andar, mas ainda precisamos ter cuidado.''\n''BLARGH-BLAAA!''\n''Fale baixo, Bárbara.''\n''Blarb.''\n''É isso aí, garota.''","Unidade",[],["Shurima"],"RARO (A)"],"04FR006":["Inquisidor Draklorn","Ao me invocar, invoque 1 Servo Congelado.\nFim de Rodada: Se a Contagem de qualquer um dos seus Servos Congelados for 4 ou menos, Avance-a para 0.","","\"Minha soberana se comunica comigo em sonhos, a voz jamais excedendo um sussurro. 'Siga-me', diz ela. Esse é um comando que não posso desobedecer.\"","Unidade",[],["Freljord"],"ÉPICO (A)"],"04FR012":["Clausura Gélida","Oblitere todos os inimigos para invocar 1 Túmulo Congelado em seus lugares com o inimigo retido em seu interior.","","\"Mais cedo ou mais tarde, o frio domina tudo.\" – Lissandra","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"04FR016":["Despojos de Guerra","Dê +1|+2 a um aliado.\nSaquear: Dê +2|+4.","","\"Os avarosianos ficam cada vez mais fracos e opulentos em suas terras férteis. Descansem, fracotes desprezíveis. Enquanto vocês sonham com a fartura de amanhã, nós a tomaremos.\" – Vrynna, Mãe das Cicatrizes","Feitiço",[],["Freljord"],"COMUM"],"04FR013":["Resistência ao Frio","Receba uma gema de Mana vazia e dê +0|+2 a um aliado.","","\"Tenha cuidado com o gelo... mas, acima de tudo... cuidado com o que há dentro dele!\" – Rabiscos na parede de uma hospedaria freljordana","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"04FR005":["Lissandra","Ao me invocar, invoque 1 Servo Congelado e Avance esse Monumento 2 rodadas.","Você invocou 2+ aliados de custo 8+. Quando eu subir de nível, crie 1 Observador na mão.","\"Além desses muros, espreitam os Observadores, suspensos nas camadas de gelo, congelados no tempo... Enquanto aguardam, preciso dar início aos meus planos...\"","Unidade",[],["Freljord"],"Campeão"],"04FR011":["Sucumba ao Frio","Congele um inimigo.\nInvoque 1 Servo Congelado.","","\"O frio suscita muitas reações. Vamos ver qual será a sua.\"\n– Lissandra","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"04FR001":["Servo Congelado","Contagem 9: Invoque 1 Servo Praeglacius.","","Sem sombra de dúvidas, havia muitos guerreiros imbecis no exército desordenado de Trundle que poderiam ser usados como escudos descartáveis na linha de frente, mas Lissandra queria algo mais leal, algo que servisse a ela e somente a ela...","Monumento",[],["Freljord"],"COMUM"],"04FR007":["Sepultamento","Oblitere uma unidade para invocar 1 Túmulo Congelado em seu lugar com a unidade retida em seu interior.","","\"Curve-se ou congele.\" – Lissandra","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"04FR017":["Dádiva Ancestral","Dê +2|+2 ao aliado no topo do seu deck.\nIluminado: Dê +2|+2 a todos os aliados no seu deck.","","O frio implacável e as nevascas excruciantes de Freljord matam a maioria dos que entram nessas terras desoladas. Porém, os que sobrevivem encontram em si uma força que os faz perseverar pelo resto de suas vidas.","Feitiço",[],["Freljord"],"COMUM"],"04FR014":["Ravina Arruinada","Ao me invocar, cure o seu Nexus em 2.\nContagem 1: Cause 2 de dano a TODAS as unidades.","","Formas bizarras feitas de gelo sombrio surgem por toda a ravina, e seus espinhos externos afugentam qualquer intruso em potencial.","Monumento",[],["Freljord"],"RARO (A)"],"04FR009":["Estilhaço de Gelo","Cause 1 de dano a TUDO.","","\"Eu enterrarei o mundo em gelo.\" – Lissandra","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"04FR015":["Poro Mitológico","Ao me invocar, dê uma palavra-chave aleatória aos Poros aliados.","","Dizem que há uma figura lendária conhecida por todos os poros. Contam que, durante suas viagens, ele dá todos os tipos de presentes mágicos aos mais dignos de seus amigos peludos.","Unidade",["PORO"],["Freljord"],"RARO (A)"],"04FR019":["Matriarca das Glacipresas","Ao me invocar, invoque 1 Matilha das Glacipresas.","","Os lobos das Glacipresas, agachados e cautelosos, cercaram o drüvask. O cheiro da morte, mordaz e intenso, impregnava o ar.","Unidade",["CANINO"],["Freljord"],"RARO (A)"],"04FR018":["Abominável Guardião das Neves","Enquanto eu estiver na mão, no Início de Rodada: Se você tiver 2+ Yetis, me invoque e crie uma cópia minha no seu deck.\nJogar: Compre um Yeti.","","\"... e, além de tudo, são sorrateiros! Da última vez em que estive lá, me abriguei numa caverna e acabei encontrando alguns filhotes dormindo. Tentei manter distância, mas um dos grandões voltou bem na hora. Era grande feito uma montanha e estava coberto de neve! E não para por aí, porque depois...\" – Bjerg Balbuciador","Unidade",["YETI"],["Freljord"],"ÉPICO (A)"],"04FR010":["Três Irmãs","Crie 1 Lampejo Congelado, Fúria do Norte ou Sepultamento Fugaz na mão.","","As irmãs freljordanas Avarosa, Serylda e Lissandra contavam com enorme poder, mas cada uma escolheu usá-lo de forma diferente: uma com misericórdia, outra com militarismo e outra com malícia.","Feitiço",[],["Freljord"],"RARO (A)"],"04NX002":["Palavras Sussurradas","Reputação: Eu custo 2 a menos.\nCompre 2.","","Antes das notícias, vêm os boatos. Antes dos boatos, o acontecimento. Antes do acontecimento, a intenção.","Feitiço",[],["Noxus"],"RARO (A)"],"04NX010":["Espinho da Rosa","Ao me invocar, crie 1 Astúcia na mão.","","\"Aelana, minha querida amiga! Por acaso já falou com o Lorde Duin? Ah, que pena. Eu mal via a hora de colocar o papo em dia. Espero que ele não tenha se afobado hoje. Eu não gostaria nada se alguma coisa acontecesse com o nosso companheiro...\" – Lady Auvray, Espiã da Rosa Negra","Unidade",[],["Noxus"],"COMUM"],"04NX021":["Desafiador Emérito","Quando você me alveja, eu ganho +1|+0.","","Após inúmeras batalhas, Beryn jurou nunca mais empunhar uma espada, mesmo que isso significasse abrir mão da própria vida. Mas quando a estranha névoa avançou sobre Noxus e dominou Thea, ele soube que teria de quebrar seu juramento, pois iria salvá-la a qualquer custo.","Unidade",[],["Noxus"],"RARO (A)"],"04NX022":["Desafiadora Destruída","Ao me invocar, crie 1 Incursão Noturna na mão.","","Ao final de sua sentença, Thea sabia que nunca voltaria para casa. A guerra – e Noxus – tinham feito dela uma assassina. Ela nunca teria paz. Sendo assim, ela resolveu tirar proveito de suas novas habilidades na arena.","Unidade",[],["Noxus"],"RARO (A)"],"04NX015":["Negócios Sangrentos","Reputação: Eu custo 2 a menos.\nUm aliado com 5+ de Poder Golpeia um inimigo.","","\"As piores ameaças são aquelas que ninguém vê.\" – LeBlanc","Feitiço",[],["Noxus"],"COMUM"],"04NX019":["Escamossauro Feroz","Quando um inimigo me bloquear, me conceda +3|+0 nesta rodada.","","Surpreso pela resiliência da criatura encontrada na costa de Ionia, o jovem general insistiu em levá-la com ele, ansioso para encontrar a fonte de tamanha força.","Unidade",["RÉPTIL"],["Noxus"],"ÉPICO (A)"],"04NX008":["Estrategista Indomável","Reputação: Eu custo 2 a menos.\nAo me invocar, Mobilize.","","Nos gabinetes reservados da Rosa Negra, os nobres noxianos movem suas peças, e a morte acomete vítimas distantes.","Unidade",[],["Noxus"],"RARO (A)"],"04NX006":["Espiã da Rosa Negra","Reputação: Ao me invocar, me transforme em uma cópia idêntica ao aliado Mais Forte que Golpeou nesta rodada.","","\"O valor de um segredo depende apenas do preço que pagam para que não seja revelado.\"","Unidade",[],["Noxus"],"ÉPICO (A)"],"04NX001":["Mímica","Reputação: Eu custo 3 a menos.\nAo jogar seu próximo feitiço nesta rodada, copie-o com os mesmos alvos.","","A imitação também é uma forma de elogio, e elogios podem ser letais.","Feitiço",[],["Noxus"],"RARO (A)"],"04NX004":["LeBlanc","","Vi você causar 15+ de dano. Quando eu subir de nível, crie 1 Imagem-Espelho na mão.","\"Meus caros, não precisamos brigar entre nós. Por enquanto, não tomaremos nenhuma medida drástica. Vamos nos reunir mais uma vez quando nosso emissário trouxer notícias. Afinal...\"","Unidade",[],["Noxus"],"Campeão"],"04NX016":["Fiandeira Estridente","Atacar: Conceda +2|+0 a Aranhas aliadas nesta rodada.","","\"Vamos, meu bem. Deixe que as outras ouçam o seu chamado. Você sabe como isso as atiça... e sabe como me agrada.\" – Elise","Unidade",["ARANHA"],["Noxus"],"RARO (A)"],"04NX007":["Atakhan, Emissário da Devastação","Jogar: Ressuscite o aliado Mais Forte que tiver morrido.\nAtacar: Eu ganho Poder igual ao Poder total de todos os aliados.","","Uma aberração gigantesca e desconhecida cobria o local envolto por fumaça. Lá, os magos seguiam entoando um cântico em um coro desarmônico, com suas vozes alcançando um tom rouco e frenético encoberto por medo. O monstro respirava fundo, sentindo o pavor crescente daquelas pessoas, e ganhava um enorme poder a cada arfada.","Unidade",[],["Noxus"],"ÉPICO (A)"],"04NX018":["Sangríneo Carmesim ","Na próxima vez que você invocar outro aliado, cause 1 de dano a ele; eu ganho +1|+1.","","\"Quase ninguém os têm como bichinhos de estimação, sabia? Um corte feito por essas garras pode abrir veias facilmente... mas, por mim, tudo bem.\" – Clara, Discípula Carmesim","Unidade",["FELINO"],["Noxus"],"COMUM"],"04NX003":["Sigilo de Malícia","Reputação: Eu custo 2 a menos.\nCause 2 de dano a qualquer coisa.","","Quando a batalha estiver ganha, você não deve hesitar – precisa seguir adiante, avançar e aniquilar o inimigo.","Feitiço",[],["Noxus"],"COMUM"],"04NX017":["A União Faz a Força","Invoque 2 Saqueadores da Legião.","","Os soldados noxianos podem até deixar poucos sobreviventes, mas os saqueadores deixam menos ainda.","Feitiço",[],["Noxus"],"COMUM"],"04NX009":["Lâmina Espinhosa","Conceda +5|+0 a um aliado nesta rodada.","","\"Você vai agir com graça e cordialidade. Vai bajulá-los e fazer com que baixem a guarda. Vai ouvi-los e aprender com o que disserem. E, quando chegar a hora, você vai dar conta da situação e vai MATÁ-LOS.\" – LeBlanc","Feitiço",[],["Noxus"],"COMUM"],"04SI005":["Kindred","A cada rodada, na primeira vez que você Eliminar uma unidade, eu marco o inimigo Mais Fraco.\nFim de Rodada: Abata as unidades que eu marquei.","Vi você Eliminar 2+ unidades marcadas por mim.","Era uma vez um solitário\nQue se partiu pela metade\nDepois de dividido, sentiu-se renascido\nTamanha a felicidade.","Unidade",[],["Ilhas das Sombras"],"Campeão"],"04SI055":["Viego","A cada rodada, na primeira vez que outro aliado morrer, invoque 1 Névoa Invasora.","Vi aliados com 20+ de Poder total morrerem.","''Tem algo de muito intrigante na história do jovem rei. Algo em seu coração... uma fome que não pode ser saciada, um desejo impossível de ser realizado.'' – Dos registros de Nunyo Necrit de Camavor","Unidade",[],["Ilhas das Sombras"],"Campeão"],"04SI016":["Parasita Espiritual ","Jogar: Abata um aliado para comprar 2.","","Eles se escondem nas sombras, esperando um sinal de cansaço ou uma distração. Depois vêm as garras, a boca escancarada e, finalmente, a escuridão.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"04SI007":["O Demônio Etéreo","Jogar: Abata um aliado para abater um inimigo.","","\"Agora que meu tempo neste lugar chega ao fim, ando pensando não em minha primeira morte, mas na segunda. Quem será a última alma a lembrar-se do meu nome? E, quando ela também se for... o que será de mim?\" – Benfeitor Ilustre","Unidade",["AVE"],["Ilhas das Sombras"],"RARO (A)"],"04SI011":["Escuridão Adentro","Compre 1.\nAnoitecer: Ative o efeito Anoitecer de um aliado, ignorando quaisquer efeitos que exijam a seleção de alvos.","","\"Venha, criança. Não precisa ter medo.\" – Mãe Mascarada","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"04SI018":["O Arvoredo Retorcido","Quando eu tiver visto 3+ aliados com Assustador ou Anoitecer atacarem, me destrua para invocar Maldíbula.","","Um altar já esquecido\nEm uma trilha abandonada\nQue na escuridão ainda abriga\nA fera que ali fora deixada","Monumento",[],["Ilhas das Sombras"],"ÉPICO (A)"],"04SI015":["Escaravelho Marinho","Quando outro aliado morrer ou usar o Suspiro Final: Abdique 1.","","\"Vamos, seus imprestáveis, preparem as armadilhas! E vale lembrar: se aparecer um escaravelho marinho, é pra cortar a corda e seguir viagem. Não vou expor minha quilha à carniça que sobrar do rango deles, entenderam?\" – Capitão de Águas de Sentina","Unidade",["MONSTRO MARINHO"],["Ilhas das Sombras"],"RARO (A)"],"04SI004":["As Asas e a Onda","Jogar: Entro no jogo como Primeira Onda ou Último Vento.","","Os Kinkou só falam de dois deuses: a primeira onda, que nutre a vida em suas águas quentes, e o último vento, que arranca a vida com suspiros gélidos e terminais.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"04SI017":["Canção das Ilhas","Dê Roubo de Vida, Assustador e Efêmero a um aliado.","","\"Venha, criança. Veja o que eu vejo, e sinta o que eu sinto. Não tema a escuridão.\" – O Reacendedor","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"04SI054":["Soldada Camavorana","Ao me invocar, invoque 1 Névoa Invasora.","","Com uma lealdade inabalável, os soldados de Camavor marcharam com Viego na vida e na morte.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"04SI001":["Refúgio da Ovelha","Conceda \"Não posso sofrer dano nem morrer\" ao aliado Mais Fraco nesta rodada.","","\"Brilhe mais uma vez, antes do fim.\" – Ovelha","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"04SI056":["Névoa Fulminante","Drene 2 de 2 inimigos.","","''Eu pego o que quero e descarto o que não quero.'' – Viego","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"04SI012":["Raposa Astral","Jogar: Abata um aliado para causar 3 de dano ao Nexus inimigo.","","Algumas tribos targonenses contam histórias sobre a Raposa, uma divindade da morte representada por uma estrela solitária no céu. Reza a lenda que, a cada nova morte, essa divindade desce até a montanha e guia a nova alma até os céus, a fim de criar sua própria constelação sombria.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"04SI029":["Desespero","Escolha uma unidade para Golpear seu Nexus e depois a abata.","","''Fiz de tudo para encontrá-la, mas não foi o suficiente.''\n– Viego","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"04SI009":["Fiandeiro de Almas","Ao me invocar, eu ganho +1|+1 e Assustador se um aliado tiver morrido nesta rodada.","","\"Era uma vez um pobre infeliz que resolveu cortejar uma aranha, sem nem imaginar que poderia acabar na teia dela...\"","Unidade",["ARANHA"],["Ilhas das Sombras"],"COMUM"],"04SI013":["Mãe Mascarada","Jogar: Abata um aliado para me dar os atributos e as palavras-chave dele.","","Dizem que a Mãe Mascarada criou os Kindred e todas as encarnações da morte. Mas, se não foi ela quem fez a própria máscara, quem terá lhe dado?","Unidade",[],["Ilhas das Sombras"],"COMUM"],"04SI021":["Dracovíbora Rastejante","Para me pôr em jogo, eu Golpeio um aliado ou causo 3 de dano ao seu Nexus.","","A princípio, soldados demacianos ouviram o som de garras contra o chão da praça. Foi só quando elas invadiram a torre do relógio que eles finalmente perceberam que todos aqueles membros pertenciam a uma só criatura.","Unidade",["DRAGÃO"],["Ilhas das Sombras"],"COMUM"],"04SI002":["Jornada Espiritual","Abata uma unidade e depois a ressuscite.","","\"Isso é apenas um intervalo.\" – Ovelha","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"04SI053":["Hidravinha Intrusa","Ao me invocar ou no Início de Rodada: Invoque 1 Névoa Invasora.","","Maokai trabalhou incansavelmente para cultivar a vida nas Ilhas das Sombras. A ambivalência da Névoa não a torna menos cruel.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"04SI003":["Ícone Decadente","Ao me invocar, invoque 1 Presa.","","Quem esquece o próprio deus da morte, senão aqueles amaldiçoados com a imortalidade? E o que pode ser mais terrível para um deus da morte do que ser esquecido? ","Unidade",[],["Ilhas das Sombras"],"COMUM"],"04SI028":["Dragão Camavorano","Para me pôr em jogo, eu Golpeio um aliado ou causo 3 de dano ao seu Nexus.\nQuando eu abater outra unidade, Drene 1 de Vida do Nexus inimigo.","","Por vários séculos, a Névoa Negra recrutou e deformou criaturas por todo o mundo, transformando-as em versões assombrosas do que eram antes.","Unidade",["DRAGÃO"],["Ilhas das Sombras"],"RARO (A)"],"04MT014":["Olho dos Ra-Horak","Contagem 1: Atordoe os 2 inimigos Mais Fracos.\nAmanhecer: Invoque uma cópia minha com Contagem: 2.","","\"O sol derramará a luz d'Ela sobre nós. Os fracos e indignos vão se acovardar diante do olhar d'Ela!\" – Sacerdotisa Solari","Monumento",[],["Targon"],"RARO (A)"],"04MT008":["Malphite","Jogar: Atordoe um inimigo.","Você invocou Monumentos equivalentes a 10+ de Mana. Quando eu subir de nível, caso você esteja com o Símbolo de Ataque, crie 1 Força Incontrolável na mão.","\"Última palada do tour em Tágon! É o PAPAI! Ele é o MAIOR gigante de Tágon e canta uma musiquinha bem legal. Só não tenta subir nele que senão dá cosquinha, e se ele fizer um ATCHIM quando você tiver subindo, vai cair!\"\n– Aventuras com Lasquinha, parte 6","Unidade",[],["Targon"],"Campeão"],"04MT010":["Pico Pontestrelado","Contagem 2: Crie na mão 2 cartas Celestiais aleatórias que custem 3 ou menos.","","Quem escala o Monte Targon logo é recompensado com algumas das vistas mais esplêndidas de Runeterra. À medida que o pico se apruma, o mesmo ocorre com suas recompensas.","Monumento",[],["Targon"],"RARO (A)"],"04MT005":["Lasquinha","Depois que você invocar um Monumento nesta partida, eu ganho +2|+2.","","\"Oi, tudo bom? Eu xô o Lasquinha e vim mostá Tágon pa voxês! É beeeeem gandão, então picisa de sapato bom pa andá! VAMO!\"\n– Aventuras com Lasquinha, parte 1","Unidade",[],["Targon"],"COMUM"],"04MT009":["Escadas Espiraladas","Contagem 3: Crie 1 Semente de Força na mão.","","\"Pimela palada! Eu chamo aqui de tontolia, porque AAAAH é deglau pa lá e pa cá e te deixa tonto! A vista também é legal, e essa é uma das coisas que eu mais gosto em Tágon. Tá bom, VAMO!\" – Aventuras com Lasquinha, parte 2\n","Monumento",[],["Targon"],"RARO (A)"],"04MT001":["Trilha do Desabamento","Contagem: 2 – Oblitere o inimigo Mais Fraco.","","\"Pexual, ICUTA AQUI: cuidado que a QUEDA É GANDE e eu até já caí! Eu sou de péda, então num faz mal, mas vocês... cuidado. Olha, é o Lochoso! Vamo lá dar oi!\"\n– Aventuras com Lasquinha, parte 3","Monumento",[],["Targon"],"COMUM"],"04MT018":["Íbex Amedrontado","Quando me auxiliarem, conceda +1|+1 a mim e ao meu aliado auxiliar nesta rodada.","","''Não tenha medo do vendaval trovejante\nQuando ele soprar pela montanha uivante\nNão se preocupe, não há o que temer\nDescanse, mamãe vai te proteger.'' – Canção de ninar targonense","Unidade",[],["Targon"],"COMUM"],"04MT004":["Azuporã","Suspiro Final: Invoque 1 Insígnia de Perspicácia.","","\"TO-DO MUN-DO fala 'OI, ZUZU!'... OI, ZUZU! Uma vez achei que ele também tinha falado 'OI, ZUZU!', mas acho que foi o eco da minha voz. TUDO BEM, ele é todo mágico, azul e tal, nem picisa falar! TÁ BOM, TCHAU, ZUZU, VAMU LÁ!\"\n– Aventuras com Lasquinha, parte 5","Unidade",[],["Targon"],"COMUM"],"04MT013":["Ignifalco Solari","Amanhecer: Atordoe o inimigo Mais Forte.","","Os Solari acreditam que foram os ignifalcos de Targon, com seu brilho radiante, que atraíram a atenção da Chama Imortal e inspiraram seu ciclo de morte e renascimento.","Unidade",["AVE"],["Targon"],"COMUM"],"04MT003":["Elemental da Terra","Depois que você invocar 4+ Monumentos nesta partida, eu ganho +3|+0.","","\"Esse aqui é o LOCHOSO! Ele é um gandão que vive aqui faz um TEMPÃO. Eu sei que ele é legal e tem jeito de bonzinho, mas ele leva um monte de coisa pesada nas costas e pode cair em cima das pessoas às vezes, então CUIDADO, tá? Bigado, vamo indo então!\"\n– Aventuras com Lasquinha, parte 4","Unidade",[],["Targon"],"COMUM"],"04MT002":["Quebra-pedras","Jogar: Se tiver invocado 4+ Monumentos nesta partida, cause 4 de dano a um inimigo e 2 de dano ao Nexus inimigo.","","De tempos em tempos, os grandes colossos de Targon despertam e abrem novos caminhos no topo da grande montanha. Esses eventos nunca são tranquilos, e muito menos seguros.","Unidade",[],["Targon"],"ÉPICO (A)"],"04MT006":["Epifania Constelada","Evoque.\nSe você tiver um aliado Celestial, substitua o seu deck por 20 cópias de Contemple o Infinito.","","\"Olha só, Kulun! As estrelas têm tantas histórias pra contar! Qual delas vamos ler hoje?\" – Sonhaluna","Feitiço",[],["Targon"],"ÉPICO (A)"],"04MT012":["Convocação do Destino","Dê +8|+8 a um aliado na mão.","","\"Aceite o seu destino e brilhe muito mais do que qualquer um poderia imaginar.\" – Taric","Feitiço",[],["Targon"],"ÉPICO (A)"],"04MT007":["Estrondar Terreno ","Atordoe um inimigo. Cause 3 de dano a ele se você tiver invocado um Monumento nesta partida.","","\"Opa, é só o chão tlemendo, o papai nem tá fazendo nada com a mão, PELAÍ, TÁ SIM, ENTÃO bom, vamo SUBINDO!\" – Lasquinha","Feitiço",["ELEMENTAL"],["Targon"],"RARO (A)"],"04MT015":["Alinhamento Celeste","Amanhecer: Crie uma carta aleatória com Anoitecer na mão.\nAnoitecer: Crie uma carta aleatória com Amanhecer na mão.","","E assim segue o ciclo de noite e dia; um sempre acompanhando o outro.","Feitiço",[],["Targon"],"COMUM"],"04DE004":["Rastreadora Fervente","Ao invocar uma carta Elite, reduza o meu custo em 1.","","Embora os noxianos tenham montado uma bela armadilha, ninguém conhecia a floresta melhor do que os patrulheiros de Demacia. Cada galho, cada pegada era uma pista que os levava ao seu príncipe.","Unidade",["ELITE"],["Demacia"],"RARO (A)"],"04DE014":["Lanchinho de Dragão","Quando você joga um Dragão, ele me Golpeia e você compra 1.","","\"Está ouvindo esse som vindo lá do alto? Não é um pássaro, meu garoto. É o chamado de caça de um dragão.\"\n– Fazendeiro demaciano","Unidade",[],["Demacia"],"COMUM"],"04DE001":["Lorde Honroso","Quando eu Desafiar um inimigo pela primeira vez, me conceda Barreira nesta rodada.","","Após saber do desaparecimento do filho, o rei Jarvan III deixou Lorde Barrett Buvelle, seu amigo de confiança, encarregado de organizar um grupo de buscas. O príncipe voltou são e salvo, mas, para o eterno arrependimento do rei, o mesmo não pôde ser dito do Lorde.","Unidade",["ELITE"],["Demacia"],"COMUM"],"04DE012":["Ascensão de Campanha","Na próxima vez que você jogar uma unidade nesta rodada, dê Patrulheiro a ela. Ela passa a ser uma carta Elite.","","Quando a bravura de Demacia é colocada à prova, seus cidadãos respondem à altura.","Feitiço",[],["Demacia"],"COMUM"],"04DE003":["Cataclisma","Um aliado inicia um ataque livre Desafiando um inimigo.","","\"Pelo rei!\" – Jarvan IV","Feitiço",[],["Demacia"],"RARO (A)"],"04DE002":["Égide de Ouro","Conceda Barreira a um aliado nesta rodada.\nMobilize.","","\"Mais uma vez, soldados de Demacia!\" – Jarvan IV","Feitiço",[],["Demacia"],"RARO (A)"],"04DE006":["Destreza em Campo","Dê +1|+1 a um aliado.","","\"Eu posso te ensinar alguns truques.\" – Lorde Buvelle","Feitiço",[],["Demacia"],"COMUM"],"04DE008":["Jarvan IV","Ao atacar, pague meu custo para me invocar Desafiando o inimigo Mais Forte.","Aliados sobreviveram a 3+ Golpes de bloqueadores inimigos.","Os noxianos sabiam em que local o príncipe Jarvan faria sua caçada e quantos demacianos o acompanhariam, além de estarem cientes de que a honra do jovem não o permitiria fugir de um confronto. Com tudo isso, a armadilha estava pronta.","Unidade",["ELITE"],["Demacia"],"Campeão"],"04DE005":["Cithria, Dama das Nuvens","Ao me invocar, dobre o Poder e a Vida de outros aliados e dê Desafiador a eles.","","\"Quem mais Demacia poderia enviar para salvar seu príncipe se não a própria Dama das Nuvens?\" – Rei Jarvan III","Unidade",["ELITE"],["Demacia"],"ÉPICO (A)"],"04DE020":["Dracoguarda Destruído","Quando um aliado com Fúria abater uma unidade, dê +1|+1 a ele.","","A Névoa se apossou da mente de Gregem, fazendo-o reviver Wrenwall incessantemente. Tomado pela fúria e amargura que guardava dentro de si, ele se voltou contra seus antigos companheiros.","Unidade",[],["Demacia"],"COMUM"],"04DE010":["Rei Jarvan III","Ao me invocar, compre Jarvan IV.\nSe ele já estiver em jogo, conceda Desafiador e Patrulheiro aos aliados nesta rodada.","","\"O que um pai sacrificaria para salvar o filho? Ou melhor, que tipo de sacrifício um rei faria?\" – LeBlanc","Unidade",["ELITE"],["Demacia"],"ÉPICO (A)"],"04DE016":["Kadregrin, o Destruído","Jogar: Dê +1|+1 e Desafiador a um aliado.","","Kadregrin já semeava o caos antes da chegada da Névoa Negra a Demacia. Porém, sob o comando de Viego, suas habilidades passaram a servir às forças do Rei Destruído.","Unidade",["DRAGÃO"],["Demacia"],"RARO (A)"],"04DE013":["Petricórnio Imponente","Não sofro dano de Habilidades nem feitiços inimigos.","","Dizem que os majestosos petricórnios vêm da época em que a floresta de petricita ainda era jovem, e que os chifres são feitos de um material similar ao que dá forma a essas árvores anciãs.","Unidade",[],["Demacia"],"COMUM"],"04DE015":["Esquadrilha de Rapina","Jogar: Crie 1 Vanguarda de Rapinas Prateadas, 1 Investida Anuviante ou 1 Plumageiro Rastreador na mão.\nAtacar: Conceda +1|+1 a outros aliados Desafiando nesta rodada.","","Só de olharem para a Esquadrilha de Rapina lá no alto, os soldados demacianos já se enchem de coragem em meio aos campos de batalha. Ao vê-los perfurando as nuvens, quem está no solo se sente revigorado e pronto para continuar lutando.","Unidade",["ELITE","AVE"],["Demacia"],"ÉPICO (A)"],"04DE007":["Escudeira Penitente","Se você Contemplar uma carta Elite ao me invocar, crie 1 Estandarte Desgastado na mão.","","Aproximando-se dos muros da cidade, suas pernas finalmente cederam. A Vanguarda Destemida levaria sua mensagem até o rei que, por sua vez, resgataria o príncipe. Assim, o erro que ela cometera seria corrigido e a honra dela seria mantida.","Unidade",[],["Demacia"],"COMUM"],"04DE009":["Cavaleiro Galante","Quando eu Desafiar um inimigo pela primeira vez, me transforme em Cavalaria da Vanguarda.","","Ao darem o comando, todos os soldados demacianos foram convocados para ajudar nas buscas pelo príncipe. A situação exigia, acima de tudo, eficácia.","Unidade",["ELITE"],["Demacia"],"RARO (A)"],"05BC058":["Kennen","Ao me invocar, crie 1 Marca da Tormenta na mão.","Você invocou o mesmo aliado 5+ vezes.","Kennen também tinha ouvido o rugido de alguma coisa... oculta. Não importava se era humano ou monstro — os Kinkou protegeriam suas terras a qualquer custo.","Unidade",["YORDLE"],["Bandópolis","Ionia"],"Campeão"],"05BC010":["Treinador de Tubarões","Quando os aliados atacarem, invoque 1 Dentinho atacante.","","A rotina do Treinador se repete toda noite: peixe com cerveja na janta e uma tragada rápida de seu cachimbolha, seguido de beijinhos na cabeça de seus tubarões e uma historinha antes de dormirem.","Unidade",["YORDLE"],["Bandópolis","Águas de Sentina"],"RARO (A)"],"05BC102":["Feiticeiro Fastidioso","Início de Rodada: Recarregue 1 de Mana de Feitiço.","","Se não há dor maior do que a dor de se cortar com papel, então pode-se dizer que ninguém conhece a dor melhor do que um bibliotecário.","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC230":["Portal Espiritual","Para me pôr em jogo, descarte 1. Dê +1|+1 aos aliados.","","\"Nunca lembro como essas coisas funcionam.\" – Poppy","Feitiço",[],["Bandópolis"],"COMUM"],"05BC099":["Escoteiro Bombado","Ao me invocar, eu ganho +1|+1 para cada outro yordle aliado que você tiver.","","\"Quer saber qual é o meu segredo? Vai ter que perguntar pros meus bíceps. São eles que fazem a magia acontecer.\"","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC133":["Tristana","Eu tenho +1|+0 para cada aliado multirregional que você conjurou nesta partida.\nAo invocar um aliado multirregional, dê +1|+0 a ele.","Você invocou 5+ aliados multirregionais.","\"Plano A: a gente explode a entrada e começa a atirar. Se isso não funcionar, vamos pro plano B: a gente explode a saída e continua atirando. Aí a gente se reúne e vai pro plano C, que é basicamente o plano A de novo...\"","Unidade",["YORDLE"],["Bandópolis"],"Campeão"],"05BC023":["Peximboi","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Megapeximboi.","","Minipeximbois gostam de tirar um cochilo nas pedras estivais ao lado das terras tribais de Nakotak. Minipeximbois não gostam de serem empurrados das tais pedras estivais por yordles travessos...","Unidade",[],["Bandópolis"],"ÉPICO (A)"],"05BC029":["Yuumi","Início de Rodada: Dê +1|+1 à unidade que estou Conectada. Se não houver uma, eu ganho +1|+1.","Eu ou a unidade a que estou Conectada atacamos 3 vezes.","Yuumi tinha que confessar que, apesar de todo o rebuliço, gostava bastante do Livro. Gostava do cheiro dele. Gostava das ilustrações. Ela gostava até de atravessar os portais dele...! Mas nada era tão bom quanto ter Norra sã e salva em casa.","Unidade",["FADA","FELINO"],["Bandópolis","Targon"],"Campeão"],"05BC078":["Arpão Elétrico","Para me pôr em jogo, descarte 1. Cause 2 de dano a uma unidade e 2 de dano ao Nexus inimigo.","","\"Vai ser um espetáculo!\" – Rumble","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC106":["Resmunguesma","","","\"Mesmo com seu pequeno porte, a resmunguesma apresenta um grande apetite e algo que só consigo descrever como 'um terrível mau humor'.\"\n– Registro Ecológico do Conquiliologista, dia 17","Unidade",[],["Bandópolis","Águas de Sentina"],"COMUM"],"05BC161":["Gnar","Golpear: Crie 1 Graveto Pontudo na mão ou reduza o custo em 2 se já tiver uma cópia.","Fim de Rodada: Você causou dano ao Nexus inimigo nesta rodada.","Há muito tempo, Gnar e sua espécie prosperavam no Vale Nakotak. Era um lugar inocente, intocado pelas comodidades modernas. É uma pena que o passar do tempo tirou-o de Gnar, mas que bom que o tempo não funciona como o esperado em Bandópolis.","Unidade",["YORDLE"],["Bandópolis","Freljord"],"Campeão"],"05BC073":["Química Criativa","Ao me invocar, invoque 1 Bomba Rudimentar.","","Giselle era uma das alunas mais brilhantes do Professor Heimerdinger – até ouvir falar dos estranhos experimentos que Ziggs realizava em Zaun. Depois disso, era só \"hexplosivos\" pra cá e \"escreve uma carta de recomendação pra eu poder estagiar com ele\" pra lá. ","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC039":["Granadeiro Bronco","Lealdade: Invoque um seguidor Yordle aleatório de custo 3 ou menos.","","\"A Alice tem duas balas: uma dá 'oi' e a outra dá 'tchau'. Quer que eu te apresente pra ela?\"","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC148":["Silfo Furioso","Ao me invocar, se você tiver causado dano ao Nexus inimigo 4+ vezes nesta partida, eu ganho Impacto 4 vezes.","","Consistente por fora, duro e amargo por dentro.","Unidade",["FADA"],["Bandópolis","Piltover e Zaun"],"COMUM"],"05BC119":["Tropa","Suspiro Final: Crie uma cópia minha na mão no Início de Rodada.","","\"Um verdadeiro supervilão nunca terá tropas demais! Esses camaradinhas sabem seu lugar, obedecem cada palavra e sempre voltam para receber mais instruções.\"\n– Trecho do Cap. 2 de \"Como ser um supervilão\", escrito por Lorde Veigar","Unidade",[],["Bandópolis","Ilhas das Sombras"],"COMUM"],"05BC019":["Peixe Arco-íris","","","A Peixe Arco-íris ficou feliz em fazer reconhecimento aéreo, mesmo que isso significasse dar o maior salto de sua vida. Ela aceitaria qualquer folga, por menor que fosse, do olhar faminto de Yuumi.","Unidade",["FADA"],["Bandópolis"],"COMUM"],"05BC093":["Veigar","Ao me invocar, crie 1 Escuridão na mão se não tiver. Início de Rodada: Dê 1 de dano adicional às suas cópias de Escuridão globalmente.","Você causou 12+ de dano com Escuridão.","\"Este mundo terá medo de mim, carregará por toda a eternidade as cicatrizes que eu infligir e sucumbirá perante a força do meu poder. Todos tremerão sob a sombra da minha magnitude!\"\n– Trecho do Cap. 1 de \"Como ser um supervilão\", escrito por Lorde Veigar","Unidade",["YORDLE"],["Bandópolis","Ilhas das Sombras"],"Campeão"],"05BC007":["Empilhadores de Pedras","","","Os yordles ainda não entenderam como a gravidade funciona. Mas tudo bem — a gravidade também não entendeu como Bandópolis funciona.","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC174":["Amizade!","Conceda Barreira ou Escudo de Feitiço a um aliado nesta rodada.","","\"Vou te proteger com meu selvagem e feroz... miau!\"\n– Yuumi","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC185":["Jogo das Conchas","Recarregue seu Mana de Feitiço. Conceda +1|+1 e Elusivo a um aliado nesta rodada.","","\"JURO que vejo eles entrando na concha da esquerda, mas quando eu ESCOLHO a tal da concha, ela está vazia. Começo a achar que estão trapaceando...\"\n– Registro Ecológico do Conquiliologista, dia 14","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC096":["Tenor do Terror","Ao me invocar, se você tiver jogado uma carta criada ou abatido uma unidade usando um feitiço nesta partida, invoque 1 Grave dos Pesares.","","Se Veigar precisava de ajuda para harmonizar o conceito de justiça, então não havia ninguém melhor do que esses dois para fazer o serviço. Eles entendem tudo de harmonização – e de tacar o terror.","Unidade",["YORDLE"],["Bandópolis","Ilhas das Sombras"],"RARO (A)"],"05BC088":["Rumble","Jogar: Descarte até 3 cartas para dar aos aliados Rumbles globalmente Impacto para o primeiro, Ataque Rápido para o segundo e Escudo de Feitiço para o terceiro.","Vi Mech Yordles aliados causarem 12+ de dano.","\"Eeeeee isso deve dar.\"\n\"ERRO.\"\n\"O QUÊ?! Mas eu acabei de consertar!\"\n\"FALHA DE SISTEMA IMINENTE.\"\n\"Desliga. DESLIGA LOGO!\"\n– Rumble e Tristy","Unidade",["MECH","YORDLE"],["Bandópolis","Noxus"],"Campeão"],"05BC056":["Monja dos Ventos","Ao me invocar, crie 1 Postura da Nuvem na mão.","","\"A técnica da nossa escola é derivada do controle sobre a respiração. Assim como as tempestades são derivadas dos ventos.\"","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC190":["Mechapresentador da Arena","Atacar: Conceda +2|+0 aos outros aliados atacantes nesta rodada.","","\"Como faço pra gritar no microfone todas as noites? Gargarejo com óleo de motor. Cinco minutos de manhã e cinco à noite.\"","Unidade",["YORDLE"],["Bandópolis","Noxus"],"ÉPICO (A)"],"05BC042":["Shake de Roxamora","Aumente um aliado para 3|3 nesta rodada.","","\"Eu era igual a você, não conseguia nem levantar um cogumelinho! Mas aí descobri o incrível Shake de Roxamora. Ele tem tudo o que um yordle precisa para soltar o monstro que tem dentro de si. Depois de uma série de exercícios daqueles, é só tomar um Shake no grau para se tornar tão forte quanto eu!\" \n– Propaganda impressa","Feitiço",[],["Bandópolis"],"COMUM"],"05BC205":["Horizonte de Eventos","Atordoe um inimigo e Atordoe todos os inimigos com 2 ou menos de Poder.","","\"É só... ficar bem aí...\" – Veigar","Feitiço",[],["Bandópolis"],"COMUM"],"05BC223":["Trapeira","Escolha 1 dentre 3 unidades ou feitiços do deck inimigo e plante 3 Cogumelos Venenosos em todas as cópias da carta escolhida.","","\"Regra 986: armadilhas NÃO SÃO brinquedos... mas são superdivertidas!\"","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC091":["Promoter da Arena","Jogar: Descarte 1 para Manifestar um Mech Yordle e reduzir seu custo em 1.","","\"INGRESSOS! COMPRE OS SEUS INGRESSOS! TÁ PELA METADE DO PREÇO! Ai, ai, ai, se eu não vender isso, o chefe vai me matar... literalmente.\"","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC163":["Ziggs","Atacar: Eu causo 1 de dano ao meu bloqueador e ao Nexus inimigo.","Você destruiu 4+ Monumentos aliados.","\"A gente PRECISA causar uma boa impressão. O novo inspetor de segurança vai passar aqui, e você sabe muito bem o que isso significa!\"\n\"Chega de explosões?\"\n\"QUÊ?! Não! A gente só precisa explodir as coisas sem ele ver! 'Chega de explosões'... Enlouqueceu?!\" – Ziggs e Otto","Unidade",["YORDLE"],["Bandópolis","Shurima"],"Campeão"],"05BC151":["Maga dos Espelhos","Ao jogar um seguidor criado, invoque uma cópia idêntica a ele. Ao jogar um feitiço criado, copie-o com os mesmos alvos.","","\"Ah, ela é uma mestra excepcional em armar jogos de espelhos — faz todos os meus designs parecerem ainda mais refinados. E, com uma pequena manipulação nas luzes, até consegue dar um pouco de verticalidade para um certo alguém...\" – Alfaiate Esnobe","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"05BC027":["Campo Minado de Hexplosivos","Ao me invocar ou quando você me destruir, Atordoe o inimigo Mais Forte.","","\"Como assim 'isso não parece seguro'?\" – Ziggs","Monumento",[],["Bandópolis"],"COMUM"],"05BC200":["Portal Yordle","Para me pôr em jogo, descarte 1. Manifeste um Yordle que custe 3 ou menos e invoque-o.","","\"Nunca deixe um artilheiro para trás!\" – Tristana","Feitiço",[],["Bandópolis"],"COMUM"],"05BC021":["Bomba Saltitante","Cause 2 de dano a uma unidade ou cause 1 de dano a dois inimigos.","","\"Lá vai bomba!\" – Ziggs","Feitiço",[],["Bandópolis"],"COMUM"],"05BC167":["Soldada de Bandópolis","Golpe ao Nexus: Crie 1 Gatoruja Faminto na mão.","","\"Colocando bandido no lugar e criança pra nanar!\"","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC179":["Desbravador Yordle","Atacar: Dê +0|+1 aos aliados com Poder igual ou inferior ao meu.","","\"Poppy! Que bela execução da nossa nova tática! O que você acha de chamá-la de 'Floracão Aveleiro'?\"\n\"Olha, eu só acertei o malvado com o meu martelo. A gente não pode chamar essa tática só de 'Martelo'?\"\n\"Mas esse já é o nome das últimas três!\" – Kip e Poppy","Unidade",["YORDLE"],["Bandópolis","Demacia"],"ÉPICO (A)"],"05BC214":["Bomba Megainfernal","Cause 1 de dano a todos os inimigos, depois repita a operação.","","\"Hora de trazer... 'A Grandona'!\" – Ziggs","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC221":["Círculo dos Cogumelos","Ao me invocar ou em Início de Rodada: Nesta rodada, me conceda Poder equivalente ao número de outras Fadas aliadas em jogo ou Conectadas.","","As cabecinhas de alfinete são fofas de tirar o chapéu.","Unidade",["FADA"],["Bandópolis","Ionia"],"RARO (A)"],"05BC041":["Poppy","Atacar: Dê +1|+1 aos aliados com Poder igual ou inferior ao meu.","Eu ataquei com aliados 3 vezes.","A humildade é uma virtude do heroísmo, mas muitos historiadores concordam que a Poppy passa um pouco dos limites.","Unidade",["YORDLE"],["Bandópolis","Demacia"],"Campeão"],"05BC176":["Projétil Errante","Dê +1|+0 a um aliado. Cause 1 de dano a um inimigo.","","\"Zuuum!\" – Yuumi","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC105":["Fuzinúsculos","Eu custo 1 a menos para cada aliado multirregional que você tiver invocado nesta partida.\nAo me invocar, eu ganho Impacto 3 vezes.","","Isso sim é que é equipe.","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC066":["Pena Rápida","","","\"C... a... d... ê... a... N... o... r... r... a...? Ai, ai, o que eu falo?\"\n– Mordomo Roedor","Unidade",["FADA"],["Bandópolis"],"COMUM"],"05BC177":["Dragão de Papel","","","\"Mais uma dobra, e tá vendo? Uma girafa! Ele se chama Meias.\" \n\"Por que 'Meias'?\" \n\"Norra ama meias, então vai amá-lo também!\" – Mordomo Roedor","Unidade",["FADA"],["Bandópolis"],"ÉPICO (A)"],"05BC136":["Sucateiro","Para me pôr em jogo, descarte 1.\nManifeste um Mech Yordle.","","\"Entulho. Lixo. Inútil... Opa, é DISSO AQUI que eu tô falando!\" – Rumble","Feitiço",[],["Bandópolis"],"COMUM"],"05BC164":["Dardo Venenoso","Cause 1 de dano a qualquer coisa e Plante 3 Cogumelos Venenosos no deck inimigo.","","\"Haha! Na mosca!\" – Teemo","Feitiço",[],["Bandópolis"],"COMUM"],"05BC194":["A Árvore de Bandópolis","Início de Rodada: Crie um seguidor de uma nova região na mão. Então, se eu tiver visto aliados de 10 regiões, você vence a partida.","","Com sua estrutura atingindo alturas que os olhos sequer alcançam, a Árvore de Bandópolis é uma instalação imponente situada no coração da cidade. Seus galhos retorcidos e fartos dividem opiniões: para alguns, a árvore representa esperança e amizade – mas, para outros, não passa de um monólito agourento e misterioso. Porém, todos concordam que a Árvore de Bandópolis remete a uma alma ancestral e poderosa.","Monumento",[],["Bandópolis"],"ÉPICO (A)"],"05BC127":["Rissu, a Tempestade Silenciosa","Ao me invocar, invoque 1 Nuvem Tempestuosa.","","Preparar uma Nuvem Tempestuosa levava tempo — tempo que Rissu não tinha. Suas mãos trabalhavam sem parar enquanto a Aberração se aproximava. Um pouco de nuvem aqui, uns raios ali e... CRACK! BUM! Ela conseguira! Mas será que seria o bastante?","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"05BC216":["Engenhoca Yordle","Destrua um Monumento ou crie 2 seguidores multirregionais aleatórios na mão.","","\"Calma, tamo no rolê!\" – Gêmeos Bombardeiros","Feitiço",[],["Bandópolis"],"COMUM"],"05BC212":["Inspetor de Segurança","Início de Rodada: Crie 1 Inspeção Aprovada! na mão.","","Wilfred não botou muita fé no começo. Durante a inspeção, também não. Na verdade, ele continuou desconfiado até o final — mas Ziggs e os outros especialistas em hexplosivos provaram que sabiam dar um show e tanto. ","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC141":["Contenção Heroica","Conceda +2|+1 a 2 aliados nesta rodada.","","\"'Lá estavam os heróis, costas com costas...'\"\n... Bumbum com bumbum! Hehehehehe!\"\n\"N-não! Peppy, se tiver que interromper, deixe pra momentos menos dramáticos!\" \n– Contos narrados em volta da fogueira de acampamento dos yordles","Feitiço",[],["Bandópolis"],"COMUM"],"05BC209":["Defesa Estressante","Deixe uma unidade com 1|6 nesta rodada.","","O Baguiatriz é uma montaria leal e inabalável na maioria das vezes. Porém, quando colocada em situações de muito estresse, ele é conhecido por reagir de forma... não convencional.","Feitiço",[],["Bandópolis"],"COMUM"],"05BC210":["Cospe-Fogo","Dê +2|+0 e Impacto a um aliado.","","\"Se eles não estão gritando, é porque não tá quente o suficiente! Heh heh.\" – Rumble","Feitiço",[],["Bandópolis"],"COMUM"],"05BC013":["Tentáculos Sorrateiros","Seu oponente descarta a carta de menor custo que tiver.","","\"Não esquecer: na próxima expedição, é melhor manter objetos valiosos nos bolsos DA FRENTE.\" \n– Registro Ecológico do Conquiliologista, dia 19","Feitiço",[],["Bandópolis"],"COMUM"],"05BC100":["Cogumelhotinho","Golpear: Plante 3 Cogumelos Venenosos no deck inimigo.","","\"Como é? Dois recrutas estavam patrulhando a floresta, deram de cara com um monstro de grama aterrorizante e estão prestes a morrer de forma lenta e dolorosa? Bom garoto! Me leva até lá!\" – Teemo","Unidade",["CANINO"],["Bandópolis"],"COMUM"],"05BC098":["Catalisador Desequilibrado","Golpear: Dê 1 de dano adicional às suas cópias de Escuridão globalmente.","","A escuridão se materializa em inúmeros tamanhos e de várias formas – e algumas delas são INCRIVELMENTE fofinhas.","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC122":["Yordle Novato","Ao invocar outro yordle, me conceda +2|+0 nesta rodada.","","\"Gigantus gramíneos. Essas criaturas aterrorizantes se camuflam deitando sobre o solo como grama normal e atacam qualquer desavisado que passar por ali. Ao se deparar com um, é melhor não parar de correr!\" – Ava Dedicada","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC120":["Capitão Yordle","Ao invocar outro aliado com Poder igual ou menor que o meu, dê +1|+1 a ele.","","\"Se aventurar por aí significa topar com os caras mais malvados e fazer amizade com eles!\"","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC046":["Punho de Trovão","Ao me invocar, se você tiver invocado 1 Punho de Trovão nesta partida, me transforme em Masa, o Trovão Retumbante.","","Quando Masa acertou o boneco de treinamento, um raio irrompeu de seu punho, partindo a madeira em dois e chamuscando os pelos de suas mãos. Ele puxou a corda, examinando sua mão cor de bronze e refletindo sobre o treinamento — finalmente estava pronto. De repente, um rugido monstruoso ecoou ao longe.","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC018":["Cavaleiro Pomposo","","","\"Novecentos e noventa e oito... Novecentos e noventa e nove... mil! Prontinho, Pio, impecável como sempre. Beleza, agora é a minha vez!\"","Unidade",["YORDLE"],["Bandópolis","Demacia"],"RARO (A)"],"05BC132":["Tiro Destruidor","Eu custo 2 a menos se você tiver 1 Tristana ou se tiver jogado cartas de 4+ regiões nesta partida.\nCause 3 de dano a uma unidade.","","Para cada CAPOW tem um CABUM esperando para nascer.","Feitiço",[],["Bandópolis"],"COMUM"],"05BC168":["Sapo Pintado","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Gigagrompe.","","Durante várias gerações, os yordles do Vale Nakotak buscaram entender seus vizinhos, os grompes. Primeiro, o Líder Hegabo tentou cutucá-los com um graveto. Em seguida, o Líder Babobu tentou cutucá-los com um graveto. O Líder Nakotak tinha um plano inédito: cutucá-los com um graveto.","Unidade",[],["Bandópolis"],"RARO (A)"],"05BC014":["Minidáctilo","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Terrordáctilo.","","As criaturas do Vale Nakotak são tão diversas e alegres quanto a terra que habitam... e tão propensas a explodir quanto ela.","Unidade",["AVE"],["Bandópolis"],"COMUM"],"05BC138":["Gambiarreiros","Na primeira vez que você descartar uma carta ou causar dano ao Nexus inimigo, eu ganho +2|+1.","","\"Essa foi uma luta das boas. Bom trabalho, pessoal. Agora limpem toda essa imundice e, hã, vocês já sabem: o que ainda der pra usar... é só consertar e colocar à venda na loja de novo! AHAHAHA!\" – Karl, o Mandante da Arena","Unidade",[],["Bandópolis"],"COMUM"],"05BC198":["Foto da Galera","Cause 1 de dano a uma unidade. Se você tiver 4+ aliados, cause 2 de dano.","","\"Tá, essa aqui vai pro periódico. Não esquece de sorrir dessa vez! Um... dois... três e... xis!\" – Tristana\n","Feitiço",[],["Bandópolis"],"COMUM"],"05BC181":["Postura da Nuvem","Conceda +2|+0 e \"Fim de Rodada: Me Retorne\" a um aliado nesta rodada.","","\"Recupere o fôlego e encontre a sua força!\" – Monja dos Ventos","Feitiço",[],["Bandópolis"],"COMUM"],"05BC160":["Poro Primitivo","","","Os poros de outrora tinham crânios muito mais espessos do que seus parentes contemporâneos, o que os tornava um pouco mais burros, porém mais hábeis na arte da cabeçada.","Unidade",["PORO"],["Bandópolis","Freljord"],"COMUM"],"05BC005":["Donzelas das Algas","Golpe ao Nexus: Crie 1 Travessura na mão.","","\"Nossa, acabei de ter um sonho muito estranho. Eu estava cavucando as algas, procurando meu chapéu de concha... Até que, de repente, escutei uma melodia encantadora. Porém, quando dei por mim, já estava sentado aqui, com a caneta na mão, escrevendo este relato. E não me lembro de ter sentado para tirar um cochilo...\"\n– Registro Ecológico do Conquiliologista, dia 22","Unidade",[],["Bandópolis"],"RARO (A)"],"05BC020":["Bibliotecária Assistente","Golpe ao Nexus: Compre um feitiço que custe 3 ou menos.","","\"Jelly é minha MELHOR AMIGA! Ahn, depois de você, Livro. E da Norra. Tá, Jelly é minha TERCEIRA MELHOR AMIGA. Isso ainda é muito bom, né?!\" – Yuumi","Unidade",["FADA"],["Bandópolis"],"COMUM"],"05BC049":["Conquiliologista","Jogar: Manifeste um feitiço das suas regiões que custe 3 ou menos.","","\"Hoje será um dia memorável! Uma dia recheado de exploração nas profundezas! Espero que tudo ocorra... MAR-avilhosamente bem! Hehe!\" \n– Registro Ecológico do Conquiliologista, dia 1","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC001":["Minimorfo","Transforme uma unidade em 1 Minipeximboi 3|3 e Silencie-a.","","\"Que gracinha! Que coisinha linda! E é TÃO PEQUENININHA!\" – Veigar","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC026":["Caminhos Ocultos","Eu custo 2 a menos se você já tiver criado 2+ cartas nesta partida. Compre 2.","","Poucos forasteiros conhecem os caminhos até Bandópolis – porém, marcas estranhas em pedras e árvores espalhadas por Runeterra oferecem dicas para aqueles que sabem o que procurar.","Feitiço",[],["Bandópolis"],"COMUM"],"05BC152":["Viajantes Aborrecidos","Ao me invocar, TODOS os jogadores compram 1. Depois, o oponente descarta a carta de custo mais alto que tiver.","","\"Pior. Viagem. De todas.\" – Elle","Unidade",["YORDLE"],["Bandópolis","Piltover e Zaun"],"COMUM"],"05BC070":["Ava Dedicada","Ao me invocar ou no Fim de Rodada: Plante 3 Cogumelos Venenosos no deck inimigo.\nAs armadilhas que estiverem nas cartas inimigas dobram ao ativarem.","","\"Regra 378: um bom escoteiro sempre dispõe de coragem, bravura e prontidão!\"","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"05BC015":["Lagartiquinho","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Lagarto Lávico.","","\"Come a pimenta!\", vociferou Nakotak, provavelmente. \"Não, come a pimenta VOCÊ!\", retrucou Jojo, também provavelmente. Enquanto discutiam, um lagarto pequeno passou correndo, perseguindo uma mosquinha. A dupla de yordles fitou o lagarto, a pimenta e depois um ao outro. Se lâmpadas existissem, uma teria queimado.","Unidade",["RÉPTIL"],["Bandópolis"],"COMUM"],"05BC145":["Escudeira Yordle","Jogar: Crie 1 Lancinha ou 1 Escudinho na mão.","","\"Minha lança já pertenceu a uma grande heroína... Eu pedi pra Poppy segurar ela um pouquinho!\"","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC140":["Trenó de Poros","Atacar: Invoque um Poro atacante aleatório com 1 de custo.","","\"Aí um dos poros disse 'PRA LÁ!', e lá se foram em direção ao horizonte, enquanto os outros poros saíram em disparada atrás deles, se esforçando bastante pra acompanhar!\"\n– Ingvar, a Jovem","Unidade",["PORO"],["Bandópolis","Freljord"],"ÉPICO (A)"],"05BC129":["Mandante da Arena","","","\"A cada minuto que se passa, nasce um novo trouxa no mundo, e eu vou tirar proveito de todos eles... Essa arena de mechs vai virar uma MINA DE OURO!\"","Unidade",["YORDLE"],["Bandópolis","Noxus"],"COMUM"],"05BC004":["Arirolvo","Ao me invocar, crie 1 Travessura na mão.","","\"Curiosos e brincalhões, os arirolvos são uma espécie bem divertida e... Espera, eu não tinha preparado um terceiro sanduíche?\" \n– Registro Ecológico do Conquiliologista, dia 7","Unidade",[],["Bandópolis"],"COMUM"],"05BC155":["Monge da Brasa","Ao invocar outro aliado, eu ganho +1|+0.","","\"Pequenas centelhas se tornam grandes chamas. Somos as brasas da sua destruição!\"","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC104":["Força Primitiva","Dê +2|+2 e Impacto a um aliado.","","Sim, ele é muito fofo. Sim, ele tem pavio curto. Não, você não ia gostar de pagar para ver.","Feitiço",[],["Bandópolis"],"COMUM"],"05BC218":["Ajuda Feérica","Crie 1 Gatoruja Faminto e dê +1|+1 aos aliados Fadas na mão.","","\"Quem anda alimentando essas coisas?\" – Poppy","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC192":["Gêmeos Bombardeiros","Ao me invocar, crie na mão um Monumento aleatório que custe 2 ou menos.","","O Confusilador Bomberante-X fez exatamente o que foi criado para fazer: tocar o caos. Além disso, é muito fácil fazer baliza com ele. ","Unidade",["YORDLE"],["Bandópolis","Shurima"],"COMUM"],"05BC162":["Líder Nakotak","Quando um aliado se transformar, cure-o completamente e dê +1|+1 e Impacto a ele.","","O Chefe Nakotak se proclamou líder da tribo depois de ter encontrado um grande osso de dinossauro nos montes de neve ao redor de suas terras. Os outros não sabiam que ossos de dinossauro equivaliam à liderança da tribo, mas nenhum se importou muito. Então, o cargo ficou para Nakotak.","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC032":["Lanterninha Reluzente","A cada rodada, a primeira Fada que você jogar custa 2 a menos.","","\"A Lanterna segue a Norra, mariposas-luna seguem a Lanterna, os ratos seguem as mariposas-luna! Segue, segue!\"","Unidade",["FADA"],["Bandópolis"],"RARO (A)"],"05BC166":["Graveto Pontudo","Cause 1 de dano a qualquer coisa. Compre 1.","","Primeira regra de qualquer experimento: cutuque o objeto para ver no que dá.","Feitiço",[],["Bandópolis"],"COMUM"],"05BC006":["O Arsenal","Ao me invocar, eu ganho uma palavra-chave aleatória para cada Monumento aliado que você destruiu nesta partida.\nQuando você destrói um Monumento aliado, eu ganho uma palavra-chave aleatória.","","Aonde quer que Ziggs fosse, Arnie ia atrás. Seu jeito sereno era perfeito para contrabalancear a energia caótica de Ziggs. Arnie tinha inúmeras funções, como verificar o estoque de munições, apagar incêndios e colocar as mãos sobre as orelhas de Ziggs quando ele (sempre) esquecia os protetores auditivos. ","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"05BC110":["Alpinista Erudito","","","\"Tá bom, tá bom, você já me contou que ela gosta muito de chá, de meias, de você, de botões e de colecionar cacarecos, mas ainda não me contou COMO ela é!\" ","Unidade",["YORDLE"],["Bandópolis","Targon"],"COMUM"],"05BC063":["Guerreira do Tornado","Ao me invocar, eu ganho +1|+0 e uma palavra-chave aleatória.\nMantenho esses fortalecimentos e palavras-chave quando Retorno.","","O Tornado a mantém calma com exercícios de respiração... e com a canalização de seus dilemas internos em um ciclone brutal de lâminas mortais. ","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC217":["Brotinho de Silfo","Manifeste uma Fada e dê +1|+1 a ela.","","Toda criatura viva precisa de sustento. As fadas não são exceção, mas é difícil saber exatamente o que fazem com ele.","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC180":["Apressar","Retorne uma unidade com 3 ou menos de Poder.","","\"Somos ágeis como o vento!\" – Kennen","Feitiço",[],["Bandópolis"],"COMUM"],"05BC040":["Troca de Amuletos","Manifeste 1 Arirolvo ou um de 2 feitiços das suas regiões que custe 3 ou menos.","","\"Solte o meu sanduíche agora mesmo!\" – Conquiliologista","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC213":["Safanão","Cause 1 de dano a um inimigo e Atordoe-o.","","\"Ahanga!\" – Gnar","Feitiço",[],["Bandópolis"],"COMUM"],"05BC208":["Investida Heroica","Um aliado Golpeia um inimigo. Se ele sobreviver, Atordoe-o.","","\"Sai daí!\" – Poppy","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC085":["Sentinato Arruaceiro","Jogar: Descarte 1 para Manifestar um Mech Yordle e dê Escudo de Feitiço a ele.","","\"Dá pra abaixar isso aí?! Eu mal consigo me ouvir contando todo esse dinheiro!\" – Karl, o Mandante da Arena","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC112":["Muda de Pinstouro","Jogar: Eu ganho Barreira nesta rodada ou Impacto.","","As Mudas de Pinstouro são criaturas tímidas e, apesar de sua primeira reação ser recuar, se ameaçadas...","Unidade",["FADA"],["Bandópolis","Ionia"],"COMUM"],"05BC135":["Tiro Duplo","Um aliado Golpeia um inimigo. Se o aliado for multirregional, ele Golpeia o inimigo outra vez.","","\"Noz M1-85: um fuzil totalmente automático, calibre carvalho, com bandomira especializada e finalizador de roxamora. A mamãe aqui vai botar pra quebrar hoje!\"\n– Soldada de Bandópolis","Feitiço",[],["Bandópolis"],"COMUM"],"05BC084":["Chio","Jogar: Descarte 1 para Manifestar um Mech Yordle.","","Estatura pequena, personalidade GRANDE.","Unidade",[],["Bandópolis"],"COMUM"],"05BC184":["Bardos Barulhentos","Ao me invocar, crie 1 Gatoruja Faminto na mão.","","\"Esta é uma canção\nSobre Poppy, a queridinha da nação!\nPoppy, a grandiosa, poderosa... em ação! \n– Letra riscada do 'Livro de Canções de Reginaldáctilo e Fatimisqueiro, Bardos Extraordinários'","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC116":["Prefeito de Bandópolis","A cada rodada, a primeira unidade multirregional que você jogar custa 1 a menos.\nJogar: Manifeste um seguidor multirregional.","","Não se sabe se houve mesmo eleições para prefeito em Bandópolis, mas, sem dúvidas, ter um bigode de respeito seria um pré-requisito à candidatura.","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"05BC111":["Yordles Unidos ","Conceda +2|+2 aos aliados nesta rodada. Se você tiver jogado cartas de 4+ regiões, conceda aos aliados +3|+3.","","\"Caramba... o nosso grupo tá tão maneiro.\" – Tristana","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC224":["Transposição","Retorne um aliado. Se o próximo aliado jogado nesta rodada tiver um custo igual ou menor, custará 0.","","\"Corpo veloz, mente veloz!\" – Kennen","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC130":["Chapa Quente","Atacar: Dê +1|+1 e uma palavra-chave aleatória ao Campeão no topo do seu deck.","","Os churrascos de verão do Otto tinham certa fama. Embora ficasse animado com a grelha, ele deixava aos convidados poucas opções além de carne \"bem passada\" ou \"muito bem passada\".","Unidade",["YORDLE"],["Bandópolis","Shurima"],"COMUM"],"05BC191":["Veredito da Guardiã","Coloque uma unidade inimiga no topo do deck inimigo.","","\"E não volte mais!\" – Poppy","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC052":["Cacarecos Preciosos","Encha sua mão com cartas aleatórias. Elas custam 0 e são Fugazes. Você só pode jogar mais 3 cartas nesta rodada.","","O lixo de um mortal é uma pilha gigantesca de sucata preciosa para um yordle.","Feitiço",[],["Bandópolis"],"RARO (A)"],"05BC050":["Benêmona","Ao me invocar, crie 2 Travessuras na mão.","","\"Quem for suscetível a náuseas deve se aproximar desta gigante gentil com EXTREMA CAUTELA. Acredite, seu estômago vai te agradecer... Pensando bem, eu não deveria ter comido aquele segundo sanduíche de cogumelo...\" \n– Registro Ecológico do Conquiliologista, dia 3","Unidade",[],["Bandópolis"],"COMUM"],"05BC094":["Acólito Bulboscuro","Ao me invocar, crie 1 Escuridão na mão se não tiver.","","\"Sim, tenho quase certeza de que o rapaz lá em cima tem muitas histórias para contar. Todos sabem que ele tem muito a dizer, mas ninguém consegue entender NADA do que ele diz.\" – Alfaiate Esnobe","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC146":["Pintora de Bandópolis","Jogar: Descarte 1 para criar um seguidor multirregional na mão e reduza o custo em 1.","","\"A arte da pintura não se trata de copiar o que se vê, e sim de expressar como VOCÊ vê o mundo. E acabei de ver que você se mexeu DE NOVO! Para de se mexer!\"","Unidade",["YORDLE"],["Bandópolis","Piltover e Zaun"],"COMUM"],"05BC235":["Ferreiro Yordle","Atacar: Conceda Ataque Rápido aos aliados com Poder igual ou inferior ao meu nesta rodada.","","\"A Poppy nunca me escuta, mas acho bom você escutar: O que importa não é o martelo, e sim o yordle que o empunha.\"\n","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC175":["Telescópio Errante","Jogar: Manifeste uma carta Celestial que custe 3 ou menos, uma carta Épica ou um seguidor multirregional.","","A parte mais estranha não era ver o telescópio levantar, se espreguiçar e andar por aí, mas vê-lo fazer questão de se vestir conforme o clima, o que dava início à jornada em busca de um cachecol confortável para telescópios.","Unidade",["FADA"],["Bandópolis","Targon"],"RARO (A)"],"05BC182":["Investida Relâmpago","Retorne um aliado para causar 2 de dano a qualquer coisa.","","\"Primeiro o estalo, depois o estrondo!\" – Kennen","Feitiço",["ELEMENTAL"],["Bandópolis"],"RARO (A)"],"05BC069":["Yordle Palestrinha","Atacar: Crie 1 Dardo Venenoso Fugaz na mão.","","Nunca deixe ele desembestar a falar.","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC057":["Alfaiate Esnobe","Ao me invocar, reduza em 1 o custo das suas cópias de Escuridão globalmente.","","\"Ao instituir uma seita secreta, é preciso garantir que cada fanático ofereça algo único para essa união de supervilões. Um dos meus companheiros, por exemplo, tem um senso de estilo letal.\"\n– Trecho do Cap. 4 de \"Como Ser um Supervilão\", escrito por Lorde Veigar","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"05BC108":["Yordle Explorador","Ao invocar outro Yordle, dê +1|+0 a ele.","","\"A glória da exploração não tem preço, mas as maiores descobertas são sempre... hã... lucrativas.\"","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"05BC183":["Vovô Feérico","Ao me invocar, crie 1 Gatoruja Faminto na mão.\nAo invocar outra Fada, dê +1|+0 a ela.","","\"Venham, ouçam minhas palavras,\nO triste conto do Vovô Fada.\nTodos os dias, ele dava de comer às aves esfomeadas,\nUma mistura estranha de sementes e coalhadas...\"\n– Grande História de Bandópolis","Unidade",["FADA"],["Bandópolis","Ionia"],"RARO (A)"],"05BC188":["Conchianos Curiosos","Ao escolher uma carta de não Campeão dentre opções aleatórias, crie uma cópia dela na mão e reduza seu custo em 1.","","Conhecidos por sua timidez, sabe-se que os conchianos se escondem em suas conchas até que a curiosidade os force a sair. Quando emergem, demonstram toda sua personalidade brincalhona, pregando peças e imitando com maestria os sons de outras criaturas marinhas.","Unidade",[],["Bandópolis"],"ÉPICO (A)"],"05FR001":["Xamã Trevoguari","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Combatente Trevoguari.","","\"Nós não morremos feito covardes! Morremos com garras e dentes à mostra, assim, honramos o Lobo.\" – Vidente Hyara","Unidade",[],["Freljord"],"COMUM"],"05FR002":["Xamã Mamute","Fim de Rodada: Se você tiver causado dano ao Nexus inimigo nesta rodada, me transforme em Combatente Mamute.","","Quando enfrentam predadores, as manadas de mamutes cercam os filhotes jovens e as fêmeas prenhas. Então, os xamãs do grande espírito do mamute invocam não apenas a força física do espírito, mas também a força da união, com a qual protegem sua família.","Unidade",[],["Freljord"],"RARO (A)"],"05FR013":["Udyr","Ao me invocar ou Golpear: Crie 1 Troca de Postura na mão ou, se já tiver, reduza o custo a 0.","Você jogou Troca de Postura 3+ vezes.","\"Os Espíritos moldam o mundo assim como nós e o mundo moldamos os Espíritos. Ao extrair o poder deles, tiramos poder do nosso âmago.\"","Unidade",[],["Freljord"],"Campeão"],"05FR016":["Convocação Xamânica","Crie 2 Trocas de Postura Fugazes com custo 0 na mão.","","\"Você vai vê-los... grandes Espíritos com dentes e garras, escamas e penas. Nesse momento, tremerá de medo e veneração e saberá que os Deuses Antigos não nos esqueceram.\" – Vidente Hyara","Feitiço",[],["Freljord"],"COMUM"],"05FR012":["Vidente Hyara","Ao me invocar, crie 1 Troca de Postura na mão.\nA cada rodada, a primeira unidade Troca de Postura que você jogar custa 0.","","Respeitada por todos, a grande xamã, Vidente Hyara, perdeu a visão há muito tempo e enxerga através dos olhos dos falcões e águias que se aninham em sua casa no cume da montanha. Agora, notícias preocupantes levaram-na a descer a montanha... ela espera que os presságios não passem de meras visões.","Unidade",[],["Freljord"],"RARO (A)"],"05FR014":["Ira de Freljord","Jogar: Congele um inimigo.\nInimigos com 3 ou menos de Poder não podem bloquear.","","\"Eu estive lá anos atrás... primeiro, veio o frio, penetrante e implacável. depois, a tempestade, colérica e indiferente. Por último, um rugido tão forte que abalou meus ossos. Caí de joelhos e orei para que não tivéssemos cometido um grave erro. Invocar um grande espírito é pedir por sua vingança... e misericórdia.\" – Vidente Hyara ","Unidade",[],["Freljord"],"ÉPICO (A)"],"05FR017":["Fera Interior","Conceda +1|+1 a um aliado nesta rodada. Crie 1 Troca de Postura na mão.","","\"Venham, espíritos. Venham...\" – Udyr","Feitiço",[],["Freljord"],"COMUM"],"05FR006":["Orador das Presas","Jogar: Cause 1 de dano aos DOIS Nexus.","","Poucas famílias xamânicas servem à tribo Garra do Inverno há tanto tempo quanto a de Chuluun. Sendo um xamã da grande morsa, ele pressagia e anuncia a fartura do mar... e os perigos dele. ","Unidade",[],["Freljord"],"COMUM"],"05FR015":["Espíritos Libertos","Dê +1|+1 aos aliados globalmente. Depois, cause 1 de dano a TUDO.","","\"Ancestrais, revigorai nossa força contra o frio invasor e afugentai nossos inimigos com tempestades de vento e gelo, pois nunca nos esquecemos de vós e das honras que vos devemos.\"\n– Oração do Xamã Trevoguari","Feitiço",[],["Freljord"],"RARO (A)"],"05FR005":["Ossividente","Quando eu sobreviver a dano, cause 1 de dano ao Nexus inimigo.","","Poucos preveem o futuro tão bem quanto os xamãs a serviço do Alce dos Ossos. Pouquíssimos aguentam ver a morte iminente de quem busca sua clarividência.","Unidade",[],["Freljord"],"COMUM"],"05FR004":["Errante Vulpina","Ao me invocar, crie 1 Troca de Postura na mão.","","\"Ambiciosa e cautelosa. Rápida e silenciosa. O estilo da raposa é a alegria de ver e não ser vista. Em viagens ou guerras, um líder sábio honra quem segue o espírito dela, pois não se vence batalha alguma sem desbravadores e batedores.\" – Vrynna, Mãe das Cicatrizes","Unidade",[],["Freljord"],"COMUM"],"05IO003":["Ancestral Sem Rumo","Eu custo 2 a menos para cada unidade que você tiver Retornado nesta rodada.","","\"Himon'she, é uma honra poder viajar com você. Disseram que você tinha uma sabedoria imensurável. Aonde estamos indo?\"\n\"Ora, minha querida, eu estava seguindo você!\" – Ahri e o Ancestral Sem Rumo","Unidade",[],["Ionia"],"COMUM"],"05IO004":["Ahri","Atacar: Na primeira vez que eu Atacar Golpeando, me troque pelo aliado à minha direita e, depois, Retorne-o.","Você Retornou 5+ unidades.","Ela procurava a si mesma nos segredos alheios. Se viu através dos olhos de muitos. À medida que se aproximava da floresta, pensou: \"Será que desta vez será apenas mais uma lente, ou, só desta vez, encontrarei um espelho?\".","Unidade",[],["Ionia"],"Campeão"],"05IO023":["Encanto","Retorne um aliado para conceder Vulnerável a um inimigo nesta rodada.","","\"Me conte um segredo.\" – Ahri","Feitiço",[],["Ionia"],"COMUM"],"05IO020":["Cantaventos","Jogar: Retorne uma unidade.","","O caos dá garras aos indefesos. Um lobo cerca sua presa, mas é interrompido por um galho caído. Um falcão mergulha para atacar, mas sai da trajetória graças a um vento forte. Nós somos o galho. E o vento.","Unidade",[],["Ionia"],"COMUM"],"05IO007":["Sai'nen das Mil Caudas","Ao me invocar, compre 2 e conceda +1+1 aos aliados nesta rodada.","","A floresta oferece seus segredos de bom grado... mas poucos têm coragem de fazer perguntas a ela.","Unidade",[],["Ionia"],"ÉPICO (A)"],"05IO021":["Muda de Salgueiro Divino","Jogar: Retorne um aliado para invocar uma cópia Efêmera dele.\nContagem 3: Invoque outra cópia Efêmera dele.","","Uma vez, o Salgueiro Divino cresceu em Omikayalan. Agora, o que cresce por lá pode ser mais forte ou mais fraco — afinal, o importante mesmo é ser algo novo.","Monumento",[],["Ionia"],"RARO (A)"],"05IO024":["Filhos da Floresta","Retorne um aliado ou gaste 8 de Mana para invocar cópias Efêmeras dos 3 seguidores Mais Fortes que você Retornou nesta partida.","","Lembranças têm presas.","Feitiço",[],["Ionia"],"ÉPICO (A)"],"05IO001":["Guardiã do Arvoredo","Ao me invocar, me conceda +1|+0 e Elusivo nesta rodada.","","\"Dizem que você não fala pra poupar a todos do peso que o seu conhecimento tem. Hmm... Aposto que você só se cansou de responder a tantas perguntas.\" – Ahri","Unidade",[],["Ionia"],"COMUM"],"05IO025":["Matriarca Caudamanto","A cada rodada, na primeira vez que você Retornar um seguidor, invoque uma cópia Efêmera idêntica a ele.","","O mistério é mais fascinante que sua solução.","Unidade",[],["Ionia"],"RARO (A)"],"05IO026":["Os Lamentados","Golpe ao Nexus: Me Retorne.","","Se quiser venerar a caçada, terá que lamentar os caçados.","Unidade",[],["Ionia"],"RARO (A)"],"05IO006":["Sete Vidas","Invoque 1 Guardião Fronteiriço.","","A floresta precisava de um guardião — alguém que pudesse montar guarda nas fronteiras por anos, talvez séculos, sem se mexer. Gai'sh se voluntariou e rapidamente provou sua dedicação com uma soneca de 10 anos.","Feitiço",[],["Ionia"],"ÉPICO (A)"],"05IO002":["Manto das Memórias","Escolha um aliado alvejado por feitiços inimigos Rápidos, Lentos ou Habilidades com um único alvo aliado. Interrompa-os.","","A flecha desconhece a intenção do caçador e o valor da caça.","Feitiço",[],["Ionia"],"COMUM"],"05SH014":["Xerath","Quando você destruir um Monumento aliado, cause 1 de dano ao inimigo Mais Fraco.","Você destruiu 4+ Monumentos aliados.","\"A princípio, eram amigos, mas o tempo e a afinidade os tornou irmãos. Sem sombra de dúvidas, Azir jamais teria conquistado tanto sem Xerath ao seu lado.\" \n– Escriba Kah'nir, História do Batalhão dos Ascendentes","Unidade",["ASCENDENTE"],["Shurima"],"Campeão"],"05SH017":["Arauta do Mago","Ao me invocar, se você tiver destruído 4+ Monumentos aliados nesta partida, dê +2|+2 e Sobrepujar aos seus Campeões globalmente.","","Enquanto erguia o olhar em direção ao sol vermelho que pairava nos céus de Shurima, a Arauta abriu os braços e entoou aos ventos: \"Viva o Mago Ascendente!\". Sua voz ecoava pelo círculo de colunas destruídas que jaziam ao seu redor. \"Viva Xerath!\"","Unidade",[],["Shurima"],"RARO (A)"],"05SH011":["Devoto Eterno","Suspiro Final: Invoque 1 Sarcófago.","","Por mais que a tumba fosse recheada de riquezas, isso pouco importava aos olhos dos mortos e exilados.","Unidade",[],["Shurima"],"RARO (A)"],"05SH022":["Duelo no Deserto","Conceda -2|-0 a um inimigo nesta rodada. Um aliado e esse inimigo Golpeiam um ao outro.","","\"Um viajante que não teme o deserto, não conhece o deserto.\" – Provérbio shurimane","Feitiço",[],["Shurima"],"COMUM"],"05SH003":["Obelisco do Poder","Contagem 3, ao me invocar ou quando você me destruir: Dê +2|+0 ao aliado Mais Forte.","","Pilares faiscantes e crepitantes ergueram-se das areias, locais de poder subvertidos que reforçariam o já poderoso exército de Xerath.","Monumento",[],["Shurima"],"COMUM"],"05SH016":["Acólito Ruinoso","Jogar: Destrua um Monumento aliado para dar +1|+1 aos Acólitos Ruinosos aliados globalmente.","","Todos os acólitos de Xerath sacrificaram algo em troca de poder, mas seus seguidores mais poderosos foram ainda mais além. Eles se tornaram meras sombras das pessoas que um dia já foram, transformando-se em conduítes e fontes de energia para seu novo imperador.","Unidade",[],["Shurima"],"COMUM"],"05SH018":["Serventia da Desolação","Invoque 1 Estátua de Estase para reter todas as unidades e Monumentos que foram abatidos ou destruídos nesta rodada.","","Energia mágica não se dissipa — se renova.","Feitiço",[],["Shurima"],"ÉPICO (A)"],"05SH012":["Altar Erguido","Contagem 3 ou quando você me destruir: Invoque 1 Dami'yin, o Liberto.","","\"Devemos erguer um obelisco em cada foco de poder — um instrumento que o grande Mago Ascendente poderá usar para extrair poder direto das areias.\" – Arauta do Mago","Monumento",[],["Shurima"],"ÉPICO (A)"],"05SH020":["Constructo da Desolação","Crie 1 Acólito Ruinoso ou 1 Obelisco do Poder na mão.","","\"Shurima será moldada à minha imagem.\" – Xerath","Feitiço",[],["Shurima"],"COMUM"],"05SH015":["Vidente das Areias","Ao me invocar, compre 1. Se comprar um Monumento, repita este efeito.","","O horizonte à frente vibrava com energia — onde outros viam apenas areia e sedimentos, ela enxergava linhas energéticas, malhas ofuscantes de pura energia que jaziam ali, ao seu dispor.","Unidade",[],["Shurima"],"ÉPICO (A)"],"05SH004":["Energia Indomável","Conceda +2|+1 a um aliado nesta rodada ou destrua um Monumento aliado para conceder +4|+2 a um aliado nesta rodada.","","\"Vou arrancar o poder do deserto e destruir todos que se opuserem a mim!\" – Xerath","Feitiço",[],["Shurima"],"COMUM"],"05SH002":["Errante das Ruínas","Quando você destrói um Monumento aliado, eu ganho +1|+1.","","Os acólitos já eram bem-sucedidos antes de buscar Xerath. Mas, agora que tinham estudado o que ele um dia estudou, eram imbatíveis.","Unidade",[],["Shurima"],"COMUM"],"05SH007":["Ritual Arcano","Destrua um Monumento aliado ou uma de suas gemas de Mana para causar 4 de dano a uma unidade.","","\"Um pequeno sacrifício em troca de um grande poder.\"\n– Xerath","Feitiço",[],["Shurima"],"RARO (A)"],"05NX009":["Alma Perdida","Ao me invocar ou me descartar, crie 1 Revenã das Lâminas Gêmeas na mão.","","Os demacianos rastejaram em direção às muralhas e encontraram a morte descendo por elas. Embora tenham conseguido derrubar alguns membros da Legião Cinérea, o curso sombrio da guerra logo se mostrou inevitável.","Unidade",[],["Noxus"],"ÉPICO (A)"],"05NX006":["Granadeiro Renascido","Para me pôr em jogo, descarte 1.\nAo me descartar, invoque uma cópia idêntica a mim.","","\"Temos entre nós um caso irregular. Embora a maioria dos ressuscitados abomine o retorno à vida, esse sujeito parece compreender a sua sorte e apreciar as oportunidades advindas disso. Interessante.\"\n– Anotações do Dr. Esslanger","Unidade",[],["Noxus"],"COMUM"],"05NX005":["Belicista Ancestral","Ao me descartar, dê +2|+0 ao seu aliado Mais Forte.","","Conforme os poderes da Senhora Noradi aumentavam, ela se perguntava se eles poderiam se imbuir nos cadáveres das tumbas mais antigas de Noxus. Para ela, a luz da vida era uma mera faísca superficial. Mas, naquela chama fraca, as sombras da guerra ainda dançavam.","Unidade",[],["Noxus"],"RARO (A)"],"05NX001":["Sion","Ao me descartar, dê Sobrepujar ao seu aliado Mais Forte e me coloque no seu deck.\nEu tenho +1|+0 para cada carta que você descartou nesta partida (máx. de +7|+0).","Você descartou ou invocou 35+ de Poder.","Sion teve lampejos de memórias vagas. Legiões posicionadas diante dele. Honrarias. Coroas. Guerra. O último suspiro de um rei. O grande vazio. Sangue. Mas eles passaram rápido e se foram, como fitas desbotadas ao vento.","Unidade",[],["Noxus"],"Campeão"],"05NX003":["Sal e Suturas","Para me pôr em jogo, descarte uma carta.\nInvoque 1 Granadeiro Renascido e conceda-o +2|+0 nesta rodada.","","\"Levante-se outra vez, criança...\" – Dr. Esslanger, Médico Atencioso","Feitiço",[],["Noxus"],"RARO (A)"],"05NX015":["Desafiador Caído","Ao me invocar, dê Não Bloqueia ao inimigo Mais Fraco.\nSuspiro Final: Crie 1 Desafiador Reerguido na mão.","","\"Os primeiros minotauros que ressuscitei eram dóceis e inofensivos. Nem o tumulto da guerra nem a ameaça de morte eram capazes de atiçar seus sentidos.\"\n– Anotações do Dr. Esslanger","Unidade",[],["Noxus"],"RARO (A)"],"05NX019":["Pela glória!","Reputação: Eu custo 3 a menos. Invoque 2 Trifarianas Ambiciosas.","","Quem busca a glória faz de tudo para encontrá-la.","Feitiço",[],["Noxus"],"RARO (A)"],"05NX013":["Cavaleiro Caído","Ao me descartar, crie 1 Cavaleiro Reerguido na mão.","","\"Só depois de esfregarem a armadura do cavaleiro com folhas de erva-embreada eles foram poupados da crueldade do basilisco. Assim como essas feras, as plantas são nativas dos campos, e são tão pungentes quanto venenosas.\"\n– Anotações do Dr. Esslanger","Unidade",[],["Noxus"],"COMUM"],"05NX012":["Urro do Assassino","Para me pôr em jogo, descarte 1. Abata o inimigo Mais Fraco.","","\"Aliado, inimigo... Não faz diferença.\" – Sion","Feitiço",[],["Noxus"],"COMUM"],"05NX014":["Armas dos Perdidos","Cause 3 de dano a uma unidade e invoque 1 Quebra-escudos Trifariano.","","\"Quebra-escudos!\" – Sion","Feitiço",[],["Noxus"],"COMUM"],"05NX004":["Médico Sepulcral","Jogar: Descarte 1 para comprar uma unidade.","","O Dr. Esslanger era um médico aposentado e respeitado, cuja reputação fora conquistada ao longo de anos de dedicação e trabalho. Mas foi apenas quando uma jovem nobre foi levada ao seu consultório, com o sangue escurecido pela traição, que ele realmente começou a servir a Noxus.","Unidade",[],["Noxus"],"COMUM"],"05NX016":["A Senhora do Sangue","Quando um aliado não Fugaz for descartado da mão, crie 1 cópia Fugaz dele na mão.","","Na calada da noite, a Senhora Faris Noradi retirou sua Legião Cinérea da capital noxiana. Após três semanas árduas e sangrentas, o exército enfim se aproximou do pequeno posto demaciano que os batedores haviam identificado. Era hora da demonstração.","Unidade",[],["Noxus"],"ÉPICO (A)"],"05NX002":["Nobre Rebelde","Eu ganho +2|+1 quando você tiver descartado 3+ cartas nesta partida.","","\"Quer inspirar lealdade em um possível traidor? Nada melhor do que mostrar a volta de um conspirador assassinado para lutar sob a bandeira noxiana. De uma forma ou de outra, todos acabam se submetendo.\" – A Senhora do Sangue","Unidade",[],["Noxus"],"COMUM"],"05BW005":["Nami","Ao jogar um feitiço, dê +1|+0 ao outro aliado Mais Fraco que não estiver Imóvel.","Você jogou 5+ feitiços com uma Nami aliada em jogo.","\"Já se despediu de todos, jovem Conjuradora?\"\n\"Sim, grande mãe.\"\n\"Está com medo?\"\n\"... Sim, grande mãe.\"\n\"Que bom. Ter medo é ter cautela. Mas confie em si mesma, como todos nós confiamos. Agora vá. E que as correntezas te protejam.\"","Unidade",[],["Águas de Sentina"],"Campeão"],"05BW006":["Vazante","Cause 2 de dano aleatoriamente a um inimigo ou ao Nexus inimigo e crie 1 Fluxo na mão.","","\"Preste atenção ao humor das marés...\" – Nami","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"COMUM"],"05BW002":["Aventureiro Saltareias","","","\"Alguns deles caçam a gente, mas, até aí, eles sempre caçam de tudo. Sabe, a maioria das criaturas da superfície que já conheci só quer curtir o mar como a gente. No fundo, somos todos iguais.\"","Unidade",[],["Águas de Sentina"],"COMUM"],"05BW008":["Guarda Abissal","Ao jogar um feitiço, me conceda +2|+0 nesta rodada.","","Muitos na nossa tribo acham Loto um pouco desconcertante. Eles só enxergam um lutador incansável e o pesar em seu olhar aflito. Mas eu sei o que ele carrega no peito: o medo de não ser forte o bastante para nos salvar... e um amor extraordinário.\" – Tama, Cantora Marai","Unidade",[],["Águas de Sentina"],"COMUM"],"05BW011":["Almirante Shelly","A cada rodada, ao jogar 2 feitiços, dê +1|+1 aos outros aliados.","","\"PLESTE BEM ATENÇÃO, SOLDADO. FIQUE SABENDO QUE EU TENHO MAIS DE 300 MORTES NA MINHA CONTA E SOU A MAIOR ALMILANTE DE TODA A MALINHA, ENTÃO, QUANDO EU MANDÁ NADÁR, CÊ NADA, TÁ BÃO? TÁ BÃO ENTÃO, OBLIGADA!\"","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"05BW003":["Maré Violenta","Cause 1 de dano a dois inimigos aleatórios diferentes e crie 1 Maré Avassaladora no seu deck.","","\"Oceanos, espalhem-se!\" – Nami","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"RARO (A)"],"05BW004":["Avatar das Marés","Se fosse receber uma gema de Mana, recarregue seu Mana de Feitiço.\nAo jogar um feitiço, crie na mão um feitiço aleatório que custe 3 ou menos e dê Fugaz a ele.","","Para os Marai, Leo'lei é presságio de grandes mudanças. Dizem que cada movimento de suas graciosas asas influenciam o curso das marés.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"05BW001":["Vigia Marai","Ao me invocar, invoque um seguidor aleatório com 1 de custo.","","Os Marai raramente se aventuram para longe de casa, mas Ai'la nasceu com a curiosidade nas veias. Mesmo fazendo jus ao dever que tem com a tribo, ela passa cada minuto acordada sonhando com o dia em que poderá ser livre de verdade.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"05BW010":["Grande Mãe Marai","Ao me invocar, crie no seu deck 5 feitiços aleatórios que custem 6+ e reduza o custo deles para 3.","","O lar ancestral dos Marai é protegido pela luz celestial de uma pedra da lua. A cada cem anos, a luz começa a diminuir, e um novo Conjurador das Marés precisa encontrar outra pedra. Sem ela, o povo Marai cairia na escuridão e seria vitimada pelos horrores que assolam as profundezas.","Unidade",[],["Águas de Sentina"],"COMUM"],"05BW013":["Cantora Marai","Ao me invocar, se você tiver jogado um feitiço nesta rodada, eu ganho Elusivo.","","\"O oceano acredita que as ondas voltarão.\nConfia na vazante, no fluxo e na oscilação.\nQuando a onda rebenta na areia, \no oceano solta o rugido da maré cheia.\"\n– Estrofe de \"Serenata para a Conjuradora das Marés\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"05PZ015":["Motoqueira da Justiça","Sempre que o oponente comprar, Plante 1 Bomba de Clarão entre as 8 cartas no topo do deck inimigo.","","\"A policial foi vista perseguindo o suspeito em alta velocidade na direção de uma armadilha armada por ela mesma. Após a captura, a agente emitiu sua própria multa por excesso de velocidade, alegando (de forma um tanto dramática) que a 'justiça é uma via de mão dupla'.\"\n– Trecho do relatório de operação de um Vigia","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"05PZ012":["Arquivista da Delegacia","Jogar: Escolha um feitiço dentre as 5 primeiras cartas no seu deck e crie uma cópia idêntica Fugaz na mão. Depois, coloque essas 5 primeiras cartas no deck.","","Detetives não são nada sem pistas. O trabalho do arquivista é coletar todas as informações e encontrar possibilidades ainda não identificadas.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"05PZ026":["Linha de Montagem","Invoque 2 Operários da Forja.","","\"Mudança de turno!\" – Chefe da Forja","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ019":["A Mais Procurada","Escolha um jogador para descartar a carta de menor custo que tiver e comprar 3.","","\"Tudo tem seu custo.\" – Corina Veraza","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"05PZ031":["Albus Ferros","Ao me invocar, compre Jayce. Atacar: Cause 3 de dano ao Nexus inimigo. Para cada feitiço com 6+ de custo que você tiver jogado nesta partida, aumente o dano em 1.","","\"E, mais uma vez, o magnânimo Albus Ferros ARREBATOU a atenção de todos ao dar um lance consideravelmente maior que o do Clã Cadwalder pelo direito de financiar a pesquisa de Hexportais de Jayce. É como o ditado diz: 'Um belo dia para os Ferros é um belo dia para Piltover'. E ontem foi, sem sombra de dúvidas, um ótimo dia para os Ferros.\"\n– Trecho de uma matéria patrocinada no Diário de Piltover","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"05PZ027":["Disparo Chocante","Cause 3 de dano a um inimigo ou ao Nexus inimigo, e 3 de dano a outro inimigo.","","\"Atirar!\" – Jayce","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"05PZ022":["Jayce","Jogar: Eu ganho Ataque Rápido ou Desafiador.","Você jogou dois feitiços com 6+ de custo. Quando eu subir de nível, crie 1 Portão Acelerador na mão.","\"Então, Rosa, como você bem sabe, essa tecnologia Poderomativa promete mudar o mundo.\"\n\"Um trabalho realmente inovador, Jayce. A maneira como esses metalibradores se encaixam um no outro é de tirar o fôlego.\"\n\"É mesmo. E foi tudo ideia do Axel! Né não, meu chapa?\"\n\"Sabe como é, né, chapa? Não gosto de me gabar...\"","Unidade",[],["Piltover e Zaun"],"Campeão"],"05PZ017":["Vapores do Sumidouro","Cause 2 de dano a uma unidade. Se você tiver adicionado 2+ cartas à sua mão nesta rodada, cause 3 de dano.","","\"É bom deixar arejar um pouco. No início, é difícil aguentar o cheiro. Mas depois que você se acostuma... não tem nada melhor!\" – Comerciante de Cogumelos","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ013":["Pacificadora de Piltover","Cause 2 de dano a uma unidade e Plante 2 Bombas de Clarão entre as 8 cartas no topo do deck inimigo.","","\"Pegue MEU cartão.\" – Caitlyn","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ020":["Emboscada","Conceda +2|+0 a um aliado nesta rodada. Se você tiver adicionado 2+ cartas à sua mão nesta rodada, conceda Elusivo a ele nesta rodada.","","\"Vamos cercar o local e usar bombas de fumaça para esconder nossos movimentos.\" – Caitlyn","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ024":["Financista dos Ferros","Jogar: Manifeste um feitiço com 6+ de custo das suas regiões.","","\"Uma das únicas coisas boas de ter os Ferros financiando o meu trabalho é poder trabalhar com o Reggie. O cara não é só uma das pessoas mais competentes que eu já conheci, como também é um sujeito sensacional.\"\n– Trecho do diário de Jayce","Unidade",[],["Piltover e Zaun"],"COMUM"],"05PZ010":["Informações Antecipadas","Plante 2 Bombas de Clarão entre as 8 cartas no topo do deck inimigo.\nCompre 1.","","\"Ao meu sinal.\" – Caitlyn","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ014":["Corina, Mestra do Crime","Jogar: Plante 5 Bombas de Clarão entre as 5 cartas no topo do deck inimigo ou ative os efeitos de todas as armadilhas nas 5 cartas no topo do deck inimigo.","","Quando os Vigias de Piltover arrombaram sua porta, Corina sorriu. Enquanto eles pisoteavam suas preciosas flores, elas lançavam nuvens de pólen tóxico. Tudo conforme planejado.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"05PZ002":["Informação Privilegiada","TODOS os jogadores compram 2.","","\"Esse caso é muito famoso, sabe? Hoje mesmo um sujeito veio dar uma olhada nele. Fique à vontade!\" – Arquivista da Delegacia","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ021":["A Forja do Amanhã","Ao me invocar, invoque 1 Operário da Forja. Ao jogar um feitiço com 6+ de custo, me destrua e recarregue seu Mana de Feitiço.","","Se a força motriz de Piltover são suas invenções, então as forjas são as engrenagens.","Monumento",[],["Piltover e Zaun"],"RARO (A)"],"05PZ025":["Chefe da Forja","Golpear: Recarregue 1 de Mana de Feitiço.","","\"Para tirar uma ideia do papel, é preciso ter duas coisas: uma é um bom financiamento, e a outra, uma boa forja. E não estou falando só das ferramentas ou do maquinário da forja, não — se a pessoa no comando não tiver o que é preciso para fazer tudo funcionar... a sua ideia não vai sair do papel.\" – Jayce","Unidade",[],["Piltover e Zaun"],"COMUM"],"05PZ006":["Caitlyn","Golpear: Plante 2 Bombas de Clarão entre as 8 cartas no topo do deck inimigo.","5+ das suas armadilhas foram ativadas.","Caitlyn sempre foi uma investigadora obstinada e meticulosa, qualidades que a ajudaram a subir rapidamente nos ranques da polícia de Piltover. Mas, quando o caso de um certo 'C' caiu em suas mãos, depois de ter sido abandonado por vários outros oficiais, parecia que Caitlyn finalmente havia encontrado alguém à sua altura. Quase.","Unidade",[],["Piltover e Zaun"],"Campeão"],"05PZ004":["Esquadrão Policial","Ao me invocar, crie 1 A Mais Procurada na mão.","","Desde a chegada ao local da ação até a montagem do aríete, a preparação não demorou muito. Agora era só esperar o sinal da Caitlyn.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"05PZ009":["Policial Infiltrado","Golpe ao Nexus: Plante 2 Bombas de Clarão entre as 8 cartas no topo do deck inimigo.","","Como todas as crianças zaunitas, Zayne Asako precisou amadurecer rápido para sobreviver à violência das ruas sombrias. Depois de perder o irmão para a violência desnecessária das gangues, ele se alistou na polícia de Piltover na esperança de que a razão e a lei finalmente tornassem sua cidade segura.","Unidade",[],["Piltover e Zaun"],"COMUM"],"05PZ016":["Golpe de Misericórdia","Coloque um seguidor inimigo no deck inimigo, depois seu oponente compra 1.","","A grande cidade de Piltover abriga algumas das mentes mais geniais de Runeterra. As prisões de Piltover também abrigam algumas das mentes mais geniais de Runeterra.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"05PZ030":["Anomalia Hextec","Ao me comprar ou me criar na mão, ou a cada Início de Rodada: Enquanto eu estiver na mão, me transforme em um feitiço aleatório de custo 6+.","","\"...tornar a tecnologia hextec estável foi a coisa mais difícil que já fiz. Na maioria das noites, parecia até que os cristais e a hexita estavam conspirando para me passar a perna. Foi só depois de várias tentativas e erros que eu consegui fazer os componentes trabalharem em harmonia...\"\n– Trecho do diário de Jayce","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"05PZ028":["Cruza-céu dos Ferros","Eu ganho +2|+0 depois que você jogar um feitiço com 6+ de custo nesta partida.","","\"O povo desta cidade venera a 'inteligência', mas de que adianta a mente mais brilhante sem os recursos necessários para expressá-la? Basta. Mostrarei a Piltover o que é a verdadeira grandeza. E ela sobrevoará as cabeças de todos, bloqueará o sol e carregará o meu nome.\" – Albus Ferros","Unidade",[],["Piltover e Zaun"],"COMUM"],"05PZ038":["Barragem de Mísseis","Cause 4 de dano a um inimigo e 1 de dano a todos os outros inimigos.","","\"É pra irem pra cima, não pra TODO LADO! Ai, caramba!\" – Heimerdinger","Feitiço",[],["Piltover e Zaun"],"COMUM"],"05PZ035":["Raxinim Fedorento","Suspiro Final: Crie uma cópia minha com 2 Cogumelos Venenosos no deck inimigo.","","O fedor de um raxinim no auge da temporada de cogumelos é inigualável. Imagine um esgoto a céu aberto cheio de peixes estragados e ovos podres, e já dá para ter uma boa ideia do que esperar.","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"05PZ029":["Portador Hextec","Dê +1|+0 aos aliados Tecnológicos globalmente depois que você jogar um feitiço com 6+ de custo nesta partida.","","O Portador Hextec foi inicialmente construído para transportar materiais brutos por Piltover. Com o tempo, porém, parece que os moradores da cidade desenvolveram certo carinho por ele. A equipe da forja de Jayce o apelidou de Latinha, enquanto um lorde piltovense aparentemente doou um chapéu a ele e, agora, até mesmo as crianças que o encontram o enfeitam com o que tiverem em mãos.","Unidade",["TECNOLÓGICO"],["Piltover e Zaun"],"RARO (A)"],"05SI014":["Catálogo de Arrependimentos","Início de Rodada: Crie na mão uma cópia Fugaz de um feitiço não Fugaz que você tenha jogado na última rodada.","","Do que Ilhas das Bênçãos esquecem, as Ilhas das Sombras se lembram. Do que as Ilhas das Sombras se esquecem, as Ilhas das Bênçãos se lembram.","Monumento",[],["Ilhas das Sombras"],"ÉPICO (A)"],"05SI013":["Guardiões da Névoa","A cada rodada, na primeira vez que você abater uma unidade com um feitiço, invoque 1 cópia Efêmera de Espectro da Névoa.","","A Névoa Negra aprisiona suas vítimas em ciclos de tormento sem fim infligidos por si mesmas. E é através dos Apanhadores da Névoa que Tek e Kana dão a essas almas uma chance de quebrar esses ciclos.\n","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"05SI009":["Senna","Ao me invocar ou Atacar: Crie 1 Escuridão na mão se não tiver. Seus feitiços de dano e abate passam a ser Rápidos.","Vi você abater 3+ unidades com feitiços ou um Lucian aliado morrer.","\"Juntar-se à causa dos Sentinelas significa lutar. Significa perder a si ou aqueles que você ama. Mas, acima de tudo, significa viver. Por você... e por aqueles que você ama.\"","Unidade",[],["Ilhas das Sombras"],"Campeão"],"05SI016":["Sombra da Alvorada","Abata uma unidade e conceda a todos os inimigos -2|-0 nesta rodada.","","\"Não há sombra sem luz. Não há morte sem vida.\" – Senna","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"05SI004":["Vigilante das Ilhas","A cada rodada, cause 2 de dano ao Nexus inimigo na primeira vez que você abater uma unidade com um feitiço.","","\"O cachorrinho é o cachorrinho.\" – Sabedoria rabiscada na alma","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"05SI012":["Sentinela Solari","Ao me invocar, crie 1 Escuridão na mão se não tiver.","","\"Não sinto mais a energia do sol. Mesmo assim, mantenho-a em minhas lembranças — isso já é suficiente.\"","Unidade",[],["Ilhas das Sombras"],"COMUM"],"05SI008":["Sentinela Ixtalense","Ao me invocar, crie 1 Escuridão na mão se não tiver. Ao jogar a próxima carta Escuridão nesta rodada, copie-a alvejando o Nexus inimigo.","","\"Senna, você me perguntou o que me trouxe até aqui. É verdade que não perdi nada para a Névoa, já que ela não ameaça minha terra natal. Mas ela existe, mesmo quando não deveria. Estou aqui para saber por quê. Preciso mesmo de um passado triste para me juntar à causa?\"","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"05SI003":["Escuridão Perfurante","Drene 5 de uma unidade.","","\"A morte e a vida se atraem.\" – Senna","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"05SI010":["Dess e Ada","Ao me invocar, crie 1 Escuridão na mão se não tiver. Sua próxima carta Escuridão nesta rodada custa 0 e recebe \"Eu causo dano a todos os inimigos\".","","\"Outro pesadelo?\"\n\"Dessa vez não foi tão ruim. Você não estava lá.\"\n\"Besta. E qual foi a parte ruim?\"\n\"Você não estar lá.\"","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"05SI011":["Sentinela Prodígio","Na primeira vez que você abater uma unidade com um feitiço, eu ganho +2|+1.","","O que será que a Névoa vê ao se deparar com Maeve? Exuberância, confiança... otimismo inabalável? Seja o que for, mal deve ver a hora de apagar essa chama insolente. Afinal, o que a morte teme se não o ardor da vida?","Unidade",[],["Ilhas das Sombras"],"COMUM"],"05SI015":["Sentinela Buhru","Na primeira vez que você abater uma unidade com um feitiço, eu ganho +2|+1.","","As filosofias dos Buhru e dos Sentinelas compartilham de um único ponto crucial: todas as coisas devem ter um fim, e algumas precisam ser obrigadas a chegar lá.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"05MT004":["Camphor, a Dúvida","Ao me invocar, se você tiver alvejado aliados em 4 rodadas diferentes, eu ganho Escudo de Feitiço, Sobrepujar e Desafiador.","","Durante séculos, a demônia Camphor vagou pelas terras de Targon, tirando de suas vítimas os pontos fortes que as definiam. Dos poderosos, ela tomava a força; dos sábios, o conhecimento. Mas ela não tinha interesse nessas dádivas — era a insegurança, a miséria e o sofrimento causados que a saciavam. Camphor era um monstro em todos os sentidos da palavra.","Unidade",[],["Targon"],"ÉPICO (A)"],"05MT006":["Chamabranca Ferido","","","\"Os targonenses não precisam de mais provas para atestar a crueldade dos deuses. Olhe o que fizeram conosco. Olhe o que fizeram com nossos queridos companheiros.\" – Pantheon","Unidade",["DRAGÃO"],["Targon"],"RARO (A)"],"05MT008":["Escudo-cometa","Dê +1|+1 a um aliado e Atordoe um inimigo.","","Pantheon era bem versado na arte da guerra. Graças a inúmeras batalhas travadas, ele sabia que seus inimigos ficariam de olho na lança, mas não no escudo.","Feitiço",[],["Targon"],"RARO (A)"],"05MT014":["Beleza Celestial","Atordoe dois inimigos.","","\"O céu noturno de Targon é de uma beleza estonteante. É fácil se perder contemplando a imensidão, sem saber até onde ela se estende e que tipo de seres podem estar a nos observar...\" – Alpinista targonense","Feitiço",[],["Targon"],"COMUM"],"05MT003":["Pantheon","","Você alvejou aliados em 5+ rodadas diferentes.","Este é Atreus, que teve sua liberdade roubada pelos próprios Aspectos que venerava. Estas são as chamas da Guerra, que deixaram Atreus com dádivas que poucos mortais conseguem compreender. Este é um homem pronto para lutar e morrer por aqueles que ama.","Unidade",[],["Targon"],"Campeão"],"05MT013":["Iula","Jogar: Dê Escudo de Feitiço ou Sobrepujar a um aliado. Caso não o faça, dê a mim.","","Iula ainda lembra o ardente pesar que atravessou seu corpo ao ouvir sobre a morte do marido. Quando Pantheon apareceu perguntando se ela o ajudaria a destruir a criatura que havia se deleitado com a dor que sentira, a resposta dela foi rápida.","Unidade",[],["Targon"],"COMUM"],"05MT009":["Laços de Batalha","Dê +2|+2 a 2 aliados.","","Guerrear contra os deuses parecia uma missão ingrata, mas em meio aos gritos e depois de marcar a pele com cicatrizes, os corajosos aprenderam algumas lições. Os deuses eram individualistas, egoístas, e tinham perdido o dom da camaradagem. Essa seria a arma e a armadura que usariam contra eles.","Feitiço",[],["Targon"],"COMUM"],"05MT010":["Mística Cega","Jogar: Dê +1|+1 a um aliado e Silencie um seguidor inimigo.","","Eshiyme já foi uma profetisa renomada que usava sua Visão para guiar quem precisasse. Porém, essa dádiva fora roubada por Camphor, que desejava saciar-se com a inevitável angústia de Eshiyme. Camphor nunca poderia ter imaginado a coragem da profetisa.","Unidade",[],["Targon"],"COMUM"],"05MT002":["Juntos Resistimos","Conceda +1|+2 a 2 aliados nesta rodada.","","\"É nos laços que cultivamos com nossos semelhantes que devemos encontrar força.\" – Pantheon","Feitiço",[],["Targon"],"RARO (A)"],"05MT012":["Colosso Liberto","Ao me invocar ou Atacar: Crie 1 Gema na mão.","","Colossos são os antigos e venerados protetores dos pontos mais reverenciados de Targon. Prejudicá-los é o mesmo que prejudicar a montanha. Torturá-los é um crime imperdoável a olhos targonenses.","Unidade",[],["Targon"],"COMUM"],"05MT011":["Encarando o Impossível","Se o oponente tiver mais unidade que você, dê +1|+1 a um aliado para cada unidade extra que ele tiver.","","Essas corajosas criaturas sabiam que estavam prestes a enfrentar seres de poder inimaginável. Sabiam que a morte era quase certa. Mesmo assim, lá estavam.","Feitiço",[],["Targon"],"ÉPICO (A)"],"05MT005":["Idealizador de Sagas","","","Tor sentiu sua vida esvaindo a cada pulsação. Porém, em meio àquela sepultura e à escuridão, onde deveria ser envolto pelo medo, ele encontrou propósito: não só encararia a morte de bom grado, como também levaria consigo o demônio que ousou encurtar sua vida. É assim que ele seria lembrado. Esta seria a saga de Tor.","Unidade",[],["Targon"],"COMUM"],"05DE003":["Gorlith, o Inescalável","Jogar: Ao me invocar, troque minha Vida pela do seu Nexus.\nInimigos com menos Vida do que eu não podem me bloquear.","","\"Um tributo honroso para aqueles que se foram, mas ficaram na memória: Quando as pessoas de Demacia virem os raios de sol refletindo na figura dele, saberão o que é esperança, e o espírito indomável que inspirou a construção viverá através dele.\"\n– Placa da oficina Durand","Unidade",[],["Demacia"],"ÉPICO (A)"],"05DE009":["Galio","Ao me invocar, dê +0|+3 aos outros aliados.","Fim de Rodada: Seus aliados têm 25+ de Vida total.","Durante muitos anos após sua criação, Galio permaneceu adormecido, inerte, inconsciente. Depois que a magia deu-lhe vida, ele experimentou a emoção da batalha e descobriu a alegria de estar entre os vivos. Agora, quando dormia, sentia falta dessas maravilhas!","Unidade",[],["Demacia"],"Campeão"],"05DE020":["Escudo de Durand","Dê +0|+3 a um aliado. No próximo Início de Rodada, dê +0|+2 a ele.","","A mera visão do Galio basta para inspirar o coração nobre dos demacianos.","Feitiço",[],["Demacia"],"RARO (A)"],"05DE021":["O Poder da Vanguarda","Para me pôr em jogo, gaste todo o seu Mana. Invoque 1 Vanguarda Destemida e aumente os atributos da carta invocada até atingir a quantia gasta. Se 9+ de Mana for gasto, dê +2|+2 aos outros aliados Elite.","","Quando parece que não há mais esperança, os soldados de Demacia se inspiram na Vanguarda.","Feitiço",[],["Demacia"],"ÉPICO (A)"],"05DE017":["Ventos de Guerra","Cure completamente um aliado. Depois, o aliado e um inimigo Golpeiam um ao outro.","","\"Então vamos botar pra quebrar!\" – Galio","Feitiço",[],["Demacia"],"RARO (A)"],"05DE010":["Escultora de Durand","Quando você invocar outro aliado, dê +0|+1 a ele.","","\"Pode não ser óbvio para leigos, mas a obra de um grande artista está entre um talhar e outro do cinzel.\"","Unidade",[],["Demacia"],"COMUM"],"05DE013":["Cervo de Petricita","Auxiliar: Sofro todo o dano no lugar do meu aliado auxiliado nesta rodada.","","Atrás do Guarda montado no cervo, o Guardião de petricita ofuscava a criatura que havia inspirado sua figura elegante.","Unidade",[],["Demacia"],"ÉPICO (A)"],"05DE015":["Dragão da Montanha","Fúria me dá +0|+2 em vez de +1|+1.","","Apesar de sua aparência, os serenos dragões da montanha não se irritam facilmente, e seu estoicismo ao redor de outras criaturas montanhesas faz com que sejam defensores natos de rebanhos vulneráveis.","Unidade",["DRAGÃO"],["Demacia"],"ÉPICO (A)"],"05DE019":["Arquiteto de Durand","Auxiliar: Conceda +0|+2 e Formidável ao meu aliado auxiliado nesta rodada.","","\"O Guarda Cordielmo trouxe más notícias\", anunciou calmamente o arquiteto, focando em enrolar de novo o pergaminho para esconder o tremor nas mãos. Ele se virou para os escultores, que estavam à espera, e deu um aceno rígido com a cabeça. \"Parece que chegou a hora de os defensores secretos de Demacia saírem das sombras.\"","Unidade",[],["Demacia"],"RARO (A)"],"05DE014":["Pupila de Durand","Jogar: Dê +0|+1 e Robusto a um aliado.","","Shireen tirou os olhos de seu trabalho ao ouvir o som de cascos velozes. A pressa do guarda deixou-a inquieta, mas curiosa. Ela incitou seu pássaro de petricita a voar no encalço do homem.","Unidade",[],["Demacia"],"COMUM"],"05DE012":["Asalonga de Petricita","Quando você invocar outro aliado, eu ganho Desafiador.","","Quando a Asalonga cruzou o céu, os soldados desalentados de Demacia comemoraram no chão, inspirados por sua forma resistente.","Unidade",[],["Demacia"],"RARO (A)"],"05DE018":["Cão de Petricita","","","\"É sempre uma alegria vê-los ganhando vida. Você esquece que cada um é único e que sua personalidade é um reflexo do artista que os criou.\" – Escultora de Durand","Unidade",[],["Demacia"],"COMUM"],"06NX024":["Lorde Jubalarga","Jogar: Cause 2 de dano a um inimigo.\nSeus feitiços Rápidos, feitiços Lentos e Habilidades têm \"Quando eu causar dano a um inimigo Atordoado ou que já sofreu dano, abata-o\".","","\"Ato dois: Um lorde duvidoso e sem muitas posses, além de uma manopla Kashuri roubada, encanta uma plateia de ionianos. No entanto, sua máscara é grosseira e não esconde muito. Ele implora por sua vida, alegando ignorância. A mão de ferro que queria usar para governar agora está vazia.\"","Unidade",[],["Noxus"],"RARO (A)"],"06NX033":["Execução Estratégica","Atordoe 2 inimigos ou gaste 6 de Mana para invocar 1 General da Legião.","","As atribuições são as primeiras grandes decisões antes de uma batalha. Um bom comandante sabe que elas são essenciais para a vitória...","Feitiço",[],["Noxus"],"RARO (A)"],"06NX012":["Annie","Atacar: Eu causo 2 de dano ao meu bloqueador. Se ele tiver sido abatido ou removido, eu causo 2 de dano ao Nexus inimigo.","Vi você jogar 6 feitiços Rápidos, feitiços Lentos ou Habilidades. Quando eu subir de nível, crie 1 Tibbers na mão.","Há mais de uma década, Amoline Kiosar fugiu do Conservatório Floricorvus com algo inestimável e incandescente sob seu controle. Os patrulheiros da Floricorvus a procuraram em todos os cantos do império, mas nenhuma das pistas levou a Amoline. E assim, anos depois, quando chegaram notícias de uma garota perdida queimando de raiva nas Montanhas Ferrifarpos ao norte, Fynn Retrick relutantemente juntou suas coisas e foi investigar. Ele achava que não encontraria nada. Como estava errado.","Unidade",[],["Noxus"],"Campeão"],"06NX029":["A Botica Cinzenta","Quando um aliado com 5+ de Poder morrer, crie um seguidor aleatório com 5+ de Poder na mão.","","\"Hoje me peguei pensando na minha pequena enfermaria na Colina Toporrosa, e nos anos que passei lá tentando desvendar os segredos da fisiologia. Anos! Agora estou trabalhando para Madame Noradi há alguns meses, e já me dei conta de que não tinha aprendido nada. Como eu era simplório. E afortunado.\"\n– Notas do Dr. Esslanger","Monumento",[],["Noxus"],"ÉPICO (A)"],"06NX032":["Cão-dragão Obediente","Quando um aliado atacar, eu ataco com ele.","","\"Os cães-dragão são maravilhosos, não acha? Sempre querendo agradar. Tão maleáveis. Se ao menos meus inimigos tivessem as mesmas qualidades.\" – Espinho da Rosa","Unidade",["CANINO"],["Noxus"],"COMUM"],"06NX030":["Desertor da Legião","Eu ganho todos os fortalecimentos dos aliados globalmente.","","\"Ato um: Um ex-soldado, tendo abandonado seu posto após o roubo de um antigo artefato Kashuri, se esconde em um bar de Qayanvi, onde esbanja arrogância e bebe sem parar. Mal sabe ele que seu tesouro roubado conta tudo o que vê para o seu verdadeiro dono! Sua vida se esvai como vinho, o carmesim noxiano sobre ouro ioniano.\"","Unidade",[],["Noxus"],"RARO (A)"],"06NX013":["Lançador de Feitiços","Jogar: Atordoe um inimigo ou, se ele já estiver Atordoado, cause 2 de dano a ele.","","Aluno: Sydell Kythera\nProfessora: J. Willough\nRelato: Fui picada por uma aranha no antebraço esquerdo. Sydell alega um mal-entendido, mas seu sorriso desmente sua inocência. Ele terá duas semanas de tarefas adicionais (refeitório).\"\n– Carta de Disciplina da Floricorvus","Unidade",["ARANHA"],["Noxus"],"COMUM"],"06NX040":["Treinamento Trifariano","A cada rodada, na primeira vez que um aliado com 5+ de Poder atacar, Mobilize.","","Ao meu comando, vocês vão lutar! Se matarem seu parceiro de luta, encontrem outro! Se tombarem, morram sabendo que sua morte deixou Noxus mais forte! Soldados trifarianos... comecem!\" – Avaliadora Trifariana","Monumento",[],["Noxus"],"ÉPICO (A)"],"06NX028":["Conservatório Floricorvus","Contagem 11: Crie 1 Tybaulk na mão.\nEu Avanço 1 rodada para cada feitiço Rápido, feitiço Lento ou Habilidade que você jogou nesta partida.","","\"... a essa altura, com certeza a notícia do fracasso da Academia Rosaguarda já chegou a você. Espero que aprenda com os erros da sua irmã. Espero que administre suas instalações de maneira a beneficiar o império.\"\n– Carta queimada encontrada nos escombros do conservatório","Monumento",[],["Noxus"],"RARO (A)"],"06NX014":["Desintegrar","Escolha uma unidade. Na próxima vez que ela sofrer 1 ou mais de dano nesta rodada, abata-a.","","A Diretora Telsi falou demoradamente sobre os princípios noxianos, deixando as crianças cada vez mais entediadas e inquietas. Mas, enquanto a maioria dos alunos continha em grande parte suas reações, Annie agia. Primeiro com fumaça, depois com fogo.","Feitiço",["ELEMENTAL"],["Noxus"],"COMUM"],"06NX031":["Yeti Acorrentado","Reputação: Eu custo 4 a menos.","","A multidão se espantou quando os dois yetis acorrentados foram trazidos para o lendário fosso de luta de Bordent. Ninguém achava que os animais fossem fortes o bastante para quebrar as correntes, pois ninguém nunca tinha enfrentado o poder de um yeti antes.","Unidade",["YETI"],["Noxus"],"COMUM"],"06NX009":["Cinzento em Cativeiro","Atacar: Eu causo 3 de dano ao meu bloqueador. Se ele tiver sido abatido ou removido, eu causo 3 de dano ao Nexus inimigo.","","\"Ato três: Uma guardiã cruel e seu animal de estimação. O cinzento é inocente mesmo em seu terrível propósito. O artefato que carrega força a subserviência. A guardiã se recusa a gritar enquanto é devorada por seu animal de estimação. Ah, se todos os noxianos fossem tão nobres no momento de sua morte...\"","Unidade",[],["Noxus"],"COMUM"],"06NX015":["Estudante Manalma","Na primeira vez que você jogar um feitiço Rápido, um feitiço Lento ou uma Habilidade a cada rodada, eu jogo Brasas Mágicas.","","\"Conheço Daani já há alguns anos. Rapaz adorável. Família adorável. Então, em minha última viagem, fui até a aldeia dele e encontrei o pobre Daani sentado na praça, sozinho. Disse que estava esperando a família voltar para casa. O pobre rapaz deve ter ficado sentado lá por meses. Não tive coragem de dizer a ele o que eu tinha visto no caminho...\" – Fynn Retrick","Unidade",[],["Noxus"],"COMUM"],"06NX037":["Contapedras Noxiano","Crie 1 Determinação Afiada, Reta da Morte ou Armas dos Perdidos Fugaz na mão.","","\"Clara, querida, você tem que tirar o sangue dessas peças.\" – Ophelia Noradi, Aristocrata Carmesim","Feitiço",[],["Noxus"],"RARO (A)"],"06NX008":["A Monitora","Ao jogar um feitiço Rápido, um feitiço Lento ou uma Habilidade, eu ganho +1|+0.","","\"Muitas das crianças estão em uma idade em que suas inclinações naturais as levam a se rebelar contra as orientações formais. Por sorte, a mais velha é aceita pelo resto e simpática à nossa causa. Se os alunos resolverem ignorar nossas lições, ensinaremos através dela.\" – Diretora Telsi","Unidade",[],["Noxus"],"ÉPICO (A)"],"06MT044":["Estrelacórnio Solari","Amanhecer: Conceda +0|+2 aos outros aliados nesta rodada.","","Os estrelacórnios nascem das estrelas, e alguns são mais brilhantes do que outros.","Unidade",[],["Targon"],"COMUM"],"06MT036":["Consulta Celeste","Cure completamente todos os aliados, depois aumente o Poder deles para deixar igual à Vida.","","\"Devemos ter compaixão por nós mesmos antes de tudo. O resto virá.\" – Soraka.","Feitiço",[],["Targon"],"ÉPICO (A)"],"06MT039":["Poleiro do Dragão","Contagem 3: Invoque Inviolus Vox.","","\"Dizem que os dragões celestiais nascem das nebulosas, brotando totalmente formados da poeira cósmica. Mas como nós, meros mortais, podemos saber? De longe, tudo o que vemos é a luz deles.\" – Arauta dos Dragões","Monumento",[],["Targon"],"ÉPICO (A)"],"06MT045":["Trifecta Celestial","Evoque uma carta Celestial com custo baixo, médio e alto.","","\"As estrelas estão prevendo um grande potencial. Alguma coisa está vindo. Que forma ela vai tomar? Não me cabe saber! O que você acha, Kulun?\" – Sonhaluna","Feitiço",[],["Targon"],"RARO (A)"],"06MT043":["Contapedras Targonense","Crie 1 Contemple o Infinito, Quietude ou Bênção Targonense Fugaz na mão.","","\"É muito estranho, Shorin... Mesmo sem virar a pedra, sei exatamente qual constelação está pintada nela.\" – Viajante Tyari","Feitiço",[],["Targon"],"RARO (A)"],"06MT029":["Esmus, Sopro do Mundo","Ao me invocar, Plante 1 Sino na carta no topo do seu deck.\nAuxiliar: Dê +1|+1 ao meu aliado auxiliado.","","\"... mas ouvi dizer que Esmus foi criada pelo próprio Protetor, e com o nascimento dela, o som veio ao mundo!\"\n\"Minto! Sabe-se que Esmus tem o rosto de uma velha cantora que tinha o coração de um anjo, mas a voz dos mortos... até que o próprio Bardo lhe concedeu uma voz de pura beleza!\"\n\"Minto! Esmus é...\"\n– Parte de Nascimento de Esmus, um famoso jogo de bardos","Unidade",[],["Targon"],"COMUM"],"06MT038":["A Luz Sinuosa","Anoitecer: Conceda +2|+1 e Sobrepujar aos outros aliados nesta rodada.","","\"Mãe Lua, dê-nos forças,\nEmbora a escuridão nos rodeie,\nCom a sua luz, iremos triunfar.\"\n– Prece Lunari","Unidade",[],["Targon"],"COMUM"],"06MT047":["Vórtice Místico","Ao me invocar ou quando começar a minha Contagem, Plante 3 Sinos no seu deck. Contagem 2: Compre 1.","","\"Então eu vi... milhares deles, todos cantando e dançando de várias formas. Logo em seguida, vi um clarão, e todos se foram, e o templo também. Não restou uma pedra sequer. E em minhas mãos? Bem, o Velho Gaff ficou lá segurando um sino.\" – O conto do velho Gaff, parte 3","Monumento",[],["Targon"],"RARO (A)"],"06MT041":["Matilha de Cães Estelares","Meus fortalecimentos Destinados são dados a cartas Matilhas de Cães Estelares aliadas globalmente.","","Os cães estelares não ouviam nem atendiam aos alpinistas em suas jornadas. Eles seguiam alheios, aparentemente envolvidos pela magia da montanha.","Unidade",["CANINO"],["Targon"],"COMUM"],"06MT049":["Benção de Mikael","Dê +1|+2 a um aliado e remova todas as palavras-chave negativas dele.","","Aqueles que escutam o badalar dos sinos são tocados pela pureza de sua melodia.","Feitiço",[],["Targon"],"RARO (A)"],"06RU025":["Evelynn","Origem: Abraço da Agonia.\nAo me invocar, invoque uma Carcaça aleatória.","Quando eu vir você ou um aliado abaterem uma Carcaça aliada, me conceda as palavras-chave dela nesta rodada e eu subo de nível.","As pupilas da sacerdotisa se dilataram por completo, e sua mão tremia de nervosismo e empolgação. Ela estava pronta. Este era o momento que Evelynn mais desejava. Ela sorriu, e lentamente mudou seu semblante. Então, como sempre, a gritaria começou.","Unidade",[],["Runeterra"],"Campeão"],"06RU001":["Bardo","Origem: O Protetor Andarilho.\nAtacar: Plante 3 Sinos no seu deck.","Você aumentou o total dos atributos dos aliados em jogo ou na mão em 20+.","\"Sim, o Velho Gaff já viu muita coisa estranha na vida! A primeira vez foi o próprio Protetor, eu acho. Parecia uma estrela atravessando o céu. Foi como se o mundo inteiro tivesse parado por um minuto, e era só eu e ele...\" – Conto do Velho Gaff, parte 1","Unidade",[],["Runeterra"],"Campeão"],"06RU002":["Jhin","Origem: O Virtuoso.\nAtacar: Cause 2 de dano a todos os inimigos Atordoados.","Você jogou 12+ feitiços Rápidos, feitiços Lentos ou Habilidades.","\"Prelúdio: Estamos na cidade de Qayanvi, onde um velho mestre convoca um jovem pupilo. A tarefa dele é espantar um grupo de vilões perversos e recuperar artefatos sagrados roubados. O ator está ansioso, mas ainda não está em posição. Por enquanto ele só se prepara, aguardando nas coxias.\"","Unidade",[],["Runeterra"],"Campeão"],"06FR029":["Pavor Glacial","Congele um inimigo e invoque 1 Matilha das Glacipresas.","","Com o frio, chegam também as glacipresas, e eles nem precisam alcançar suas presas... só esperar mesmo.","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"06FR033":["Javali de Caça","Suspiro Final: Receba uma gema de Mana vazia.","","O ciclo da vida e da morte parece diferente em Freljord. A natureza implacável faz com que nada seja desperdiçado.","Unidade",[],["Freljord"],"COMUM"],"06FR038":["Asas da Criofênix","Cause 3 de dano a TODAS as unidades.\nIluminado: Cause 3 de dano a todos os inimigos e cure seu Nexus em 3.","","Na sombra das asas da grande Criofênix, os seguidores festejaram e os inimigos tremeram.","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"06FR030":["Precursor dos Servos","Jogar: Invoque 1 Servo Congelado ou Avance todos os seus Servos Congelados em 1 rodada.","","Mal se ouvia o clamor estranho e agudo da criatura, mas quando ele ecoou pelas paredes de pedra da ravina, os batedores sentiram a vibração em suas entranhas. Diante de seus olhos, rachaduras surgiram rapidamente pela superfície do gelo, de forma rápida e desproporcional.","Unidade",["AVE"],["Freljord"],"COMUM"],"06FR039":["Ferocidade do Garreroz","Transforme um seguidor aliado em 1 Garreroz Alfa.","","\"Grande espírito Garreroz, conceda-nos seu poder!\" – Udyr","Feitiço",[],["Freljord"],"RARO (A)"],"06FR028":["Revna, a Guardiã Mitológica","Ao me invocar, dê meus atributos às unidades no seu deck, depois compre uma unidade com 5+ de Poder.","","Os guardiões mitológicos avarosianos costumam ser os anciãos mais experientes da tribo, protetores das pessoas e ótimos contadores de histórias. Eles mantêm viva a tradição da caça e da luta com histórias e canções. ","Unidade",[],["Freljord"],"ÉPICO (A)"],"06FR037":["Gelo Rachado","Dê \"Me Congele no próximo Início de Rodada\" a um inimigo.","","Sempre é preciso testar o gelo antes de pisar nele, não importa o quanto ele pareça resistente.","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"06BC045":["Poeirinha Espirrenta!","Conceda +1|+1 aos aliados nesta rodada. Se eles tiverem sido criados, conceda +2|+2.","","\"OLÁ. EU SER SÓ COGUMELO EU FALANDO NÃO SABER POR QUE NEM COMO NEM NADA FAVOR SÓ DEIXAR EU SER COGUMELO. VALEU. TCHAU.\" – Cogumelo","Feitiço",[],["Bandópolis"],"ÉPICO (A)"],"06BC036":["Paparo, o Grande","Jogar: Manifeste um yordle.\nAtacar: Dê +1|+0 a yordles aliados.","","\"TODO MUNDO ama o Paparo! Todo verão, ele nos traz amuletos de todo o mundo, e eles sempre são ou deliciosos, ou lindos, ou confusos! Às vezes, são as três coisas ao mesmo tempo! – Ava Dedicada","Unidade",["YORDLE"],["Bandópolis"],"ÉPICO (A)"],"06BC040":["Contapedras Bandopolitano","Crie 1 Engenhoca Yordle, Contenção Heroica ou Arpão Elétrico Fugaz na mão.","","Os yordles nunca recusam um joguinho... mas não se surpreenda se as regras mudarem do nada!","Feitiço",[],["Bandópolis"],"RARO (A)"],"06BC039":["Solte a Bomba","Cause 2 de dano a uma unidade e invoque 1 Bomba Rudimentar.","","\"Tá... isso não é nada bom\", Giselle falou baixinho, tentando se proteger.","Feitiço",[],["Bandópolis"],"COMUM"],"06BC044":["Prisão Cósmica","Cause 2 de dano a um inimigo e Atordoe outro. Plante 6 Sinos no seu deck.","","\"Mamãe, pra onde o Protetor vai?\"\n\"Ele vai pra todo lugar, meu amor. Até aonde a vista alcança.\"\n\"Por quê?\"\n\"Ah, meu bem. Não pense no porquê. Nem os anciãos mais sábios entendem os caminhos do Protetor...\"\n– Uma mãe e uma criança","Feitiço",[],["Bandópolis"],"RARO (A)"],"06BC026":["Byrdo, Tocante de Sinos","Ao me invocar, plante 1 Sino na carta no topo do seu deck.","","\"... na segunda vez foi um estrondo. Eu estava varrendo o chão quando, de repente, vi meu jantar espalhado pela mesa e minhas panelas e frigideiras cambaleando sob duas pernas, saindo porta afora! Corri tão rápido quanto esses joelhos me permitiram e as encontrei naquele templo, vasculhando as prateleiras como se estivessem procurando por algo.\" – O conto do Velho Gaff, parte 2","Unidade",[],["Bandópolis"],"COMUM"],"06BC030":["Cogumelo de Proximidade","Cause 1 de dano a uma unidade. Se uma das suas armadilhas ou dádivas tiverem sido ativadas nesta rodada, cause 3 de dano à unidade.","","\"Se começar a brilhar, vai detonar!\" – Regra 463 dos Escoteiros de Bandópolis","Feitiço",[],["Bandópolis"],"COMUM"],"06BC031":["Maduli, Guarda do Portão","Ao me invocar, plante 1 Sino na carta no topo do seu deck e depois dobre as dádivas no seu deck.","","\"Levei um susto grande, grande mesmo. Braços brotando pra tudo quanto é lado. Uns dentes grandes como rochas. Ah, e quando a criatura passou aquela baqueta nos dentes, saiu uma melodia tão estranha que eu pensei que ia morrer. Fugi, ah se fugi. Mas não antes de ver... buracos no céu! Devia ter centenas deles!\"\n– O conto do Velho Gaff, parte 4","Unidade",[],["Bandópolis"],"RARO (A)"],"06BC035":["A Árvore de Papel","Quando um aliado com uma unidade Conectada atacar, dê +1|+0 à unidade Conectada.","","As folhas da árvore de papel reluzem com a mesma magia feérica que criou a própria árvore. E, assim como os pássaros que inspiraram sua forma, elas não conseguem resistir ao fascínio das coisas brilhantes.","Monumento",[],["Bandópolis"],"RARO (A)"],"06IO005":["Encenações Nefastas","Retorne uma unidade com 3 ou menos de Vida.","","\"Não se pode apressar a arte.\" – Jhin","Feitiço",[],["Ionia"],"COMUM"],"06IO038":["Apoio Moral","Eu custo 2 a menos se você tiver auxiliado um aliado nesta partida. Conceda Barreira a um aliado nesta rodada.","","\"Confie no equilíbrio. Ande no limite.\" – Shen","Feitiço",[],["Ionia"],"COMUM"],"06IO012":["Chamado dos Kinkou","Invoque 1 Guardiã das Máscaras agora ou no próximo Início de Rodada. Compre 1.","","\"Velhas máscaras permitem que jovens olhos vejam claramente.\"\n– Guardiã das Máscaras","Feitiço",[],["Ionia"],"COMUM"],"06IO009":["Emboscada do Dragão","Inicie um ataque livre com 2 Dragonitos.","","\"Desejo e sua manifestação.\"\n– O Mestre dos Dragões","Feitiço",[],["Ionia"],"COMUM"],"06IO033":["Tempestade de Lâminas","Pelo resto da partida, quando fizer a Dança das Lâminas, invoque outra Lâmina atacante.\nDança das Lâminas 1.","","\"Você conduz, e eu sigo!\" – Dançarina das Fitas","Feitiço",[],["Ionia"],"ÉPICO (A)"],"06IO004":["A Criadora","Jogar: Retorne uma unidade com menos Poder do que eu.","","\"Um talento extraordinário, a Criadora. Uma artesã lendária! Uma arte inigualável! Execução impecável! Já é uma grande honra estar na presença dela, imagine portar um instrumento feito por ela.\" – Testemunha Kashuri","Unidade",[],["Ionia"],"RARO (A)"],"06IO010":["Monte da Ventania","Ao me invocar, compre Yasuo e Atordoe o inimigo Mais Forte.\nAo receber o Símbolo de Ataque, Atordoe o inimigo Mais Forte.","","Para a maioria das pessoas, a paz é um lar feliz e o acolhimento tranquilo encontrado em um abraço carinhoso. Para Yasuo, é o momento raro quando os ventos se acalmam e oferecem promessas em vez de lembranças. ","Monumento",[],["Ionia"],"ÉPICO (A)"],"06IO036":["Contapedras Ioniano","Crie 1 Encenações Nefastas, Ritual de Renovação ou Manter a União Fugaz na mão.","","\"Aprender a entender seu adversário é uma habilidade essencial, mesmo fora de combate. Mas antes de tudo, o objetivo de um jogo é se divertir. Agora, traga meu escalda-pés!\" – Mentor Inspirador","Feitiço",[],["Ionia"],"RARO (A)"],"06IO003":["A Contrarregra","Jogar: Atordoe um inimigo.","","\"Ato quatro: Uma jovem sacerdotisa entra em nossa história. A tragédia dela é contada pelos lábios pálidos daqueles que ela traiu. Desesperada para se redimir de sua transgressão, ela carrega em seus braços um grande fardo, um presente dourado para os noxianos que ela acolheu em sua terra. Ficamos nos perguntando: foi a tristeza ou a bala que partiu seu coração?\"","Unidade",[],["Ionia"],"COMUM"],"06IO035":["Estudante Kinkou","Quando outro aliado receber Barreira, me conceda Barreira nesta rodada se eu não tiver.","","\"Priorize o equilíbrio em todos os níveis. Mente, corpo e espírito. Resista aos impulsos urgentes da juventude. Eleve sua perspectiva.\" – Shen","Unidade",[],["Ionia"],"RARO (A)"],"06PZ032":["Vitrolex Estridente","Escolha um de dois feitiços novos com 2 de custo para criar na mão e reduza o custo dele a 0 nesta rodada. Repita mais duas vezes.","","O primeiro vitrolex de Zaun funcionava surpreendentemente bem. Só tinha um problema: ninguém sabia regular o volume.","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ042":["Imperfeccionista Maligna","Jogar: Selecione uma carta na mão. Crie 4 cópias idênticas dela no seu deck e reduza o custo delas em 1.","","\"Bem, tudo o que tenho a dizer sobre hoje é que as coisas podiam ter sido melhores. É só. Eu do futuro... você sabe o que fizemos.\"\n– Diário de Kay","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ025":["Solidão","Ao me invocar, invoque uma Carcaça aleatória.\nAo invocar um aliado com 1 de custo, dê uma palavra-chave aleatória a ele.","","\"Ao voltar para casa do Entressol, vi novamente a pobre coitada aos prantos em uma viela. Ver como todos desviam dela de forma tão incisiva parte meu coração, assim como seu desânimo palpável. Então, amanhã, se nos cruzarmos novamente, tentarei ajudá-la como for possível.\"\n– Anotações do diário de Lady Sempesci","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"06PZ043":["Contapedras Piltovense","Crie 1 Pós-choque, Transmogulador Hextec ou Dia do Progresso! Fugaz na mão.","","\"Você não encontrará um conjunto de peças como esse em nenhum lugar do mundo, senhor. Minha filha é muito detalhista.\" – Corin Reveck  ","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"06PZ027":["Convite Discreto","Crie 1 Indivíduo Suspeito ou Detonador Quimiopunk Fugaz na mão e reduza o custo dele em 1.","","A melhor balada noturna de Zaun é só para convidados. Se você não for da banda, tem que ser alguém pra conseguir entrar. Ou encontrar um ingresso no chão.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ038":["Camuflagem Garimpada","Dê Elusivo a um aliado e \"Golpe ao Nexus: Compre 1\".","","\"Vocês não vão ACREDITAR no que eu encontrei hoje!\"\n– Catador do Sumidouro","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ039":["Sucata Reaproveitada","Para me pôr em jogo, descarte até 2 cartas. Crie o mesmo tanto de seguidores das suas regiões que custem 1 a mais e reduza o custo deles em 1.","","Nas profundezas de Zaun, o povo local é obrigado a transformar a sucata e as tralhas que cata em materiais úteis. Após décadas de prática, eles ficaram muito bons nisso.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"06BW006":["Illaoi","Atacar: Faça Surgir 1 Tentáculo, depois eu ganho Poder equivalente ao seu Tentáculo Mais Forte nesta rodada.","Vi eu ou cópias aliadas de Tentáculos causarem 15+ de dano.","O \"Olho de Nagacáburos\" é apenas um nome, mas Illaoi o encara como um desafio de vida, como se sua deusa fosse uma companhia constante e que se chateia com facilidade.","Unidade",[],["Águas de Sentina"],"Campeão"],"06BW036":["Rato do Cais","Eu tenho +1|+0 para cada rodada diferente em que você causou dano ao Nexus inimigo.","","\"Não há lugar mais sangrento em Águas de Sentina do que a baía. Veja só esses ratos. Criados no sangue. Eles sempre querem mais. Nunca estão satisfeitos, os desgraçados.\"\n– Carniceiro Farpado","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"06BW038":["Megapresa","Quando chegar às Profundezas, cure seus aliados e o Nexus em 3.","","\"O que ele quer?!\"\n\"Está... atrás das laranjas!\"\n\"Pelo amor da Mulher Barbada, DÁ LOGO O SACO INTEIRO!\" – Marinheiros azarados","Unidade",["MONSTRO MARINHO"],["Águas de Sentina"],"COMUM"],"06BW030":["Olho de Nagacáburos","Faça Surgir 2 Tentáculos.\nCompre 2.","","Nagacáburos concede atos divinos. Desde que você sobreviva ao ato de adorá-la.","Feitiço",[],["Águas de Sentina"],"COMUM"],"06BW011":["Nagacáburos","Ao me invocar ou no Início de Rodada: Faça Surgir 2 Tentáculos. Depois, se o seu Tentáculo Mais Forte tiver 12+ de Poder, crie 1 Fúria de Nagacáburos na mão.","","\"A Mãe Serpente. A Grande Cráquem. A Mulher Barbada. Nagacáburos não se importa com nomes, e menos ainda com os mortos inquietos.\" – Illaoi","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"06BW021":["Sermão da Correnteza","Cause 3 de dano a uma unidade inimiga.\nFaça Surgir 3 Tentáculos.\nCause 1 de dano ao Nexus inimigo.","","\"Desde criança, aprendemos a navegar por águas turbulentas. Hesitar significa morrer. Naturalmente, a primeira provação de uma sacerdotisa é lembrar-se dessa lição e combater a correnteza a todo custo. Pois uma Portadora da Verdade é a própria correnteza, e não precisa nadar contra ela.\" – Illaoi","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"06BW045":["Sangue na Água","Cause 1 de dano a qualquer coisa, depois Mobilize.","","Quase nada consegue afastar os tubarões da Baía do Estripador. Depois de provarem o sangue, eles sempre querem mais.","Feitiço",[],["Águas de Sentina"],"COMUM"],"06BW028":["Golpe de Tentáculo","Faça Surgir 2 Tentáculos, depois seu Tentáculo Mais Forte e um inimigo se Golpeiam.","","\"A vida é um teste. E com mais frequência do que gostaríamos, a dor é a professora.\" – Illaoi","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"06BW035":["A Voz do Mar","Ataque: Faça Surgir 1 Tentáculo e conceda Sobrepujar ao Tentáculo Mais Forte nesta rodada.","","Invocar Nagacáburos não exige um ritual complicado. Ela atende ao chamado daqueles cujas almas são páreo para o oceano e a oscilação de suas marés. É uma batalha que poucos conseguem travar.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"06BW015":["Prece Atendida","Faça Surgir 2 Tentáculos, ou gaste 5 de Mana para fazer Surgir 4.","","Para Nagacáburos, as preces não envolvem súplicas, nem dar ou receber. A bênção dela é semelhante à própria vida: cresça, persevere, lute, e assim, às vezes, a recompensa chegará até você.","Feitiço",[],["Águas de Sentina"],"COMUM"],"06BW007":["Ídolo Vigilante","Início de Rodada: Cause 2 de dano a mim e faça Surgir 1 Tentáculo.","","Quando os terrores debandam das Ilhas das Sombras, o ídolo se ilumina como um farol reluzente no horizonte.","Unidade",[],["Águas de Sentina"],"COMUM"],"06BW037":["Recompensa Rica","Manifeste um seguidor com custo que você pode bancar.","","\"Tá bom, Baz. Vai querer tentar de novo mesmo?\"\n\"Dessa vez não tem erro, Gav. Além disso, já enfrentamos tudo que é nojeira que essa cidade tem a oferecer.\"\n\"Enfrentamos e perdemos, Baz.\" – Baz e Gav, aspirantes a caçadores de recompensas","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"06BW041":["Picaretagem","Escolha 1 de 2 cartas de não Campeão da mão do inimigo e crie uma cópia na sua mão. Saquear: Eu custo 1 a menos.","","\"CINCO tacadas certeiras? Parece que ganhei de novo!\"\n– Malandro da Sinuca","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"06BW016":["Vigia Buhru","Ao me invocar, faça Surgir 3 Tentáculos.","","A simplicidade é o melhor da vida. Gotas de água salgada no rosto, o canto dos pássaros... e um inimigo simples no horizonte.","Unidade",[],["Águas de Sentina"],"COMUM"],"06BW009":["Líder Buhru","Jogar: Um aliado com 1 de custo inicia um ataque livre.","","\"Lembre-se da sabedoria do oceano! Se você não se mover, será movido! Siga minha voz se estiver perdido, pois seu inimigo sabe exatamente onde está.\" ","Unidade",[],["Águas de Sentina"],"RARO (A)"],"06BW043":["Contapedras Sentinense","Crie 1 Mais Pólvora!, Trapaceiro Brincalhão ou Lançar Isca Fugaz na mão","","\"Não tente pegar alguém blefando em uma partida de contapedras. Águas de Sentina tem os melhores mentirosos. Se quiser ganhar, tem que olhar pras mãos.\" – Twisted Fate","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"06BW018":["Steem","Ao me invocar, invoque uma Carcaça aleatória.\nAo invocar um aliado com 1 de custo, dê Vulnerável ao inimigo Mais Forte.","","O primeiro encontro de Evelynn com Steem superou todas as expectativas que ela poderia ter. Evelynn se lembra de seu sorriso em meio ao sofrimento, e como ele era tão apaixonado quanto ela pela violência. Depois de finalmente derrotar Steem, ela preferiu não destruir o demônio, mas uni-lo a ela para sempre. Ela pensou que, juntos, talvez eles possam compartilhar com o mundo o amor mútuo pela carnificina.","Unidade",[],["Águas de Sentina"],"COMUM"],"06SH014":["Aberração do Vazio","Ao me invocar, eu ganho todas as palavras-chave positivas que os aliados tiveram nesta partida.\nQuando um aliado tiver uma nova palavra-chave positiva, eu a ganho.","","\"Já tínhamos ouvido falar das rupturas do Vazio e da devastação causada por elas. Mas ver pessoalmente... Não sei se um dia vou conseguir tirar aquela visão da cabeça e aquele horror do coração.\" – Sobrevivente de Belveth","Unidade",[],["Shurima"],"ÉPICO (A)"],"06SH016":["Arauto do Enxame","Jogar: Eu ganho as palavras-chave positivas de uma unidade e ela ganha as minhas.","","\"Falou comigo... como se me conhecesse. Como se quisesse me mostrar... alguma coisa...\" – Kai'Sa","Unidade",[],["Shurima"],"RARO (A)"],"06SH009":["Kai'Sa","Ao me invocar ou no Início de Rodada: Se tiver o Símbolo de Ataque, crie 1 Segunda Pele na mão.","Você Evoluiu.","Poucos dias antes, Kai'Sa notou que sua segunda pele se agitava e a empurrava de forma cada vez mais incisiva para a costa de Shurima. Alguma coisa estava errada, e, ao se aproximar de Belveth, Kai'Sa percebeu a dimensão do horror que se revelava diante dela.","Unidade",[],["Shurima"],"Campeão"],"06SH048":["Rito de Passagem","Manifeste um Monumento aliado que tenha sido destruído nesta partida e invoque-o.","","\"Um instante guardado no tempo.\" – Zilean","Feitiço",[],["Shurima"],"COMUM"],"06SH037":["Definharra Baccai","Jogar: Dê Vulnerável a um inimigo.\nQuando um inimigo for Desafiado, conceda -2|-0 a ele nesta rodada.","","A sanidade deles definhou como dunas ao vento. Em seu lugar, uma semente de raiva cresceu e virou uma fúria que nem as águas do deserto puderam aplacar.","Unidade",[],["Shurima"],"COMUM"],"06SH008":["Anciã Belvethiana","","","Shalatai se espantou diante de tanto horror. Lá estava Ferai, a filha do açougueiro, esmagada. Ao lado dela estava Gorrub, o filho do pescador, ainda esticando as mãos sem vida para alcançar seu amor. Tantas memórias desfeitas. Tantas vidas perdidas. Com desgosto, Shalatai voltou-se para o mal, pronta para dar a vida para salvar o resto de seu povo.","Unidade",[],["Shurima"],"COMUM"],"06SH042":["Contapedras Shurimane","Crie 1 Predador Desumano, Peso do Julgamento ou Fogo Espiritual Fugaz na mão.","","\"Em um jogo de contapedras, não é a vitória que importa. O que importa é estar bem bonito!\" – Akshan","Feitiço",[],["Shurima"],"RARO (A)"],"06SH050":["Areias do Tempo","Conceda -2|-0 aos inimigos nesta rodada. Crie 1 Século Instantâneo Fugaz na mão.","","As areias do tempo correm sem cuidado ou consideração. Seu esquema é de cruel indiferença, mas nem todos são escravos de suas insensíveis conspirações...","Feitiço",[],["Shurima"],"RARO (A)"],"06SH049":["Chamado da Glória","Eu custo 2 a menos para cada aliado Ascendente que você tiver invocado nesta partida.\nManifeste uma carta do Deck do Imperador que custe 9 ou menos.","","\"Olhe a nossa obra. Olhe o que construímos.\" – Azir","Feitiço",[],["Shurima"],"RARO (A)"],"06SH036":["Cripta da Renovação","Ao invocar um Campeão, me destrua para dar +2|+1 e Escudo de Feitiço a ele.","","Nasus emergiu do sarcófago com a mente limpa e as feridas completamente curadas. Ele rabiscou umas palavras e espiou os sarcófagos acima do seu, imaginando qual seria o estado mental das aberrações que ali estavam. Só o tempo diria se essa magia seria capaz de devolver a sanidade aos Baccai. Uma magia contestada pelos outros Ascendentes. Mas eles não estavam mais lá, e Renekton e sua loucura estavam. Nasus rabiscou mais algumas palavras, na esperança de ter finalmente encontrado uma forma de salvar seu irmão.","Monumento",[],["Shurima"],"ÉPICO (A)"],"06SH011":["Sobrecarga","Dê Sobrepujar e Escudo de Feitiço a um aliado.","","\"Vou te mostrar como se luta.\" – Kai'Sa","Feitiço",[],["Shurima"],"COMUM"],"06SH017":["Exploradora do Vazio","Cause 1 de dano a um seguidor. Se você tiver Evoluído, cause 3 de dano a uma unidade.","","\"Dói, não é?\" – Kai'Sa","Feitiço",[],["Shurima"],"RARO (A)"],"06SH007":["Voidling","Enquanto eu estiver na mão, tenho uma palavra-chave aleatória que muda a cada rodada. Ao me invocar, eu ganho essa palavra-chave.","","Dharna se lembrou de que tinha aberto as janelas naquela manhã e sentido o aroma de pão fresquinho. Mais à frente, pescadores já tinham começado a levar o apurado do dia para os mercados. Ela se lembrou de ter sorrido, pensando que seria um belo dia.","Unidade",[],["Shurima"],"COMUM"],"06SH010":["Detonadora do Vazio","","","A erupção do Vazio na cidade de Belveth foi ao mesmo tempo repentina e aterrorizante. A maioria dos civis ficou apavorada com o caos que tomou conta da cidade e fugiu o mais rápido possível. A maioria, mas não Koyemi.","Unidade",[],["Shurima"],"COMUM"],"06SH034":["Dominação","Ao me invocar, invoque uma Carcaça aleatória.\nAo invocar um aliado com 1 de custo, dê +1|+0 a ele.","","Às vezes, tudo o que o poderoso quer é se sentir impotente.","Unidade",[],["Shurima"],"ÉPICO (A)"],"06DE045":["Luz Inspiradora","Dê Espírito aos aliados.","","\"Chega de se esconder! Venha para a luz e brilhe junto comigo!\" – Lux","Feitiço",[],["Demacia"],"COMUM"],"06DE038":["Lorde Eldred, Líder dos Caçadores de Magos","Outros aliados e seu Nexus têm Robusto.\nQuando um aliado sobreviver a dano, dê +1|+1 a ele.","","\"Não pude deixar de ouvir seus sussurros fervorosos, querida esposa. Aconselho que tenha mais cautela ao discutir assuntos de família em público. Nunca se sabe quem pode estar ouvindo.\"","Unidade",[],["Demacia"],"ÉPICO (A)"],"06DE037":["Decreto Real","Conceda +2|+2 e Desafiador a um aliado nesta rodada ou invoque 1 Lorde Honroso.","","\"Agora mesmo, Rei Jarvan. Resolveremos isso a qualquer custo.\" – Barrett Buvelle, Lorde Honroso","Feitiço",[],["Demacia"],"RARO (A)"],"06DE035":["Pilar de Petricita","TODOS os feitiços custam 2 a mais.\nContagem 2.","","Os Caçadores de Magos colocam enormes obeliscos de petricita em seus complexos, garantindo que até os magos mais fortes fiquem completamente impotentes.","Monumento",[],["Demacia"],"COMUM"],"06DE042":["Contapedras Demaciano","Crie 1 Barreira Prismática, Deter ou Por Demacia! Fugaz na mão.","","\"Por que o nome é 'O Gambito do Rei'? As rainhas também se arriscam!\" – Cithria de Campinuvem","Feitiço",[],["Demacia"],"RARO (A)"],"06DE036":["Patriarca Protetor","Atacar: Compre uma unidade. Se for um Dragão, invoque-o atacando.","","\"Felizmente, minha pesquisa sugere que os patriarcas da ninhada passam a maior parte do tempo caçando a uma boa distância das crias. Podemos concluir que, se o macho voltar, viraremos todos comida de dragão! Haha!\" – Anden Mayne, Pesquisador Acadêmico","Unidade",["DRAGÃO"],["Demacia"],"ÉPICO (A)"],"06DE030":["Fascinação","Invoque uma Carcaça aleatória e dê +1|+0 a ela.","Missing Translation","\"Mais perto, amorzinho...\" – Evelynn","Feitiço",[],["Demacia"],"COMUM"],"06SI012":["Gwen","Atacar: Quando outro aliado ganha Poder Sagrado, eu também ganho. Drene 2 do Nexus inimigo.","Causei 10+ de dano.","Gwen retalhou a Névoa Negra, achando estranho como toda aquela área já tinha sido completamente envolvida por ela. Depois do seu corte e recorte, a mansão encantada apareceu entre as árvores sombrias como um farol e, como era de se esperar, Gwen se sentiu atraída por ela. Era tão intrigante, tão... grandiosa!","Unidade",[],["Ilhas das Sombras"],"Campeão"],"06SI020":["Espinho de Ódio","Abata um aliado para causar 3 de dano a uma unidade. Se Evelynn começou no seu deck, invoque uma Carcaça aleatória.","","\"Pode gritar à vontade.\" – Evelynn","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"06SI013":["Eternas Dançarinas","Atacar: Ressuscite uma cópia Efêmera atacante do aliado morto Mais Forte que não Eternas Dançarinas com meu Poder ou menos.","","É sempre mais fácil juntar-se a alguém na pista de dança do que ser a primeira pessoa lá. As gêmeas, porém, estão sempre dispostas a mostrar aos outros como se faz.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI037":["Contapedras das Ilhas das Sombras","Crie 1 Marca das Ilhas, Jornada Espiritual ou Derrocada Fugaz na mão.","","\"Objetos... reluzentes. Peças... regras para aprender. Jogo interessante. Emocionante... habilidades inigualáveis... inesquecível.\" – Diário recuperado","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"06SI040":["Retorno Tormentoso","Ressuscite o seguidor Mais Forte que tiver morrido e dê Efêmero e Assustador a ele. Conceda -1|-0 aos inimigos nesta rodada.","","Os espíritos podem ser banidos por um tempo, mas eles sempre voltam.","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI027":["Linha na Agulha","Abata um aliado para causar dano equivalente ao Poder dele a um inimigo.","","\"Agulhas a postos!\" – Gwen","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"06SI018":["Vora","Ao me invocar, invoque uma Carcaça aleatória.","","Ao contrário de outros demônios, que atraem as vítimas com mentiras, Vora é muito objetiva em seus desígnios, muito dominada pelo desejo. Em vez de uma predadora em busca de comida, ela é uma fera selvagem que precisa ser alimentada.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"06SI015":["Conduza a Banda","Invoque 2 Bandas Assombrosas.","","\"Mantenham o ritmo! Rápido, vamos!\" – Regente das Névoas","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"06SI030":["Convite Formal","Crie cópias na mão de 2 seguidores aliados que morreram nesta partida.","","\"Aqui estamos, meu bem. Fiquei sabendo que esta noite será esplêndida, e acho que veremos muitos rostos conhecidos!\" – Fantasma Festivo","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"06SI026":["Regente das Névoas","Suspiro Final: Crie 1 Banda Assombrosa na mão.","","\"Podem tocar, amigos! Este será o concerto mais animado de todos os tempos!\"","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"06SI033":["Tumba Assombrada","Contagem 2: Ressuscite o aliado Mais Forte que tiver morrido.","","O som da espada no escudo foi como uma sentença de morte, e atraiu espíritos cujos laços com o mundo não tinham sido totalmente cortados, cujos desejos não tinham sido saciados nem mesmo na morte.","Monumento",[],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI016":["Anfitrião Animado","","","\"Você está CORDIALMENTE CONVIDADO para uma festa memorável no FESTIVAL DA MEIA-NOITE. Venha beber, dançar e celebrar conosco na MANSÃO DE PORCELANA! (A festa acabará exatamente ao raiar do dia)\" \n– Convite escrito à mão com uma caligrafia sofisticada","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"06SI028":["Mordomo Espectral","","","O que seria de uma festa chique sem bebidas chiques?","Unidade",[],["Ilhas das Sombras"],"COMUM"],"06SI043":["Vegetação Rasteira","Abdique 3.\nDrene 2 de uma unidade.","","Até mesmo nas Ilhas das Sombras, a vegetação nativa encontra novos propósitos.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"06SI022":["Amante Espectral","","","Não sei se ele era um fantasma, uma lembrança ou um sonho, mas algo nele não me era estranho...","Unidade",[],["Ilhas das Sombras"],"COMUM"],"06SI019":["Sultur","Ao me invocar, invoque uma Carcaça aleatória.","","\"Cuidado com as pessoas que sorriem nestas ilhas assombradas. Talvez sejam recém-chegadas e não compreendam a brutalidade do lugar. Talvez sejam loucas. Talvez não sejam nada disso. Mas cuidado.\"\n– Anotações de Jens Tommen","Unidade",[],["Ilhas das Sombras"],"COMUM"],"06NX022":["Iniciação Legionária","Compre um aliado com 5+ de Poder ou deixe um aliado com 5 de Poder nesta rodada.","","\"Poucos recebem a oportunidade de servir na Legião Trifariana. Não desperdice essa chance.\" – Avaliadora Trifariana","Feitiço",[],["Noxus"],"ÉPICO (A)"],"06NX019":["Desertor Noxiano","Atacar: Meu Poder aumenta e fica igual ao do aliado Equipado Mais Forte nesta rodada.","","\"Andei sonhando de novo, ouvindo aquela voz no escuro. Dez anos... Uma década inteira sendo o cão obediente do império. Faça isso. Mate aquilo. E pra quê? Pra glória de Noxus? A glória não passa de uma mentira bonita, e eu caí nela. Mas isso acabou. Kayn me mostrou um caminho diferente, e ele leva à vingança.\"\n— Diário de Royce, o Carrasco","Unidade",["CULTISTA"],["Noxus"],"COMUM"],"06NX023":["Pescadora Ioniana","Ao me invocar, eu Improviso.","","A vida de Trisk virou de ponta-cabeça quando, durante o que seria sua última participação num torneio de pescaria, ela pescou Jax, que se debatia, desesperado. Ele se recusa a comentar sobre o incidente, mas o monstro marinho do qual Trisk o salvou fica maior cada vez que ela reconta essa história.","Unidade",["MESTRE DE ARMAS"],["Noxus","Ionia"],"COMUM"],"06NX044":["Urdidora Sorrateira","Atacar: Deixe o Poder dos outros aliados atacantes equivalente ao meu nesta rodada.","","''Uma boa mãe ensina os filhos a caçar, mas uma grande mãe... caça por eles.'' – Elise","Unidade",["ARANHA"],["Noxus"],"COMUM"],"06NX041":["Pombo Carmesim","Auxílio: Cause 1 de dano ao meu aliado auxiliado e me conceda +1|+1 nesta rodada.","","\"É bastante divertido, alimentar os pássaros. Apostei com o pobre Feoward que eles sugariam o sangue tão profundamente quanto um basilisco de Bordent, e vejam só: os pombos são realmente noxianos!\" – Edvin Cortain, Curador Carmesim","Unidade",["AVE"],["Noxus"],"ÉPICO (A)"],"06NX020":["A Balista Darkin","Você pode gastar 8 de Mana para me pôr em jogo como Naganek de Zuretta.","","As estepes do leste de Valoran eram conhecidas por serem estéreis, impróprias para alimentar ou abrigar o povo noxiano. Mas, com o passar dos séculos, um novo império foi fundado, faminto por expansão. Terras jamais cultivadas encontraram fertilidade sob novas técnicas agrícolas, e armas antes consideradas enterradas foram descobertas mais uma vez.","Equipamento",["DARKIN"],["Noxus"],"ÉPICO (A)"],"06NX039":["Banquete do Regozijo","Cause 2 de dano a um aliado para conceder +2|+0 aos aliados nesta rodada.","","\"Não é um banquete até alguém começar a gritar. Então grite, garoto.\" – Vladimir","Feitiço",[],["Noxus"],"COMUM"],"06NX026":["Martelos Gloriosos","","","Vessid não é lá o Desafiador mais rápido de Bordent, mas, quando seus martelos gloriosos atingem o alvo, nunca resta um oponente para revidar.","Equipamento",[],["Noxus"],"COMUM"],"06NX034":["Portador Furioso","Um aliado Equipado Golpeia um inimigo.","","\"Irmãos de sangue... mais uma vez!\" — Desertor Noxiano","Feitiço",["CULTISTA"],["Noxus"],"RARO (A)"],"06NX036":["Escudeiro Rúnico","Ao me invocar, Reforje.","","Durante meses, ele trabalhou arduamente em meio ao frio e à chuva, uma tarefa ingrata sem fim à vista. No entanto, o fim chegou. Finalmente, ele seria alguém na vida.","Unidade",[],["Noxus"],"COMUM"],"06NX027":["Confronto Brutal","Destrua o equipamento de um inimigo. Um aliado e esse inimigo Golpeiam um ao outro.","","\"Um, dois, olha como grita,\nO soldado é uma larei-ra,\nTrês, quatro, olha como queima,\nTibbers quer uma foguei-ra!\" – Annie","Feitiço",[],["Noxus"],"RARO (A)"],"06MT035":["Xolaani, a Tecelã de Sangue","Eu tenho +2|+2 para cada aliado que morreu com o Poder aumentado.\nPotencializada 16: Me transforme em Xolaani, a Ruína dos Aspectos.","","Xolaani observou enquanto Anaakco caía de joelhos, subjugado pela própria inimiga que desejava tão desesperadamente destruir. Aos poucos, os batimentos do seu coração ressoaram em uníssono com os outros. Outro coração para controlar. Outro corpo para comandar.","Unidade",["DARKIN"],["Targon"],"ÉPICO (A)"],"06MT007":["Serpe Seráfica","Potencializado 5: Sobrepujar.","","\"Ah, agora eu entendi... As formas deixadas na montanha eram meras impressões; caminhos para os seres do reino além das estrelas...\" – Guardião Mitológico Skai'en","Unidade",["DRAGÃO"],["Targon"],"RARO (A)"],"06MT037":["Selado em Aço","Oblitere um aliado e crie 1 Forma Corrompida com os atributos dele.","","Já que não seria fácil derrotar os deuses-guerreiros sepultados nessas armas, eles foram contidos.","Feitiço",[],["Targon"],"RARO (A)"],"06MT031":["Mihira, o Aspecto da Justiça","Fim de Rodada: Dê +1|+1 aos aliados em jogo e na mão.\nPotencializada 5: Elusivo, Roubo de Vida e Sobrepujar.","","\"Alguns reverenciam os Aspectos como deuses. Outros os veem como mensageiros do reino além. Outros ainda os temem... e talvez com razão.\" – Guardião Mitológico Skai'en","Unidade",[],["Targon"],"ÉPICO (A)"],"06MT010":["Sentença Divina","Conceda \"Não posso sofrer dano nem morrer\" a um aliado nesta rodada.\nConceda +1|+0 a todos os aliados nesta rodada.","","\"Protegida pela chama da justiça!\" – Kayle","Feitiço",[],["Targon"],"RARO (A)"],"06MT016":["Mensageiro Alado","Potencializada 3: Elusivo.","","\"Sim... Reconheço você. A mensagem que carrega... só pode ser uma convocação.\" – Ryze","Unidade",[],["Targon"],"COMUM"],"06MT015":["Chamas Purificadoras","Dê +2|+2 a 2 aliados na mão.","","\"O mal queimará!\" – Kayle","Feitiço",[],["Targon"],"COMUM"],"06MT042":["Protetora Crepuscular","Amanhecer: Conceda +1|+1 a aliados com Amanhecer nesta rodada.\nAnoitecer: Dê +1|+0 a aliados com Anoitecer.","","Nas horas crepusculares e logo antes do nascer do sol, ouve-se o pio da coruja, um lembrete dos espaços liminares entre o anoitecer e o amanhecer.","Unidade",["AVE"],["Targon"],"RARO (A)"],"06MT008":["Kayle","Eu tenho +1|+0 para cada vez que um aliado atacou com Poder aumentado.\nAo me invocar, dê +1|+0 aos aliados.\nPotencializada 6: Ataque Rápido.","Início de Rodada: Eu tenho 11+ de Poder.","\"Os demacianos a conhecem como a Protetora Alada, mas aqueles de nós que vivem sob o abrigo das estrelas em Targon a conhecem como a filha da Justiça, portadora de um propósito divino e de uma espada de fogo estelar.\"\n– Guardião Mitológico Skai'en","Unidade",[],["Targon"],"Campeão"],"06MT004":["Pastor Errante","Jogar: Escolha um aliado, e ele Improvisa. Se não escolher, eu Improviso.","","Jax ajudou Chaska a salvar o bando da investida de silfos furiosos. Depois, Chaska salvou Jax de silfos furiosos. Quando um dos dois não está passeando por aí, eles viajam juntos.","Unidade",["MESTRE DE ARMAS"],["Targon","Bandópolis"],"COMUM"],"06MT017":["Clérigo Divino","Potencializado 3: Roubo de Vida.","","\"É dito que, quando Mihira partiu deste lugar, ela deixou uma parte de si para trás — uma chama sagrada, ardendo intensamente. Há anos minha família cuida desse fogo, mantendo-o aceso na esperança de que ela retorne.\"","Unidade",[],["Targon"],"RARO (A)"],"06MT040":["O Invólucro da Vastidão","Depois que você Equipar um aliado nesta partida, eu custo 2 a menos.\nConceda Escudo de Feitiço a um aliado nesta rodada.","","Contemple o céu noturno e fixe seus olhos em uma pequena parte do firmamento. Imagine todos os que viveram ali dentro, todo o conhecimento obtido e todas as experiências vividas ao longo de incontáveis milênios. Visualize todas essas informações condensadas em um fragmento que cabe na palma da sua mão. Pense em quanta sabedoria você teria. Quanto poder.","Feitiço",["CULTISTA"],["Targon"],"RARO (A)"],"06MT034":["Impacto Celestial","Oblitere uma unidade ou Monumento: Cure seu Nexus em 3.","","\"Quem ajudará quando mais precisarmos?\" — Anciã Shurimane","Feitiço",[],["Targon"],"RARO (A)"],"06MT033":["Bandas Dracônicas","Meu portador é um Dragão.","","Muitos invocam o poder dos dragões, embora isso se manifeste de formas diferentes por toda Runeterra. Aqueles que invocam o poder de um dragão celestial podem acabar descobrindo que têm uma força interior incandescente tão quente e brilhante quanto a de uma estrela.","Equipamento",[],["Targon"],"COMUM"],"06MT053":["Artesã Generosa","Ao jogar um feitiço, dê +1|+1 a um aliado aleatório na mão.","","Com olhos bondosos e a expressão oculta atrás de um véu, ela oferece cristais de oração a quem estiver pronto para a peregrinação. Ela não cobra por essa ação. Afinal, o preço será pago na Montanha.","Unidade",[],["Targon"],"ÉPICO (A)"],"06MT006":["A Magnetita Darkin","Auxiliar: Dê +1|+1 ao meu aliado auxiliado.\nVocê pode gastar 8 de Mana para me pôr em jogo como Horazi.","","Talvez os responsáveis por aprisionar os Darkin pensassem que enterrar a lendária guerreira Horazi dentro de um orbe de metal estelar diminuiria suficientemente seu ímpeto irascível. Mas, à medida que seu general agia, Horazi também se agitava — e ela descobriu que até mesmo os antigos protetores de Targon podiam ser tentados por promessas sussurradas à distância.","Equipamento",["DARKIN"],["Targon"],"ÉPICO (A)"],"06MT018":["Guardião da Lei","Jogar: Atordoe inimigos com menos Poder do que eu.","","\"Temo que o dia finalmente tenha chegado... a Justiça retorna com asas douradas, e traz consigo um exército brilhante!\"\n– Guardião Mitológico Skai'en","Unidade",[],["Targon"],"COMUM"],"06MT052":["Bênção Celestial","Dê Espírito a um aliado em jogo e a um aliado na mão.","","\"Pela graça divina.\" – Kayle","Feitiço",[],["Targon"],"COMUM"],"06MT032":["Cultista Lunari","Ao me invocar ou depois de Equipar um aliado nesta partida, crie 1 Gema na mão.","","Ela buscou um fim para o conflito entre Sol e Lua, dia e noite. O arco oferecia poder, embora custasse um preço terrível. Ainda assim, ela se dedicou a ele na esperança de que a guerra fosse cessada de uma vez por todas. ","Unidade",["CULTISTA"],["Targon"],"COMUM"],"06RU008":["Jax","Origem: O Grão-Mestre das Armas.\nAutoequipar: A Chama de Icathia.","Aliados Equipados atacaram com 16+ de Poder total.","Séculos atrás, Jax perdeu sua terra natal para o Vazio. Agora, ele viaja pelo mundo procurando guerreiros com força de vontade — e pura ousadia — para um dia enfrentar esse terrível inimigo.","Unidade",["MESTRE DE ARMAS"],["Runeterra"],"Campeão"],"06RU006":["Ryze","Origem: O Mago Rúnico.\nAo me invocar ou no Início de Rodada: Crie 2 Mergulhos no Passado no seu deck.","Eu vejo 3+ Runas Globais únicas.","Ryze chegou ao topo, acompanhado pelo servo silencioso de Kayle. Ele contemplou a terra marcada pela guerra abaixo de si; as monstruosidades Darkin estavam em plena batalha. Durante séculos, ele observara a humanidade passar de uma catástrofe a outra. E se, pensou ele, seus esforços fossem inúteis e Runeterra estivesse fadada a morrer?","Unidade",[],["Runeterra"],"Campeão"],"06RU005":["Kayn","Origem: O Ceifador das Sombras.\nAutoequipar: A Foice Darkin.\nQuando eu abato um inimigo, eu me curo em 2.","Eu Golpeei duas vezes. Quando eu subir de nível, me Retorne.","Quando outro corpo caiu, Kayn soltou uma risada alegre, sabendo que em breve alcançaria a segunda arma Darkin que jazia ali. Dentro dele, a expectativa de Rhaast crescia, sabendo que a ruína de Kayn estava próxima.","Unidade",["DARKIN"],["Runeterra"],"Campeão"],"06RU026":["Aatrox","Origem: O Aniquilador de Mundos.\nAutoequipar: A Espada Darkin.\nAo me invocar ou Golpear: Cure seu Nexus em 2 e crie 1 Aniquilador de Mundos na mão se ainda não tiver.","Você jogou Aniquilador de Mundos.","Mesmo através dos continentes, Aatrox sentiu o despertar dela. Como o ódio ainda queimava. Ele já havia quebrado suas estátuas, e agora poderia travar uma guerra final contra a Covarde de Icathia e, ao destruí-la, acabar com essa existência lamentável.","Unidade",["DARKIN"],["Runeterra"],"Campeão"],"06RU009":["Varus","Origem: A Flecha da Vingança.\nAutoequipe O Arco Darkin.","Você alvejou 7+ aliados.","E se, com o tempo, influenciado pelas vozes mortais em seu interior, o homem que virou Darkin se lembrasse de si mesmo? E se, em vez de dominar essas vozes, ele começasse a acreditar nelas?","Unidade",["DARKIN"],["Runeterra"],"Campeão"],"06FR004":["Ferreira Aprendiz","Na primeira vez que você Equipar um aliado, Forje-o.","","Ornn construiu a forja viva muitos, muitos anos atrás, mas só foi procurar por ela recentemente. Ele jamais pensou que ela sairia por aí em busca de um novo dono.","Unidade",[],["Freljord"],"COMUM"],"06FR011":["Ornn","Jogar: Me Equipe com uma cópia idêntica ao equipamento de um aliado ou com o equipamento Mais Forte da mão.\nAtacar: Me Forje duas vezes.","Um aliado Golpeou causando 8+ de dano com um Golpe.","Se alguém perguntasse por que Ornn tem tão pouca paciência, ele responderia que, na verdade, tem muita paciência. Paciência até de sobra, por isso seu trabalho é incomparável. O que ele não tem paciência é com PESSOAS. Mas ninguém nunca perguntou isso, então ele nunca deu essa resposta.","Unidade",[],["Freljord"],"Campeão"],"06FR035":["Ao Resgate","Conceda +0|+3 a um aliado nesta rodada. Se ele tiver sofrido dano, conceda +2|+3.","","\"Não se preocupe, porinho. Estou com você!\" – Braum","Feitiço",[],["Freljord"],"COMUM"],"06FR034":["O Frio Imperdoável","Congele o inimigo Mais Forte. Se você tiver Equipado um aliado nesta partida, me copie.","","Anaakca avançou com tamanha velocidade que a própria Freljord pareceu segui-la. Os sobreviventes da carnificina dela logo sentiram a pele congelar e o coração parar.","Feitiço",["CULTISTA"],["Freljord"],"COMUM"],"06FR018":["A Lança Darkin","Atacar: Dê +1|+1 aos 2 aliados no topo do seu deck.\nVocê pode gastar 8 de Mana para me pôr em jogo como Anaakca.","","\"Mãe de guerra, o aperto do inverno se intensificou. Os avarosianos abandonaram seus postos avançados. O norte é o mar... nosso único caminho leva ao leste.\"\n\"Não dê ouvidos a ele, mãe de guerra. Ali fica o Alvor e, além dela, as florestas sussurrantes. É melhor morrer do que enfrentar aquela terra amaldiçoada.\"\n\"Que bom que nenhum de vocês decidirá o destino do meu povo.\"\n\"Tem razão, mãe de guerra. Mas talvez exista um terceiro caminho. Deixe-me viajar ao leste. É melhor perder um batedor para a Escuridão do que todo o nosso povo.\"\n– Mãe de guerra Sejuani em reunião com seus generais","Equipamento",["DARKIN"],["Freljord"],"ÉPICO (A)"],"06FR012":["Artesã Aprimorada","Ao me invocar, crie 1 Tempo e Dedicação na mão.","","''Minha mãe me contou histórias sobre Ornn assim como a mãe dela o fez, e a mãe da mãe dela também. Hoje, eu farei o mesmo, então preste atenção. Nada de interrupções. Muito tempo atrás, do outro lado de um agitado e fumegante mar...''","Unidade",[],["Freljord"],"COMUM"],"06FR005":["Forja de Ornn","Ao me invocar ou no Início de Rodada: Crie 1 Tempo e Dedicação Fugaz na mão.","","Sozinho na forja de Pedra-Lar, ouvindo nada além dos sons do rio fundido logo abaixo e o soar do martelo na bigorna... Ah, como ele adorava isso.","Monumento",[],["Freljord"],"RARO (A)"],"06FR040":["Vigia das Tribos","Ao me invocar, dê +1|+1 aos aliados para cada subtipo diferente que você invocou nesta partida.","","\"... e tinha uma criatura GRANDONA que cuidava de tooooodas as criaturas PEQUENAS...\" – Ingvar, a Jovem","Unidade",[],["Freljord"],"ÉPICO (A)"],"06FR020":["Fratura","Cause 1 de dano a TUDO ou destrua o equipamento de uma unidade.","","O frio não poupa nada nem ninguém.","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"06FR027":["Lesmamute Felpudo","Potencializado 8: Regeneração.","","Embora os trolls não sejam muito conhecidos por seu intelecto, podem ser surpreendentemente engenhosos.","Unidade",[],["Freljord"],"RARO (A)"],"06FR032":["Dádiva dos Sangue da Fornalha","Cure seu Nexus em 4 e dê +1|+1 a todos os aliados e equipamentos no seu deck. Compre 1 deles.","","''Venha, se aqueça perto do fogo.'' – Reparador Sangue da Fornalha","Feitiço",[],["Freljord"],"ÉPICO (A)"],"06FR022":["Fôlego do Fole","Forje um aliado e cause 1 de dano a TODAS as unidades. Repita a operação.","","''Um empenho de aço a ser forjado!'' – Ornn","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"06FR021":["Poro Emburrado","Potencializado 3: Sobrepujar, Regeneração e Robusto.","","\"Bora, você tem que tomar o remédio! Se não tomar, não vai melhorar!\" – Ingvar, a Jovem","Unidade",["PORO"],["Freljord"],"COMUM"],"06FR023":["Colosso Forjado","Ao me Equipar pela primeira vez, crie uma cópia minha de custo 4 na mão e dê a ela os atributos do equipamento.","","Apesar de não admitir, Ornn ficou muito satisfeito com os colossos. Eles serviam ao propósito atribuído... e o melhor de tudo: não falavam.","Unidade",[],["Freljord"],"ÉPICO (A)"],"06FR008":["Reparador Sangue da Fornalha","Jogar: Forje um aliado duas vezes e cure ele e o seu Nexus em 3.","","Os Sangue da Fornalha já não existiam mais quando Ornn decidiu deixar o mundo. Gerações se passaram desde então, e o nome desse grupo quase foi esquecido. Porém, os contos sobre Ornn ressurgiram nos últimos tempos, e dizem que alguns voltaram a adotar o estilo de vida deles.","Unidade",[],["Freljord"],"COMUM"],"06FR009":["Ferreiro Perito","Jogar: Forje um aliado.","","Quando Fiske pensou no tipo de aprendiz que teria, ele idealizou uma pessoa dedicada, forte, capaz e que levasse o ofício a sério. Mas Kindra... não era nada disso. Ela tinha a mania de sonhar acordada, e preferia brincar a trabalhar. Também sempre fazia um alvoroço com aquela tartaruguinha idiota dela. Mas... pelo menos ela estava aprendendo, e era isso que importava.","Unidade",[],["Freljord"],"COMUM"],"06FR024":["Porrete de Osso","","","\"Triturar!\" – Tarkaz, o Desgarrado","Equipamento",[],["Freljord"],"COMUM"],"06FR017":["Cultista do Vale de Gelo","Seus aliados Equipados têm Sobrepujar.","","A Garra do Inverno tinha razão. Os avarosianos estavam sendo gentis DEMAIS. Estava na hora de uma nova pessoa tomar a liderança, alguém que não tentaria unificar Freljord através da paz, e sim governá-la. ","Unidade",["CULTISTA"],["Freljord"],"RARO (A)"],"06FR041":["Toque Invernal","Receba uma gema de Mana vazia. Iluminado: Eu custo 1. Compre 1.","","Runas estranhas pulsam nas facetas da gema em suas mãos. Com um clarão, a luz se ergue através da superfície, envolvendo seu braço em uma espiral arrepiante. Mas esse arrepio é revigorante, não gelado, como se o frio em si te imbuísse com a própria essência. ","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"06FR036":["Misticismo Selvagem","Receba uma gema de Mana vazia.\nInvoque 1 Místico Selvagem.","","\"Os espíritos, as estrelas... nos reuniram de novo.\" – Vidente Hyara","Feitiço",[],["Freljord"],"ÉPICO (A)"],"06BC015":["Norra","Golpe ao Nexus: Plante 1 Portal Misterioso entre as 4 cartas no topo do seu deck.","Você invocou 6+ aliados criados.","Norra trabalhava rápido, sempre pensando em seu lar. Trabalhar com portais era um negócio complicado, e ela ainda nem tinha tomado sua primeira xícara de chá. Mas Norra amava um bom enigma, principalmente do tipo que a fazia se perder nas dimensões compactas entre o espaço e o tempo. Ainda assim, ela trabalhava rápido, pensando em sua gatinha que devia estar preocupada e ansiosa pelo jantar.","Unidade",["YORDLE"],["Bandópolis"],"Campeão"],"06BC043":["Contos de Poros","Crie 3 Poros aleatórios com 1 de custo na mão.","","\"...DAÍ O PORO DISSE: \"EI, EU TAMBÉM QUERO UM PORITO!\", DAÍ OS POROS SE JUNTARAM TUDO NA REUNIÃO DOS POROS PRA FALAR SOBRE OS PROBLEMAS DOS POROS E, SABE, CADÊ OS PORITOS E POR QUE NÃO TEM MAIS POROS E DAÍ...\" – Ingvar, a Jovem","Feitiço",[],["Bandópolis"],"COMUM"],"06BC051":["Atiradora de Bananas","Jogar: Cause dano equivalente ao meu Poder a uma unidade.","","''OPA! ALGUÉM AÍ PRECISANDO DE POTÁSSIO?'' – Nana, momentos antes do ''Incidente'' ","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"06BC047":["Partilha","Conceda a um aliado com uma unidade Conectada os atributos e as palavras-chave da unidade Conectada a ele nesta rodada e mova a unidade Conectada para outro aliado.","","Podem até achar que um pastor não tem lugar no campo de batalha, mas as habilidades que vêm com o cargo são surpreendentemente úteis. Você só precisa encarar todos os guerreiros como ovelhas precisando ser pastoradas.","Feitiço",["MESTRE DE ARMAS"],["Targon","Bandópolis"],"RARO (A)"],"06BC019":["A Especialista em Chás","Ao me invocar, Plante 1 Portal Misterioso entre as 4 cartas no topo do seu deck.","","Ashane era uma renomada especialista em chás antes de se perder no Fim do Reino. Enquanto realizava experimentos com novos sabores, acabou misturando duas folhas que a colocaram em um sono profundo. Ela sonhou com criaturas estranhas e estruturas impossíveis, cujas silhuetas contrastavam com o horizonte infinito. Porém, ao acordar, Ashane descobriu que aquilo não foi um sonho.","Unidade",["FADA"],["Bandópolis"],"COMUM"],"06BC029":["O Cajado Darkin","Golpear: Recarregue 1 de Mana de Feitiço.\nVocê pode gastar 8 de Mana para me pôr em jogo como Baalkux.","","O Bandobosque parecia o lugar perfeito para esconder uma arma Darkin, eles pensaram. O Bandobosque é, por natureza, intransponível — e os yordles saberiam se manter longe de uma malignidade tão abjeta. Mas os targonenses falharam em calcular a eficácia dessa magia tão peculiar e os efeitos que ela teria na flora local.","Equipamento",["DARKIN"],["Bandópolis"],"ÉPICO (A)"],"06BC038":["O Surto Repentino","Depois que você Equipar um aliado nesta partida, eu custo 2 a menos.\nDeixe um aliado com 4|4 nesta rodada.","","\"Temos tanto poder dentro de nós.\" – Varus","Feitiço",["CULTISTA"],["Bandópolis"],"RARO (A)"],"06BC017":["Portalpalooza","Plante 2 Portais Misteriosos entre as 4 cartas no topo do seu deck.\nCompre 1.","","''Eu devia pegar as Baixas Estradas mais vezes! Como sou boba, sempre esqueço de tomar cuidado pra não bater a cabeça...''\n– Norra","Feitiço",[],["Bandópolis"],"RARO (A)"],"06BC020":["Cortador de Origami","Me conceda +1|+0 por cada armadilha ou dádiva ativada nesta rodada.","","A magia do origami pode ser bem imprevisível. Ela se alimenta tanto da intenção de criar algo novo quanto do desejo que a criação tem de finalmente ser moldada.","Equipamento",[],["Bandópolis"],"RARO (A)"],"06BC028":["Cultista Florente","Depois que você Equipar um aliado nesta partida, eu ganho Elusivo.","","Pessoas, plantas, animais... A influência corruptora dos Darkin não poupa nada nem ninguém.","Unidade",["CULTISTA"],["Bandópolis"],"COMUM"],"06BC021":["Criação de Sucata","Suspiro Final: Plante 1 Portal Misterioso entre as 4 cartas no topo do seu deck.","","Ele havia nascido no dia anterior, mas Marv, apelido dado carinhosamente por Norra, já tinha muito orgulho de ser seu assistente. Porém, ele insistia severamente em ser chamado de \"sucata\", e não \"lixo\", que carrega uma certa conotação negativa.","Unidade",["FADA"],["Bandópolis"],"COMUM"],"06BC042":["Metamorfos Curiosos","Quando um seguidor aliado se transformar em outro seguidor, me transforme em uma cópia idêntica a ele.","","Camaleão vê, camaleão vira.","Unidade",[],["Bandópolis"],"RARO (A)"],"06BC023":["Placas Confusas","Retorne um feitiço Rápido ou Lento para a mão ou destrua o Equipamento de uma unidade. Compre 1.","","\"Nossa! Foi por aqui, por ali, ou... será que foi acolá? Eu nunca consigo me lembrar!\" – Norra","Feitiço",[],["Bandópolis"],"RARO (A)"],"06BC041":["Rebimbocas da Sucatita","Ao me descartar, me invoque. Ao invocar um Mech Yordle, dê uma palavra-chave aleatória a ele.","","Grande ou pequena, inanimada ou não, se você precisa encontrar alguma bugiganga, procure a Sucatita! Só não pergunte à Sucatita onde está, porque ela não é adepta à catalogação.","Monumento",[],["Bandópolis"],"RARO (A)"],"06BC011":["Jornada Mágica","Plante 1 Portal Misterioso entre as 4 cartas no topo do seu deck e Plante 1 Sino na carta no topo do seu deck.","","Vagando a seu bel-prazer por vários reinos, Bardo escuta atentamente, sabendo que um grande conflito se aproxima — algo que poderia silenciar toda a canção da criação.","Feitiço",[],["Bandópolis"],"COMUM"],"06BC032":["Coleção Eclética","Para cada aliado, Plante 1 Portal Misterioso e 3 Sinos entre as 10 cartas no topo do seu deck e Plante 1 Bomba de Clarão e 3 Cogumelos Venenosos no deck do inimigo.","","''Portais pra lá, portais pra cá!''\n– Norra","Feitiço",[],["Bandópolis"],"ÉPICO (A)"],"06BC024":["Guia do Reino","A cada rodada, na primeira vez que uma das suas armadilhas ou dádivas for ativada, conceda +1|+1 e Impacto aos aliados nesta rodada.","","Gaspar foi o primeiro yordle a chegar no Fim do Reino. Por muitos anos, ele vagou sozinho entre caminhos e trajetos distorcidos que pareciam não levar a lugar algum. Depois de decidir que ninguém deveria passar por isso, ele agora ajuda outros viajantes perdidos a encontrar o caminho de volta para casa.","Unidade",["FADA"],["Bandópolis"],"RARO (A)"],"06BC033":["Mechpulverizador","Para me pôr em jogo, descarte 1.","","''Contemplem! Das ruínas de uma balsa afundada, pesquei a luva de boxe. Das profundezas da cidade que chamam de Zaun, consegui molas, e das forjas de Demacia, encontrei metal! Temos aqui uma verdadeira criação do mundo!''\n– Paparo, o Grande","Equipamento",[],["Bandópolis"],"COMUM"],"06BC016":["Biblioteca Viva","Ao me invocar, se uma das suas armadilhas ou dádivas tiverem sido ativadas nesta rodada, compre 1.","","Ele considera que seu dever é ter uma quantidade incrível de conhecimento, então coleciona tomos de vários viajantes que passaram pelo Fim do Reino. Infelizmente, todo esse conhecimento acabou subindo à cabeça dele.","Unidade",["FADA"],["Bandópolis"],"COMUM"],"06IO044":["Melodia Celeste","Ao me invocar, reduza o custo dos feitiços no seu deck pela metade. O valor é arredondado para cima.","","''Alguns buscam paz na meditação. Outros buscam conhecimento para autorreflexão. Aqueles que encontram o próprio centro, seja por expressão ou criação, trarão paz tanto para si quanto para os outros.\" – Karma","Unidade",[],["Ionia"],"ÉPICO (A)"],"06IO013":["Estilo Wuju","Conceda +2|+0 a um aliado nesta rodada.\nCrie 1 Meditar na mão.","","''Um corte de muitos.''\n– Master Yi","Feitiço",[],["Ionia"],"RARO (A)"],"06IO023":["O Leque Darkin","Atacar: Invoque 1 Dragonito atacante.\nVocê pode gastar 9 de Mana para me pôr em jogo como Praa, o Andafendas.","","\"Há tempos que sinto uma sombra que pulsa com raiva silenciosa na ponte entre os dois mundos. Embora eu saiba que não devo mergulhar na Escuridão atrás dela, o pulso tem se tornado mais forte, mais rápido, e temo que as criaturas do reino espiritual logo começarão a procurá-la.\" – Shen","Equipamento",["DARKIN"],["Ionia"],"ÉPICO (A)"],"06IO029":["O Espírito do Wuju","Fluxo: Eu custo 2 a menos.\nAo me invocar, compre um feitiço.","","\"Mestre Doran acreditava que cada olho do Espírito do Wuju mostrava uma perspectiva única da natureza de uma pessoa. Mas, por mais que eu tente, as lentes do meu elmo só comtemplam vários tons de verde. O que foi que ainda não entendi?\" – Lui, Discípula de Doran","Unidade",[],["Ionia"],"COMUM"],"06IO037":["A Chama Sombria","Jogar: Capture um aliado. Ao atacar pela primeira vez em cada rodada, invoque uma cópia Efêmera atacante dele.","","\"O que é a vida senão uma sombra da existência? Abrace a Escuridão e viverá para sempre.\" – Zed","Monumento",[],["Ionia"],"ÉPICO (A)"],"06IO031":["Espada da Alma","Fluxo: Eu custo 2 a menos.","","''Espada e corpo.'' – Master Yi","Equipamento",[],["Ionia"],"COMUM"],"06IO014":["Discípulo Vastayês","Golpe ao Nexus: Me Retorne e me transforme em Vento de Shimon.","","Ting deu um sorrisinho enquanto os atacantes invadiam o templo. Finalmente uma chance para ele provar seu valor! Primeiro Wukong, agora Yi... Ambos dispensaram seus talentos. Deixe os outros correrem até o ''mestre''! Ele estava pronto. Ele era o Vento de Shimon. ","Unidade",[],["Ionia"],"ÉPICO (A)"],"06IO008":["Master Yi","Início de Rodada: Reduza em 1 o custo de um feitiço na sua mão e Fluxo: Dê +2|+0 a todas as cópias aliadas de Master Yis globalmente.","Master Yis aliados causaram 12+ de dano.","Master Yi se lembrou da arma Darkin. Desde sua descoberta, um terrível pressentimento passou a incomodá-lo. Como alguns de seus alunos demonstraram interesse demais no assunto, Yi colocou as lâminas curvadas sob vigilância nas profundezas do templo. Com certo esforço, ele afastou tais pensamentos e continuou a meditar. Repassar os ensinamentos do Wuju era tudo o que importava, e Jun demonstrava um talento promissor.","Unidade",[],["Ionia"],"Campeão"],"06IO040":["Técnica dos Ventos Gêmeos","Escolha um seguidor. Invoque uma cópia Efêmera idêntica a ele. Se for um inimigo, Atordoe-o.","","Para os ionianos, o vento é o mais volúvel dos elementos. Volúvel, mas não indomável. ","Feitiço",[],["Ionia"],"RARO (A)"],"06IO011":["Jun, a Prodígio","Ao me Equipar pela primeira vez, me conceda Barreira e Roubo de Vida nesta rodada.","","Ao sinal de Yi, Jun desferiu uma série de golpes tão precisos quanto os do próprio mestre. Apesar de desviar habilmente dos ataques, ele se curvou perante ela com um sorriso orgulhoso no rosto.","Unidade",[],["Ionia"],"RARO (A)"],"06IO015":["A Testemunha","Fluxo: Eu custo 2 a menos.\nJogar: Atordoe um inimigo.","","Qual é o papel dela neste estranho e terrível espetáculo? Ah, mais do que ouvinte, ela é observadora, as lentes que filtram tudo e a tudo julgam em contraste com a verdade e a beleza. A Testemunha!","Unidade",[],["Ionia"],"COMUM"],"06IO030":["Vale da Névoa","Ao me invocar, compre um equipamento.\nA cada rodada, na primeira vez que um aliado desequipado for Equipado, recarregue 2 de Mana de Feitiço.","","''O Vale da Névoa é um lugar sagrado. As espadas aqui encontradas chegaram há séculos... Acredito que qualquer lâmina deixada aqui com um poema na empunhadura atrairá espíritos de antigos portadores perdidos que, por fim, irão abençoá-las.''\n– Discípula de Doran, pergaminho escrito à mão","Monumento",[],["Ionia"],"RARO (A)"],"06IO034":["Escolha Decisiva","Se você tiver Equipado um aliado nesta partida, eu custo 1 a menos.\nConceda +2|+0 ou +0|+2 a um aliado nesta rodada.","","Quando Jun analisou os corpos caídos pelo chão, lágrimas de raiva escorreram por seu rosto. Ela falhou com todos eles... e com seu mestre. Agora, só restava uma escolha a ser feita.","Feitiço",["CULTISTA"],["Ionia"],"RARO (A)"],"06IO028":["Isca Fascinante","Conceda Desafiador a um aliado nesta rodada. Se ele estiver Equipado, compre 1.","","A isca certa desperta a fome de qualquer um.","Feitiço",["MESTRE DE ARMAS"],["Ionia","Noxus"],"RARO (A)"],"06IO025":["Fanático da Lâmina Sombria","Depois de Equipar um aliado nesta partida, crie 1 Demônio da Sombra na mão.","","Nas trevas, ele a viu: uma arma capaz de cortar as sombras. Naquele momento, ele ouviu uma voz distante, porém poderosa, chamando-o. Usando a veracidade das palavras que ouvia como guia, ele a seguiu — e chegou a Kayn.","Unidade",["CULTISTA"],["Ionia"],"COMUM"],"06IO039":["Caudalonga Navori","Jogar: Invoque 1 Brigante Navori ou conceda +1|+1 aos outros aliados nesta rodada.","","O caudalonga fez amizade com seu companheiro brigante numa noite de inverno enquanto compartilhavam o que restava de uma fogueira abandonada. Ao final da semana, eles haviam descoberto um senso comum de traquinice e um forte interesse no brilho dourado das moedas.","Unidade",[],["Ionia"],"COMUM"],"06IO032":["Alma Indigna","Fluxo: Eu custo 2 a menos.\nRetorne uma unidade ou um Monumento. Caso tenha unidades Conectadas, destrua-as primeiro.","","\"Você não é digno do poder que empunha.\" – Rhaast","Feitiço",[],["Ionia"],"RARO (A)"],"06IO001":["Discípula de Doran","Ao me invocar, crie 1 Preparação na mão.","","''Aprendi tudo que podia para continuar essa arte sagrada. Assim como Doran, o mestre dele e o mestre do mestre dele... espero que seus espíritos guiem meu martelo.''\n– Discípula de Doran, pergaminho escrito à mão","Unidade",[],["Ionia"],"COMUM"],"06IO016":["Evocadora de Dragões","Início de Rodada: Fluxo: Invoque 1 O Empíreo e dê Efêmero a ele.","","\"A forma da água reflete a forma do seu desejo. Diga-me, viajante... o que você vê?\"","Unidade",[],["Ionia"],"ÉPICO (A)"],"06PZ034":["Hexbliterador","Cause 6 de dano a uma unidade. Se fosse abatê-la, oblitere-a.","","Para algumas criaturas, a morte não é suficiente.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"06PZ006":["Bis","Crie na mão um feitiço Novo aleatório com 2 de custo, reduza seu custo em 2 e dê Fugaz a ele.","","Não há nada mais satisfatório do que uma boa ressonância.","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"06PZ021":["Seraphine","Ao me invocar, crie na mão um feitiço Novo aleatório com 2 de custo.","Você jogou 9+ feitiços Novos.","Seraphine e seu pai nunca falavam sobre as idas \"secretas\" da garota à Subferia nem sobre os aprimoramentos sutis que ela continuava fazendo ao próprio palco. A jovem tinha certeza de que o pai iria proibi-la de participar do duelo musical mais insano de Zaun, mas, uma noite, ele passou o panfleto por baixo de sua porta. Ela apenas sorriu e pôs as mãos à obra.","Unidade",[],["Piltover e Zaun"],"Campeão"],"06PZ040":["Bar do Beco","Ao me invocar, invoque 1 Barman do Beco.\nSuas novas cartas custam 1 a menos.","","Depois de secar os últimos copos, o taverneiro parou por um momento para examinar o lugar. Esse cantinho, esse lar longe de casa, já tinha testemunhado muitos estranhos se tornarem amigos, além de apresentar grafites e marcas de muitas noites agitadas. O taverneiro sorriu para si mesmo. Não era um lugar perfeito, mas era dele.","Monumento",[],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ008":["A Harpa Darkin","Você pode gastar 8 de Mana para me pôr em jogo como Styraatu.","","Enquanto os targonenses se perguntavam onde deveriam espalhar as armas Darkin, um deles sugeriu as terras que ficariam conhecidas como Zaun. Seria perfeito se fossem enterradas nas profundezas das passagens cavernosas e tortuosas, pensaram eles. Longe do alcance dos humanos. Mas não dos chireanos.","Equipamento",["DARKIN"],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ018":["Nota Aguda","Cause 2 de dano a uma unidade. Se você tiver jogado 6+ feitiços Novos nesta partida, cause 1 de dano a outra unidade.","","Simples e clara.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ014":["Presidente do Fã-clube","Jogar: Manifeste um feitiço que custe 5 e reduza o custo dele a 2.","","\"O que importa não é a grandeza da sua voz, e sim a do seu coração!\" – Presidente do fã-clube","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"06PZ030":["Projetos Inspirados","Atacar: Crie um feitiço Novo com 2 de custo na mão e dê Fugaz a ele.","","\"Ih, querida, parece que vem chuva aí.\"\n\"Hã? Pai, tá tão claro lá fora.\"\n\"Rápido, cubra os projetos! É uma chuva de IDEIAS!\"\n\"Paaaaai.\"\n– Seraphine e seu pai","Equipamento",[],["Piltover e Zaun"],"RARO (A)"],"06PZ046":["Fórmula","Compre 2. Recarregue seu Mana de Feitiço.","","''Magia não passa de verdades científicas que ainda não foram descobertas.'' – Jayce","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ007":["Cultista Ambicioso","Depois de Equipar um aliado nesta partida, crie na mão um feitiço Novo que custe 2 e reduza o custo dele a 0 nesta rodada.","","\"Sempre me dispus a fazer sacrifícios em nome da ciência. Apesar dos riscos pessoais, o poder irrestrito e inesgotável que ganhei com a troca foi uma recompensa mais do que adequada.\"","Unidade",["CULTISTA"],["Piltover e Zaun"],"COMUM"],"06PZ041":["Gatinho Ardiloso","Ao me invocar, se tiver me criado, compre 1 e me dê +2|+1.","","Quando não estão dormindo no meio do dia ou vomitando no meio da noite, os gatos estão sempre fazendo algum tipo de travessura.","Unidade",["FELINO"],["Piltover e Zaun"],"COMUM"],"06PZ036":["A Diva de Zaun","Jogar: Cause 1 de dano a todos os inimigos. Se você tiver jogado 6+ feitiços Novos nesta partida, cause 3 de dano.","","\"Zaun! Espero que estejam prontos pra gritar, porque a gente vai afundar esse lugar de novo!\" – Diva de Zaun","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"06PZ010":["Acusticista","Golpear: Crie na mão um feitiço Novo aleatório com 2 de custo.","","Ele sonhara em deixar Zaun e viajar pelo mundo com uma música em seu coração. Agora, o mundo jazia adormecido em seu quarto, esperando pelas músicas que o amanhã poderia trazer.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ022":["Solo de Bateria","Compre 2 cartas.\nFluxo: Reduza o custo delas em 1.","","O tempo é a base da música, mas, de vez em quando, você tem que se soltar.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ029":["Favorita do Público","Conceda +2|+0 e Ataque Rápido a um aliado nesta rodada.\nFluxo: Crie na mão um feitiço Novo com 2 de custo.","","\"Mais alto, Zaun!\" – Seraphine","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ020":["Bolota, o Hextécnico","Golpe ao Nexus: Reduza em 1 o custo do feitiço mais caro na sua mão.","","Você não encontrará o nome dele nos projetos nem o verá creditado nas canções, mas aqueles que sabem concordaram: Bolota era o coração de toda a operação.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"06PZ009":["Arranjo Cáustico","Fluxo: Eu custo 2 a menos.\nCause 1 de dano a todos os inimigos.","","Romper o estardalhaço e a barulheira de Zaun exige um som especial, mas a Diva sempre dá conta.","Feitiço",[],["Piltover e Zaun"],"COMUM"],"06PZ037":["A Dissonância Violenta","Cause 1 de dano a uma unidade. Se você tiver Equipado um aliado nesta partida, me copie com o mesmo alvo.","","Se a dissonância é a cacofonia da destruição, que o massacre continue.","Feitiço",["CULTISTA"],["Piltover e Zaun"],"RARO (A)"],"06PZ019":["Segurança Zaunita","Início de Rodada: Fluxo: Recarregue 2 de Mana de Feitiço.","","Se tudo fosse do jeito dele, NINGUÉM entraria.","Unidade",[],["Piltover e Zaun"],"COMUM"],"06PZ033":["Gatalista v1.0","Seus feitiços e Habilidades causam 1 de dano adicional.","","\"Local: Setor 3, Subsolo 19B\nItem: arma de fogo ilegal\nObservações: confiscada durante a Operação Luz do Sumidouro. Arma altamente perigosa. Manuseie com extremo cuidado.\"\n— Relatório de campo do Vigia de Piltover","Equipamento",[],["Piltover e Zaun"],"COMUM"],"06BW029":["Náufrago Piltovense","Ao me invocar, eu Improviso.","","Pesh conheceu Jax em uma briga nas docas, e a fuga oportuna dos dois foi mais conveniente do que qualquer parceria. Desde então, Pesh leva Jax para lá e para cá, já que as coisas parecem simplesmente quebrar perto dele. E, se tem uma coisa que Pesh gosta mais do que uma boa briga, são coisas precisando de conserto.","Unidade",["MESTRE DE ARMAS"],["Águas de Sentina","Piltover e Zaun"],"COMUM"],"06BW034":["Metal Pesado","Destrua o equipamento de uma unidade e cause 2 de dano a ela.","","''QUEM ARREMESSA UMA ÂNCORA EM UMA BRIGA DE BAR?! QUAL É O PROBLEMA DE VOCÊS?!'' – Taverneiro de Águas de Sentina","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"06BW027":["Partes Fazem o Todo","Para me pôr em jogo, descarte 1. Compre 2 cartas e, se tiver descartado um equipamento, invoque 1 Miragem Icathiana.","","O bando de Jax é prova de que o todo pode ser maior que a soma de suas partes. Mas Pesh insiste em uma filosofia diferente: às vezes, as partes são ótimas por si só.","Feitiço",["MESTRE DE ARMAS"],["Águas de Sentina","Piltover e Zaun"],"RARO (A)"],"06BW039":["A Onda Infinita","Depois que você Equipar um aliado nesta partida, eu custo 2 a menos.\nCompre 2 cartas e dê Fugaz a elas.","","Embora os velhos ossos de Ibaaros se movessem lentamente, as águas que se avolumavam à frente dele avançavam a uma velocidade quase incompreensível.","Feitiço",["CULTISTA"],["Águas de Sentina"],"RARO (A)"],"06BW026":["Cultista Buhru","Quando aliados Equipados atacarem, cause 1 de dano ao Nexus inimigo.","","A origem do poder era irrelevante; a deusa dela não se importaria com isso. O que interessava era a glória que ela conquistaria aniquilando monstros.","Unidade",["CULTISTA"],["Águas de Sentina"],"COMUM"],"06BW014":["O Arpão Darkin","Atacar: Compre 1 carta no próximo Início de Rodada e dê Fugaz a ela.\nVocê pode gastar 9 de Mana para me pôr em jogo como Ibaaros.","","\"Fujam, fujam do Estreito de Daray, todos entoam,\nOnde as águas sussurram e os ventos atraiçoam,\nOnde fera marinha e pássaro bem pouco povoam,\nPois as profundezas desse Estreito não perdoam.\"\n– Rima de Águas de Sentina","Equipamento",["DARKIN"],["Águas de Sentina"],"ÉPICO (A)"],"06BW004":["Teste de Espírito","Conceda Vulnerável a um inimigo nesta rodada. Se ele morrer ainda nesta rodada, cause 1 de dano ao Nexus inimigo.","","\"Vai encarar ou se acovardar?\" – Illaoi","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"06BW044":["Tritão Travesso","Golpe ao Nexus: Compre 1 carta e dê Fugaz a ela.","","\"Monstrinhos nojentos e ladrões, esses aí. Mas são facinhos de achar quando já afanaram algo, pelo menos.\"","Unidade",["RÉPTIL"],["Águas de Sentina"],"COMUM"],"06BW047":["Marai Arteira","Ao jogar um feitiço, invoque 1 Barril de Pólvora.","","''Bibi é um pouco... perturbada, eu sei. Mas é por isso que amamos ela!'' – Ai'la, Vigia Marai","Unidade",[],["Águas de Sentina"],"RARO (A)"],"06BW023":["Alfanje Irregular","Saquear: Eu custo 2 a menos.","","''É como dizem: nada encerra uma discussão em Águas de Sentina mais rápido que um sabre.''\n''Talvez uma pistola.''\n''Cala a boca, Baz.''\n– Baz e Gav, aspirantes a caçadores de recompensas","Equipamento",[],["Águas de Sentina"],"COMUM"],"06BW042":["Navio Carregado","Cause 2 de dano a uma unidade. Compre 1 carta no próximo Início de Rodada para cada ponto de dano causado e dê Fugaz a ela.","","\"O Rex vai cuidar da explosão, não se preocupe. E eu cuido do tesouro. Vou cuidar da parte do Rex também, senão ele vai colocar tudo dentro do canhão e fazer uma bagunça.''\n– Suboficial","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"06BW040":["Olho da Deusa","Atacar: Faça Surgir 2 Tentáculos.","","\"Fique firme diante do olhar Dela!\" – Illaoi","Equipamento",[],["Águas de Sentina"],"RARO (A)"],"06SH032":["Arsenal Enterrado","Contagem 2: Crie 1 Tesouro das Areias na mão.","","\"Por que você fica fuçando tudo?\"\n\"Ué, você acha que são armadilhas? E que uma pedra vai aparecer do nada pra...\"\n\"CORREEEE!\"\n– Argus e Silvio, ladrões de túmulos","Monumento",[],["Shurima"],"COMUM"],"06SH035":["O Altar de Sangue","Ao Eliminar uma unidade, reduza em 1 o custo da próxima unidade Darkin que você jogar.","","O altar pulsava com vida mais uma vez, sacudindo a areia ao redor com uma batida lenta e constante. Cada um dos discípulos de Xolaani sentia a mesma batida no fundo do coração. Cada músculo, pensamento, momento... estava sob o controle dela.","Monumento",[],["Shurima"],"RARO (A)"],"06SH046":["Relicário do Acólito","Ao me invocar, crie 1 Acólito Ruinoso na mão. Ao me destruir, crie 1 Relicário do Acólito nas 5 cartas no topo do seu deck.","","\"Nossas mãos moldam o deserto!\" – Acólito Ruinoso","Monumento",[],["Shurima"],"RARO (A)"],"06SH033":["Maldição da Tumba","Preveja. Conceda a uma unidade \"Sofro o dobro do dano e, se eu for morrer, me Oblitere\" nesta rodada.","","\"Somente tolos buscam um poder que não podem controlar.\" – Xerath","Feitiço",[],["Shurima"],"RARO (A)"],"06SH028":["Portal do Vazio","Ao invocar um aliado ou quando um aliado morrer, dê cada uma das suas palavras-chave positivas a 3 aliados no seu deck.","","O Arauto do Enxame ergueu duas mãos à estrutura gigantesca acima dele. \"UM TRONO\", gritou, \"PARA UMA IMPERATRIZ\". O portal do vazio pulsou com vida. Em breve.","Monumento",[],["Shurima"],"ÉPICO (A)"],"06SH005":["Baccai Esquecido","Jogar: Preveja. Se você escolher um Darkin ou um equipamento, eu ganho +1|+1.","","Ele segurava um cinto trançado, um presente que recebeu de seu amigo Rhaast antes da cerimônia de Ascensão de ambos — mas, mesmo que reverenciasse o poder do Darkin, também guardava um ressentimento que escondia em seu coração bestial.","Unidade",["CULTISTA"],["Shurima"],"COMUM"],"06SH056":["Castigar","Abata TODOS os seguidores.","","Às vezes a luz te atrai, e às vezes ela é atraída por você.","Feitiço",[],["Shurima"],"RARO (A)"],"06SH040":["Ressurreição Negligente","Depois que você Equipar um aliado nesta partida, eu custo 2 a menos. Ressuscite o Campeão aliado Mais Forte que tiver morrido.","","\"Você nunca morrerá, porque eu não deixarei.\"\n– Xolaani","Feitiço",["CULTISTA"],["Shurima"],"ÉPICO (A)"],"06SH021":["Horror Camuflado","Jogar: Eu Golpeio um inimigo.","","Enquanto o ataque prosseguia, criaturas maiores e ainda mais ferozes jorravam da passagem crescente. A cidade de Belveth foi destruída; no entanto, como quis a crueldade do destino, o nome dela perduraria.","Unidade",[],["Shurima"],"RARO (A)"],"06SH051":["Pastora de Pedregursos","Ao invocar outro aliado, Avance seu Monumento com a Contagem mais alta em 1 rodada.\nAo me invocar, invoque 1 Pedregurso Hibernado.","","\"Os rochidos tratam Sadira como se fosse uma deles. Ela fugiria com eles em um piscar de olhos se eu deixasse, a pestinha!\" – Kadira, Naturalista do Deserto","Unidade",[],["Shurima"],"RARO (A)"],"06SH055":["Sacerdotisa da Luz do Deserto","Início de Rodada: Cause 4 de dano a mim. Compre um Campeão e dê a ele +2|+2 ou, se seu deck começou com 6+ Campeões diferentes, invoque-o.","","Os fiéis se mantêm firmes conforme o mal se aproxima, oferecendo seus últimos suspiros para invocar a luz da justiça. Eles sabem que esse chamado desesperado por salvação será atendido antes que a escuridão consuma tudo.","Unidade",[],["Shurima"],"ÉPICO (A)"],"06SH004":["As Carniceiras Darkin","Suspiro Final: Se meu portador não for 1 Servo Darkin, invoque 1 Servo Darkin.\nVocê pode gastar 6 de Mana e abater um aliado para me pôr em jogo como Xolaani.","","Enquanto a luta continuava, Jun, desesperada e gravemente ferida, voltou-se para a voz que sussurrava em seus pensamentos. \"Você nunca morrerá\", disse a voz em um tom suave como chuvas de verão, \"porque eu não deixarei\".","Equipamento",["DARKIN"],["Shurima"],"ÉPICO (A)"],"06SH038":["Lâmina Pendular","Golpear: Crie 1 Descoberta de Sorte na mão.","","\"Persiga o que deseja. Sem dar trégua.\" – Exploradora das Ruínas\n","Equipamento",[],["Shurima"],"COMUM"],"06DE048":["Texurso Segurança","","","''Se veio pra ser amigo, seja muito bem-vindo, viu? Mas, se alguém com coração ardiloso botar um pezinho aqui, vai provar a vingança do poderoso protetor!''","Unidade",["ELITE"],["Demacia"],"COMUM"],"06DE024":["Pega Essa!","Conceda +1|+1 a um aliado nesta rodada ou Equipe-o com um equipamento da mão que custe 2 ou menos.","","Essa técnica se torna ainda mais dolorosa se o grupo estiver de barriga vazia.","Feitiço",["MESTRE DE ARMAS"],["Demacia","Freljord"],"RARO (A)"],"06DE025":["Recruta Benevolente","Ao me invocar, conceda Barreira aos aliados Equipados nesta rodada.","","\"Esse garoto é um risco. Insisti para que não o trouxessem na nossa caçada, já que ele ainda chama aquela criatura vil de 'irmã'. É de uma ingenuidade tão grande que, francamente, me revolta. Ainda assim, acho que tenho pena dele. Na pior das hipóteses, essa será uma lição importante para ele.\" – Do diário pessoal de Sirius Rowill, Cavaleiro-Patrulheiro Zeloso","Unidade",[],["Demacia"],"RARO (A)"],"06DE033":["Silenciar e Suprimir","Destrua o equipamento de uma unidade e, se for um seguidor, Silencie-o.","","''Suas ações têm consequências.'' – Lorde Eldred, Líder dos Caçadores de Magos","Feitiço",[],["Demacia"],"RARO (A)"],"06DE039":["Rugido de Icathia","Invoque 2 Miragens Icathianas Equipados com até 2 Equipamentos da mão que custem 2 ou menos.","","Jax passou incontáveis sonhos lutando ao lado de sua família perdida. Algumas batalhas eles ganham, outras eles perdem, mas sempre estão juntos.","Feitiço",["MESTRE DE ARMAS"],["Demacia"],"RARO (A)"],"06DE011":["A Égide Darkin","Você pode gastar 5 de Mana para me pôr em jogo como Joraal.","","\"Filho, escute. Aquele escudo nunca deve ser tocado. Há muito tempo, ele foi concedido à nossa família sob a condição de que fosse protegido e deixado em paz. Ele é minha responsabilidade e, quando eu morrer, será sua. Entendeu? Nunca mais vá até ele. Jamais toque nele.\"\n\"Mas mamãe, a voz que vem dele... me chama. Ela soa tão triste.\"\n\"... Mais uma razão para ficar longe, filho.\"\n– Lady Fortis e seu filho","Equipamento",["DARKIN"],["Demacia"],"ÉPICO (A)"],"06DE021":["Vayne","Ao me invocar ou no Início de Rodada: Crie 1 Rolamento na mão ou reduza o custo em 1 se já tiver uma cópia.","Vi você atacar 4 vezes.","\"Nosso alvo já foi humano, então é mais inteligente do que as feras comuns. Um passo em falso pode condenar todos nós à morte. Fiquem dentro do campo de visão uns dos outros, comuniquem qualquer coisa suspeita, mas, acima de tudo, lembrem-se...\"","Unidade",[],["Demacia"],"Campeão"],"06DE043":["Capricão de Confiança","Na primeira vez que invocar uma carta Elite, eu ganho +2|+2.","","\"Ela não é tão rápida quanto uma rapina prateada, mas a rapidez das suas perninhas surpreende qualquer um.\"\n– Cithria, Dama das Nuvens","Unidade",["CANINO"],["Demacia"],"COMUM"],"06DE018":["Condenar","Se você tiver atacado 2+ vezes nesta rodada, eu custo 5 a menos.\nUm aliado Golpeia um inimigo.","","\"Virotes purificantes.\" – Vayne","Feitiço",[],["Demacia"],"COMUM"],"06DE041":["A Força dos Campeões","Conceda +4|+4 aos aliados nesta rodada e Mobilize.","","\"Para a batalha com corações radiantes!\" – Lux","Feitiço",[],["Demacia"],"ÉPICO (A)"],"06DE026":["Mitos Icathianos","Crie 1 Miragem Icathiana na mão que custa 0 nesta rodada ou crie 1 Espátula Dourada na mão.","","As lendas dizem que o dono original da Espátula Dourada era uma criatura marinha de destreza culinária excepcional que buscava tornar-se um guerreiro tão forte e ousado quanto Jax.\n\nJá outras histórias mais críveis afirmam que essa lenda específica foi inventada por certo cozinheiro que estava viajando na maionese.","Feitiço",[],["Demacia"],"RARO (A)"],"06DE044":["Touro de Petricita","Não sofro dano de Habilidades nem feitiços inimigos.","","\"Nada é mais forte que petricita.\" – Arquiteto de Durand","Unidade",[],["Demacia"],"RARO (A)"],"06DE017":["Briga de Peixe","Um aliado e um inimigo Golpeiam um ao outro, ou um aliado Equipado Golpeia um inimigo e, depois, é desequipado.","","\"Toma essa!\" – Pescadora Ioniana","Feitiço",["MESTRE DE ARMAS"],["Demacia"],"COMUM"],"06DE040":["Possibilidade Tentadora","Escolha um seguidor ou equipamento entre as 4 cartas no topo do seu deck. Compre-o e devolva o resto ao seu deck.","","Sussurros serenos e sedutores plantam desejos no fundo do coração. Como uma farpa, eles inflamam e se transformam em fome, evoluindo para transgressão e, finalmente, trazendo a morte. E, assim, o ciclo continua.","Feitiço",["CULTISTA"],["Demacia"],"COMUM"],"06DE028":["Harpia Maldissangue","Jogar: Me Equipe com um equipamento que esteja na mão e custe 2 ou menos.\nNa primeira vez em que eu morreria no estado Equipado, eu me curo completamente e o meu equipamento é destruído.","","\"Kian, se você estiver lendo isso... espero que eu já tenha morrido. Não consigo controlar o que está acontecendo comigo. O sangue sob as minhas unhas não sai. E sinto tanta coceira. Coço e coço, mas não adianta. Dói. Só quero que isso acabe. Se eu tiver sobrevivido, prometa que vai parar de tentar me encontrar.\n\nEu pediria perdão, mas não mereço. Cuide bem da mamãe, tá?\"\n– Carta amassada encontrada em uma bolsa rasgada","Unidade",[],["Demacia"],"ÉPICO (A)"],"06DE027":["Cavaleiro-Patrulheiro Zeloso","Atacar: Conceda +1|+1 aos aliados Equipados nesta rodada.","","\"Janan, certo? O que você sabe sobre o Sirius?\"\n\"Ah, o Cavaleiro-Patrulheiro Rowill? Revogaram o título dele alguns anos atrás. Aparentemente, ele ignorou de propósito todas as ordens que tinha recebido. Parece que ele faz o que quer e não aceita 'não' como resposta.\"\n\"Ah.\"\n\"Enfim... por que deixou ele participar da caçada?\"\n\"Não deixei.\"\n\"Então por que... ah, certo. Fantástico.\"\n– Vayne e Janan, a Caçadora Viúva","Unidade",[],["Demacia"],"RARO (A)"],"06DE019":["Caçadora Viúva","Jogar: Me Equipe com um equipamento da mão que custa 2 ou menos.","","\"Apesar de parecer uma lutadora competente, o luto dessa mulher é recente e ameaça consumi-la. O desespero é, sem dúvida, uma motivação atraente (eu que o diga), mas desmedido assim? Talvez ela queira morrer...\" – Do diário pessoal de Sirius Rowill, Cavaleiro-Patrulheiro Zeloso","Unidade",[],["Demacia"],"COMUM"],"06DE032":["Aço Demaciano","","","A espada e o escudo básicos usados pelas forças de Demacia.","Equipamento",[],["Demacia"],"COMUM"],"06DE029":["Elkin Inabalável","Na primeira vez que um aliado for Equipado, eu ganho Robusto.","","\"Para trás, criatura vil! Se arrancar um único fio do pelo imaculado da Pureza, vou garantir que você sofra uma AGONIA ETERNA!\" – Sirius Rowill, Cavaleiro-Patrulheiro Zeloso","Unidade",[],["Demacia"],"COMUM"],"06DE010":["Desertora dos Cavaleiros-Patrulheiros","Depois que você Equipar um aliado nesta partida, eu ganho Patrulheiro.","","Anos de repressão sobre sua magia criaram dentro dela um complexo ódio por si mesma, que era maliciosamente descontado em suas vítimas. Após desertar dos cavaleiros-patrulheiros, sua fúria não tinha finalidade — até que uma voz a chamou na escuridão. A voz falava de uma nova ordem, uma em que ela poderia praticar sua crueldade sem restrição alguma.","Unidade",["CULTISTA"],["Demacia"],"RARO (A)"],"06DE006":["Cozinheiro de Combate","Ao me invocar, eu Improviso. Depois, me Forje.","","Depois de servir no exército demaciano, Breshi achou que ia se aposentar e cozinhar em uma taverna de algum vilarejo tranquilo. Mas esse sonho foi arruinado por Jax após uma briga de bar e uma opinião bem ruim sobre ovos com gema dura. Desde então, Breshi abraçou um novo objetivo de vida: ensinar Jax a ter um pouco de bom gosto.","Unidade",["MESTRE DE ARMAS"],["Demacia","Freljord"],"COMUM"],"06DE034":["Loba Leal","Se um aliado tiver morrido nesta rodada, eu custo 2 a menos.\nJogar: Me Equipe com um equipamento da mão que custe 2 ou menos e me Forje.","","\"A Maggie está comigo desde que era filhote. Pode até já estar velha, mas ainda é mordaz feito uma lâmina recém-afiada. Eu daria a minha vida por ela — e sei que ela daria a dela por mim.\" – Janan, a Caçadora Viúva","Unidade",["CANINO"],["Demacia"],"COMUM"],"06SI045":["Cisão Anímica","Abata um aliado para invocar 2 cópias Efêmeras dele.","","Eles nem estavam usando mesmo.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"06SI007":["A Alabarda Darkin","Para me pôr em jogo, abata um aliado.\nVocê pode gastar 10 de Mana para me pôr em jogo como Taarosh.","","Testando os limites de sua cela, Taarosh ouviu o chamado de seu general. E ele responderia, de uma forma ou de outra.","Equipamento",["DARKIN"],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI034":["Espectro dos Ecos","Fim de Rodada: Para cada aliado morto nesta rodada, dê +1|+1 a todas as cópias aliadas dele globalmente.","","\"Eu não sei que tipo de magia perversa praticam e nem QUERO saber. Tudo o que preciso saber é que, caso se ergam, vão morrer. De novo.\" – Vigilante das Ilhas","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI029":["Lança Maléfica","Se um aliado tiver morrido nesta rodada, eu custo 2 a menos.","","\"Não há justiça a se fazer... apenas vingança.\" – Kalista","Equipamento",[],["Ilhas das Sombras"],"COMUM"],"06SI032":["Quietus","Abata uma unidade com 4 ou menos de Poder e Vida somados ou destrua o equipamento de uma unidade.","","Independentemente de como a morte se manifestará nas Ilhas das Sombras, torça para que seja abençoadamente rápida.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"06SI031":["Lâminas dos Caídos","Conceda a um aliado \"Suspiro Final: Invoque 1 Miragem Icathiana com o meu equipamento\" nesta rodada.","","Às vezes, o melhor que você pode fazer por um aliado abatido é pegar a arma dele e continuar a luta.","Feitiço",["MESTRE DE ARMAS"],["Ilhas das Sombras","Shurima"],"RARO (A)"],"06SI014":["Saguão Opulento","Ao me invocar, invoque 1 Banda Assombrosa.\nInício de Rodada: Se tiver o Símbolo de Ataque, invoque 1 Banda Assombrosa.","","\"Os participantes estão prontos, o palco está montado, nosso público aguarda. Maestro, por gentileza!\" – Anfitrião Animado","Monumento",[],["Ilhas das Sombras"],"ÉPICO (A)"],"06SI038":["Prodígio Redimido","Atacar: Invoque 1 Banda Assombrosa atacante.","","Tentar alcançar a perfeição era limitador, rígido. A perfeição não tinha vida; não podia respirar. Agora, a imperfeição perfeita, ela sim era algo pelo qual valia a pena lutar.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"06SI003":["Fireth, a Ceifadora das Areias","Ao me invocar, eu Improviso.","","Jax perguntou o nome de Fireth inúmeras vezes em suas primeiras semanas de viagem juntos, mas ela só rosnava: \"Eu sou a Ceifadora!\". Breshi encontrou a solução perfeita — ele tinha acabado de fazer um bolo e precisava do nome do integrante mais forte do grupo para comemorar adequadamente.","Unidade",["MESTRE DE ARMAS"],["Ilhas das Sombras","Shurima"],"ÉPICO (A)"],"06SI006":["Guardiã da Caixa","Depois que você Equipar um aliado nesta partida, eu ganho Roubo de Vida.","","\"A Caixa não revela seus segredos livremente, Shieda Kayn. Eles têm um preço terrível. Mas, se tiver coragem de olhar para a sombra das sombras, descobrirá que coisas maravilhosas e aterrorizantes jazem ali.\" – Ysdra, Guardiã da Caixa","Unidade",["CULTISTA"],["Ilhas das Sombras"],"COMUM"],"06SI039":["A Forma do Medo","Abata um aliado para invocar 1 Névoa Invasora.","","Apenas um tolo olharia para a Névoa Negra na esperança de encontrar uma forma familiar.","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"06SI042":["Cavaleiro Imortal","Se fosse receber Efêmero, eu ganho +1|+1 em vez disso.","","Soldados que foram treinados para resistir a punições em vida eram apenas mais diligentes e capazes na morte — inabaláveis pelo frio, dor ou medo.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"06SI036":["Devastação Absoluta","Abata TODAS as unidades, exceto aliados Darkin e aliados Equipados.","","Quando ela segurou as armas, sua humanidade se esvaiu e, em seu lugar, uma essência odiosa preencheu o receptáculo vazio que um dia fora a estudante Jun. A essência a atravessou, envolvendo-a de cima a baixo, e saiu para o mundo, agitando os Darkin adormecidos.","Feitiço",["CULTISTA"],["Ilhas das Sombras"],"RARO (A)"],"06SI046":["Vigilante Determinado","Suspiro Final: Compre 1.",""," ''... e, assim, eu continuo vigilante, por toda eternidade, além da vida e da morte. Esse é meu dever.''","Unidade",[],["Ilhas das Sombras"],"COMUM"],"06SI041":["Vigilante do Vale Enluarado","Ao invocar um aliado Efêmero, dê +1|+0 a ele.\nAnoitecer: Invoque 1 Muda.","","Longe das margens das Ilhas das Sombras, há bosques de árvores consideradas mortas há muito tempo, tortas e imóveis para todos, exceto para um excelente observador, que notará que, no solo encharcado pelo luar, surge nova vida.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"07PZ009":["Relologi Aprimorado","Jogar: Preveja e depois compre 1 e reduza o custo em 1.","","\"Esse carinha só precisava de uns ajustes. Engrenagens novas aqui, um braço novo ali, e mais uma chance na vida. O tempo é um presente que todos deveriam ganhar mais.\" – Ekko","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"07PZ017":["Comerciante de Bombas de Clarão","Ao jogar um feitiço, Plante 1 Bomba de Clarão entre as 8 cartas no topo do deck inimigo.","","\"...E sabe o que mais torna essas belezinhas melhores do que cogumelos? Você decide quando elas explodem! ISSO é que é valor agregado!\"","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"07PZ005":["Pela Culatra","Cause 1 de dano a um inimigo e ao Nexus inimigo. Descarte até 2 cartas para aumentar o dano em 1 para cada carta descartada.",""," \"Tá, tá. Pode até ser que funcione uma vez só, mas, confia em mim, vai ser um estouro!\" – Jinx","Feitiço",[],["Piltover e Zaun"],"RARO (A)"],"07NX009":["Tiro Estiloso","Cause 1 de dano ao Nexus inimigo. Na próxima vez que um aliado Golpear o Nexus nesta rodada, crie 1 Tiro Estiloso na mão.","","\"Ninguém tinha chance contra mim quando eu só tinha bastões e pedras. Agora com esse equipamento? É melhor nem tentar.\" – Samira","Feitiço",[],["Noxus"],"ÉPICO (A)"],"07NX008":["Elegância Afiada","Saquear: Eu ganho +2|+0.","","\"Meu preço é alto, e eu não trabalho para qualquer um. Se tiver a sorte de me contratar, você leva elegância, atitude e lâminas que nunca erram o alvo. Mas, acima de tudo, você leva estilo. Porque quem não ama matar com classe?”","Unidade",[],["Noxus"],"COMUM"],"07NX014":["Pirueta","Saquear: Eu custo 2 a menos.\nCause 1 de dano a qualquer coisa e Atordoe um inimigo.","","\"Quê? Eu estava só me aquecendo. Não me diga que você morreu enquanto eu me aquecia.\" – Elegância Afiada","Feitiço",[],["Noxus"],"RARO (A)"],"07NX007":["Samira","Saquear ou Golpear: Crie 1 Talento Natural na mão se ainda não tiver.","Eu vi você jogar 6 cartas. A contagem é reiniciada quando você inicia uma rodada com o Símbolo de Ataque.","\"Estou sempre perseguindo algum alvo que fez mais dívidas do que podia pagar. E fugir dessas dívidas rende inimigos do pior tipo. O tipo que recorre a mim.\"","Unidade",[],["Noxus"],"Campeão"],"07NX006":["Cavalheiro Cortês","Saquear: Dobre meu Poder.",""," \"Olha, eu costumo gostar de estabelecer algumas regras, tipo: 'não toque no meu cabelo nem no meu rosto', mas para que isso? Você não vai encostar um dedo em mim.\"","Unidade",[],["Noxus"],"COMUM"],"07NX015":["A Dama Saqueadora","Saquear: Dê +1|+0 aos aliados.","","\"Ah, a Dama. Adora um drama, aquela ali. Alguns podem torcer o nariz para uma certa pompa, mas, quando ela está inspirada, todo mundo sai ganhando.\" – Elegância Afiada","Unidade",[],["Noxus"],"COMUM"],"07NX003":["Manda Ver","Conceda +2|+0 a um aliado nesta rodada.\nSaquear: Conceda +2|+1 a um aliado.",""," \"Indari mexeu os pauzinhos para entrarmos sem confusão. Espero ter tempo de arrumar uma na hora de sair.\" – Samira","Feitiço",[],["Noxus"],"COMUM"],"07NX004":["Artífice Astuta","Ao me invocar, ative o efeito Saquear de todos os aliados.","","\"Em certos lugares, abrir uma loja pode ser difícil, mas, assim que viram o que eu e Lani estávamos vendendo, o dinheiro começou a entrar. Não vi nosso alvo entre os interessados, mas tem muita gente pensando em violência esta noite. Afinal, descobrir quem quer matar quem é uma boa forma de sondar o terreno.\" – Miel","Unidade",[],["Noxus"],"RARO (A)"],"07NX001":["Demolidora Destemida","Jogar: Cause 1 de dano ao Nexus inimigo ou ative o efeito Saquear de um aliado.","","\"O ramo de armas exige uma relação saudável com as informações. Conceitos, testes, reformas, alterações: tudo isso requer informação. Nada como um rápido teste de campo para criar uma amostra funcional e abrir umas crateras!\"\n– Lani","Unidade",[],["Noxus"],"RARO (A)"],"07NX005":["Capitã Indari","Ao me invocar, eu Improviso.\nSaquear: Forje outros aliados.","","\"Já trabalhei com muitos agentes. Alguns eram fáceis de lidar, outros eram desafiadores... E tem a Samira. Eu já me acostumei com o fato de que não posso controlá-la. Em vez disso, eu administro o caos, miro na direção correta e, de vez em quando, participo.\"","Unidade",["MESTRE DE ARMAS"],["Noxus"],"RARO (A)"],"07BW018":["Babs Delirante","Ao recarregar Mana, eu ganho +1|+0 para cada Mana recarregado.","","\"Jack, querido, espia aqui! Tem uma coisa que te interessa, né?\"","Unidade",[],["Águas de Sentina"],"COMUM"],"07BW021":["Corsária Ousada","Saquear: Invoque um seguidor aleatório com 1 de custo e dê Imprudente a ele.","","\"Eu ficaria longe se fosse você. Ela tem a péssima mania de transferir os próprios problemas para os outros.\" – Samira","Unidade",[],["Águas de Sentina"],"COMUM"],"07BW002":["Jack","Golpear: Crie 1 Moeda na mão.\nAo recarregar Mana, me curo em 1 para cada ponto de Mana recarregado.","Você gastou 12+ de Mana em uma rodada.","\"Precisa ter coragem sobrando ou inteligência faltando pra me desafiar, mas, seja como for, o resultado é sempre o mesmo. Meu conselho? Só se preocupe em sair com vida.\"","Unidade",[],["Águas de Sentina"],"Campeão"],"07BW040":["Nukkle","Ao me invocar, crie 1 Mako Fugaz na mão.","","\"Uma mordidinha aqui, um cortezinho acolá, tudo na tranquilidade. Um pouco de sangue na água nunca fez mal a ninguém. Bem, pelo menos não a mim.\" – Nukkle","Unidade",[],["Águas de Sentina"],"RARO (A)"],"07BW001":["Produtor Pérfido","Ao recarregar Mana, crie na mão um seguidor aleatório Fugaz que custa exatamente o seu total de Mana.","","\"Pro trabalho sujo, procure o Jack. Quer saber onde, quando, quem e quanto? É só falar comigo.\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"07BW003":["Trombadinha","Suspiro Final: Crie 1 Moeda na mão.","","\"Ei, volta aqui, traste! Isso é o dinheiro da minha batata!\" – Anjinho","Unidade",[],["Águas de Sentina"],"COMUM"],"07BW014":["Pablo Cinco-Socos","Ao me invocar, crie 1 Troca de Soco Fugaz na mão.","","\"É assim que se faz, Jack! Continua a espalhar esse seu charme de Águas de Sentina que eu te deixo pronto pra qualquer luta. Ahh, isso me lembra os velhos tempos, quando eu era tão lindo que me chamavam de Pablo-Pintura... Como não? Ah, mas chamavam! Aquela pancada na cabeça deve ter bagunçado sua memória.\" – Pablo Cinco-Socos","Unidade",[],["Águas de Sentina"],"COMUM"],"07BW013":["Anjinho","Saquear: Crie 3 Moedas na mão.","","\"Isso é o melhor que você sabe fazer? Que fofo. Minha vez.\"","Unidade",[],["Águas de Sentina"],"COMUM"],"07BW006":["Negócio Arriscado","Cause 3 de dano a uma unidade. Se ela for abatida, crie 2 Moedas na mão.","","\"Quem não arrisca não petisca. E esses dentes nasceram pra arriscar.\" – Jack","Feitiço",[],["Águas de Sentina"],"ÉPICO (A)"],"07BW026":["Corrente Farpada","Saquear: Eu custo 2 a menos.\nCompre 2 cartas no próximo Início de Rodada e dê Fugaz a elas.","","Quando você escuta o barulho, já é tarde demais pra fugir.","Feitiço",[],["Águas de Sentina"],"RARO (A)"],"07BW027":["Pai Fúria","Saquear: Recarregue 1 de Mana de Feitiço e crie na mão um feitiço aleatório com 1 de custo das suas regiões.","","As origens do Pai Fúria são tão turvas quanto uma nuvem carregada — mesmo quem pergunta nunca escuta uma resposta direta. Pelo menos, não uma que dê pra ouvir em meio ao estrondo da destruição que ele causa.","Unidade",[],["Águas de Sentina"],"RARO (A)"],"07BW008":["Troca de Soco","Um aliado e um inimigo Golpeiam um ao outro. Esse Golpe não pode deixá-los com menos de 1 de Vida.","","Às vezes os negócios são firmados com dinheiro e óleo para lamparina, e às vezes com punhos e dentes. É assim que funciona. Mas uma troca justa? Aí é bom negócio!","Feitiço",[],["Águas de Sentina"],"COMUM"],"07BW041":["Socrustáceo","Golpear: Crie 1 Moeda na mão.","","\"Hmmm, eu sei que não é lá um equipamento dos mais comuns. Mas dá uma experimentada. Aposto que você vai se acostumar.\" – Bull","Equipamento",[],["Águas de Sentina"],"RARO (A)"],"07BW004":["A Corte do Rei","Ao me invocar, compre 1 Jack.\nAo invocar um aliado, crie 1 Troca de Soco Fugaz na mão.\nQuando um aliado sobreviver a dano, dê Imprudente a ele.","","A embarcação particular do Jack o levou pelas águas de Runeterra com seu bando, de Águas de Sentina a Ionia. Como ela viaja debaixo d'água sem afundar é um mistério, mas dizem que é sob a superfície que mora o verdadeiro perigo...","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"07BW025":["Inferna","Ao ativar Saquear, compre 1 carta e dê Fugaz a ela.","","\"Ser piromaníaco no mar traz algumas vantagens. A água não deixa as chamas fugirem do controle e nunca pede uma parte dos lucros.\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"07IO020":["Tá Fora!","Retorne um aliado e crie 1 Moeda na mão, ou gaste 5 de Mana para Retornar um inimigo e criar 1 Moeda na mão.","","\"Eu só interfiro em duas situações: se o seu oponente estiver se divertindo muito quebrando a sua cara ou se você estiver se divertindo muito e eu não quiser ficar de fora!\" – Profissional da Arena","Feitiço",[],["Ionia"],"RARO (A)"],"07IO014":["Mestre Bingwen, o Analista","Jogar: Na próxima vez que você jogar uma unidade nesta rodada, invoque uma cópia Efêmera idêntica a ela.","","Bingwen, o Pássaro, já foi lutador e ganhou esse nome pela postura e agilidade semelhantes às de uma garça. Desde que se aposentou, assumiu o papel de treinador, usando seus olhos afiados e seu rigor para separar \"o joio do trigo\" em termos de talento.","Unidade",[],["Ionia"],"ÉPICO (A)"],"07IO023":["Veterano","Jogar: Retorne o inimigo Mais Forte. Se você tiver gastado 16+ de Mana nesta rodada, Retorne todos os inimigos.","","\"Não vou tirar a máscara, garota. E, a menos que você queira ficar com a cara igual a ela, não vai perguntar de novo.\"","Unidade",[],["Ionia"],"RARO (A)"],"07IO011":["Sett","Na primeira vez que eu ficaria com menos de 1 de Vida durante um ataque, me conceda Barreira.","Você gastou 40+ de Mana.","Sob efeito do rugido da multidão que lota sua arena clandestina exclusiva, Sett aproveita um raro momento de introspecção. Ele se lembra de tudo pelo que lutou e do que ainda vem pela frente. Mas de uma coisa ele tem certeza: é bom ser o Chefe.","Unidade",[],["Ionia"],"Campeão"],"07IO046":["Asaluz Real","Outros aliados Aves têm +1|+0 e Ataque Rápido.","","\"Vagando por essas selvas, descobri que os espécimes mais bonitos são sempre os predadores mais letais.\" – Anura","Unidade",["AVE"],["Ionia"],"RARO (A)"],"07IO009":["Contadora Cuidadosa","Golpe ao Nexus: Crie 1 Moeda na mão.","","Em meio a pescadores ambiciosos e picaretas interesseiros, Lise tem uma qualidade que Sett valoriza acima de tudo: é confiável. Ela nunca falta, nunca faz corpo mole e nunca deu motivos de dúvida para Sett. Isso deu a Lise carta branca e mandou um recado para os encrenqueiros: se apostar contra a casa, vai perder.","Unidade",[],["Ionia"],"RARO (A)"],"07IO019":["Mixologista Cativante","Jogar: Cure um aliado ou o seu Nexus em 3 e crie 1 Moeda na mão.","","\"Na primeira rodada, todo mundo se apresenta. Na segunda, eles ficam à vontade. Os problemas começam a aparecer na terceira, e, a partir da quarta, ninguém guarda mais nenhum segredo. Você não imagina as coisas que eu escuto!\"","Unidade",[],["Ionia"],"COMUM"],"07IO017":["Apostas na Mesa","Compre 2 e crie 2 Moedas na mão.",""," \"Eles nos dão dinheiro, e nós damos a eles uma chance. Heh... E ainda tem quem se pergunte como a casa sempre sai ganhando.\"","Feitiço",[],["Ionia"],"COMUM"],"07IO047":["Cobra Fascinante","A cada rodada, na primeira vez que você jogar outro seguidor, invoque uma cópia idêntica a ele. Se seu tabuleiro estiver cheio, em vez disso, me dê os atributos e palavras-chave dele.","","\"Acha que essas flores valem alguma coisa? E não me chame de louco, mas elas não parecem estar... dançando?\"\n– Furtivista Piltovense","Unidade",["RÉPTIL"],["Ionia"],"ÉPICO (A)"],"07IO013":["Profissional da Arena","Ao me invocar, crie 1 Moeda na mão.","","\"Alguns estão nessa por dinheiro, outros por sangue, e outros pelo clamor da multidão. Eu? Nunca consegui decidir. Preciso de tudo isso, e tenho isso tudo pra dar e vender.\"","Unidade",[],["Ionia"],"COMUM"],"07IO012":["Segurança Temporário","Ao me invocar, crie 1 Segurança Temporário Fugaz na mão e dê +1|+1 aos outros Seguranças Temporários.\nPotencializado 5: Ataque Rápido.","","''Se quiserem achar que você é idiota, deixe acharem. Deixe os inescrupulosos pensarem que estão no controle. Não há nada melhor do que ver a cara deles quando percebem que subestimaram você.'' – Sett","Unidade",[],["Ionia"],"RARO (A)"],"07IO007":["Quebra-Crânio","Atordoe 2 inimigos e crie 1 Moeda na mão.","","\"O quê? Ele disse que daria a outra face, só não disse de quem!\" – Sett","Feitiço",[],["Ionia"],"COMUM"],"07SH023":["General das Areias Caídas","Eu tenho +1|+0 para cada aliado Efêmero que você conjurou nesta partida.","","\"Embora talvez você não passe de grãos de areia para esse inimigo, eu te vejo. Sinto sua presença nas dunas. Compartilhe sua força comigo, e vamos destruir nossos inimigos juntos!\"","Unidade",[],["Shurima"],"RARO (A)"],"07SH018":["Guardião do Segredo","Ao me invocar, crie no fim do seu deck dois Campeões aleatórios de nível 2 que não estejam na sua mão, deck ou jogo.","","Ele não sabia exatamente o que tinha visto, que forma a calamidade poderia assumir, nem quando... mas conhecia este mundo e seu povo. Eles não estão prontos. Talvez nunca estejam.","Unidade",[],["Shurima"],"ÉPICO (A)"],"07SH008":["Ataque em Bando","Inicie um ataque livre com uma cópia Efêmera exata de cada aliado Felino.","","Uma caçadora solitária é assustadora por si só, mas um bando é realmente feroz.","Feitiço",[],["Shurima"],"COMUM"],"07FR008":["Filhote Gélido","Gaste 6 de Mana para me pôr em jogo como Mãe Gélida.","","Há muitos perigos em Freljord, especialmente para quem ainda não aprendeu suas frias verdades.","Unidade",["CANINO"],["Freljord"],"COMUM"],"07FR009":["Ferreira Inovadora","Ao me invocar, eu Improviso.\nA cada rodada, na primeira vez que você Forjar ou Equipar um aliado, cure seu Nexus em 1.","","\"A bolinha de pelo pode até não me ajudar a trabalhar mais rápido, mas me deixa com um sorriso no rosto. Isso já é ajuda suficiente.\" – Ferreira Inovadora","Unidade",["MESTRE DE ARMAS"],["Freljord"],"RARO (A)"],"07FR005":["Bastião de Servos","Eu não sofro dano de Habilidades nem de feitiços de aliados.","","\"Depois que começa, a avalanche não pode mais ser detida.\" – Lissandra","Unidade",[],["Freljord"],"RARO (A)"],"07SI002":["Colheita de Almas","Abata um seguidor com 3 ou menos de Poder ou gaste 3 de Mana para abater um Campeão com 3 ou menos de Poder.","","É só um sussurro no ar, difícil de ser ouvido, mas sentido com intensidade, que troca uma vida por outra.","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"07SI001":["Erradicação","Abata TODAS as unidades com 3 ou menos de Poder.","","Quem olhar para mim conhecerá o toque da obliteração, e dele nunca se libertará.","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"07SI007":["Companheiro Sepulcral","A cada rodada, compre 1 na primeira vez que um aliado morrer.","","\"Acabei de ensinar um truque novo pra ele! Quer ver?\"\n– Fantasma Travessa","Unidade",["CANINO"],["Ilhas das Sombras"],"COMUM"],"07MT003":["Filhote Cósmico","Início de Rodada: Eu e o seu Nexus nos curamos em 1.","","Como a lágrima de um alvorecer, elas cruzam os céus com seu brilho calmo e radiante, curando feridas e consertando o que está quebrado.","Unidade",[],["Targon"],"RARO (A)"],"07MT001":["Estrela Cadente","Cause 4 de dano a um inimigo que já tiver atacado nesta rodada ou que esteja Atordoado.","","As estrelas observam nossas ações, boas ou ruins. Os justos são exaltados, e os corruptos são julgados.","Feitiço",[],["Targon"],"COMUM"],"07MT007":["Estudioso Imolado","Suspiro Final: Crie na mão cópias dos 3 primeiros feitiços que jogou em mim.","","\"A Camphor já levou muita coisa de muita gente. Quando chegar a sua hora de morrer, morra do seu jeito. Não dê essa satisfação a ela.\" – Pantheon","Unidade",[],["Targon"],"ÉPICO (A)"],"07BC005":["Fada das Lâminas Esculpida","","","\"Olha só, essa é novidade.\" – Fada das Lâminas","Unidade",["FADA"],["Bandópolis"],"COMUM"],"07BC009":["Torta na Cara","Cause 1 de dano a uma unidade. Crie 1 Docinho Destrutivo na mão.","","Prepare-se.","Feitiço",[],["Bandópolis"],"RARO (A)"],"07BC015":["Condensar","Selecione um seguidor. Crie na mão uma cópia de custo 1 com os atributos 1|1.","","\"Hmm... Acho que 'menor' nem sempre quer dizer 'mais fofinho'!\" – Lulu","Feitiço",[],["Bandópolis"],"RARO (A)"],"07DE002":["Mandado de Busca","Um aliado com 4+ de Poder Captura uma unidade ou um aliado Captura um Monumento.","","\"Fique em silêncio e não se mova. Qualquer resistência seria tolice.\" – Inspetora dos Caçadores de Magos","Feitiço",[],["Demacia"],"RARO (A)"],"07DE005":["Em Formação!","Conceda +2|+2 a um aliado nesta rodada.","","\"Aguentem firme! Vocês estão debilitados, não destruídos!\"\n– Vanguarda Destemida","Feitiço",[],["Demacia"],"COMUM"],"07DE008":["Altar à União","Ao me invocar, compre uma unidade.\nAo invocar um aliado, aumente seus atributos até atingirem o valor de custo.","","A primeira vez que viu o Altar, Cithria ficou sem palavras. Por um tempo, ela ficou imóvel e maravilhada com a magnanimidade daqueles nobres heróis. Seria ela ousada o suficiente para estar ao lado deles?","Monumento",[],["Demacia"],"RARO (A)"],"07PZ019":["Lagartuagem Quimtec","Eu tenho +1|+0 para cada aliado com 1 de custo que você tiver invocado nesta partida.","","\"Eu preciso desenhar um MONTÃO de perna no cavalo, Senhor Lagarto, porque a gente tem que chegar BEEEM RAPIDINHO no castelo. Ah, não! Ele ficou meio... torto. E um tiquinho verde.\" – Ingvar, a Jovem","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"07PZ021":["Anura e Froop","Aliados com um subtipo diferente dos outros aliados em jogo custam 1 a menos.","","\"Não vou te machucar, colega! Vim até essa selva pela ciência, não pela destruição.\"","Unidade",["RÉPTIL"],["Piltover e Zaun"],"ÉPICO (A)"],"07PZ022":["Corrente Divina","Cause 1 de dano a um inimigo ou ao Nexus inimigo e 1 de dano a outro inimigo.","","A maioria dos piltovenses não estão nem aí para os padrões do vento. No entanto, para muitos zaunitas, até mesmo uma brisa errante tem cheiro de salvação.","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"COMUM"],"07PZ013":["Monumento do Sumidouro","Se seu Nexus sofreria dano que não fosse de Cogumelo Venenoso, seu oponente Planta 5 Cogumelos Venenosos no seu deck para cada ponto de dano.","","Nas profundezas sob as ruas de Zaun, você é o que você come.","Monumento",[],["Piltover e Zaun"],"ÉPICO (A)"],"07PZ015":["Bugigangação Épica","Para me pôr em jogo, gaste todo o seu Mana. Invoque 1 Bugiganga Fujona e aumente os atributos dela até atingir a quantia gasta.","","\"A principal responsabilidade de um cientista é controlar as variáveis. As consequências dos acidentes, em um campo de estudo como o nosso... Ah, estremeço só de pensar nisso!\"\n– Professor Heimerdinger","Feitiço",[],["Piltover e Zaun"],"COMUM"],"07NX028":["Capitão Kalrix","Golpe ao Nexus: Cause dano ao Nexus inimigo equivalente a metade da Vida dele. O dano causado é arredondado para cima.","","O objetivo do império de Noxus é, acima de tudo, a expansão. Madeira, pedra ou aço — nada pode parar o avanço de um aríete noxiano.","Unidade",[],["Noxus"],"ÉPICO (A)"],"07NX034":["Salão de Banquetes Carmesim","Aliados custam 1 a menos. Ao jogar um aliado, cause 2 de dano.","","''Venham, meus amigos, sentem-se! A companhia é boa, e as bebidas não têm fim. Mal posso esperar para que vejam o que temos para o jantar.'' – Vladimir","Monumento",[],["Noxus"],"ÉPICO (A)"],"07NX032":["Tomo Corvino","Quando meu portador jogar uma Habilidade, copie-a.","","O Conservatório Floricorvus era especialmente conhecido por sua coleção de textos, muitos dos quais acabaram se tornando combustível para o fogo estrondoso de uma aluna notoriamente difícil...","Equipamento",[],["Noxus"],"RARO (A)"],"07NX033":["Courósseo de Três Caudas","Ao me invocar, eu ganho +1|+1 para cada subtipo diferente que outros aliados tenham.","","\"Cuidado, seus imbecis! Noxianos só compram feras de combate em perfeitas condições. Qualquer arranhão vai sair direto do seu salário!\" – Magnata Magnânimo","Unidade",["FELINO"],["Noxus"],"COMUM"],"07RU015":["O Rei Poro","Origem: O Decreto do Rei Poro.\nA cada rodada, ao invocar outro Poro pela primeira vez, crie 1 Poritos na mão.","Você invocou 6+ Poros novos. Quando eu subir de nível, crie um Porito Especial aleatório na mão.","Ingvar reconhece potencial quando vê. Mesmo com um visual um pouco rústico, esse amado companheiro poderia facilmente ser o governante de um gazilhão de trilhões de Poros... com um pouco de imaginação. ","Unidade",["PORO"],["Runeterra"],"Campeão"],"07RU012":["Neeko","Origem: Amigos da Selva Multiformes!\nJogar: Você pode me Disfarçar como 1 de 3 seguidores com 2 de custo da minha Origem.","Atacar: Você atacou com aliados que têm 6+ subtipos diferentes.","Neeko pode assumir muitas formas, mas seu coração nunca muda, sempre levando-a de volta para sua família e sua floresta.","Unidade",["METAMORFO"],["Runeterra"],"Campeão"],"07BW043":["Invocação das Marés","Cause 1 de dano a uma unidade. Faça Surgir 1 Tentáculo para cada ponto de dano causado.","","Somente os mais eruditos são capazes de manipular os elementos.","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"RARO (A)"],"07BW035":["O Covil do Vigarista","Suas cartas na mão têm Fugaz.\nAo jogar uma carta, compre 1.","","\"Eu acho que você deve conhecer sua mão e mantê-la em segredo... ou se preparar para perder tudo.\" – Twisted Fate","Monumento",[],["Águas de Sentina"],"ÉPICO (A)"],"07BW042":["Caçador do Convés","Jogar: Manifeste um seguidor que tenha um subtipo diferente dos aliados em jogo.","","\"Mantemos esse carinha desgrenhado por perto por um motivo: não temos problemas com ratos do cais há anos!\"\n– Ajudante do Apavorador","Unidade",["FELINO"],["Águas de Sentina"],"COMUM"],"07BW039":["Grinzo, o Príncipe Dragão","A cada rodada, na primeira vez que invocar um aliado com 1 de custo, recarregue 1 de Mana de Feitiço.","","\"Senhor Lagarto, o que faz aqui? Você também gosta de Poros?!\" – Ingvar, a Jovem","Unidade",["DRAGÃO"],["Águas de Sentina"],"RARO (A)"],"07BW033":["Canto da Sereia","Invoque uma Carcaça aleatória.\nDê +1|+1 a aliados com 1 de custo globalmente.","","Em alto mar, alguns marinheiros de Águas de Sentina tampam os ouvidos com algodão nas noites mais tranquilas. Eles sabem muito bem que a música sob as ondas não oferece nada além de um túmulo aquático.","Feitiço",[],["Águas de Sentina"],"COMUM"],"07IO041":["Brisa Rejuvenescedora","Cure seu Nexus em 3 e compre 2 feitiços.","","\"O vento é o único aliado do errante.\" – Yasuo","Feitiço",["ELEMENTAL"],["Ionia"],"COMUM"],"07IO043":["Oráculo Que Tudo Vê","Jogar: Escolha 1 de 3 feitiços Rápidos ou Lentos da mão ou do deck do inimigo. Crie 1 Entalhes Proféticos para o feitiço.","","O olho livre do mundo material tudo vê. Por mais que o oráculo pareça cego, quem o confunde com um alvo fácil é repreendido de forma célere e sem misericórdia.","Unidade",[],["Ionia"],"RARO (A)"],"07IO049":["Airis","Golpe ao Nexus: Invoque uma Carcaça aleatória.","","''Xiu, estamos quase chegando. Você disse que queria conhecer minha amiga, lembra? Confie em mim, ela vai te adorar.''","Unidade",[],["Ionia"],"RARO (A)"],"07SH038":["Filhote Pakaa","Emboscada 1\nGolpe ao Nexus: Invoque 1 Protetora Pakaa.","","A fofura é uma aparência, mas a ferocidade é um instinto. Com tempo e aprendizado, até mesmo o menor dos pakiti se torna forte e selvagem.","Unidade",["FELINO"],["Shurima"],"COMUM"],"07SH041":["Desbravando a Selva","Manifeste uma carta com Emboscada.","","O reconhecimento da selva é a tarefa menos desejada de todas por uma única razão: ela é cheia de surpresas.","Feitiço",[],["Shurima"],"RARO (A)"],"07SH004":["Espreitar","Conceda +2|+0 a um aliado nesta rodada. Se for 1 Sombra no Arbusto, conceda +2|+2.","","\"Caminhe suavemente, pakiti. Ataque com precisão.\"\n– Nidalee","Feitiço",[],["Shurima"],"COMUM"],"07SH013":["Nidalee","Emboscada 2","Vi você invocar ou transformar 4 outros aliados.","\"Eu sempre vou proteger você, garota lagarto. Faremos esses ladrões pagarem. Juntas.\" – Nidalee","Unidade",["FELINO"],["Shurima"],"Campeão"],"07SH009":["Vingador Vastayês","Emboscada 3\nQuando eu me transformar de Emboscada do Vingador Vastayês, impeça todos os feitiços Rápidos, feitiços Lentos e Habilidades dos inimigos.","","\"Não temam, pequeninos. Eu os protegerei... e minha dívida com Nidalee será paga.\"","Unidade",[],["Shurima"],"COMUM"],"07SH039":["Soldado Adaptável","Emboscada 0\nAo me invocar ou transformar, dê Vulnerável ao inimigo Mais Fraco.","","\"Essa belezinha aqui pode transformar até um novato em um profissional em escalar árvores e saltar rochas. Custou uma fortuna, mas tenho certeza de que posso pagar esses empréstimos com a pele de uma ou duas feras raras...\"","Unidade",[],["Shurima"],"RARO (A)"],"07SH044":["Aurora Alucinati","Emboscada 4\nQuando eu me transformar, invoque 1 Aurora Alucinati.","","\"Como eu gostaria de ver uma! A maioria dos expedicionários acredita que Auroras Alucinati sejam um mito, mas um jovem jura que não. Ele me disse que a ave tem cores vivas e uma envergadura tão larga quanto a altura de um homem. Olhar nos olhos dela, ele me confidenciou uma noite, é entender que você é a presa.\" – Do diário de campo de Anura, dia 21","Unidade",["AVE"],["Shurima"],"RARO (A)"],"07SH003":["Furtivista de Dirigível","Emboscada 3\nQuando eu me transformar de Emboscada do Furtivista de Dirigível, na próxima vez que eu bloquear ou sofrer um bloqueio nesta rodada, Capture meu inimigo.","","\"Rá! Tentem me pegar agora, suas feras tolas. Nem a gravidade pode derrotar a espécie superior!\"","Unidade",[],["Shurima"],"ÉPICO (A)"],"07SH011":["Arapuca","Ao me invocar ou na primeira vez que um aliado se transformar a cada rodada, dê Vulnerável ao inimigo Mais Fraco.","","\"Sangue ao vento.\" – Nidalee","Monumento",[],["Shurima"],"COMUM"],"07SH046":["Vale da Imitação","Ao jogar um seguidor, me transforme em uma cópia idêntica a ele nesta rodada.","","''E essa é minha palada favolita e a MAIS BO-NIII-TA do passeio. Tanta gente gostou do meu passeio aquele dia que constluílam um LASQUINHA GLANDÃO E PODELOSO, e ele vai fazê palte do passeio pla semple. Fala \"OI, LASQUINHAZÃO'', pessoal! O Lasquinhazão ama TODO mundo, plincipalmente quem veio no passeio dele.''\n– Aventuras com Lasquinha, parte 6","Monumento",[],["Shurima"],"COMUM"],"07SH043":["Parofante Grandioso","Emboscada 5","","Como seus residentes mais antigos, alguns dizem que parofantes guardam a memória e o coração da própria selva. Embora normalmente sejam criaturas gentis, eles não hesitarão em defender seu lar contra qualquer ameaça, grande ou pequena. ","Unidade",[],["Shurima"],"ÉPICO (A)"],"07SH040":["Porcouriço","Eu ganho +2|+1 na primeira vez que um aliado se transformar.","","\"Pequenos mamíferos onívoros cobertos por espinhos semelhantes a cerdas, que podem ser liberados em alta velocidade quando perturbados. A cauda é farpada e ágil, provavelmente usada como arma defensiva. De acordo com expedicionários experientes, as criaturas são notoriamente rabugentas e difíceis de lidar...\" – Do diário de campo de Anura, dia 3","Unidade",[],["Shurima"],"RARO (A)"],"07SH005":["Magnata Magnânimo","Jogar: Manifeste uma carta com Emboscada.\nQuando um aliado se transformar, dobre o Poder e a Vida dele.","","\"Vocês perderam tudo para O QUÊ?! Uma cientista com uma aberração réptil? E o que estão esperando, seus paspalhos? Andem logo e tragam meu dinheiro de volta!\"","Unidade",[],["Shurima"],"RARO (A)"],"07FR011":["Templo ao Gelo Verdadeiro","Ao invocar um aliado, aumente a Vida dele até um valor equivalente ao Poder dele.","","Embora o significado deste templo tenha se perdido no tempo, seu guardião de pedra ainda resiste, inexorável sob o peso de incontáveis avalanches. Rodeado de gelo, ele parece imbuído de uma luz estranhamente sedutora...","Monumento",[],["Freljord"],"ÉPICO (A)"],"07FR010":["Garrafiada Gélida","Saquear: Os atributos de um aliado ficam iguais aos meus.","","Embora a garrafiada gélida cace principalmente pequenos mamíferos, as garras dessa fera freljordana são suficientes para transformar quase qualquer coisa em uma refeição.","Unidade",["AVE"],["Freljord"],"COMUM"],"07FR015":["Ingvar, a Jovem","Jogar: Escolha um aliado. Dê +1|+1 a ele e a todos os outros aliados com o mesmo subtipo ou Manifeste um seguidor que tenha o mesmo subtipo.","","Autonomeada supervisora de Poros e exploradora de Freljord, Ingvar tem certeza de que a aventura aguarda por ela em algum lugar... E ela vai encontrá-la. ","Unidade",[],["Freljord"],"ÉPICO (A)"],"07FR017":["Trovoado Cristalino","Jogar: Cause 2 de dano a TODAS as outras unidades.","","A violência do trovoado cristalino é indiscriminada e imediata, sendo capaz de mudar o rumo de uma batalha em instantes. Muitos veem o pássaro como o primeiro presságio de uma tempestade grande e terrível que redefinirá a estrutura da terra em sua essência.","Unidade",["AVE"],["Freljord"],"RARO (A)"],"07FR016":["Sauriano Glacial","Ao me invocar, dê +1|+1 às 3 unidades no topo do seu deck. Se um aliado tiver um subtipo diferente do meu, compre 1 delas.","","Com um coração enorme escondido por baixo de uma carapaça grossa, esses corcéis são vitais para abrir caminho de forma confiável pelas montanhas congeladas.","Unidade",["RÉPTIL"],["Freljord"],"RARO (A)"],"07SI010":["Aracnídeo Necrótico","Ao me invocar, invoque 2 Crias Necróticas.\nQuando outro aliado morrer, Drene 1 do Nexus inimigo.","","Encontradas apenas nas regiões mais tenebrosas das Ilhas das Sombras, essas aranhas secretam um necroveneno letal que anestesia a pele enquanto apodrece a carne.","Unidade",["ARANHA"],["Ilhas das Sombras"],"ÉPICO (A)"],"07SI012":["Caranguejeira Fiandeira","Jogar: Se um aliado tiver um subtipo diferente do meu, conceda -2|-0 a um inimigo nesta rodada.","","Caranguejeiras fiandeiras tomam muito cuidado ao criar seus ninhos. Elas são especialmente afetuosas com suas crias aracnídeas... mas igualmente cruéis quando se trata de ameaças em potencial.","Unidade",["ARANHA"],["Ilhas das Sombras"],"COMUM"],"07SI013":["Espectreva Proliferante","Suspiro Final: Crie uma cópia idêntica do seu exemplar Mais Forte de Espectreva Proliferante no deck e depois dobre os atributos de Espectrevas Proliferantes no deck.","","''A Névoa me ensinou muitas coisas. De todas as lições, a mais importante foi saber quando correr.'' – Sentinela Ixtalense","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"07SI004":["Tesouras Sagradas","Atacar: Quando outro aliado ganha Poder Sagrado, meu portador também ganha.","","\"Com uma boa tesoura e linha de qualidade, dá pra consertar quase tudo!\" – Gwen","Equipamento",[],["Ilhas das Sombras"],"RARO (A)"],"07MT009":["Era dos Dragões","Dentre as 9 cartas no topo do seu deck, compre todos os Dragões e reduza o custo deles a 0 nesta rodada. Depois, embaralhe o resto no seu deck.","","\"Conhecer um dragão é dominar a si mesmo. Conhecer muitos é dominar o mundo.\" – Adorante de Dragões Ottrani","Feitiço",[],["Targon"],"RARO (A)"],"07MT013":["Chamado Cósmico","Evoque um Celestial que custe 7 ou mais ou pague 8 para reduzir o custo dos seus Celestiais pela metade globalmente. O valor é arredondado para cima.","","O Árbitro observa incessantemente a chegada das bênçãos do céu.","Feitiço",[],["Targon"],"COMUM"],"07MT006":["Amantes Desafortunados","Jogar: Retorne um aliado e dê a ele meus atributos.","","\"Poucas paisagens são mais esplêndidas que o encontro entre o sol e a lua.\" – Diana","Unidade",[],["Targon"],"COMUM"],"07BC020":["Senhor Catatreco","Quando uma ou mais das suas armadilhas ou dádivas forem ativadas, Plante 2 delas no deck do jogador.","","Ninguém sabe quando o Senhor Catatreco começou sua coleção nem de onde veio. Ele parece ser amigável o bastante… ainda que deixe um rastro preocupante de riscos de tropeção aonde quer que vá.","Unidade",[],["Bandópolis"],"RARO (A)"],"07BC016":["Chave de Retornância","Ao me descartar, me Equipe em um aliado desequipado aleatório.","","\"Não vou mentir: estou sempre perdendo minhas ferramentas. Essa aqui, entretanto, sempre aparece de volta quando eu preciso!\" – Inspetor de Segurança","Equipamento",[],["Bandópolis"],"COMUM"],"07BC018":["Estudioso do Portal","Ao me invocar, Plante 1 Portal Misterioso entre as 4 cartas no topo do seu deck.\nAo invocar um aliado criado, dê Impacto a ele.","","No decorrer de qualquer pesquisa sempre há surpresas... Felizmente, dessa vez, é uma boa. ","Unidade",["FADA"],["Bandópolis"],"ÉPICO (A)"],"07BC011":["Felpudinhos Ferozes","Ao me invocar, dê +1|+1 e Impacto aos outros aliados que têm subtipos.","","Para o desprazer dessa trupe de furtivistas piltovenses, eles só parecem inofensivos.","Unidade",["AVE"],["Bandópolis"],"COMUM"],"07DE014":["Sargento Fiscalizador","Jogar: Escolha uma unidade que custe 3 ou menos entre as 5 cartas no topo do seu deck. Invoque-a e coloque o resto no seu deck.","","O sargento de recrutamento demaciano carrega uma grande responsabilidade. Seus recrutas irão ocupar muitos cargos diferentes, todos unidos no dever e amor por Demacia.","Unidade",["ELITE"],["Demacia"],"ÉPICO (A)"],"07DE015":["Falcoleão Cristado","Jogar: Se um aliado tiver um subtipo diferente do meu, Manifeste um feitiço demaciano.","","\"Os registros confirmam o primeiro avistamento do falcoleão em quase cinquenta anos. Linda crista azul, olhos inteligentes. O corpo é blindado, mas os ossos são leves o suficiente para escalar árvores e até planar com alcance limitado. Estruturas de asas quase reminiscentes de rapinas demacianas. Retornarei com mais detalhes.\" – Do diário de campo de Anura, dia 12","Unidade",["AVE"],["Demacia"],"RARO (A)"],"07DE011":["Caçador de Magos Novato","Feitiços que custam menos de 3 têm 3 de custo.","","\"Silêncio! Isso não é um mero jogo, como ousas alegar, mas o encanto de uma intervenção arcana traiçoeira. Vou desmascarar tua natureza mágica e trapaceira, canalha! Mesmo que precise queimar este lugar inteiro!\"","Unidade",[],["Demacia"],"COMUM"],"07DE016":["Balen, o Benevolente","Atacar: Dê +0|+1 a outros aliados Formidáveis globalmente.","","O grande porte de Balen, companheiro de longa data da família Durand, esconde sua precisão gentil. Embora tenha começado como assistente, Balen é muito talentoso e excepcionalmente criativo em seu ofício. Os Durand têm orgulho de chamá-lo de amigo.","Unidade",[],["Demacia"],"ÉPICO (A)"],"08SI042":["Mordekaiser","Jogar: Abata até 2 aliados.\nAo Eliminar outro aliado, ressuscite-o.","15+ aliados morreram. Aliados com 5+ de Poder contam duas vezes.","Preso à sua armadura guardada no coração do Bastião Imortal, Mordekaiser forjou o próprio trono no Reino Cinzento. Para cada um que busca destruí-lo, muitos outros servirão a ele tanto na vida quanto na morte.","Unidade",[],["Ilhas das Sombras","Noxus"],"Campeão"],"08SI040":["Erastin, o Desonrado","Ao me invocar, eu ganho Imortal.\nAtacar: Conceda -1|-0 aos inimigos nesta rodada.","","Os dragões de Camavor já foram magníficos e respeitados, mas nem mesmo eles estavam a salvo da corrupção da Ruína que tudo consome. Erastin não é exceção: sua majestade, há muito perdida, agora está distorcida na pitoresca aparência de imortal.","Unidade",["DRAGÃO"],["Ilhas das Sombras"],"ÉPICO (A)"],"08SI007":["Legião dos Desgarrados","Jogar: Dê Imortal a um aliado na mão.","","Não importa que forma as almas tinham antes de serem aprisionadas no Reino Cinzento. Lá, a individualidade tem pouco valor. Anônima e destemida, a Legião, com sua uniformidade, é ainda mais útil ao Revenã de Ferro.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"08SI003":["Espectros Agrilhoados","Suspiro Final: Na próxima vez que você ressuscitar um aliado, crie uma cópia minha na mão.","","\"Faz muito tempo que fomos acorrentados. Em breve, você também entenderá nosso sofrimento, e todos nós sofreremos por toda a eternidade, até que nos seja concedido o esquecimento pela mão do Mestre...\"","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"08SI021":["Sinuoso Solitário","Quando outro aliado morrer ou usar Suspiro Final: Plante 4 Sinos no seu deck.","","Não ligue para esse barulho sinistro, é só o velho Sinuoso fazendo a ronda. Ele sempre fica feliz em ver os recém-chegados... mas o sentimento certamente não é mútuo.","Unidade",[],["Ilhas das Sombras"],"COMUM"],"08SI030":["Sepultura Marinha","Oblitere 6 cartas no fim do deck inimigo.","","Para os monstros que habitam as profundezas de Runeterra, um navio é só um lanchinho.","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"08SI037":["Caniferrus Espectral","Para me pôr em jogo, abata um aliado.\nAo me invocar, invoque 1 Ocasoquilador das Mil Garras.","","Essas feras nunca se esquecem do cheiro de alguém que tentou fugir... e, quando os canis cercam a presa, um ocasoquilador nunca está longe.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"08SI041":["Aperto Mortal","Abata um aliado para causar 5 de dano a uma unidade.","","\"A escuridão é o destino de todos, exceto o meu.\"\n– Mordekaiser","Feitiço",[],["Ilhas das Sombras"],"COMUM"],"08SI036":["Limiar Cinzento","Jogar: Amaldiçoe um inimigo com Terror.\nAo invocar um aliado Titânico, me destrua para comprar 2.","","\"Estas almas, nós oferecemos a ti. Este caminho, nós pavimentamos com ossos diante de ti. Estes reinos, nós rasgamos ao meio para abrir caminho para o teu eterno exército de ferro.\" – Cultista do Aperto Mortal","Monumento",[],["Ilhas das Sombras"],"RARO (A)"],"08SI004":["Reino da Morte","Um aliado inicia um ataque livre Desafiando o inimigo Mais Forte.\nAbata TODAS as outras unidades.","","\"A morte é o meu domínio.\" – Mordekaiser","Feitiço",[],["Ilhas das Sombras"],"ÉPICO (A)"],"08SI026":["Cultista do Aperto Mortal","Ao me invocar ou ao invocar um aliado Titânico, Amaldiçoe o inimigo Mais Forte com Terror.","","Aos olhos de seus seguidores, o Revenã de Ferro é a única esperança para os que buscam o oblívio. Paz pela dominação é um conceito que os sectários aceitam de braços abertos.","Unidade",[],["Ilhas das Sombras"],"RARO (A)"],"08SI018":["Espectrógrafo","Jogar: Escolha um feitiço de Explorador para criar na mão.","","\"O terreno é inescrutável. A visibilidade, próxima de zero. Eu encontrei inimigos em cada curva... mas, estranhamente, aliados inesperados também.\" – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Ilhas das Sombras","Unidade",[],["Ilhas das Sombras","Targon"],"RARO (A)"],"08SI015":["Amálgama de Ritos Vis","Para me pôr em jogo, abata um aliado.\nSuspiro Final: Cure seu Nexus em 2.","","Feras de guerra têm valor para qualquer exército. No Reino Cinzento, elas são fusões de almas torturadas, cada uma mais sedenta e violenta em sua não senciência. ","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"08BW008":["Nilah","Atacar: Crie 1 Turbilhão entre as 6 cartas no topo do seu deck.","Você comprou 15+ cartas.","Ao norte, um novo desafiante aguarda Nilah e seu grupo de caçadores de monstros: um ser chamado Volibear, que ameaça destruir a mesma Freljord que um dia o adorou. Para Nilah, a chance de testar suas habilidades contra um monstro que outros chamam de ''deus'' é uma oportunidade única na vida. Sem falar nas monstruosidades menores que ela terá que adicionar à lista de conquistas pelo caminho. ","Unidade",[],["Águas de Sentina"],"Campeão"],"08BW032":["Alegria Eterna","Conceda +1|+0 aos aliados nesta rodada e cure em 2 aliados que sofreram dano.","","\"Alegria, transbordante e sem fim!\" – Nilah","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"COMUM"],"08BW038":["Dançarina dos Chakrans","Jogar: Cause 1 de dano a qualquer coisa.\nSuas Habilidades Drenam.","","Ela se move em uma dança de água e lâminas, extraindo aço do turbilhão de espuma e dos respingos. Ela não precisa ver para sentir o fluxo de suas armas; elas são movidas pelas águas, e às águas sempre devem retornar.","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"08BW015":["O Dançarino das Marés","Ao me invocar, compre 1 Nilah.\nA cada rodada, ao jogar sua terceira carta, conceda a outros aliados +2|+0 e Imprudente nesta rodada.\nSe eu fosse receber Fugaz, me revele em vez disso.","","''Ouvi dizer que aquele navio com formato estranho é o mais rápido que Águas de Sentina já viu. Bem ágil, também. A capitã é bem peculiar, mas parece que ela sabe o que está fazendo. Talvez a gente aprenda uma coisa ou outra.''\n– Barman de Águas de Sentina","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"08BW002":["Lâmina Sem Forma","Cause 2 de dano a uma unidade. O dano não pode deixar a Vida dela abaixo de 1.","","''Monstros que se acham deuses têm uma grande queda pela frente, não importa onde seja.'' – Nilah","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"COMUM"],"08BW025":["Mestre Vigia","Depois de comprar 3+ cartas em uma rodada nesta partida, eu ganho +1|+1 e Imprudente.","","''Ei, cara, que alvoroço é esse? Relaxa! Não há nada na água que não possamos enfrentar!'' – Devoto do Desafio","Unidade",[],["Águas de Sentina"],"COMUM"],"08BW026":["Devoto do Desafio","Ao me invocar, Eleve sua mão. Eu ganho +1|+1 para cada carta Elevada. Compre 2.","","''Ah, você tá mesmo se esforçando? Sinto que preciso me segurar... Odeio isso!''","Unidade",[],["Águas de Sentina"],"RARO (A)"],"08BW028":["Polvaventureiro","Jogar: Escolha um feitiço de Explorador para criar na mão.","","\"Exemplar peculiar. Bastante azul. Olhos bem grandes. Grandes demais, até. Levarei para estudá-lo melhor.''\n– Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Piltover","Unidade",[],["Águas de Sentina","Piltover e Zaun"],"RARO (A)"],"08BW009":["Timoneiro Experiente","Jogar: Manifeste dois feitiços Elementais diferentes que você tiver jogado nesta partida. Eles custam 0 nesta rodada.","","''A mente é um rio. Ao longo do tempo, a dedicação de seu fluxo esculpe a face das montanhas e, pouco a pouco, pode crescer cada vez mais e tocar novas margens.''","Unidade",[],["Águas de Sentina"],"RARO (A)"],"08BW010":["Enxurrada","Pelo resto da partida, todos os seus feitiços e Habilidades Elementais causam 1 de dano adicional.","","''Nas mãos dos sábios, a água dá forma a tudo.'' – Devoto da Sabedoria","Feitiço",["ELEMENTAL"],["Águas de Sentina"],"ÉPICO (A)"],"08BW031":["Sefirsa, Flagelo das Profundezas","Ao gastar Mana para jogar outra unidade, crie na mão uma carta aleatória de mesmo custo. Ela é Fugaz e custa 0.","","Apesar do apetite mesmo pelas feras marinhas mais estranhas, alguns monstros são demais até para os capitães mais experientes de Águas de Sentina. Eles falam de Sefirsa aos sussurros, como uma luz hipnótica que se move nas profundezas à sombra das ondas; um monstro empoleirado sobre uma quantidade enorme de navios naufragados e homens afogados.","Unidade",["MONSTRO MARINHO","DRAGÃO"],["Águas de Sentina"],"ÉPICO (A)"],"08BW037":["Crupiê Honesto","Ao jogar uma carta de custo igual ao meu Poder, eu ganho +1|+1.","","\"Viu, que tal apostar mais alto, hein? Sabe como é, quem não arrisca não petisca. Essa mesa promete, pode confiar. E a casa é bem generosa neste belíssimo estabelecimento. Juro pela língua da mamãe.\"","Unidade",[],["Águas de Sentina"],"RARO (A)"],"08BW036":["Pináculo Coralino Marai","Ao gastar Mana para jogar uma unidade, recarregue 1 de Mana de Feitiço.","","\"Faz tempo que o coral é nosso abrigo e aliado. Ele cuida da gente, e nós cuidamos dele, assim ninguém sucumbe à escuridão da Treva.\" – Grande Mãe Marai","Monumento",[],["Águas de Sentina"],"COMUM"],"08BW023":["Vikrash, o Exuberante","Ao me invocar, crie 1 Turbilhão entre as 6 cartas no topo do seu deck.","","''Vejam, meus amigos, como todo o mundo se move conosco! As ondas dançam sob o casco, o vento sopra pelas velas, e os pássaros viajam pela brisa. Alegrem-se e juntem-se a mim nesse grande chamado!''","Unidade",[],["Águas de Sentina"],"ÉPICO (A)"],"08PZ007":["Bando de Andorinhas","Invoque 1 Andorinha do Vendaval e dê +1|+1 para cada feitiço ou Habilidade Elemental que você tiver jogado na partida.\nCompre 1.","","Quando as andorinhas do vendaval se reúnem, uma tempestade se avizinha.","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"RARO (A)"],"08PZ031":["Óculos Suspeitos","Escolha um seguidor aliado. Transforme meu portador em uma cópia idêntica dele enquanto eu estiver equipada.","","Não pergunte como isso funciona.","Equipamento",[],["Piltover e Zaun"],"RARO (A)"],"08PZ025":["Protótipo de Porobot","Suspiro Final: Dê ''Ao me jogar, invoque 1 Protótipo de Porobot'' a um feitiço aleatório com 6+ de custo na sua mão.","","''É só um protótipo'', gritou o aprendiz enquanto as chamas consumiam o laboratório. ''Eu não programei ele para engolir todos os equipamentos que tiver pela frente! Eu nem sei pra ONDE aquele metal todo tá indo!''","Unidade",["PORO"],["Piltover e Zaun"],"RARO (A)"],"08PZ005":["Olho da Tempestade","Conceda +2|+0 a um aliado nesta rodada.\nCompre 2.","","\"Fique em paz! A tempestade pode rugir ao seu redor, mas não vai te machucar.\" – Janna","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"COMUM"],"08PZ019":["Furacão Divino","Eu custo 2 a menos se você tiver comprado 3+ cartas nesta rodada.\nCause 3 de dano a uma unidade e 2 de dano ao Nexus inimigo.","","\"A tempestade está sob meu comando.\" – Janna","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"RARO (A)"],"08PZ028":["Dragão Quimtec","Ao jogar um feitiço, compre 1. Ao comprar enquanto estiver com a mão cheia, cause 1 de dano ao Nexus inimigo.","","Zaun exige adaptação, e o Dragão Quimtec não é exceção. Uma fera iluminada pelo brilho verde doentio dos aprimoramentos enquanto se agarra à parte baixa da cidade. As sombras gêmeas das asas arruinadas do dragão pairam sobre passagens escuras e anunciam uma fúria nascida da angústia de sua própria corrupção.","Unidade",["DRAGÃO"],["Piltover e Zaun"],"ÉPICO (A)"],"08PZ001":["Janna","Jogar: Eleve 2 para comprar 2 no próximo Início de Rodada.\nA cada rodada, nas 3 primeiras vezes que você comprar uma carta, reduza o custo dela em 1.","Eu vi você jogar 8 cartas com custo reduzido.","\"Zaun é mais cara a Janna do que qualquer outro lugar. Afinal, foi ela quem salvou as pobres almas que Piltover deixou à própria sorte. Sim... Se houver respostas, é aqui que eu as encontrarei.\" – Marinheiro Ventonato","Unidade",[],["Piltover e Zaun"],"Campeão"],"08PZ026":["Chamado do Vendaval","Invoque 1 Andorinha do Vendaval.","","\"Todos os filhos do vento respondem ao meu chamado.\"\n– Janna","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"COMUM"],"08PZ006":["Iascylla, Acrostólio das Profundezas","Ao jogar uma Habilidade ou feitiço Elemental, copie-o com os mesmos alvos.","","\"Venha, Iascylla! Você é velha mesmo se Ashlesh sabe seu nome. Mas, velha ou jovem, bonita ou feia, não importa. Não há honra maior para nenhum monstro do que cair sob minha lâmina em mar aberto.\" – Nilah","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"08PZ018":["Marinheiro Ventonato","Eu custo 2 a menos se você tiver comprado 3+ cartas nesta rodada.","","\"Sim, eu tinha o que queria. Mas tudo que conquistei foi roubando, e roubar deixa um homem vazio. A primeira coisa que encontrei para seguir foi o vento... então agora estou aqui, esperando que ela me leve a um caminho melhor.\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"08PZ008":["Maryam, a Protetora do Templo","Jogar: Eleve 1 para comprar 1 ou recarregar seu Mana de Feitiço.","","Convencida de que foi salva pelo espírito do vento quando jovem, Maryam pregou as virtudes de Janna de sua terra natal, Shurima, até Zaun. Agora ela é matriarca do templo de Zaun e se dedica a transmitir a bondade de Janna aos jovens e oprimidos.","Unidade",[],["Piltover e Zaun"],"ÉPICO (A)"],"08PZ009":["Templo Afundado","Fim de Rodada: Eleve sua mão.\nInício de Rodada: Compre a mesma quantidade de cartas mais 1.","","Muito se perdeu no colapso desastroso que acabou separando Zaun de Piltover. Janna pode ter perdido seu templo para as ondas, mas salvou as pessoas que lá ofereciam sua adoração.","Monumento",[],["Piltover e Zaun"],"ÉPICO (A)"],"08PZ002":["Ventania Uivante","Cause 2 de dano a uma unidade.\nAumente meu dano em 1 para cada carta que tiver jogado nesta rodada, até 3 vezes.","","\"Minha fúria sobre os ventos uivantes!\" – Janna","Feitiço",["ELEMENTAL"],["Piltover e Zaun"],"RARO (A)"],"08PZ024":["Peixeiro Picareta","Início de Rodada: TODOS os jogadores compram 1; depois, dê Fugaz à carta do seu oponente.","","\"Hoje é pague um leve dois. Só hoje! Peixe fresco, pescado faz só um... hã, mês? Dois por um! Como assim você não quer o segundo? É de graça!\"","Unidade",[],["Piltover e Zaun"],"COMUM"],"08PZ020":["Eolinuvem Glorioso","Eu custo 2 a menos se você tiver comprado 3+ cartas nesta rodada.\nAo me invocar, compre 2 cartas no próximo Início de Rodada.","","\"Meu querido Zéfiro. Desça das nuvens e repouse em meus ombros por um tempo, sim?\" – Janna","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"08FR012":["Invocação do Trovão","Compre 1.\nInvoque 1 Insígnia da Tempestade.","","\"Em nome de Valhir, fazemos esta oferenda...\" – Profetisa de Valhir","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"08FR033":["Berserker Vinculâmina","Ao jogar um feitiço Lento que alveja um único aliado, copie-o em mim.","","''Você acha que um punhado de flechas vai me impedir? Rá! Tudo que você joga contra mim se torna uma arma no meu arsenal. Tudo que for perdido será reforjado em gelo!''","Unidade",[],["Freljord"],"COMUM"],"08FR019":["Divisor de Céus","Conceda +1|+3 a um aliado nesta rodada.","","Envolto em nuvens e coberto por relâmpagos, o deus-urso permanece intocável no centro da tempestade.","Feitiço",["ELEMENTAL"],["Freljord"],"COMUM"],"08FR001":["Volibear","Jogar: Jogue Tempestade Implacável 3 vezes. Cada uma alveja um inimigo aleatório diferente ou o Nexus inimigo se não houver nenhum.","Fim de Rodada: Você causou 50+ de dano.","\"Ajoelhe-se diante de mim, mortal, e talvez saia com vida! Seu poder é medíocre, mas pode ser digno de servir ao meu. Ajoelhe-se ou suma deste mundo!\"","Unidade",[],["Freljord"],"Campeão"],"08FR018":["Confronto de Gigantes","Invoque 2 seguidores Titânicos aleatórios.\nEu custo 1 a menos para cada feitiço ou Habilidade Elemental que você tiver jogado nesta partida (quantidade máxima: 10).","","\"Com seu corpo, eu forjei as montanhas. Com o fogo de sua bocarra, esculpi mil fiordes.\" – Volibear","Feitiço",["ELEMENTAL"],["Freljord"],"ÉPICO (A)"],"08FR011":["Caprina Chamabrasas","Ao jogar uma Habilidade ou feitiço Elemental, me Forje.","","\"O Senhor da Forja prometeu mudanças e, em vez disso, martelou as correntes da inação. Aqueles que adoram um deus fraco também são fracos. Somente pelo poder de Valhir alcançaremos a glória do passado!\"","Unidade",[],["Freljord"],"RARO (A)"],"08FR008":["Emissário da Tempestade","Cause 4 de dano a TODAS as unidades, exceto aliados Titânicos.","","\"Que a tundra se tinja de vermelho!\" – Volibear","Feitiço",["ELEMENTAL"],["Freljord"],"RARO (A)"],"08FR024":["Cão das Neves Yadulskiano","Atacar: Dê +1|+1 aos 2 aliados no topo do seu deck.","","Embora sejam originários de Yadulsk, esses filhotes foram domesticados por várias tribos de Freljord para fins de rastreamento, caça e resgate em avalanches. Com uma constituição robusta e um apetite saudável por diversão, eles são adorados da tundra à taiga.","Unidade",["CANINO"],["Freljord"],"COMUM"],"08FR015":["Rhond, a Serpente de Magma","Jogar: Invoque 3 Insígnias da Tempestade.","","Embora poucos ainda o adorem, todos os freljordanos conhecem a história da grande batalha de Volibear contra Rhond. Muito antes de qualquer mortal pisar no norte congelado, esse confronto cindiu a terra e formou as cordilheiras e os rios da tundra.","Unidade",[],["Freljord"],"ÉPICO (A)"],"08FR030":["Boadir do Gelo Preto","Ao me invocar, invoque 2 Servos Congelados e Avance-os para 2.","","''Ela era f-feroz! Servos reduzidos a gelo escuro, avalanches sob suas garras, um rugido que derrubava a neve das montanhas! Uma rainha guerreira e nada menos! M-matar servos é trabalho de uma rainha guerreira.'' – Bjerg Balbuciador","Unidade",["DRAGÃO"],["Freljord"],"ÉPICO (A)"],"08FR002":["Profetisa de Valhir","Ao me invocar, invoque 1 Insígnia da Tempestade.","","\"Eu vejo o que os outros não podem ver: a tempestade que aniquilará a montanha, os ossos da terra se quebrarão. A antiga Freljord será forjada novamente com sangue... é apenas uma questão de tempo.\"","Unidade",[],["Freljord"],"COMUM"],"08FR028":["Arreio Adequado","Eu tenho +1|+0 para cada subtipo diferente que você conjurou nesta partida.","","\"Há feras aqui em cima que nem uma avalanche pode deter. É por isso que um bom arreio vale cada moeda.\"\n– Armadilheiro Avarosiano","Equipamento",[],["Freljord"],"ÉPICO (A)"],"08FR003":["Ursine Berserker","Ao jogar um feitiço ou Habilidade, invoque 1 Insígnia da Tempestade.","","Às vezes, os seguidores de Volibear mergulham tão profundamente no fanatismo que começam a assumir aspectos do urso. Nada ficará no caminho da vontade de Valhir, nem mesmo aqueles que os Ursine outrora chamavam de conterrâneos.","Unidade",[],["Freljord"],"RARO (A)"],"08RU014":["Dragão Ancião","Origem: Aspecto do Dragão.\nEu custo 1 a menos para cada Dádiva Dracônica diferente que você tiver jogado nesta partida.\nJogar: Jogue todas as Dádivas Dracônicas em mim.","Seus aliados atacaram com 75+ de Poder total.","\"Reza a lenda que este dragão é o mais velho de todos. O rei de todas as feras aladas. Se nós o domarmos... ora, Alatis, o que mais poderia se opor a nós? O mundo finalmente entenderia que homens e dragões são mais fortes juntos.\"\n– Volix, Aliado dos Dragões","Unidade",["DRAGÃO"],["Runeterra"],"Campeão"],"08NX003":["Cospe-Fogo Enfurecido","Jogar: Cause 2 de dano a um inimigo e 2 de dano ao Nexus inimigo.","","A expansão noxiana usurpou vários povos, assentamentos e culturas diferentes. Frequentemente, criaturas selvagem também estão à mercê da máquina da guerra, mas, no caso desse dragão, cada passo brutal de Noxus é respondido por uma fúria infernal igualmente brutal.","Unidade",["DRAGÃO"],["Noxus"],"ÉPICO (A)"],"08NX024":["Legionário de Ferro","Jogar: Cause 3 de dano a um aliado para causar 3 de dano a um inimigo.","","\"Arranque as almas das jaulas que são seus corpos!\"\n– Mordekaiser","Unidade",[],["Noxus"],"RARO (A)"],"08NX011":["Incêndio","Cause 1 de dano ao Nexus inimigo, aumentado em 1 para cada Incêndio que você tiver jogado. Crie 1 Incêndio no seu deck.","","\"Cinzas, cinzas...\" – Annie","Feitiço",["ELEMENTAL"],["Noxus"],"COMUM"],"08NX028":["Indestrutível","Dê Imortal a um aliado.","","\"Ferro eterno.\" – Mordekaiser","Feitiço",[],["Noxus"],"COMUM"],"08NX019":["Reptílio Farpado","Golpe ao Nexus: Amaldiçoe o seu oponente com Icor.","","Embora útil para a máquina de guerra de Noxus, o repitílio também é estimado nas arenas de luta da capital. Poucos oponentes, humanos ou animais, estão dispostos a enfrentar essa fera na arena, e, portanto, as raras batalhas com sua participação atraem gente de toda a cidade.","Unidade",["RÉPTIL"],["Noxus"],"COMUM"],"08NX014":["Diretora Telsi","Os efeitos aliados de Ataque e Auxílio são ativados uma segunda vez.","","A aula da diretora Telsi sobre disciplina pessoal é repleta de tarefas árduas, palmadas e detenções. Essa aula sempre foi obrigatória para os alunos do Conservatório Floricorvus. Caso contrário, ninguém se matricularia.","Unidade",[],["Noxus"],"ÉPICO (A)"],"08NX012":["Obtentor Armado","Jogar: Escolha um feitiço de Explorador para criar na mão.","","\"Achei que seria mais fácil cavar no deserto, mas não! Com tempo suficiente, a areia inevitavelmente se transforma em pedra. Venho mais uma vez solicitar financiamento para ferramentas novas.\" – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Shurima","Unidade",[],["Noxus","Shurima"],"RARO (A)"],"08NX029":["Pancada Kashuri","Abata uma unidade se ela tiver sofrido dano. Caso contrário, cause 2 de dano a ela.","","''Isso é do seu interesse. Confie em mim.'' – Lorde Jubalarga","Feitiço",[],["Noxus"],"ÉPICO (A)"],"08NX009":["Lorde Mallat","","","\"Foram necessários séculos de planejamento para capturar aquele terrível belicista. E seus amigos patéticos pretendem derrotá-lo com 'alegria'? Garota tola. Você só vai despertar a ira do Revenã e, assim, colocar todos nós em risco.\"","Unidade",[],["Noxus"],"COMUM"],"08NX025":["Revenã Terebrado","Quando um aliado for ressuscitado, dê Desafiador a ele.","","\"Você sorri, mas eu conheço a verdade do seu coração traiçoeiro! Eles sorriram ao meu lado e comeram à minha mesa enquanto planejavam me enfiar uma espada pelas costas. Não serei feito de bobo de novo. Você vai morrer como os outros: implorando perdão aos berros!\"","Unidade",[],["Noxus"],"RARO (A)"],"08SH009":["Esconjuro Ancestral","Amaldiçoe um inimigo com Terror.","","Tem coisa que é melhor ficar soterrada.","Feitiço",[],["Shurima"],"COMUM"],"08SH014":["Hordamante Cornífero","Jogar: Dê -1|-0 a 2 inimigos e desative as palavras-chave positivas deles.","","Apesar do tamanho intimidante, esse hordamante raramente é violento. Quando a horda se aproxima de um assentamento shurimane, os moradores deixam oferendas de frutas frescas no deserto próximo para distrair os visitantes de plantações mais importantes.","Unidade",["DRAGÃO"],["Shurima"],"COMUM"],"08SH004":["General das Dunas","Amanhecer ou ao ativar outro Amanhecer: Dê Vulnerável ao inimigo Mais Fraco.","","Os vastos exércitos de Shurima estão prontos para provar o poder do deserto. Quando a ordem é dada, eles avançam sem hesitação.","Unidade",["ELITE"],["Shurima"],"RARO (A)"],"08SH005":["Defensores do Disco Solar","Amanhecer: Compre 1 Defensores do Disco Solar.","","\"Somos os guardiões do deserto eterno, a história viva, os andarilhos da trilha do esplendor. Nos ajoelhamos perante o Disco Solar e nada mais, para que o mundo se ajoelhe diante da glória de Shurima.\" – Azir","Unidade",["ELITE"],["Shurima"],"COMUM"],"08SH012":["Barbara, a Caçadora de Relíquias","A cada rodada, na primeira vez que outro aliado morrer, ou Suspiro Final: Crie 1 Descoberta de Sorte na mão.","","\"Bom trabalho, Barb. Sabia que podia contar com você. Espera! Como assim eles te viram?!\" – Brutamontes de Vekaura","Unidade",["RÉPTIL"],["Shurima"],"RARO (A)"],"08SH002":["Bocarra-Dunesco","Para me pôr em jogo, abata um aliado ou remova uma de suas gemas de Mana 3 vezes.","","O bocarra-dunesco está adormecido em profundezas muito maiores do que seus primos xer'sai menores. Conhecido por devorar facilmente outros predadores xer'sai, ele raramente é documentado... Provavelmente porque pode engolir dunas inteiras (juntamente com qualquer testemunha). ","Unidade",[],["Shurima"],"ÉPICO (A)"],"08MT003":["Morgana","Jogar: Amaldiçoe um inimigo com Grilhões duas vezes.","Você alvejou unidades 10+ vezes.","\"Você chegou a mim ferida e sangrando e, no entanto, nunca vi uma expressão tão jubilante. Você é mesmo estranha, mas está segura aqui. Descanse, e, quando se sentir melhor, eu gostaria muito de ouvir a sua história.\"","Unidade",[],["Targon","Demacia"],"Campeão"],"08MT005":["Mihira, Aspecto Ascendente","Jogar: Amaldiçoe 2 inimigos com Grilhões duas vezes.","","\"Foi em nome das minhas filhas que eu aceitei a divindade. Foi pela minha família que abri mão da minha própria humanidade, para que, com esta espada flamejante, eu possa forjar um novo mundo de verdade e justiça.\"","Unidade",[],["Targon"],"ÉPICO (A)"],"08MT042":["Prisão do Pecador","Amaldiçoe um inimigo com Grilhões.\nAumente em 1 o custo das Maldições inimigas globalmente.","","\"Para encontrar a liberdade, encare sua escuridão interior.\"\n– Morgana","Feitiço",[],["Targon"],"RARO (A)"],"08MT024":["Conjurador do Olho-Rubi","Jogar: Dê Escudo de Feitiço ou Sobrepujar a um aliado na mão.","","\"Não tenha medo! Vá e não olhe para trás! Nós já realizamos essa jornada. Agora é nosso dever proteger a sua. Vá agora ao santuário dela, e a Redentora Velada concederá a proteção que você procura.\"","Unidade",[],["Targon"],"COMUM"],"08MT045":["Conjurador Acorrentado","Jogar: Me Amaldiçoe com Grilhões.","","Os Caçadores de Magos são peritos em quebrar pessoas. Eles acorrentaram suas mãos e sua magia. Eles roubaram sua voz. Mas ele sobreviveu a isso antes... e, dessa vez, a Redentora Velada estava ao seu lado.","Unidade",[],["Targon"],"RARO (A)"],"08MT015":["Lisa e Dolly","Jogar: Amaldiçoe um inimigo com Grilhões.","","\"Olha, Dolly! Estou fazendo igual você me ensinou! Será que um dia vamos poder mostrar pra mamãe o quanto eu aprendi? Você acha que ela já sabe? Sério?! Espero que você esteja certa.\" – Lisa","Unidade",[],["Targon"],"COMUM"],"08MT030":["Dragão das Gemas Dócil","Ao jogar um feitiço Rápido, um feitiço Lento ou uma Habilidade, dê +1|+1 a outros Dragões aliados.","","Os Dragões podem variar muito, tanto em temperamento quanto em aparência. Temos espécies propensas à destruição avassaladora, como os Dragões Infernais, mas também outras que protegem famílias e o meio ambiente, como o lento e afetuoso Dragão das Gemas.","Unidade",["DRAGÃO"],["Targon"],"RARO (A)"],"08MT023":["Ligação das Trevas","Atordoe um inimigo e o Amaldiçoe com Grilhões.","","\"Sofra, como os fez sofrer!\" – Morgana","Feitiço",[],["Targon"],"RARO (A)"],"08MT031":["Adorante de Dragões Ottrani","Ao me invocar, cure o seu Nexus em 2 e ganhe uma gema de Mana adicional na próxima rodada.","","No alto das encostas de Targon, ume Ottrani solitárie dedicou sua vida aos dragões. Elu se enfeita com escamas caídas e restos de ossos e traça seu caminho a partir de dentes de dragão espalhados pelo chão e da fumaça que sobe montanha acima.","Unidade",[],["Targon"],"ÉPICO (A)"],"08MT009":["Protetor Velado","Ao me invocar ou ao invocar um aliado Titânico, cure seu Nexus em 3.","","Esse protetor velado não esqueceu a bênção que o elevou além de uma mera fera. Ele paga essa dívida garantindo que qualquer um que busque certo santuário nas encostas do Targon faça uma jornada segura.","Unidade",[],["Targon"],"RARO (A)"],"08MT006":["Escudo Negro","Conceda Escudo de Feitiço a um aliado nesta rodada e o Amaldiçoe com Grilhões.","","\"Protegido da perseguição!\" – Morgana","Feitiço",[],["Targon"],"RARO (A)"],"08MT027":["Arauto da Convergência Celestial","Jogar: Ative os efeitos de Amanhecer e Anoitecer de outros aliados.\nAmanhecer: Eu ganho Sobrepujar.\nAnoitecer: Eu ganho Escudo de Feitiço.","","\"Um anel de fogo arde sobre nós. Na escuridão anunciada, somos todos iguais.\" – Porta-Voz Lunari","Unidade",["AVE"],["Targon"],"ÉPICO (A)"],"08MT025":["Fragmento Sísmico","Eu custo 3 a menos se você Contemplar uma unidade Titânica.\nCause 7 de dano a uma unidade.","","\"Ops! Ah, não, num se peocupa não, foi só uma balançada na péda, um acidente, não, papai, NÃO! Vambora!\" – Lasquinha","Feitiço",["ELEMENTAL"],["Targon"],"COMUM"],"08DE006":["Pioneiro Erudito","Jogar: Escolha um feitiço de Explorador para criar na mão.","","\"Tá frio. Eu tô com frio. Tudo é tão frio o tempo todo. Tem lugares que não são feitos para os seres humanos. Me mandem pra um lugar quente na próxima.'' – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Freljord","Unidade",[],["Demacia","Freljord"],"RARO (A)"],"08DE020":["Aprisionamento Mágico","Dê +0|+2 a um aliado. Amaldiçoe o seu oponente com Supressão.","","\"Reconheça o peso dos seus pecados!\" – Morgana","Feitiço",[],["Demacia"],"COMUM"],"08DE017":["Inquisidor dos Caçadores de Magos","Ao me invocar, Amaldiçoe o seu oponente com Supressão.","","\"Não podemos permitir que eles cheguem ao santuário da irmã caída. A magia dela é ancestral e perversa, e minhas habilidades não são capazes de suprimi-la. Rápido, levem essas aberrações de volta para o navio e depois subam a montanha em busca dos outros!\"","Unidade",[],["Demacia"],"RARO (A)"],"08DE025":["Dragão das Nuvens","Ao me invocar, reduza em 1 o custo de todas as unidades aliadas na mão.","","Com uma espessa pelagem que o protege do frio, este dragão pode atingir altitudes muito mais elevadas do que a maioria dos outros. Enérgicos, porém esquivos, os dragões geralmente são avistados lá no alto, com suas asas cortando as nuvens enquanto saltam entre rajadas de vento.","Unidade",["DRAGÃO"],["Demacia"],"ÉPICO (A)"],"08DE010":["Duelo de Cavalheiros","Conceda +0|+2 a um aliado nesta rodada.\nEsse aliado e um inimigo Golpeiam um ao outro.","","\"En garde, meu amigo! Você não seria covarde de recusar um duelo entre cavalheiros, sim?\" – Cavaleiro dos Laurent","Feitiço",[],["Demacia"],"COMUM"],"08DE022":["O Martim-Pescador","Ao me invocar, compre 1 de cada Campeão no seu deck.\nA cada rodada, ao invocar um Campeão pela primeira vez, Mobilize.","","''Lembre-se, meu filho: buscar qualquer horizonte deve ser em serviço do lar que deixamos para trás.'' – Rei Jarvan III","Unidade",[],["Demacia"],"ÉPICO (A)"],"08DE027":["Golpe de Garra","Dê +1|+1 a Aves aliadas globalmente. Uma Ave aliada Golpeia um inimigo.","","O grito da Rapina Prateada é um presságio da morte que vem dos céus.","Feitiço",[],["Demacia"],"RARO (A)"],"08DE026":["Alatis, o Imponente","Suas Dádivas Dracônicas afetam todos os Dragões aliados.","","\"A bem da verdade, eu nem sempre fui aliado dos dragões. Mas Alatis aqui me convenceu quando salvou a minha vida pela primeira vez. Ele me ensinou muito, mas sabe o que é mais importante? Não há nada melhor que servir a Demacia montado em um dragão.\" – Aliado dos Dragões","Unidade",["DRAGÃO"],["Demacia"],"ÉPICO (A)"],"08DE013":["Aliado dos Dragões","Ao me invocar, compre um Dragão se você Contemplar um Dragão.","","\"Detesto ter que admitir isso, parceiro, mas não podemos domá-lo sozinhos. Já fizemos o que podíamos. Avisarei ao general e, com o poder de Demacia ao nosso lado, com certeza derrubaremos essa fera.\"","Unidade",[],["Demacia"],"COMUM"],"08IO012":["Dragão do Oceano","Ao jogar um feitiço Rápido, um feitiço Lento ou uma Habilidade, cure seu Nexus em 1.","","\"Que fera grandiosa você é! Ver suas garras rasgando as ondas é uma beleza só. Se um dia decidir caçar algo além de peixes e aves marinhas, vai ser um prazer enfrentar você.\"\n– Nilah","Unidade",["DRAGÃO"],["Ionia"],"RARO (A)"],"08IO014":["Heisho, Concha do Mundo","A cada rodada, a primeira carta que você jogar custa 9 a menos.","","Para os habitantes deste vilarejo de Ionia, Heisho é, além de cuidador, amigo. Tendo carregado a casa de todos nas costas desde tempos imemoriais, eles podem confiar no portador do vilarejo para buscar litorais pacíficos em tempos difíceis.","Unidade",["RÉPTIL"],["Ionia"],"ÉPICO (A)"],"08IO021":["Dança Empírea","Interrompa um feitiço Rápido, um feitiço Lento ou uma Habilidade inimiga, Retorne um inimigo e invoque O Empíreo.","","\"Essa dança é a nossa lembrança.\" – Irelia","Feitiço",[],["Ionia"],"RARO (A)"],"08IO019":["Adnere, o Confiável","Ao me invocar, invoque Avicultores de Adnere.","","''Esta terra é repleta de lições. Nunca esqueça: o passar de cada estação deve ser celebrado, pois é apenas no fim que um novo começo pode nascer.''","Unidade",[],["Ionia"],"RARO (A)"],"08IO010":["Emborcar","Retorne um inimigo para aumentar em 2 o custo da próxima unidade que seu oponente jogar nesta rodada.","","\"Aqueles que nos desejam o mal encontrarão descanso no fundo do mar.\" – Moldador de Rios","Feitiço",["ELEMENTAL"],["Ionia"],"COMUM"],"08IO023":["Espíritos Marítimos Saltitantes","Jogar: Invoque uma cópia idêntica minha Efêmera.","","Durante certas épocas do ano, quando o vento sopra sobre o mar, alguns zaunitas juram que podem ver fracas impressões de duas enormes criaturas com nadadeiras dançando alegremente com as marés do oceano.","Unidade",[],["Ionia"],"COMUM"],"08BC020":["Lanche Matinal","Seu oponente descarta a carta de maior custo que tiver.","","\"Imagine ser uma minhoca, e a última coisa que você vê antes de morrer são esses olhos. Ah, minhoca não enxerga? Bem, acho que é melhor assim.\" – Elle, a Viajante Indiferente","Feitiço",[],["Bandópolis"],"COMUM"],"08BC005":["Mochila Abarrotada","Para cada Mochila Abarrotada que você jogou nessa partida, Plante 4 Sinos no seu deck e 4 Cogumelos Venenosos no deck do inimigo. Crie 1 Mochila Abarrotada no seu deck.","","''Regra 207: patrulheira que se preze leva só o essencial!''\n– Ava Dedicada","Feitiço",[],["Bandópolis"],"RARO (A)"],"08BC021":["Troca Furtiva","Retorne um aliado para invocar 1 Gatoruja Faminto no lugar dele.","","''SCUÍ?'' – Gatoruja","Feitiço",[],["Bandópolis"],"RARO (A)"],"08BC002":["Skip, o \"Rei do Recife\"","Jogar: Escolha 1 de 2 cartas de não Campeão da mão do inimigo. Eu a Capturo.","","''Sim, sou bonitão, rápido e maneiríssimo. Não sabia, velhote? Sou o rei desse recife, e você tá invadindo meu reino!''\n''E-Espere! Volte aqui agora mesmo! Preciso daquele espécime para minha pesquisa!'' – Conquiliologista","Unidade",[],["Bandópolis"],"ÉPICO (A)"],"08BC006":["Pioneira dos Portais","Jogar: Escolha um feitiço de Explorador para criar na mão.","","''Estou preocupado com o Bunches! Ah, ele parece estar cada vez mais nervoso esses dias. Até mesmo um saltinho entre portais o deixa angustiado! Não consigo entender...''\n– Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Bandópolis","Unidade",["YORDLE"],["Bandópolis","Ionia"],"RARO (A)"],"08BC004":["Portia, a Peculiar","Jogar: Manifeste um seguidor Titânico e defina os atributos dele em 1|1 e o custo em 0.","","''Claro que conheço a velha Portia! Ela é meio avoada, mas pode te levar rapidinho a qualquer lugar com um portal. Uma giradinha da cauda, e pronto!'' – Pioneira dos Portais","Unidade",["DRAGÃO"],["Bandópolis"],"ÉPICO (A)"],"08BC018":["Armadilha Açucarada","Coloque um aliado no fim do seu deck para invocar o aliado mais ao topo do seu deck.","","''Regra 571: um Patrulheiro deve estar sempre alerta. Nunca se sabe o que é uma guloseima e o que é uma cilada.\" – Ava Dedicada","Feitiço",[],["Bandópolis"],"RARO (A)"],"09SI015":["O Belo Desastre","I: Abata uma unidade com 5 ou menos de Poder e Vida somados.\nII: Drene 2 de Vida do Nexus inimigo.\nInvoque uma cópia idêntica de um aliado. Ele é Efêmero e 1|1.","","Ele subiu os degraus do palco segurando o poema na mão. Ele não colocou nenhum cartaz para anunciar a declamação, pois já tinha a única plateia que desejava.","Monumento",["HISTÓRIA"],["Ilhas das Sombras"],"ÉPICO (A)"],"09SI013":["A Conquista de Ferro","I-II: Escolha um seguidor aliado. Crie uma cópia Efêmera dele com +1|+1 na mão.\nIII: Ressuscite o seguidor Mais Forte que tiver morrido e dê Efêmero a ele.","","No Reino Cinzento, figuras atormentadas constituem um exército espectral. Depois que os portões do reino mortal forem abertos, ninguém poderá detê-los.","Monumento",["HISTÓRIA"],["Ilhas das Sombras"],"RARO (A)"],"09SI012":["Crise Existencial","Dê Melancolia aos inimigos.","","\"De que adianta fazer qualquer coisa? O que eu ganho com isso? – Vex","Feitiço",[],["Ilhas das Sombras"],"RARO (A)"],"09SI017":["Kharox","Sempre que um aliado não Tentáculo morrer ou usar Suspiro Final: Faça Surgir 2 Tentáculos.","","Dizem que Kharox, o remador solitário de um barco espectral que muitos marinheiros chamam de Última Barca, comunga com os espíritos de todos os marujos que pereceram tentando chegar às Ilhas.","Unidade",[],["Ilhas das Sombras"],"ÉPICO (A)"],"09SI014":["Tristálio","Jogar: Dê Melancolia a uma unidade 4 vezes.","","Romântico sombrio, poeta atormentado e apreciador da filosofia, Tristálio não se importa com um pouco de melancolia e perdição. Sua amada leva a fama de ser um pouco irritadiça, mas essa característica apenas a torna mais adorável a seus olhos.","Unidade",["YORDLE"],["Ilhas das Sombras"],"COMUM"],"09DE033":["Espiritinhos","","","''Espiritinhos são criaturas magníficas. Com o tempo e o sonhador ideal, o potencial deles é simplesmente infinito!'' – Mãe Espírito","Unidade",[],["Demacia","Ionia"],"COMUM"],"09DE039":["A Luz de Demacia","I: Dê Espírito a um aliado.\nII: Dê Espírito a um aliado 2 vezes.\nIII: Turbine todos os aliados.","","Os gritos da multidão ficaram mais altos conforme a luz dela banhou o rosto de cada um. Ela sempre buscou apoiar e alegrar seu povo, e, por sua vez, ele devolveu apoio e alegria com vozes de adoração: ''Luxanna! Luxanna! Luxanna!''","Monumento",["HISTÓRIA"],["Demacia"],"RARO (A)"],"09DE034":["Lux: Iluminada","Auxiliar: Dê Espírito ao meu aliado auxiliado e me conceda Barreira nesta rodada.","Aliados atacaram com ou ganharam enquanto atacavam um total de 20+ palavras-chave positivas.","Luzes rodopiavam ao redor de Luxanna, e as pessoas da cidade observavam maravilhadas. Aqui, ela era a Dama do Resplendor de Demacia, jovem Stemmaguarda exemplar e maga talentosa. Ali, Demacia era tudo que ela sempre quis.","Unidade",[],["Demacia"],"Campeão"],"09DE047":["Artefato Esquecido","Invoque 1 Combatente de Arenito e conceda Desafiador aos aliados nesta rodada.","","Em um cofre dos Caçadores de Magos para objetos mágicos confiscados, há uma estranha escultura sem identificação com um propósito esquecido há muito tempo...","Feitiço",[],["Demacia"],"RARO (A)"],"09DE041":["O Salão de Petricita","I: Um aliado Captura uma unidade.\nII: Amaldiçoe o oponente com Supressão.\nIII: Oblitere todas as cartas Capturadas por aliados.","","Os gritos da multidão desapareceram quando ela entrou no salão. As estátuas pareciam olhar em silêncio. A escuridão estava à espera, mas ela não podia recuar. Quem mais poderia evitar que Demacia se perdesse nesse pesadelo?","Monumento",["HISTÓRIA"],["Demacia"],"ÉPICO (A)"],"09DE030":["Incandescência","Turbine todas as unidades.","","''Nossa resplandescência não tem limites!'' – Lux: Iluminada","Feitiço",[],["Demacia"],"COMUM"],"09DE043":["Fulgor Ascendente","Turbine todas as unidades 3 vezes.","","''Consagrada na luz!'' – Lux: Iluminada","Feitiço",[],["Demacia"],"RARO (A)"],"09DE031":["Jarro Plumaluz","Jogar: Dê Espírito a um aliado na mão.","","Um jovem com uma máscara de baile aparece diante dela com um floreio de pétalas de rosas e criaturas luminescentes. ''Meu nome é Plumaluz. Jarro Plumaluz'', ele disse. ''Fiquei sabendo que talvez você estivesse precisando de ajuda, senhorita.''","Unidade",[],["Demacia"],"RARO (A)"],"09DE046":["Sorriso Abrasador","Turbine 2 aliados, depois eles Golpeiam um inimigo em sequência.","","''Relaxem, senhoritas. Tem Jarro para todas.'' – Jarro Plumaluz","Feitiço",[],["Demacia"],"COMUM"],"09DE045":["Alina Sonhaluz","Ao me invocar, invoque 5 Espiritinhos. Para cada um que não tiver espaço para ser colocado no tabuleiro, dê Espírito ao aliado Mais Fraco 2 vezes.","","''Quando tinha sua idade, eu tinha tanto medo da luz. Não havia ninguém para me dizer que minha magia era uma bênção, que eu era assim por um motivo. Mas agora você tem a mim para te dizer isso. Não tenha medo, Alina. Deixe sua luz brilhar!'' – Lux: Iluminada","Unidade",[],["Demacia"],"ÉPICO (A)"],"09DE040":["Caçador de Magos Estrambólico","Ao me invocar, dê Espírito aos outros aliados.","","''Lady Stemmaguarda.'' O Caçador de Magos se materializou das sombras, estendendo a mão na direção dela. O sorriso suplicante dele parecia grande demais no rosto parcialmente coberto. \"Por que você não me segue?\"","Unidade",[],["Demacia"],"COMUM"],"09DE036":["Espíritos Arbóreos","Jogar: Turbine todas as outras unidades.","","''Vamos, espiritinhos. Mostrem o caminho a quem sonha.''\n– Lillia","Unidade",[],["Demacia","Bandópolis"],"COMUM"],"09DE029":["Luminispírito","Auxiliar: Conceda todas as minhas palavras-chave positivas e seus acúmulos ao meu aliado auxiliado nesta rodada.","","''Vamos lá, Senhor Espírito. Vamos queimar essas sombras assustadoras!'' – Alina Sonhaluz","Unidade",[],["Demacia"],"RARO (A)"],"09SH010":["Reconstrutora do Império","Jogar: Dê \"Ao me destruir, me ressuscite\" a um Monumento aliado.","","A ascensão do Imperador deu esperança a Shurima. Determinada a ajudar a concretizar a visão de Azir, essa maga autointitulada \"Reconstrutora do Império\" viaja pelo deserto com o intuito de restituir as ruínas enterradas ao seu antigo esplendor.","Unidade",[],["Shurima"],"COMUM"],"09SH009":["O Exército do Imperador","I: Invoque 2 Soldados de Areia.\nII: Preveja.\nIII: Ao invocar um aliado, conceda +2|+0 a ele nesta rodada.","","Azir conhece Shurima como foi, como é e como será. Ele acredita que sua visão do futuro é muito mais que um mero sonho: é uma profecia que ele está destinado a cumprir.","Monumento",["HISTÓRIA"],["Shurima"],"ÉPICO (A)"],"09SH012":["Invocação dos Solnatas","Escolha 1 de 3 Campeões que tenham começado no seu deck e compre-o.","","Muitos artefatos dos antigos guerreiros solnatas foram perdidos com o tempo. O mesmo não pode ser dito a respeito dos deuses-guerreiros que eles representam.","Feitiço",[],["Shurima"],"RARO (A)"],"09PZ044":["A Prece da Luz de Velas","I-II: Eleve 1 para comprar 1.\nIII: Compre 1.","","Esse templo para Janna tem poucas paredes sólidas, o que condiz com os poderes da deusa. Mesmo assim, várias velas sempre estão acessas, mesmo quando uma tempestade violenta assola o restante de Zaun.","Monumento",["HISTÓRIA"],["Piltover e Zaun"],"ÉPICO (A)"],"09PZ045":["Cartografia Alada","Jogar: Eleve 1 para comprar outra carta com custo maior ou menor que a carta Elevada.","","\"Estar lá no alto é a maneira mais certa de reconhecer a própria insignificância.\"","Unidade",[],["Piltover e Zaun"],"RARO (A)"],"09PZ046":["Mutação Anômala","Escolha um seguidor aliado. Invoque 2 Gatorujas Famintos e transforme aliados em cópias idênticas do aliado escolhido.","","\"Só mais uma cópia... daí vai ficar perfeito.\" – Imperfeccionista Maligna","Feitiço",[],["Piltover e Zaun"],"ÉPICO (A)"],"09IO055":["Fadinha Floral","Ao me invocar, invoque Espiritinhos.","","\"Nossa Lillia está toda descabelada. Vá dar um jeito nisso, sim? Lembre-se: a primeira mecha é dos desejos, a segunda, dos sonhos e, a última, de tudo que não é o que parece.\" – Mãe-Espírito","Unidade",[],["Ionia"],"RARO (A)"],"09IO056":["Dança dos Espiritinhos","Retorne um aliado para dar todos os acúmulos de Espírito dele a outro aliado.","","''Os sonhos do coração estão a um cochilo de virarem realidade!'' – Lillia","Feitiço",[],["Ionia"],"RARO (A)"],"09IO048":["Mãe-Espírito","Ao me invocar, dê Espírito a Espiritinhos e Mães-Espírito aliados globalmente.","","Espíritos são animados, volúveis e nem sempre bons ouvintes. Para garantir que vão encontrar os sonhadores, a Mãe-Espírito cuida deles com pulso firme e uma boa dose de broncas.","Unidade",[],["Ionia"],"ÉPICO (A)"],"09IO049":["A Colheita das Gotas de Orvalho","I: Invoque Espiritinhos.\nII: Adormeça um aliado.","","As gotas de orvalho da Árvore-Mãe permitem vislumbrar um sonho em algum lugar de Runeterra. Cada uma delas deve ser colhida, cultivada e protegida com cuidado.","Monumento",["HISTÓRIA"],["Ionia"],"COMUM"],"09IO052":["Lillia","Ao me invocar ou ao Golpear: Crie 1 Ramo Onírico na mão ou reduza o custo em 1 se já tiver uma cópia.","Você invocou 15+ aliados ou Monumentos.","No coração do Jardim do Esquecimento, está chegando a hora da colheita das gotas de orvalho. Embora elas sejam cultivadas com carinho por Lillia e outros guardiões do jardim, uma podridão estranha as contaminou, e os sonhos que elas mostram se tornaram perturbadores e sombrios...","Unidade",[],["Ionia"],"Campeão"],"09IO046":["Jardineira Ophelis","Jogar: Cure completamente um aliado, depois Adormeça-o.","","Cuidar da Árvore dos Sonhos e do jardim ao redor é uma grande honra, porém exige sacrifícios. Em um ritual de respeito e apreciação, os guardiões do jardim oferecem as próprias memórias, perdendo uma parte de si todas as noites.","Unidade",[],["Ionia"],"COMUM"],"09IO051":["O Caminho da Raiz","I-II: Compre 1.\nIII: Reduza em 1 o custo das cartas na sua mão nesta rodada.","","O Jardim do Esquecimento é o lar de uma estranha variedade de criaturas grandes e pequenas; algumas são mais sencientes do que gostariam de ser.","Monumento",["HISTÓRIA"],["Ionia"],"RARO (A)"],"09IO053":["Dona Raiz","Ao me invocar, compre 1.","","\"Uau, um dia toda essa beleza vai mergulhar no sono eterno, e nós também. Tomara que eu mergulhe primeiro. Hehe!\"","Unidade",[],["Ionia"],"COMUM"],"09IO045":["Botão Florescente","Adormeça uma unidade.","","''Os sonhos estão florescendo!'' – Lillia","Feitiço",[],["Ionia"],"RARO (A)"],"09IO058":["O Coração da Árvore","I: Cure seu Nexus em 3 e invoque Espiritinhos.\nII: Dê Espírito aos aliados globalmente.\nIII: Manifeste uma carta de custo 8 ou mais e reduza o custo dela pela metade, arredondando para cima.","","Espíritos oníricos são os habitantes mais abundantes do Jardim. De todos os formatos, tamanhos e temperamentos, muitos deles entram em gotas de orvalho e guiam os sonhadores até seus desejos mais profundos.","Monumento",["HISTÓRIA"],["Ionia"],"ÉPICO (A)"],"09IO059":["Ventania de Aço","Atordoe um inimigo e Atordoe-o novamente no próximo Início de Rodada.","","''A lâmina acima de tudo.'' – Yone, o Perseguidor de Ventos","Feitiço",[],["Ionia"],"COMUM"],"09FR009":["Desfile de Poros","I-II: Manifeste um seguidor que tenha um subtipo diferente dos aliados em jogo.\nIII: Conceda +1|+1 a um aliado nesta rodada para cada aliado com um subtipo.","","Ingvar criou laços ainda mais fortes com os súditos do Rei Poro desde que visitou o reino dele. Marchar por Freljord em busca de aventuras é uma das melhores táticas para melhorar relações diplomáticas.","Monumento",["HISTÓRIA"],["Freljord"],"ÉPICO (A)"],"09FR014":["Brynhir Cantotrovejante","Jogar: Oblitere uma unidade na mão para invocar 1 Pináculo Tempescavado que tenha Contagem equivalente ao seu próprio custo e invoque uma cópia idêntica da unidade. (Mínimo: 1)","","''Sou fruto da tempestade da montanha e da canção de meu povo!''","Unidade",[],["Freljord"],"ÉPICO (A)"],"09FR010":["Poro Ultrafofuxo","Jogar: Cure seu Nexus em 1 para cada aliado com um subtipo.","","''Hehe! Olhe só aquele pelo!'' – Pastor de Poros","Unidade",["PORO"],["Freljord"],"COMUM"],"09FR012":["Ceifa Glacial","Dê a um aliado Vida equivalente ao Poder dele e Formidável, depois reduza o Poder a 0.","","Algumas árvores de Freljord só podem ser derrubadas pela força da própria geada de inverno.","Feitiço",[],["Freljord"],"RARO (A)"],"09BC020":["Olhar de Desdém","Dê Melancolia a uma unidade para comprar 1.","","''Parabéns. Eu te odeio.'' – Vex","Feitiço",[],["Bandópolis","Ilhas das Sombras"],"COMUM"],"09BC012":["A Reunião de Família","I: Dê Melancolia a uma unidade.\nII: Dê Impacto a um aliado.\nIII: Turbine 2 unidades.","","Saudade do que nunca vivi não se aplica. Os jantares em família são calmos por aqui, do jeitinho que a Vex gosta.","Monumento",["HISTÓRIA"],["Bandópolis"],"ÉPICO (A)"],"09BC001":["Vex","Atacar: Dê Melancolia ao inimigo Mais Forte.","Você deu Melancolia 5+ vezes distintas.","\"Ugh, garotinha rosa idiota. Eu já disse que ODEIO festas, principalmente quando tem bolo. Que nojo. Me acorda quando ela for embora, vai...''","Unidade",["YORDLE"],["Bandópolis","Ilhas das Sombras"],"Campeão"],"09BC002":["Tio Milty","Eu ganho Espírito 2 vezes quando concluir uma História.","","Apesar de ser bem diferente de sua sobrinha tristonha, o Tio Milty sempre se esforçou para criar uma conexão com ela... principalmente se for com uma história assustadora à luz de velas.","Unidade",["YORDLE"],["Bandópolis"],"RARO (A)"],"09BC013":["Dádiva Alada","I-II: Escolha um aliado, depois escolha 1 de 3 seguidores que custa 1 a mais para que ele se transforme.\nIII: Escolha um aliado, depois escolha 1 de 3 seguidores que custa 2 a mais para que ele se transforme.","","O velho Trevor Dorminhão está sempre viajando de um sonho para outro. Por sorte, esse aqui parece ser bem calmo... mas, estranhamente, todo mundo por aqui parece querer asas iguais às dele...","Monumento",["HISTÓRIA"],["Bandópolis"],"RARO (A)"],"09BC004":["Sossega o Facho","Jogar: Eu ganho Espírito ou dê Melancolia a uma unidade.","","\"Veeeeex! Pera aí! Tenho uma coisinha pra você! É um convite para sua própria FESTA DE ANIVERSÁRIO! E seu presente adiantado! Não me aguentei. Você tá animada? Precisamos decidir o que vestir, o bolo e... Vex?''","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"09BC016":["Manifestação Monstruosa","Deixe um aliado com 5 de Poder ou Vida nesta rodada.","","''Pior presente de todos os tempos.'' – Vex","Feitiço",[],["Bandópolis"],"COMUM"],"09BC003":["Presente Grotesco","Na primeira vez que um inimigo for invocado, dê Melancolia a ele.","","''Olha só, não foi um presente tão ruim no fim das contas.''\n– Vex","Unidade",[],["Bandópolis"],"RARO (A)"],"09BC018":["Sombra","Ao me invocar, compre Vex.\nEu tenho +1|+0 para cada vez diferente que você deu Melancolia nesta partida.","","''Isso aí, Sombra! Mostra pra eles. Nada de presentes, confete e PRINCIPALMENTE chapeuzinhos de aniversário.'' – Vex","Unidade",[],["Bandópolis","Ilhas das Sombras"],"ÉPICO (A)"],"09BC011":["Espíritos Melancólicos","Golpear: Eu ganho Impacto.","","''Sonhos têm um jeito esquisito de mudar os espíritos. Esses parecem ser... opa! Isso aí é bolo?'' – Lillia","Unidade",[],["Bandópolis"],"COMUM"],"09BC006":["Prefeito Bombadão","Início de Rodada: Me Turbine.","","O tempo desacelerou quando o prefeito estranhamente musculoso saiu daquele bolo inacreditavelmente alto. ''Muitos PARABÉÉÉÉÉNS PRA VOCÊ!'', disse o prefeito mostrando os músculos. ''Da melhor (e mais musculosa) autoridade eleita de Bandópolis!''\n\nDe todos os seus sonhos, esse era o que Vex mais odiava. ","Unidade",["YORDLE"],["Bandópolis"],"COMUM"],"09BW022":["A Campeã da Arena","I: Um aliado e um inimigo Golpeiam um ao outro. Esse Golpe não pode deixá-los com menos de 1 de Vida.\nII: Cure completamente um aliado.\nIII: Crie 3 Moedas na mão.","","Anjinho passou anos tentando vencer a maior luta de todas. Toda noite, ela sonha com uma pilha de moedas grande o suficiente para encher a Baía de Águas de Sentina. Dinheiro da plantação de batatas, claro.","Monumento",["HISTÓRIA"],["Águas de Sentina"],"ÉPICO (A)"],"09BW028":["Devoto Dedicado","Eu tenho +1|+0 para cada carta que você tiver comprado nesta rodada.","","''Como assim eu preciso de mais treinamento? Eu já treinei MUITO! Olha só!''","Unidade",[],["Águas de Sentina"],"RARO (A)"],"09BW027":["Costumes dos Mercenários","Roube um seguidor inimigo com 3 ou menos de Vida nesta rodada. (Não pode jogar se já tiver 6 aliados ou Monumentos.)","","''Sempre bom começar o dia trocando sangue por ouro.'' – Assassina de Aluguel","Feitiço",[],["Águas de Sentina"],"COMUM"],"09MT002":["Anfitrião das Escamas de Névoa","I-II: Para ativar, descarte 1. Evoque uma carta Celestial que custe 7 ou mais.\nIII: Reduza em 5 o custo de uma carta aleatória na mão.","","Este Ottrani solitárie se dedica à adoração dos dragões. Elu os reverencia com tanta fé que consegue ver as nobres feras tanto no mundo real quanto no mundo onírico.","Monumento",["HISTÓRIA"],["Targon"],"ÉPICO (A)"],"09MT004":["Bênçãos Veladas","Dê Espírito a um aliado 2 vezes.","","''Eu serei o santuário deles.'' – Morgana","Feitiço",[],["Targon"],"COMUM"],"09MT005":["Sonhadora da Canção Dracônica","A cada rodada, ao Evocar pela primeira vez, invoque Dragonito.","","Os dragões estão próximos. Posso sentir. Neste exato momento, eles viajam pelos meus sonhos.''","Unidade",[],["Targon"],"ÉPICO (A)"],"09NX025":["O Maioral da Arena","I-II: Conceda +2|+0 a um aliado nesta rodada.\nIII: Conceda Não Bloqueia a um inimigo nesta rodada.","","A arena ficou popular, já que qualquer um pode ganhar fama dentro dela. Esse fã específico testemunhou o máximo de embates do Draven que pôde; se tiver a oportunidade, ele também acha que pode alcançar o topo.","Monumento",["HISTÓRIA"],["Noxus"],"ÉPICO (A)"],"09NX032":["Domador de Yetis","Para me pôr em jogo, descarte 1.\nAo me invocar, invoque 1 Yeti Enfurecido.","","O sucesso da máquina de guerra noxiana se dá em parte por sua flexibilidade. Quando terrenos difíceis ou condições adversas exigem adaptação, os militares utilizam os recursos locais mais improváveis.","Unidade",[],["Noxus"],"RARO (A)"],"09NX033":["Machado de Guerra Deteriorado","Fim de Rodada: Se meu portador não atacou nesta rodada, dê Melancolia a ele.","","Covardia custa caro.","Equipamento",[],["Noxus"],"RARO (A)"]};
